/* BK-Score – Bewertung des Wissensstands, nicht der Substanz
 * ==========================================================
 *
 * Vier Achsen, je 0-10. Der entscheidende Grundsatz: Jede Achse bewertet,
 * WAS MAN WEISS – keine bewertet, ob etwas gut oder sicher ist. Das ist nicht
 * nur juristisch der Unterschied zwischen einer Tatsachenbehauptung ueber
 * Studien und einer gesundheitsbezogenen Angabe; es ist auch die einzige
 * Bewertung, die wir redlich vergeben koennen.
 *
 * evidenz      Human-Evidenz – wie viel und wie gute Daten am Menschen?
 *   0-1  keine Humandaten
 *   2-3  Fallberichte, Anwendererfahrung, unkontrollierte Serien
 *   4-5  kleine oder unverblindete Studien, nur Surrogatmarker
 *   6-7  mehrere RCTs, aber klein, kurz oder uneinheitlich
 *   8-9  grosse RCTs oder konsistente Meta-Analysen mit harten Endpunkten
 *   10   Zulassung fuer genau diese Indikation auf Basis von Phase-III-Daten
 *
 * mechanismus  Wie gut ist die Wirkkette verstanden?
 *   0-2  Marketing-Erzaehlung ohne belegten Pfad
 *   3-5  plausibel aus Zellkultur und Tiermodell, Uebertragbarkeit offen
 *   6-8  Zielstruktur bekannt und am Menschen bestaetigt
 *   9-10 Wirkkette am Menschen quantifiziert (Dosis-Wirkung, Biomarker)
 *
 * sicherheit   Sicherheits-DATENLAGE – wie gut ist Sicherheit untersucht?
 *   0-2  nicht systematisch untersucht
 *   3-5  nur Kurzzeitdaten
 *   6-8  kontrollierte Daten ueber Monate
 *   9-10 Langzeitdaten aus Zulassung und Pharmakovigilanz
 *   ACHTUNG: eine hohe Zahl heisst "gut untersucht", nicht "harmlos".
 *
 * hype         Hype-Abstand – wie weit laeuft die Vermarktung der Evidenz voraus?
 *   0-2  Versprechen ohne Grundlage
 *   3-5  ein Einzelbefund wird zur Gesamtaussage
 *   6-8  ueberwiegend korrekt, einzelne Ueberdehnungen
 *   9-10 die Werbung bleibt auf Hoehe der Daten
 *
 * anwendung    Anwendungserfahrung – wie viel dokumentierte Anwendung am
 *              Menschen liegt vor: seit wann, wie breit, in welchem Rahmen?
 *   0-1  praktisch keine Anwendung am Menschen (Forschungschemikalie)
 *   2-3  nur in Studien oder in kleinen Graumarktkreisen, wenige Jahre
 *   4-5  verbreitet ohne regulatorischen Rahmen, oder Nische mit Zulassung
 *   6-7  seit vielen Jahren breit angewendet, in einem Land reguliert
 *   8-9  jahrzehntelang, breit, unter Aufsicht mit Nebenwirkungserfassung
 *   10   jahrzehntelang in Millionen Menschen mit systematischer Pharmakovigilanz
 *   ACHTUNG: Diese Achse misst NICHT, ob etwas wirkt. Aderlass haette hier
 *   eine 10. Sie existiert, weil lange Anwendungspraxis eine eigene Tatsache
 *   ist, die man kennen sollte – und weil sie ohne eigene Achse faelschlich
 *   in die Evidenz-Achse gerutscht waere.
 *
 * Regeln
 *   - Jede Zahl braucht einen Ein-Satz-Beleg. Ohne Beleg keine Zahl.
 *   - Kein Mittelwert als Gesamtnote: die Achsen messen Verschiedenes.
 *     Das Label entsteht aus Human-Evidenz und Hype-Abstand (bkLabel()).
 *   - Shops werden nie bewertet, und keine Bewertung haengt daran, ob ein
 *     Partner das Produkt verkauft.
 *   - Aendert sich eine Zahl, entsteht ein Eintrag in aenderungen.js.
 *
 * WICHTIG – Disclaimer: Alle Bewertungen sind subjektive Einschaetzungen von
 * Biohacking Kompakt auf Basis der oben offengelegten Vergaberegeln. Sie sind
 * keine wissenschaftliche Bewertung, kein Konsens einer Fachgesellschaft und
 * keine medizinische Empfehlung. Andere koennen bei derselben Studienlage zu
 * anderen Zahlen kommen; deshalb stehen die Regeln und die Begruendung dabei.
 *
 * richtung: wohin die vorhandene Evidenz zeigt – 'positiv', 'gemischt',
 * 'negativ' (gut untersucht, Wirkung nicht bestaetigt) oder 'offen'
 * (zu wenig Daten fuer eine Richtung).
 *
 * berichtslage: optional. Was Anwender, Aerzte und Fallberichte uebereinstimmend
 *   beobachten – bewusst GETRENNT von der Evidenz und ohne Einfluss auf das
 *   Label. Uebereinstimmende, unabhaengige Berichte ueber einen spezifischen
 *   Effekt sind Evidenz: schwache, aber keine Null. Die gesamte Arzneimittel-
 *   sicherheit funktioniert so. Was sie nicht leisten: zu zeigen, dass der
 *   benannte Stoff die Ursache war, und dass der Nutzen die Risiken aufwiegt.
 *   Deshalb steht die Berichtslage daneben – nicht als Achse. Ein Balken
 *   behauptet eine Messung; das hier ist eine Einschaetzung, und sie soll auch
 *   so aussehen.
 *     stufe 1 – vereinzelt
 *     stufe 2 – verbreitet und uebereinstimmend
 *     stufe 3 – verbreitet, uebereinstimmend und spezifisch
 *   Entscheidend ist die Spezifitaet: „fuehle mich besser" ist Rauschen,
 *   „Braeunung ohne Sonne binnen einer Woche" ist Signal.
 *   Das Feld wird nur gesetzt, wo es etwas hinzufuegt – fehlt es, heisst das
 *   nicht „keine Berichte", sondern „traegt hier nichts zur Einordnung bei".
 *
 * belegLuecke: optional, erklaert WARUM die Evidenzachse niedrig steht.
 *   'unveroeffentlicht' – am Menschen geprueft, Ergebnisse nie publiziert.
 *   Im Balkendiagramm sieht das aus wie „nie versucht", ist aber etwas
 *   anderes: Es gab Studien, sie sind nur nicht ueberpruefbar. Das ist ein
 *   Warnzeichen und ein Hinweis zugleich, und es gehoert nicht verschwiegen.
 *
 * Stand: 29.08.2026 – 197 von 218 Eintraegen bewertet (Supplements, Peptide,
 * Khavinson-Bioregulatoren, Anwendungen). Nicht bewertet sind die 21 Eintraege
 * der Kategorie MHC (Ausstattung, Schwerpunkt, Netzwerk, Extern) – redaktionelle
 * Entscheidung, keine Aussage ueber diese Angebote.
 */
const BK_SCORES = [
  { id: 'aspirin-praevention', view: 'experimental', evidenz: 10, mechanismus: 9, sicherheit: 4, hype: 5, anwendung: 10, richtung: 'negativ',
    beleg: 'Für die Vorbeugung bei Gesunden ist die Frage beantwortet, und zwar mit Nein. ASPREE (NEJM 2018) randomisierte 19.114 Menschen ab siebzig ohne Herzinfarkt, Schlaganfall, Demenz oder Behinderung auf 100 mg magensaftresistentes Aspirin oder Placebo; Medianalter 74, Median 4,7 Jahre, vorzeitig beendet. Beim primären Endpunkt aus Tod, Demenz und dauerhafter Behinderung standen 21,5 gegen 21,2 Ereignisse je tausend Personenjahre (HR 1,01; p = 0,79). Die Gesamtsterblichkeit lag unter Aspirin höher (HR 1,14), dazu kamen mehr schwere Blutungen. Der Sicherheitswert bezieht sich ausdrücklich auf diese Anwendung bei Gesunden. Nach Infarkt oder Schlaganfall gilt das Gegenteil – dort ist der Nutzen belegt und dieser Eintrag nicht zuständig.' },
  { id: 'finasterid', view: 'experimental', evidenz: 9, mechanismus: 9, sicherheit: 8, hype: 4, anwendung: 9, richtung: 'gemischt',
    berichtslage: { stufe: 2, kurz: 'Wirkung bestätigt, Nebenwirkungen umstritten', was: 'Die Berichte zum Haar decken sich mit den gezählten Daten. Umstritten ist die andere Hälfte: Foren und Selbsthilfegruppen berichten anhaltende sexuelle und psychische Beschwerden auch nach dem Absetzen. Als Krankheitsbild ist das nicht etabliert, die größte Auswertung dazu lief an älteren Männern mit höherer Dosis und passt schlecht auf junge Anwender. Der Rote-Hand-Brief vom September 2025 hat die Diskussion in die Produktinformation geholt.', quellen: 'Anwenderberichte · Selbsthilfegruppen · Rote-Hand-Brief 09/2025' },
    beleg: 'Der Effekt am Haar gehört zu den am saubersten vermessenen in diesem Feld: zwei verblindete Studien mit 1.553 Männern zwischen 18 und 41, ausgezählt auf 5,1 Quadratzentimetern am Wirbel (Ausgangswert 876 Haare). Nach einem Jahr 107 Haare mehr als unter Placebo, nach zwei Jahren 138, jeweils p < 0,001, mit verblindeter Verlängerung an 1.215 Männern. Sicherheits-Datenlage 8, weil die Nebenwirkungen aus Zulassungsstudien und jahrzehntelanger Anwendung gut dokumentiert sind; die Achse bewertet die Datenlage, nicht die Gefahr. Die Nebenwirkungen sind der Grund für die gemischte Richtung: Seit dem Rote-Hand-Brief vom 15. September 2025 stehen Suizidgedanken als Nebenwirkung in der Produktinformation, Häufigkeit ausdrücklich unbekannt. Sexuelle Funktionsstörungen sind der häufigste Abbruchgrund.' },
  { id: 'nikotin-ohne-rauch', view: 'experimental', evidenz: 8, mechanismus: 9, sicherheit: 8, hype: 7, anwendung: 8, richtung: 'negativ',
    beleg: 'Der akute Effekt ist gut belegt und klein: Eine Meta-Analyse über 41 doppelblinde Studien (Heishman, Psychopharmacology 2010) fand in sechs von neun Leistungsbereichen einen Vorteil, darunter Feinmotorik, Aufmerksamkeit, Reaktionszeit und Kurzzeitgedächtnis, Effektstärken 0,16 bis 0,44 – im Labor, für etwa eine Stunde. Genau diese Arbeit benennt die Abhängigkeit als zugehörigen Befund. Die Sicherheits-Datenlage ist gut: Nikotinersatz ist in über hundert randomisierten Studien geprüft (Cochrane 2018). Das heißt gut untersucht, nicht harmlos. Die Richtung bleibt negativ, weil über dem kleinen, kurzen Effekt eine Abhängigkeit steht – und diese Abhängigkeit ist der Grund, warum Rauchen die größte vermeidbare Todesursache ist. Zum Dauergebrauch bei Nichtrauchern gibt es keine Daten. Für den Rauchstopp dagegen ist Nikotinersatz belegt wirksam (Cochrane 2018) – das ist die eine Anwendung mit klarem Nutzen. Tabakfreie Nikotinbeutel sind in Deutschland nicht verkehrsfähig.' },
  { id: 'erythrit-xylit', view: 'supplement', evidenz: 5, mechanismus: 7, sicherheit: 5, hype: 5, anwendung: 9, richtung: 'gemischt',
    beleg: 'Unentschieden, nicht entlastet. Der Mechanismus ist gezeigt: Nach 30 Gramm Erythrit stieg der Plasmaspiegel von 3,75 auf 6.480 Mikromol je Liter – mehr als das Tausendfache – und die Blutplättchen reagierten anschließend stärker, bei allen Probanden, bei jedem Reizstoff, bei jeder Stufe (ATVB 2024). Traubenzucker als Vergleich tat das nicht. Die Human-Evidenz bleibt schwach, weil diese Arbeit zehn Teilnehmer je Gruppe hatte und der Zusammenhang mit Herzinfarkt und Schlaganfall aus Beobachtung an über 4.000 Herzpatienten stammt, bei denen die Zufuhr nie gemessen wurde – nur der Blutspiegel. Erschwerend: Der Körper bildet beide Stoffe selbst, bei gestörtem Zuckerstoffwechsel mehr. Derselbe Wert kann Ursache sein oder Anzeige.' },
  { id: 'schlafapnoe-cpap', view: 'behandlungen', evidenz: 9, mechanismus: 9, sicherheit: 9, hype: 4, anwendung: 9, richtung: 'gemischt',
    berichtslage: { stufe: 3, kurz: 'Ausgeschlafen – und das stimmt auch', was: 'Die Berichte sind einheitlich und decken sich mit dem, was gemessen wurde: weniger Schnarchen, wacher am Tag, bessere Stimmung. Genau diese Endpunkte hat SAVE mitgemessen und bestätigt. Die Berichte sagen nur nichts über das Herz aus – und dort liegt die Lücke.', quellen: 'Anwenderberichte · Schlafambulanzen' },
    beleg: 'Ein Lehrstück über den Unterschied zwischen Surrogat und Ergebnis. Dass das Gerät wirkt, ist unstrittig: Der Apnoe-Hypopnoe-Index fiel in SAVE (NEJM 2016) von 29 auf 3,7 je Stunde. Schnarchen, Tagesschläfrigkeit, Lebensqualität und Stimmung besserten sich signifikant. Der harte Endpunkt fehlt: Bei 2.717 Erwachsenen zwischen 45 und 75 mit mittelschwerer bis schwerer Schlafapnoe und bereits bestehender Herz-Kreislauf-Erkrankung lag das Risikoverhältnis für Herztod, Infarkt und Schlaganfall nach 3,7 Jahren bei 1,1 (95 % KI 0,91–1,32; p = 0,34). Der Hype-Abzug gilt der Vermarktung als Herzschutz, nicht dem Gerät.' },
  { id: 'krebs-frueherkennung-bluttest', view: 'behandlungen', evidenz: 8, mechanismus: 6, sicherheit: 7, hype: 7, anwendung: 4, richtung: 'negativ',
    beleg: 'Die Evidenz ist hoch, weil es die erste randomisierte Studie überhaupt zu einem Multi-Krebs-Früherkennungstest gibt – und ihr Hauptendpunkt wurde verfehlt. NHS-Galleri schloss 142.250 Menschen zwischen 50 und 77 ein, drei Blutabnahmen über zwei Jahre, zwölf vorab festgelegte Krebsarten, die zusammen für zwei Drittel der jährlichen Krebstoten stehen. Das Inzidenzratenverhältnis für Stadium III oder IV lag bei 1,03 (95 % KI 0,92–1,14; p = 0,63). Die häufig zitierte Reduktion später Diagnosen stammt aus einem sekundären Befund (Stadium IV: 0,86), dessen Vertrauensbereich fast die Eins berührt. Der Hype-Abstand ist der höchste Posten: Vermarktet wird ein Test, der etwa drei von zehn Krebsen findet – und dessen unauffälliges Ergebnis keine Entwarnung ist.' },
  { id: 'mikrobiom-tests', view: 'behandlungen', evidenz: 6, mechanismus: 7, sicherheit: 9, hype: 7, anwendung: 6, richtung: 'gemischt',
    beleg: 'Die Grundlage ist gut: PREDICT 1 (Nat Med 2020) maß an 1.002 britischen Erwachsenen standardisierte Testmahlzeiten über neun bis elf Tage, unabhängig bestätigt an 100 Menschen in den USA. Die individuelle Streuung ist real und groß – 103 Prozent beim Blutfett, 68 beim Blutzucker, 59 beim Insulin. Für die Fettantwort trug das Mikrobiom mehr bei als die Nährstoffzusammensetzung (7,1 gegen 3,6 Prozent der Varianz), beim Blutzucker war es umgekehrt (6,0 gegen 15,4). Der Beitrag genetischer Varianten zur Vorhersage ist klein: 9,5 Prozent beim Blutzucker, 0,8 beim Blutfett, 0,2 beim C-Peptid. Der Hype-Abzug betrifft den Sprung von dieser Forschung zum verkauften Ernährungsplan – und die Tatsache, dass die Messung zwischen Anbietern heute nicht zuverlässig wiederholbar ist.' },
  { id: 'langzeit-basenbaden', view: 'behandlungen', evidenz: 6, mechanismus: 7, sicherheit: 7, hype: 6, anwendung: 8, richtung: 'gemischt',
    berichtslage: { stufe: 3, kurz: 'Rücken weich, Körper leichter – beides erklärbar', was: 'Die Berichte sind auffallend konsistent: gelöste Muskulatur, ein leichteres Gefühl danach, besserer Schlaf. Sie sind der Grund, warum das Ritual gepflegt wird, und sie sind nicht eingebildet. Nur die Erklärung, die mitgeliefert wird – ausgeleitete Säure über die Haut – trifft nicht zu. Was passt, ist Immersionsdiurese: Wasser und Salz gehen über die Niere weg, gemessen und reproduziert.', quellen: 'Anwenderberichte · Erfahrungsbericht aus dem Umfeld' },
    beleg: 'Getrennt bewerten: Begründung und Wirkung. Die Begründung trägt nicht – über die Haut wird keine nennenswerte Säure ausgeschieden; der Maßstab ist die renale Netto-Säureausscheidung von rund 71 mmol am Tag (Sebastian, NEJM 1994). Die Wirkung ist dagegen gut vermessen: In Immersionsversuchen schieden 13 Männer in drei Stunden 758 ml Urin und 56 mmol Natrium aus, ANP stieg, Aldosteron fiel (Farrow, J Appl Physiol 1992). Die Temperatur entscheidet mit: bei 32 und 34,5 °C sechsfache Ausscheidung, bei 36 °C nur dreifache (Nakamitsu 1994). Der Sicherheitsabzug betrifft die Dauer: Das Herzzeitvolumen steigt um bis zu 80 Prozent – bei Herzschwäche, niedrigem Blutdruck oder unter Diuretika ist stundenlange Immersion nichts zum Selbstausprobieren.' },
  { id: 'stehschreibtisch', view: 'tipps', evidenz: 7, mechanismus: 5, sicherheit: 9, hype: 6, anwendung: 8, richtung: 'gemischt',
    beleg: 'Die Datenlage ist gut, das Ergebnis aber ein anderes als der Verkaufsprospekt: In der bisher größten Arbeit mit Handgelenk-Messgerät (Ahmadi 2024, 83.013 Erwachsene, im Mittel 6,9 Jahre Nachbeobachtung) fand sich über den gesamten gemessenen Bereich kein Zusammenhang zwischen Stehen und schweren Herz-Kreislauf-Ereignissen. Was sich zeigte, war der Schaden des Sitzens: oberhalb von zehn Stunden am Tag stieg das Risiko je weiterer Stunde um 15 Prozent. Für das Stehen selbst gab es einen anderen Befund – 2.042 orthostatische Ereignisse, und oberhalb von rund zwei Stunden Stehen am Tag stieg das Risiko für Venenleiden. Der Hype-Abzug betrifft genau diese Verschiebung: Der Tisch wirkt, indem er Sitzzeit ersetzt, nicht indem er Stehzeit schafft.' },
  { id: 'blutdruck-zielwert', view: 'tipps', evidenz: 9, mechanismus: 8, sicherheit: 6, hype: 3, anwendung: 9, richtung: 'positiv',
    beleg: 'SPRINT (NEJM 2015) randomisierte 9.361 Menschen mit erhöhtem kardiovaskulärem Risiko, aber ohne Diabetes, auf einen systolischen Zielwert unter 120 gegenüber unter 140 mmHg. Der primäre Endpunkt lag bei 1,65 gegen 2,19 Prozent pro Jahr (HR 0,75), die Gesamtsterblichkeit 27 Prozent niedriger (HR 0,73) – die Studie wurde nach median 3,26 Jahren vorzeitig beendet. Der Sicherheitsabzug ist real und steht im selben Abstract: Hypotonie, Synkopen, Elektrolytstörungen und akutes Nierenversagen traten häufiger auf; Stürze mit Verletzung nicht. Entscheidend für die Übertragung nach Hause ist die Messmethode: SPRINT maß mit einem festgelegten Oberarmautomaten nach Protokoll. Derselbe Zahlenwert entsteht am Küchentisch anders.' },
  { id: 'ballaststoffe', view: 'tipps', evidenz: 9, mechanismus: 8, sicherheit: 10, hype: 2, anwendung: 10, richtung: 'positiv',
    beleg: 'So gut belegt, wie Ernährungsforschung es hergibt: Die Auswertung von Reynolds (Lancet 2019) fasst 185 prospektive Kohortenstudien mit zusammen 135 Millionen Personenjahren und 58 randomisierte Studien mit 4.635 Erwachsenen zusammen. Höchste gegen niedrigste Aufnahme bedeutete 15 bis 30 Prozent niedrigere Gesamt- und Herz-Kreislauf-Sterblichkeit und 16 bis 24 Prozent weniger koronare Herzkrankheit, Schlaganfall, Typ-2-Diabetes und Darmkrebs; absolut 13 Todesfälle weniger je tausend Menschen. Die größte Risikominderung lag bei 25 bis 29 Gramm am Tag. Zwei Einschränkungen bleiben: Der Hauptteil ist Beobachtung, die randomisierten Studien reichen nur bis zu Risikofaktoren – und gemessen wurde an Lebensmitteln, nicht an Pulver.' },
  // ---------- Supplements ----------
  { id: 'mikronaehrstoff-konzentrate', view: 'supplement', evidenz: 9, mechanismus: 6, sicherheit: 8, hype: 8, anwendung: 9, richtung: 'negativ',
    beleg: 'Die hohe Evidenzzahl beruht auf Studien zu klassischen Multivitaminen – die Konzentrate liefern ihre Vitaminmenge ebenfalls aus zugesetzten Reinstoffen, sind als Produkte aber kaum untersucht. Für Multivitamine gilt: 21 randomisierte Studien mit 91.074 Menschen ergaben eine Gesamtsterblichkeit von RR 0,98, die Physicians\' Health Study II fand über elf Jahre keinen Herz-Kreislauf-Effekt, COSMOS mit 21.442 Teilnehmern keinen Effekt auf Krebs, Herz-Kreislauf oder Sterblichkeit. Der einzige belastbare Pluspunkt ist ein kleiner Kognitionsvorteil in drei COSMOS-Unterstudien (0,07 Standardabweichungen) — sekundärer Endpunkt, und die Physicians\' Health Study fand dort exakt null. Die Anbieterstudien tragen nichts bei: die LaVita-Evidenz ist eine Studie mit 159 Teilnehmern in sechs Publikationen, bei der von 48 gemessenen Laborwerten 20 veröffentlicht wurden und 3 für das Produkt sprachen (Cochrane Österreich); eine randomisierte Crossover-Studie der TU München zu einem Regulatpro-Produkt fand bei 31 auswertbaren Menschen mit Typ-2-Diabetes keinen Effekt auf den HbA1c (Lee 2016, PMID 27343205). Hohe Anwendungserfahrung, weil Multivitamine seit Jahrzehnten breit genommen werden — ein Wirksamkeitsbeleg ist das nicht.' },
  { id: 'kreatin', view: 'supplement', evidenz: 9, mechanismus: 8, sicherheit: 9, hype: 8, anwendung: 9, richtung: 'positiv',
    beleg: 'Eines der am besten untersuchten Supplements überhaupt: zahlreiche RCTs und Meta-Analysen zu Kraft und Magermasse, der Phosphokreatin-Weg ist am Menschen messbar, Sicherheitsdaten reichen über Jahre. Abzug beim Hype-Abstand nur, weil die kognitiven Versprechen über die Daten hinausgehen.' },
  { id: 'omega-3', view: 'supplement', evidenz: 8, mechanismus: 8, sicherheit: 9, hype: 6, anwendung: 10, richtung: 'gemischt',
    beleg: 'Grosse randomisierte Studien (u.a. VITAL, REDUCE-IT, STRENGTH) mit harten Endpunkten liegen vor – ihre Ergebnisse widersprechen sich allerdings teils. Mechanismus und Sicherheit sind gut untersucht; beworben wird deutlich mehr, als die Studien hergeben.' },
  { id: 'vitamin-d3', view: 'supplement', evidenz: 8, mechanismus: 9, sicherheit: 9, hype: 5, anwendung: 10, richtung: 'gemischt',
    beleg: 'Die Rezeptorbiologie ist ausgezeichnet verstanden und mit VITAL und Vergleichbarem gibt es große RCTs. Der Hype-Abstand ist der schlechteste Wert: Vitamin D wird für nahezu jede Erkrankung beworben, die Studien zeigen das nicht.' },
  { id: 'magnesium', view: 'supplement', evidenz: 7, mechanismus: 8, sicherheit: 9, hype: 6, anwendung: 10, richtung: 'positiv',
    beleg: 'Als Kofaktor hunderter Enzyme biochemisch sehr gut belegt, mit soliden Studien zu Blutdruck und Schlafqualität, aber wenige große Endpunktstudien. Sicherheit gut untersucht; die Vermarktung einzelner Salzformen geht über die Vergleichsdaten hinaus.' },
  { id: 'vitamin-k2', view: 'supplement', evidenz: 6, mechanismus: 8, sicherheit: 8, hype: 3, anwendung: 8, richtung: 'gemischt',
    beleg: 'Die Wirkkette über Osteocalcin und Matrix-Gla-Protein ist am Menschen quantifiziert: MK-7 senkt dp-ucMGP um rund 50 Prozent. Die randomisierten Studien zu den eigentlichen Endpunkten sind dagegen uneinheitlich — AVADEC mit 365 Männern und 720 µg MK-7 über 24 Monate verfehlte den primären Endpunkt, VitaK-CAC mit 180 Patienten fand 2026 einen Unterschied im Koronarkalk. Die alten japanischen Frakturdaten stammen aus MK-4 im Milligrammbereich und mussten 2020 wegen Integritätszweifeln korrigiert werden. Die Vermarktung als Pflichtpartner zu Vitamin D3 geht über die Daten hinaus; eine EU-Angabe zu Herz und Gefäßen existiert nicht.' },
  { id: 'zink', view: 'supplement', evidenz: 7, mechanismus: 8, sicherheit: 8, hype: 6, anwendung: 10, richtung: 'positiv',
    beleg: 'Bei Mangel und bei Erkältungsdauer gibt es kontrollierte Studien und Meta-Analysen, die Immunfunktion ist mechanistisch klar. Überdosierung stört den Kupferhaushalt – das steht selten in der Werbung.' },
  { id: 'taurin', view: 'supplement', evidenz: 6, mechanismus: 7, sicherheit: 8, hype: 3, anwendung: 9, richtung: 'gemischt',
    beleg: 'Zum Blutdruck liegen mehrere RCTs und zwei unabhängige Meta-Analysen mit gleicher Richtung vor: rund 3 mmHg im Mittel über 7 Studien mit 103 Teilnehmern, 7,2 gegenüber 2,6 mmHg systolisch in einer doppelblinden Studie an 120 Prähypertonikern über 12 Wochen, -4,38 mmHg in einer Meta-Analyse über 34 RCTs. Alles Surrogatmarker, keine harten Endpunkte, Laufzeiten von Wochen bis Monaten. Bei Herzinsuffizienz bleiben nach der Rücknahme einer Arbeit im Jahr 2026 zwei kleine kontrollierte Studien mit 29 und 17 Patienten. Der Mechanismus ist am Menschen an einem Punkt bestätigt: biallelische Verlustvarianten im Taurintransporter SLC6A6 verursachen eine früh beginnende Netzhautdystrophie bei im Mittel 31,7 µmol/l niedrigerem Plasmataurin. Die Longevity-Zahl von 10 bis 12 Prozent stammt aus Mäusen mittleren Alters; bei den Affen wurden über 6 Monate nur Gesundheitsmarker gemessen. Die Prämisse des Taurinabfalls im Alter wurde 2025 zweimal geprüft und nicht bestätigt, deshalb liegt hype bei 3. Sicherheit bleibt 8: kontrollierte Daten über Monate, EFSA- und VKM-Bewertung, aber keine Langzeitdaten aus Zulassung und Pharmakovigilanz.' },
  { id: 'koffein', view: 'supplement', evidenz: 9, mechanismus: 9, sicherheit: 8, hype: 7, anwendung: 10, richtung: 'positiv',
    beleg: 'Der Adenosin-Antagonismus ist am Menschen quantifiziert, zu Leistung, Wachheit und Kaffeekonsum existieren große Kohorten und viele RCTs. Abzug bei der Sicherheit für die Datenlage zu hohen Dosen und Kombipräparaten.' },
  { id: 'kollagen', view: 'supplement', evidenz: 5, mechanismus: 5, sicherheit: 9, hype: 4, anwendung: 8, richtung: 'gemischt',
    beleg: 'Es gibt RCTs zu Hautfeuchtigkeit und Gelenkbeschwerden, sie sind aber klein und überwiegend herstellerfinanziert. Der Mechanismus bleibt umstritten, weil Kollagen wie jedes Protein verdaut wird. Sehr stark beworben.' },
  { id: 'whey', view: 'supplement', evidenz: 8, mechanismus: 8, sicherheit: 9, hype: 7, anwendung: 9, richtung: 'positiv',
    beleg: 'Zur Muskelproteinsynthese und zum Kraftzuwachs liegen viele RCTs und Meta-Analysen vor, Leucin als Auslöser ist am Menschen gut belegt. Der übliche Überzug betrifft Timing-Versprechen, die die Daten nicht stützen.' },
  { id: 'nmn', view: 'supplement', evidenz: 5, mechanismus: 6, sicherheit: 5, hype: 2, anwendung: 5, richtung: 'gemischt',
    berichtslage: { stufe: 1, kurz: 'Viel berichtet, aber nichts Greifbares', was: 'Berichtet wird viel, aber fast durchweg unspezifisch: mehr Energie, besseres Wohlbefinden. Genau das ist die Kategorie von Beobachtung, die sich von Erwartung, Jahreszeit und Tagesform nicht trennen lässt. Die Berichte sind zahlreich und trotzdem schwach.', quellen: 'Anwenderkreise' },
    beleg: 'Am Menschen gibt es inzwischen 15 kleine randomisierte Studien über 2 bis 24 Wochen; eine Meta-Analyse (Yang 2026) findet keine Effekte auf Gewicht, Blutzucker, Blutfette oder Blutdruck, eine weitere keinen auf die Muskelfunktion. Endpunktdaten fehlen; der NAD-Weg ist plausibel, die Anhebung im Gewebe aber schwach belegt. Sicherheitsdaten nur kurzfristig – und kaum ein Longevity-Produkt wird stärker überhöht.' },
  { id: 'spermidin', view: 'supplement', evidenz: 5, mechanismus: 6, sicherheit: 6, hype: 3, anwendung: 6, richtung: 'gemischt',
    beleg: 'Mehrere randomisierte, doppelblinde Studien liegen vor, darunter SmartAge mit 100 Teilnehmern über 12 Monate – deren primärer Gedächtnisendpunkt wurde verfehlt. Die übrigen Humanstudien sind klein, kurz und messen Surrogatmarker; Autophagie wurde am Menschen einmal gemessen, in B-Zellen einer Pilotstudie mit 40 Teilnehmern. Der Mechanismus ist im Tiermodell kausal geprüft, die Kohortendaten zur Sterblichkeit sind robust und repliziert. Pharmakokinetisch heben selbst 15 und 40 mg täglich den Spermidinspiegel im Blut nicht. Als neuartiges Lebensmittel ist Weizenkeimextrakt in der EU seit 2017/2018 zugelassen, Höchstmenge 6 mg pro Tag; gesundheitsbezogene Werbeaussagen sind nicht zugelassen. Beworben wird es trotzdem als Fasten-Ersatz zum Schlucken.' },
  { id: 'berberin', view: 'supplement', evidenz: 6, mechanismus: 6, sicherheit: 5, hype: 3, anwendung: 6, richtung: 'gemischt',
    beleg: 'Die Wirkung auf Surrogatmarker ist real und mehrfach repliziert, der Rahmen um sie herum trägt die bisherige Bewertung aber nicht mehr. evidenz bleibt 6: Es liegen viele randomisierte Studien vor (Lan et al., J Ethnopharmacol 2015, PMID 25498346: 27 RCTs, 2.569 Patienten; Ju et al., Phytomedicine 2018, PMID 30466986: 16 Studien, 2.147 Teilnehmer; Shadin et al., PLoS One 2026, PMID 42213651: über 30 Studien, über 2.000 Teilnehmer), aber alle drei Meta-Analysen stufen die Qualität der eingeschlossenen Arbeiten als niedrig ein, die Effekte sind gepoolt klein (HbA1c −0,19 Prozentpunkte, Nüchternglukose −0,71 mmol/l) und Endpunktdaten fehlen vollständig (Seo & Woo, Int J Mol Sci 2026, PMID 42653115: „Berberine improves glycemic surrogates but lacks cardiovascular or renal outcome evidence"). Die methodisch beste Arbeit, Chen et al., Lancet Gastroenterol Hepatol 2020, PMID 31926918, hat ihren primären Endpunkt erreicht (Adenomrezidiv 36 Prozent gegenüber 47 Prozent, relatives Risiko 0,77; 1.108 randomisiert) — prüft aber eine Anwendung, für die Berberin nicht beworben wird. mechanismus von 7 auf 6: Die Zielstruktur ist am Menschen nicht bestätigt. Die orale Bioverfügbarkeit liegt bei 0,68 Prozent (Ratte), beim Menschen werden nur niedrige Nanogramm-pro-Milliliter-Plasmaspiegel erreicht (Dumitru et al., Pharmaceuticals 2026, PMID 42653808), und die im euglykämischen Clamp gemessene Glukose-Aufnahmerate unterschied sich im Gruppenvergleich gegen Placebo nicht signifikant (Zhang et al., J Clin Endocrinol Metab 2008, PMID 18397984, P = 0,063). Der Lipidmechanismus über die Stabilisierung der LDL-Rezeptor-mRNA ist dagegen sauber beschrieben (Kong et al., Nature Medicine 2004, PMID 15531889). sicherheit von 6 auf 5: Chen 2020 liefert zwar kontrollierte Daten über bis zu zwei Jahre an mehr als 1.000 Menschen, das EFSA-NDA-Panel kam im am 29. Januar 2026 gebilligten Entwurf aber zu dem Schluss, dass die Daten für keine der 13 geprüften berberinhaltigen Pflanzenzubereitungen eine sichere Aufnahmemenge zulassen, und stuft die Genotoxizitätsfrage als offen ein. hype von 4 auf 3: Der Beiname „pflanzliches Ozempic" hat keine Vergleichsdaten hinter sich — eine randomisierte Studie gegen einen GLP-1-Rezeptoragonisten ließ sich nicht finden —, während der Markt stark wächst (96 Millionen US-Dollar Umsatz in den USA in 12 Monaten, plus 39 Prozent; Holland & Barrett plus 167 Prozent) und die Substanz in der EU in Nahrungsergänzungsmitteln nicht verwendet werden darf. anwendung von 7 auf 6: berberinhaltige Pflanzen werden seit Jahrhunderten eingesetzt, in der EU aber ohne regulatorischen Rahmen, mit nationalen Obergrenzen, die sich um mehr als eine Größenordnung unterscheiden, und ohne zugelassenes Arzneimittel in Deutschland. richtung von positiv auf gemischt: belegte Wirkung auf Surrogatmarker bei durchgehend niedriger Studienqualität, fast vollständiger regionaler Konzentration (Yin 2008, Zhang 2008 und Chen 2020 alle in China; Lan und Dong stützen sich zusätzlich auf CBM, CNKI und Wanfang), fehlenden Endpunktdaten und einer Sicherheitsbewertung, die keine sichere Aufnahmemenge ergeben hat. Der Bestandssatz „Pflanzenstoff, fast so wirksam wie Metformin bei Blutzucker" ruht allein auf einer Pilotstudie mit 36 Teilnehmern (Yin et al., Metabolism 2008, PMID 18442638) ohne Nichtunterlegenheitstest; die beiden Meta-Analysen zum Direktvergleich finden keinen statistisch signifikanten Unterschied zu oralen Antidiabetika, was ein fehlender Nachweis eines Unterschieds ist und kein Nachweis der Gleichwertigkeit.' },
  { id: 'ashwagandha', view: 'supplement', evidenz: 5, mechanismus: 4, sicherheit: 5, hype: 4, anwendung: 8, richtung: 'gemischt',
    beleg: 'Es gibt mehrere RCTs zu Stress und Cortisol, meist klein, kurz und herstellernah. Der Mechanismus bleibt vage. Wichtiger Punkt für die Sicherheits-Datenlage: Meldungen über Leberschäden haben mehrere Behörden beschäftigt.' },
  { id: 'melatonin', view: 'supplement', evidenz: 7, mechanismus: 9, sicherheit: 7, hype: 6, anwendung: 9, richtung: 'positiv',
    beleg: 'Die circadiane Wirkkette ist am Menschen quantifiziert, zu Einschlafzeit und Jetlag gibt es Meta-Analysen. Langzeitdaten fehlen weitgehend, und die in Deutschland üblichen Dosierungen liegen deutlich über dem, was die Studien nutzen.' },
  { id: 'urolithin-a', view: 'supplement', evidenz: 5, mechanismus: 7, sicherheit: 7, hype: 4, anwendung: 4, richtung: 'gemischt',
    beleg: 'Die Mitophagie-Wirkkette ist beim Menschen mit Biomarkern belegt: In der ersten Humanstudie (Nature Metabolism 2019) veränderte Urolithin A nach 4 Wochen die Mitochondrien-Genexpression im Muskel. Zwei randomisierte, placebokontrollierte Studien über 4 Monate – 66 Menschen zwischen 65 und 90 Jahren (JAMA Network Open 2022) und 88 Mittelalte (Cell Reports Medicine 2022) – zeigten bessere Muskelausdauer beziehungsweise rund 12 % mehr Beinkraft und niedrigeres CRP, verfehlten aber beide ihre Hauptzielgröße; beide wurden vom Hersteller Amazentis finanziert. Bei trainierten Läufern verbesserte sich die Leistung nicht. Nach Granatapfelsaft bildeten nur rund 40 % der Menschen nennenswert Urolithin A – das kommt in der Werbung selten vor.' },
  { id: 'coq10', view: 'supplement', evidenz: 7, mechanismus: 8, sicherheit: 8, hype: 5, anwendung: 9, richtung: 'gemischt',
    beleg: 'Die Rolle in der Atmungskette ist gesichert und die Blutspiegel steigen nach Einnahme zuverlässig. Klinisch tragen vor allem Q-SYMBIO (420 Patienten, 2 Jahre, 15 % vs. 26 % beim kombinierten Endpunkt) und der Cochrane-Review, der Sterblichkeit und Klinikaufenthalte als Evidenz moderater Qualität einstuft, das Sterblichkeitsergebnis aber aus dieser einen Studie zieht und ohne überzeugende Gesamtevidenz schließt. Migräneprophylaxe und Spermienparameter sind in Meta-Analysen positiv. Bei Gesunden bleibt der Leistungsnachweis aus, beim Blutdruck widersprechen sich die Auswertungen, und bei Statin-Muskelbeschwerden steht eine knapp signifikante Meta-Analyse gegen das strengste Einzel-RCT.' },
  { id: 'resveratrol', view: 'supplement', evidenz: 2, mechanismus: 5, sicherheit: 7, hype: 1, anwendung: 7, richtung: 'negativ',
    berichtslage: { stufe: 1, kurz: 'Kaum jemand berichtet etwas Spürbares', was: 'Trotz zwanzig Jahren Schlagzeilen und breiter Anwendung berichtet kaum jemand einen spürbaren Effekt. Das ist kein Widerspruch: Ein Stoff, der über Jahrzehnte wirken soll, müsste sich kurzfristig auch nicht bemerkbar machen. Es heisst aber, dass die Berichtslage hier nichts beiträgt — weder dafür noch dagegen. Wer Resveratrol nimmt, tut das auf Grundlage von Erzählungen über Mechanismen, nicht auf Grundlage eigener Beobachtung.', quellen: 'Anwenderkreise' },
    beleg: 'Das Lehrstück der Longevity-Szene: zwanzig Jahre Schlagzeilen, ein Milliardendeal – und am Menschen bis heute keine belastbaren Wirknachweise, dazu Zweifel an zentralen Sirtuin-Arbeiten. Bioverfügbarkeit gering. Der größte Hype-Abstand im ganzen Bestand.' },

  { id: 'vitamin-c', view: 'supplement', evidenz: 8, mechanismus: 8, sicherheit: 9, hype: 4, anwendung: 10, richtung: 'gemischt',
    beleg: 'Sehr gut untersucht – und genau deshalb fällt die Lücke auf: Der Cochrane-Review (Hemilä & Chalker, CD000980) wertet 29 Studienvergleiche mit 11.306 Teilnehmern aus und findet in der Allgemeinbevölkerung (10.708 Teilnehmer) keine Senkung der Erkältungshäufigkeit (RR 0,97; 0,94–1,00); nur bei extremer körperlicher Belastung – Marathon, Skilauf, Militär – halbiert sich das Risiko (5 Studien, 598 Teilnehmer, RR 0,48). Die Dauereinnahme verkürzt die Erkältungsdauer bei Erwachsenen um rund 8 Prozent und senkt die Schwere um 15 Prozent; der Beginn erst bei Symptomen zeigt über 7 Vergleiche und 3.249 Episoden keinen konsistenten Effekt. Skorbutprävention und Kollagensynthese sind zweifelsfrei belegt; ein Immun-Booster für alle ist es nicht.' },
  { id: 'vitamin-b12', view: 'supplement', evidenz: 8, mechanismus: 9, sicherheit: 9, hype: 3, anwendung: 10, richtung: 'gemischt',
    beleg: 'Bei nachgewiesenem Mangel gehört B12 zu den am besten begründeten Substanzen überhaupt – bei Normalversorgten kippt das Bild. Eine Meta-Analyse über 16 RCTs mit 6.276 Teilnehmern ohne manifesten Mangel (Markun et al., Nutrients 2021, PMID 33809274) fand weder einen Effekt auf Kognition noch auf Depressionsmaße; zur Müdigkeit, dem häufigsten Kaufgrund, hatte nur eine einzige dieser Studien überhaupt Daten. Die Cochrane-Übersicht zu kognitiv gesunden Erwachsenen (CD011906) kommt im B-Vitamin-Arm über 14 Studien mit 27.882 Teilnehmern zum selben Ergebnis, und die Cochrane-Übersicht zu Menschen mit Demenz und niedrigem Serum-B12 (CD004326, Malouf und Areosa Sastre) fand ebenfalls keinen signifikanten Effekt. Homocystein sinkt zuverlässig, aber über 71.422 Teilnehmer zeigt Cochrane (CD006612) kein weniger an Herzinfarkten und keine niedrigere Sterblichkeit. Die Biochemie ist lückenlos verstanden, Sicherheitsdaten reichen über Jahrzehnte. Beworben wird B12 als Energie-Vitamin für jeden – gezeigt ist die Wirkung nur dort, wo etwas fehlt.' },
  { id: 'vitamin-b-komplex', view: 'supplement', evidenz: 8, mechanismus: 8, sicherheit: 8, hype: 4, anwendung: 9, richtung: 'gemischt',
    beleg: 'Evidenz 8, weil große Studien mit harten Endpunkten vorliegen, überwiegend mit klarem Ergebnis: Die Cochrane-Übersicht über 15 RCTs mit 71.422 Teilnehmern (2017) findet keinen Effekt auf Herzinfarkt (RR 1,02) und Sterblichkeit (RR 1,01), aber weniger Schlaganfälle (RR 0,90; 4,3 gegenüber 5,1 Prozent), bei hoher Evidenzqualität. Eine Auswertung der Einzeldaten von 22.000 Teilnehmern aus 11 Studien (Clarke, Am J Clin Nutr 2014) zeigt keinen Effekt auf kognitives Altern. Positiv sind VITACOG (Hirnatrophie 0,76 gegenüber 1,08 Prozent pro Jahr, 168 Auswertbare) und ein kleiner Stresseffekt (SMD 0,23; Young 2019). Die Meta-Analyse in Nutrition Reviews (Wang 2022, online 2021) umfasst 95 Studien mit 46.175 Teilnehmern, davon 25 RCTs; der Folat-Demenz-Zusammenhang (HR 0,61) stammt aus Kohorten zur Ernährung, nicht aus Intervention. Mechanismus 8, weil die Homocysteinsenkung am Menschen quantifiziert ist (26 bis 28 Prozent), die Kette zu Herz und Kognition aber nicht trägt. Sicherheit 8: Nebenwirkungsdaten aus RCTs über bis zu 7,3 Jahre und behördliche Obergrenzen; hochdosiertes B6 hat ein dokumentiertes Neuropathie-Risiko, die EFSA senkte den UL 2023 auf 12 mg, das BfR schlug 2024 0,9 mg pro Tagesdosis in Nahrungsergänzungen vor.' },
  { id: 'eisen', view: 'supplement', evidenz: 9, mechanismus: 9, sicherheit: 9, hype: 5, anwendung: 10, richtung: 'gemischt',
    beleg: 'Für die Anwendung bei Mangel ist die Datenlage außergewöhnlich: Eisen ist in Deutschland als Arzneimittel gegen Eisenmangel zugelassen, und der Cochrane-Review über 57 randomisierte Studien mit 48.971 Frauen senkt die Eisenmangelanämie am Geburtstermin von 18,4 auf 5,0 %. Für den Eisenmangel ohne Anämie zeigt die Übersicht von Houston et al. (BMJ Open 2018, 18 RCTs, 1.170 Patienten) einen Effekt auf selbstberichtete Erschöpfung von SMD −0,38 (95 % KI −0,52 bis −0,23), aber keinen auf die maximale Sauerstoffaufnahme (SMD 0,11; −0,15 bis 0,37). Sauerstofftransport und Hepcidin-Regelkreis sind am Menschen mit Isotopen quantifiziert, die Sicherheit aus Jahrzehnten Arzneimittelanwendung bekannt – einschließlich der Überladung bei Hämochromatose. Der kritische Punkt bleibt die Diagnostik: Ohne Ferritin-Wert eingenommen, fehlt der Wirkung die Grundlage und das Risiko bleibt; zusätzlich verdeckt Ferritin als Akutphaseprotein bei Entzündung einen leeren Speicher. Korrektur am Bestand: Der frühere Beleg nannte „Houston et al., Br J Nutr“ mit 6 RCTs, 6 Querschnittsstudien, 1.875 Teilnehmern und einem Effekt von 0,33 (0,17–0,48). Eine solche Arbeit war nicht auffindbar; Zeitschrift, Studienzahl, Teilnehmerzahl und Effektgröße waren falsch.' },
  { id: 'selen', view: 'supplement', evidenz: 9, mechanismus: 8, sicherheit: 9, hype: 3, anwendung: 9, richtung: 'gemischt', berichtslage: { stufe: 2, kurz: 'Viele berichten Haut, Nägel, Energie', was: 'Auch hier wird viel Positives berichtet: Haut, Nägel, Schilddrüse, Energie. Diese Berichte stehen neben einer der größten je durchgeführten Präventionsstudien, die den beworbenen Nutzen nicht bestätigt hat. Genau diese Kombination ist der Grund, warum Berichtslage und Evidenz bei uns getrennt stehen – die eine ersetzt die andere nicht, in keine Richtung.', quellen: 'Anwenderkreise · Praxisberichte' },
    beleg: 'Einer der klarsten Fälle im Bestand. Die SELECT-Studie (Lippman et al., JAMA 2009, PMID 19066370) randomisierte 35.533 Männer auf den harten Endpunkt Prostatakrebs; nach median 5,46 Jahren lag das Hazard Ratio bei 1,04 (99 % KI 0,87 bis 1,24), der Endpunkt wurde verfehlt. Der Cochrane-Review 2018 (PMID 29376219) kommt über die Studien mit geringem Verzerrungsrisiko auf ein relatives Risiko von 1,01 für die Krebsinzidenz insgesamt, mit hoher Vertrauenswürdigkeit. Dazu zwei Schadenssignale aus denselben Studien: In der NPC-Nachauswertung (Stranges et al., Ann Intern Med 2007, PMID 17620655) traten unter 200 µg täglich über im Mittel 7,7 Jahre 58 gegenüber 39 Typ-2-Diabetesfälle auf (HR 1,55; 95 % KI 1,03 bis 2,33), im obersten Terzil des Ausgangswerts HR 2,70. Und bei Männern oberhalb des 60. Perzentils des Zehennagel-Selens erhöhte Selengabe die hochgradigen Prostatakarzinome um 91 % (Kristal et al., JNCI 2014, PMID 24563519). Wichtig für die Einordnung: SELECT hat nicht geprüft, ob Selen bei Mangel nützt. Unterhalb des 60. Perzentils blieb die Gabe wirkungslos, und der Schutzeffekt der Vorgängerstudie NPC beschränkte sich auf Plasmawerte unter 123,2 ng/ml (Duffield-Lillico et al., BJU Int 2003, PMID 12699469). Geprüft wurde also, ob mehr Selen bei ausreichender Versorgung nützt - nicht, ob Selen bei Mangel nützt. Die Rolle als Kofaktor der Glutathionperoxidase und als Bestandteil der Deiodasen ist unbestritten; der Sprung von dort zur Krebsprävention wurde widerlegt. Nicht widerlegt ist die Substanz insgesamt: Bei milder endokriner Orbitopathie erreichte ein RCT an 159 Patienten beide primären Endpunkte (Marcocci et al., NEJM 2011, PMID 21591944), bei Hashimoto sinken die TPO-Antikörper konsistent über 23 Studien (PMID 33774780) - das TSH allerdings nicht, und bei neu diagnostiziertem Morbus Basedow blieb eine Studie an 430 Patienten ohne Effekt (PMID 41384622). Deshalb gemischt statt negativ. EFSA aktualisierte 2023 die Obergrenze auf 255 µg/Tag, das BfR 2024 die Höchstmengen auf 40 µg je Tagesverzehrempfehlung. Beworben wird weiterhin Krebsschutz.' },
  { id: 'jod', view: 'supplement', evidenz: 9, mechanismus: 9, sicherheit: 9, hype: 4, anwendung: 10, richtung: 'gemischt',
    beleg: 'Die Schilddrüsenhormonsynthese ist am Menschen vollständig aufgeklärt, und Kaliumiodid ist in Deutschland als Arzneimittel gegen die Jodmangelstruma zugelassen – beim Mangel ist die Frage entschieden. Für milde Unterversorgung wird es dünn: Eine Dosis-Wirkungs-Meta-Analyse aus acht Kohorten fand für suboptimalen mütterlichen Jodstatus ein gepooltes Hedges g von minus 0,13 bei 95,2 Prozent Heterogenität, in der kognitiven Domäne minus 0,22 (Luo et al., Nutrients 2026, PMID 42124075); der randomisierte Test mit 832 Schwangeren verfehlte seinen primären Endpunkt (PMID 29030199). Die Schadensseite ist ebenso gut belegt wie der Nutzen: In der chinesischen Fünfjahreskohorte stieg die kumulative Inzidenz der subklinischen Hypothyreose von 0,2 auf 2,9 Prozent und die der Autoimmunthyreoiditis von 0,2 auf 1,3 Prozent (PMID 16807415). Das BfR empfiehlt für Nahrungsergänzungsmittel höchstens 100 µg täglich, und ein Tropfen Lugolscher Lösung enthält über 6.000 µg bei einer europäischen Obergrenze von 600 µg – Über- wie Unterversorgung stören dasselbe Organ.' },
  { id: 'mct-oel', view: 'supplement', evidenz: 6, mechanismus: 8, sicherheit: 7, hype: 4, anwendung: 7, richtung: 'gemischt',
    beleg: 'Dass MCT beim Menschen Ketone erzeugt, ist gut vermessen, reine Caprylsäure am stärksten (Curr Dev Nutr 2017); per PET wurde bei MCI eine 2,5- bis 3,2-fach höhere Ketonaufnahme im Gehirn gezeigt (BENEFIC-Bildgebung 2021). Klinisch: die 6-monatige RCT BENEFIC (39 vs. 44 Teilnehmer) mit Verbesserungen in mehreren kognitiven Tests, eine RCT bei Alzheimer mit 152 Patienten (Vorteil vor allem ohne APOE4) und zwei positive Meta-Analysen (Ageing Res Rev 2020; J Alzheimers Dis 2023), alle klein und kurz. Beim Gewicht -0,51 kg in 13 RCTs mit Hinweis auf kommerziellen Bias. Für Gesunde gibt es kleine, widersprüchliche RCTs (30 junge Gesunde positiv, 80 Ältere ohne Effekt), für Ausdauerleistung keinen Nutzen. Dosisabhängige Magen-Darm-Beschwerden sind gut dokumentiert.' },
  { id: 'l-theanin', view: 'supplement', evidenz: 7, mechanismus: 5, sicherheit: 6, hype: 5, anwendung: 6, richtung: 'gemischt',
    beleg: 'Für ein Nootropikum ungewöhnlich breite Datenbasis: Eine Meta-Analyse über 31 RCTs mit 1.168 Teilnehmern (Molecular Psychiatry 2026) findet nach 200 Milligramm Einzeldosis eine Verbesserung der Wahlreaktionszeit von SMD 0,51, zwei weitere Meta-Analysen (Nutrition Reviews 2025, Journal of Clinical Medicine 2025) zeigen in dieselbe Richtung. Der Stresseffekt (SMD 0,31) wird überwiegend von Studien mit hohem Bias-Risiko getragen, Angst und Müdigkeit bleiben inkonsistent. Das Mischungsverhältnis mit Koffein wurde nie gegen ein anderes getestet: jede Studie stellte genau ein Dosispaar gegen Placebo, und die EFSA führte den Aufmerksamkeitseffekt von Schwarztee 2018 allein auf das Koffein zurück. Die GABA-Erzählung stammt aus Tierdaten, die Alpha-Wellen im EEG sind ein Surrogat. Die Effekte sind real, aber kleiner und kürzer gemessen als beworben.' },
  { id: 'glycin', view: 'supplement', evidenz: 5, mechanismus: 6, sicherheit: 6, hype: 4, anwendung: 8, richtung: 'gemischt', berichtslage: { stufe: 2, kurz: 'Schneller eingeschlafen, schon am Abend', was: 'Berichtet wird übereinstimmend ein schnelleres Einschlafen bei etwa drei Gramm vor dem Zubettgehen – ein akuter, am selben Abend bemerkbarer Effekt. Er deckt sich mit kleinen publizierten Schlafstudien, die genau das gemessen haben. Die Berichte stehen hier also nicht allein, sondern neben Daten in dieselbe Richtung.', quellen: 'Anwenderkreise · deckungsgleich mit kleinen publizierten Schlafstudien' },
    beleg: 'Zum beworbenen Schlafeffekt gibt es genau drei kleine Humanstudien mit 3 Gramm vor dem Zubettgehen. Eine systematische Übersicht (GeroScience 2024, 47 Artikel mit 50 Studien über 11 Organsysteme) stuft sie als Arbeiten mit kleinen Stichproben und hohem Verzerrungsrisiko ein und hält fest, dass von allen 50 Studien nur zwei ein niedriges Verzerrungsrisiko hatten – beide an Kranken, keine an Gesunden. Objektiv gemessen wurde nur einmal: verkürzte Einschlafzeit und Tiefschlaflatenz in einer Polysomnographie mit je 11 Teilnehmern über 2 Nächte. Größere Schlafstudien existieren nicht; ein Scoping Review (Journal of Dietary Supplements 2026) fordert sie erst. Der Effekt ist also nicht widerlegt, sondern nie geprüft. Der Mechanismus über die Körperkerntemperatur stammt aus Rattenversuchen und läuft dort über NMDA-Rezeptoren im Nucleus suprachiasmaticus, nicht über den hemmenden Glycinrezeptor – die verbreitete GABA-Analogie trifft den falschen Rezeptor. Die Glutathion-Erzählung hat ihren größten Test verloren: 114 gesunde Ältere, zwei Wochen Glycin plus N-Acetylcystein in drei Dosen, primärer Endpunkt Glutathion verfehlt. Jenseits davon ist Glycin gut untersucht, nur an anderer Stelle: Meta-Analyse über 40 randomisierte Studien mit 4.937 Patienten als Zusatz zu Antipsychotika, kontrollierte Gaben über Monate bei Kranken, dazu jahrzehntelange Verwendung als Lebensmittelzusatzstoff E 640. Im Tiermodell verlängerte ein Futter mit 8 Prozent Glycin die Lebensspanne von Mäusen um 4 bis 6 Prozent.' },
  { id: 'acetyl-l-carnitin', view: 'supplement', evidenz: 6, mechanismus: 7, sicherheit: 8, hype: 3, anwendung: 7, richtung: 'gemischt', berichtslage: { stufe: 1, kurz: 'Berichte gehen auseinander', was: 'Die Berichte sind auffällig uneinheitlich: Ein Teil beschreibt mehr geistige Frische, ein ebenso grosser Teil gar nichts. Bei einem Stoff, der als Wachmacher für den Kopf verkauft wird, ist diese Streuung selbst die Aussage — und sie deckt sich mit dem Cochrane-Befund für Gesunde.', quellen: 'Anwenderkreise' },
    beleg: 'Die Rolle im Fettsäuretransport und als Acetylgruppenspender ist biochemisch gesichert, ALCAR erreicht nach Einnahme den Liquor. Klinisch am stärksten: zwei Meta-Analysen zu depressiven Symptomen (Psychosom Med 2018: 12 RCTs, 791 Teilnehmer, SMD -1,10; bestätigt 2026 mit 809 Teilnehmern), allerdings mit kleinen, sehr heterogenen Einzelstudien. Bei diabetischen Nervenschmerzen findet Cochrane (2019) einen Vorteil bei sehr niedriger Evidenzsicherheit und Herstellernähe, bei MCI und früher Alzheimer-Demenz einen kleinen Effekt (0,201). Der Cochrane-Review für Gesunde (2017) ist kein Negativbefund: Er fand nur zwei schwache Studien und zieht ausdrücklich keine Schlussfolgerung. Dagegen steht ein belegter Schaden: In SWOG S0715 (409 Frauen) verstärkte ALCAR die Taxan-Neuropathie über 2 Jahre.' },
  { id: 'tyrosin', view: 'supplement', evidenz: 6, mechanismus: 7, sicherheit: 5, hype: 4, anwendung: 6, richtung: 'gemischt',
    beleg: 'Evidenz 6, weil mehrere kleine doppelblinde RCTs funktionelle Endpunkte unter akutem Stress zeigen – Arbeitsgedächtnis in Kälte (19 Personen, Mahoney 2007), Wachsamkeit nach Schlafentzug (Neri 1995), Kampftraining (21 Kadetten, Deijen 1999) – und eine Bewertung über 10 RCTs und 4 kontrollierte Studien dafür eine schwache Empfehlung gibt (Attipoe 2015); alle Studien sind klein und akut. Mechanismus bleibt 7: Tyrosin hebt den Noradrenalin-Umsatz am Menschen messbar an (MHPG-Ausscheidung, Gelenberg 1990), die Wirkung folgt einer umgekehrten U-Kurve (Jongkees 2020). Sicherheit bleibt 5: nur Kurzzeitdaten bis 4 Wochen und 4 g pro Tag bei 30 Männern, herstellerfinanziert (Matsumoto 2026); MAO-Hemmer-Warnung in der Phenelzin-Fachinformation. Richtung gemischt statt offen, weil der Nutzen für Kognition unter Belastung konsistent ist, eine Meta-Analyse über 8 Studien aber keinen Effekt auf Ausdauer findet (Solon-Júnior 2023) und Tyrosin bei 65 depressiven Patienten nicht wirkte (Gelenberg 1990).' },
  { id: 'aminosaeuren', view: 'supplement', evidenz: 6, mechanismus: 8, sicherheit: 8, hype: 5, anwendung: 9, richtung: 'gemischt',
    beleg: 'Leucin und essenzielle Aminosäuren als Auslöser der Muskelproteinsynthese sind mit Isotopenstudien am Menschen bestätigt, und zusätzliches Protein verstärkt den Effekt von Krafttraining (Meta-Analyse über 49 RCTs mit 1.863 Teilnehmern, kein Zusatznutzen über 1,62 g/kg). Der Sprung vom isolierten Präparat zu mehr Muskelmasse ist es nicht: Eine Meta-Analyse über 9 placebokontrollierte Studien bei über 65-Jährigen (PLOS ONE 2014, überwiegend Whey, daneben Leucin und EAA) fand keinen signifikanten Effekt auf die fettfreie Masse (0,34 kg, P = 0,386) oder die Beinkraft. Isolierte BCAA steigern die Proteinsynthese akut (+22 % in 10 trainierten Männern), liefern aber nur drei der neun Bausteine. Der wiederkehrende Befund: Bei ausreichender Gesamtproteinzufuhr bringt das isolierte Präparat wenig zusätzlich.' },
  { id: '5-htp', view: 'supplement', evidenz: 5, mechanismus: 6, sicherheit: 4, hype: 3, anwendung: 6, richtung: 'gemischt', berichtslage: { stufe: 2, kurz: 'Schneller Schlaf, sehr lebhafte Träume', was: 'Übereinstimmend berichtet werden schnelleres Einschlafen und auffällig lebhafte Träume, meist schon in der ersten Nacht. Der akute Zeitverlauf passt zum Mechanismus als direkte Serotonin-Vorstufe. Ebenso regelmäßig berichtet wird die Kehrseite: Übelkeit und, bei gleichzeitiger Einnahme serotonerger Medikamente, Warnzeichen bis hin zum Serotoninsyndrom.', quellen: 'Anwenderkreise' },
    beleg: 'Die Biochemie ist am Menschen gezeigt: 5-HTP passiert die Blut-Hirn-Schranke (PET, 8 Gesunde, 6 Patienten, Acta Psychiatr Scand 1991) und hebt Serum-5-HTP und Serum-Serotonin in randomisierten Studien deutlich an (Gastroenterology 2022; Clin Nutr 2024). Klinisch ist das Bild gemischt. Für Depression findet der Cochrane-Review unter 108 Studien nur 2 mit 64 Patienten von ausreichender Qualität (Peto OR 4,10; 95 % KI 1,28–13,15), eine Meta-Analyse (Nutr Rev 2020) kommt über 7 Studien auf Hedges g 1,11 bei I² 76 % und wenigen Placebogruppen. Neuere Studien sind klein: 30 ältere Erwachsene, 12 Wochen, einfach verblindet, besserer Schlafscore nur bei schlechten Schläfern. Das größte moderne Placebo-RCT (166 Patienten, 2 × 8 Wochen) verfehlte seinen primären Endpunkt Müdigkeit (35,6 vs. 37,6 Prozent) trotz steigender Serotoninwerte, ein akutes RCT mit 112 Teilnehmern fand keinen Effekt auf Ablenkbarkeit. Die Serotoninmangel-Theorie der Depression stützt ein Umbrella-Review über 17 Arbeiten nicht (Mol Psychiatry 2023). Sicherheitsseitig nur Kurzzeitdaten; die EMS-Frage nach dem L-Tryptophan-Ausbruch 1989 ist laut Cochrane ungeklärt, dokumentiert sind ein Familienfall mit verunreinigtem Präparat und das Risiko serotonerger Kombinationen.' },
  { id: 'rhodiola', view: 'supplement', evidenz: 6, mechanismus: 4, sicherheit: 5, hype: 3, anwendung: 8, richtung: 'gemischt', berichtslage: { stufe: 2, kurz: 'Gegen Erschöpfung, binnen Stunden', was: 'Übereinstimmend berichtet wird ein am selben Tag spürbarer Effekt gegen Erschöpfung, oft binnen ein bis zwei Stunden. Die kurze Latenz spricht gegen einen reinen Erwartungseffekt über Wochen. Sie ersetzt aber keine Kontrolle: Müdigkeit schwankt ohnehin stark, und niemand vergleicht sich mit sich selbst ohne Einnahme.', quellen: 'Anwenderkreise' },
    beleg: 'Die Datenlage ist breiter, als der alte Eintrag annahm – und struktureller schwächer. Breiter: Eine Meta-Analyse von 2025 über 26 RCTs mit 668 Teilnehmern findet konsistente, kleine Effekte auf die Ausdauer (VO2max ES 0,32, Zeit bis zur Erschöpfung ES 0,38, Zeitfahrleistung ES -0,40), 24 der 26 Studien mit gutem PEDro-Wert. Schwächer: Die placebokontrollierten Erschöpfungsstudien – Darbinyan 2000 (n = 56), Spasov 2000 (n = 40), Shevtsov 2003 (n = 161), Olsson 2009 (n = 60), Darbinyan 2007 (n = 89) – verwenden fast alle denselben Extrakt SHR-5, bei dreien ist ein Wissenschaftler des Herstellerinstituts Mitautor. Die zweite Präparatefamilie WS 1375 (Edwards 2012, Kasper und Dienel 2017, Lekomtseva 2017, Koop 2020) wurde ausschließlich offen und einarmig geprüft. Der unabhängige Review von Hung, Perry und Ernst 2011 nennt genau das: „lack of independent replications“. Ishaque 2012 fasst 11 Studien mit 446 Teilnehmern zusammen, keine erfüllt CONSORT. Die EMA hat im März 2024 festgehalten, dass die Evidenz für eine klinische Wirksamkeit bei Erschöpfung nicht ausreicht und „well-established use“ deshalb nicht akzeptiert werden kann; wegen fehlender Genotoxizitätsdaten kam auch kein EU-Listeneintrag zustande. Ein Cochrane-Review existiert nicht. Die Bewertung „evidence: hoch“ ist damit nicht haltbar und wird auf „mittel“ korrigiert. Dazu kommt ein Qualitätsproblem der Handelsware: etwa ein Fünftel von rund 40 europäischen Produkten ohne Rosavin, fast 60 % von 13 Produkten ohne deklarierte Menge oder Marker, Rosavine zwischen 0,01 % und 3,08 % auf dem US-Markt.' },
  { id: 'ginseng', view: 'supplement', evidenz: 6, mechanismus: 5, sicherheit: 6, hype: 4, anwendung: 9, richtung: 'gemischt',
    beleg: 'Mehrere Meta-Analysen randomisierter Studien, aber klein, kurz und methodisch oft schwach (Umbrella-Review 2023: von 19 Meta-Analysen 5 schwach, 14 kritisch schwach). Gedächtnis: Zeng et al., Phytother Res 2024, 15 RCTs mit 671 Teilnehmenden inklusive Gesunder, SMD 0,19; keine Effekte auf Aufmerksamkeit und exekutive Funktionen. Bei kognitiver Beeinträchtigung: Kim et al., Complement Med Res 2025, 8 RCTs, MMSE +0,68, ADAS-Cog −1,10. Kleine Crossover-Studien zeigen akute Effekte auf geistige Erschöpfung auch bei Gesunden (Reay 2005, 30 Teilnehmende). Erektionsstörung (Cochrane 2021, 9 Studien, 587 Männer): Effekt auf den IIEF geringfügig, selbst berichtete Fähigkeit zum Geschlechtsverkehr RR 2,55. Nüchternblutzucker −0,31 mmol/l (16 Studien). Für sportliche Leistung überwiegend kein Nutzen (NCCIH). Mechanismus: akute Blutzuckersenkung am Menschen gemessen, neuroprotektive Effekte nur aus Zellkultur und Tier. Sicherheit: Kurzzeitdaten gut, Nebenwirkungen in RCTs ähnlich häufig wie unter Placebo (Coon und Ernst 2002); Warfarin-Interaktion durch einen Fallbericht und eine Pharmakokinetik-Studie gestützt. Anwendung: traditionelles pflanzliches Arzneimittel in der EU (EMA 2024).' },
  { id: 'loewenmaehne', view: 'supplement', evidenz: 2, mechanismus: 3, sicherheit: 3, hype: 2, anwendung: 6, richtung: 'offen',
    berichtslage: { stufe: 2, kurz: 'Fokus – oder emotionale Abflachung', was: 'Die Berichte gehen in beide Richtungen, und beide Seiten sind verbreitet. Positiv: Konzentration, Wortfindung, Nervenregeneration nach mehreren Wochen. Negativ: eine hartnäckige Häufung von Berichten über emotionale Abflachung und Libidoverlust, die teils nach dem Absetzen anhalten soll. Bemerkenswert ist, dass diese zweite Gruppe in der publizierten Literatur nicht auftaucht – eine systematische Übersicht von 2025 listet als Nebenwirkungen Magenbeschwerden, Kopfschmerz und allergische Reaktionen, die berichtete Abflachung dagegen nicht. Das macht die Berichte nicht falsch; es heißt, dass bisher niemand danach gesucht hat.', quellen: 'Anwenderkreise · systematische Übersicht Frontiers in Nutrition 2025 (Nebenwirkungsteil)' },
    beleg: 'Die Neurogenese-Erzählung ist der eigentliche Befund: Die NGF-Stimulation ist in Zellkultur und Tier gut dokumentiert, am Menschen wurde sie nie gemessen. Die beste Humanstudie ist eine randomisierte Pilotstudie mit 41 gesunden Erwachsenen über 28 Tage (Nutrients 2023) – die schnellere Reaktion im Stroop-Test (p = 0,005) wurde 60 Minuten nach einer Einzeldosis gemessen, nach 28 Tagen blieb nur ein nicht signifikanter Stress-Trend (p = 0,051), dazu Nullbefunde und einzelne leicht negative Ergebnisse. Die Autoren mahnen selbst zur Vorsicht. Über Wochen hinaus gibt es keine Sicherheitsdaten.' },
  { id: 'reishi', view: 'supplement', evidenz: 5, mechanismus: 4, sicherheit: 5, hype: 2, anwendung: 7, richtung: 'gemischt',
    beleg: 'Es gibt mehrere kleine RCTs mit gemischtem Ergebnis. Positiv: Bei Neurasthenie besserten sich unter einem Reishi-Extrakt 51,6 gegenüber 24,6 Prozent der Patienten mehr als minimal (132 Patienten, 8 Wochen, J Med Food 2005). Der Cochrane-Review zur Krebsbegleitung (Jin et al., CD007731, 5 RCTs) findet leicht erhöhte CD3-, CD4- und CD8-Anteile und in 4 Studien bessere Lebensqualität; das Tumoransprechen mit Chemo- oder Strahlentherapie (RR 1,50; 95 % KI 0,90–2,51) ist nicht eindeutig, Überlebensdaten fehlen, die Studienqualität ist unbefriedigend. Negativ: Für kardiovaskuläre Risikofaktoren (Cochrane CD007259, 5 Studien, 398 Teilnehmer; RCT mit 84 Teilnehmern, 16 Wochen) kein Effekt auf HbA1c, Blutfette oder Blutdruck; eine Meta-Analyse über 17 RCTs mit 971 Teilnehmern (Food Sci Nutr 2025) findet keinen Effekt auf Entzündungsmarker, Leberenzyme und Glukose, GRADE sehr niedrig. Für Schlaf gibt es nur Tierdaten. Sicherheitsseitig kontrollierte Daten bis 24 Wochen, ein RCT an 40 Gesunden ohne Gerinnungsveränderung und die LiverTox-Einstufung als mögliche seltene Ursache von Leberschäden; Blutungs-Fallberichte unter Gerinnungshemmern ließen sich nicht finden.' },
  { id: 'cordyceps', view: 'supplement', evidenz: 5, mechanismus: 4, sicherheit: 4, hype: 3, anwendung: 7, richtung: 'gemischt',
    beleg: 'Die Ausdauerdaten sind klein, aber konsistent genug für ein vorsichtiges Plus: Ein systematisches Review (Shu et al., Front Nutr 2025) wertete 14 RCTs mit 528 Sportlern zu Speisepilzen aus; für Cordyceps sinensis (4 RCTs, 2 bis 12 Wochen) zeigten gepoolte Daten aus je 2 bis 3 Studien Verbesserungen von Ausdauer (P = 0,05), ventilatorischer Schwelle (P = 0,03) und VO2peak (P = 0,04). Die oft zitierten 8 Studien mit 288 Sportlern betreffen alle Pilzarten zusammen. Bei 22 trainierten Radfahrern (5 Wochen) kein Effekt (Parcell 2004), bei 20 gesunden Älteren metabolische Schwelle +10,5 Prozent ohne Änderung der VO2max (Chen 2010). Für das Immunsystem gibt es Humandaten auf Surrogatebene: zwei RCTs mit je 79 Gesunden mit höherer NK-Zell-Aktivität (Kang 2015; Jung 2019). Bei chronischer Nierenerkrankung findet Cochrane über 22 Studien mit 1.746 Teilnehmern bessere Kreatininwerte, bei hohem oder unklarem Verzerrungsrisiko in allen Studien. Für ATP am Menschen, Libido und Anti-Aging gibt es keine Humandaten. Die Präparate sind taxonomisch uneinheitlich, Nebenwirkungen wurden nur in 3 Sportstudien überhaupt berichtet.' },
  { id: 'bacopa', view: 'supplement', evidenz: 6, mechanismus: 6, sicherheit: 6, hype: 5, anwendung: 7, richtung: 'positiv',
    beleg: 'Eines der wenigen Nootropika mit mehreren Meta-Analysen. Die größte, eine Netzwerk-Meta-Analyse von 2026 über 29 RCTs mit 2107 gesunden Erwachsenen, findet einen Vorteil beim Arbeitsgedächtnis gegenüber Placebo (SMD 2,03; 95 % KI 1,28–2,78) und ausdrücklich keinen bei Aufmerksamkeit und Verarbeitungsgeschwindigkeit. Damit reproduziert sie den Geschwindigkeitsbefund der älteren Meta-Analyse von Kongkeaw (9 RCTs, 518 Teilnehmer: Trail B −17,9 ms, Wahlreaktionszeit 10,6 ms, beide p < 0,001) nicht. Was über die Arbeiten hinweg hält, ist eine einzige Domäne: Gedächtnis, genauer der freie und verzögerte Abruf (Pase 2012: 9 von 17 Tests). Der Effekt braucht rund zwölf Wochen, auf Testebene wiederholt sich wenig, und ein Gutteil der positiven Studien kommt aus Australien, teils von derselben Gruppe mit demselben Extrakt. Die Acetylcholinesterase-Hemmung ist am Menschen im Plasma gemessen; Langzeitdaten fehlen.' },
  { id: 'kurkuma', view: 'supplement', evidenz: 6, mechanismus: 5, sicherheit: 7, hype: 3, anwendung: 9, richtung: 'gemischt',
    beleg: 'Bei Kniearthrose zeigen mehrere Meta-Analysen eine moderate Schmerzreduktion in der Größenordnung von NSAR bei kurzer Anwendung – eine Netzwerk-Meta-Analyse über 23 Studien mit 2.175 Patienten fand -1,63 auf der Schmerzskala und -18,85 im WOMAC-Gesamtscore, und eine Studie mit 367 Patienten Nichtunterlegenheit gegenüber Ibuprofen. Die Qualität dahinter ist schwach: Eine kritische Durchsicht stufte 37 von 48 Endpunkten als von sehr niedriger Evidenzqualität ein, und die EMA erkennt für Curcuma longa nur die traditionelle Anwendung an, keinen well established use. Für Krebsprävention, Anti-Aging und die behauptete Leber-Entgiftung fehlt Vergleichbares; einen Endpunkt Entgiftung prüft keine Studie. Der Mechanismus hat ein Bioverfügbarkeitsproblem: Viele Zellkulturbefunde beruhen auf Konzentrationen, die oral nicht erreicht werden; am Menschen sind immerhin CRP und TNF-alpha gesenkt. Sicherheitsseitig gut dokumentiert: Die DILIN-Fallserie (Am J Med 2023) beschreibt 10 Fälle curcumininduzierter Leberschädigung, davon ein Todesfall; 7 von 10 trugen HLA-B*35:01. Das BfR stellte in der Stellungnahme Nr. 040/2021 vom 14. Dezember 2021 fest, dass geprüfte Präparate mit 8,3 und 6,1 mg Curcumin pro Kilogramm Körpergewicht deutlich über dem ADI von 3 mg/kg lagen.' },
  { id: 'astaxanthin', view: 'supplement', evidenz: 6, mechanismus: 5, sicherheit: 6, hype: 3, anwendung: 7, richtung: 'gemischt',
    beleg: 'Mehrere Meta-Analysen, aber durchweg auf Surrogatmarkern und über Wochen. Haut: 8 gepoolte RCTs mit 162 gegenüber 131 Teilnehmern zeigen Feuchtigkeit SMD 0,53 (p = 0,03) und Elastizität SMD 0,77 (p = 0,009), die Faltentiefe dagegen nicht (SMD -0,26; p = 0,11; I² = 0 %). Belastung: 24 RCTs senken die Kreatinkinase (SMD -0,45), lassen maximale Sauerstoffaufnahme, Zeitfahrleistung und maximale Arbeitslast aber unverändert — der Bestandsnutzen „Verbessert Ausdauer“ ist damit widerlegt, belegt ist die Regeneration. Stoffwechsel: 9 RCTs mit 403 Patienten senken Nüchternblutzucker und LDL. Sicherheit auf 6 angehoben, weil die EFSA 2020 eine vollständige Novel-Food-Bewertung mit einem Tagesrichtwert von 0,2 mg pro kg Körpergewicht vorgelegt hat und die EU altersgestaffelte Höchstmengen festgelegt hat. Hype auf 3 gesenkt: Die Vergleichszahlen zu Vitamin C und Vitamin E stammen aus einem zellfreien Singulett-Sauerstoff-Assay (Astaxanthin 5,4 gegenüber L-Ascorbinsäure 0,00089), die Quelle nennt selbst keinen Vielfachen-Faktor, und für die beworbenen Endpunkte Falten, Ausdauer und Blaulichtschutz fehlt der Beleg; die EFSA hat 15 gesundheitsbezogene Angaben abgelehnt.' },
  { id: 'glutathion', view: 'supplement', evidenz: 5, mechanismus: 5, sicherheit: 6, hype: 3, anwendung: 7, richtung: 'gemischt', berichtslage: { stufe: 2, kurz: 'Intravenös hellt es die Haut auf', was: 'Hier ist zu trennen. Oral berichtete Wirkungen sind unspezifisch und wenig aussagekräftig. Für die intravenöse Anwendung dagegen gibt es einen sehr spezifischen, vielfach berichteten Effekt – eine Aufhellung der Haut –, der so verlässlich eintritt, dass Arzneimittelbehörden mehrerer Länder ausdrücklich davor gewarnt haben. Dass etwas passiert, ist damit belegt. Dass es erwünscht oder unbedenklich ist, nicht.', quellen: 'Anwenderkreise · Warnhinweise nationaler Arzneimittelbehörden' },
    beleg: 'Die Schwachstelle liegt vor der Wirkung: Orales Glutathion trifft im Darm auf die Gamma-Glutamyltransferase, und nach einer Einzeldosis stieg bei sieben Gesunden über 270 Minuten weder Glutathion noch Cystein noch Glutamat im Plasma an. Dagegen steht die längste Studie: sechs Monate, 54 Erwachsene, randomisiert und doppelblind, mit 30 bis 35 Prozent höheren Speichern in Erythrozyten, Plasma und Lymphozyten und 260 Prozent in Mundschleimhautzellen – berichtet gegenüber dem Ausgangswert. Eine vierwöchige randomisierte Studie an 40 Erwachsenen fand dagegen weder eine Veränderung der Oxidationsmarker noch des Glutathions selbst. Der Widerspruch ist nicht aufgelöst, und alle Endpunkte sind Ersatzwerte. Am konsistentesten ist der kleinste Befund: eine leichte Abnahme des Melanin-Index an sonnenexponierter Haut. Für Entgiftung, Immunstärkung und Anti-Aging fehlen belastbare Humandaten; Langzeitdaten über sechs Monate hinaus gibt es nicht. Die intravenöse Anwendung zur Hautaufhellung ist behördlich beanstandet.' },
  { id: 'alpha-liponsaeure', view: 'supplement', evidenz: 8, mechanismus: 6, sicherheit: 9, hype: 5, anwendung: 9, richtung: 'gemischt',
    beleg: 'Für eine eng umrissene Indikation gut belegt, für die beworbene kaum. Bei diabetischer Polyneuropathie zeigt eine Meta-Analyse über 10 RCTs mit 1.242 Patienten den Total Symptom Score um 1,69 Punkte besser als unter Placebo und die globale Zufriedenheit mit einem Odds Ratio von 2,48; Vibrationsempfinden, NIS-LL und Nervenleitgeschwindigkeit besserten sich nicht (Nutrients 2023). SYDNEY 2 (n = 181, 5 Wochen) erreichte seinen primären Endpunkt, ALADIN III (n = 509, 7 Monate, p = 0,447) und NATHAN 1 (n = 460, 4 Jahre, p = 0,105) verfehlten ihn; Mijnhout et al. 2012 lassen offen, ob die oralen Verbesserungen klinisch relevant sind, während die ältere Meta-Analyse über 4 IV-Studien mit 1.258 Patienten sie als relevant einstuft (Diabet Med 2004). Die Evidenz stammt durchgehend aus dem Racemat, nicht aus R-ALA. Für Stoffwechselgesunde als Antioxidans oder Anti-Aging-Mittel gibt es keine Endpunktdaten, für Insulinsensitivität (kein Effekt auf Insulin und HOMA-IR über 41 Arbeiten) und für nichtalkoholische Fettleber (7 RCTs, 414 Teilnehmer, kein Effekt) liegen Negativbefunde vor. Die Sicherheitsdatenlage ist dagegen ungewöhnlich gut: vierjährige kontrollierte Daten, europäische Pharmakovigilanz und eine eigene EFSA-Stellungnahme zum Insulin-Autoimmun-Syndrom.' },
  { id: 'quercetin', view: 'supplement', evidenz: 6, mechanismus: 6, sicherheit: 6, hype: 4, anwendung: 6, richtung: 'gemischt',
    beleg: 'Blutdruck ist das belastbarste Feld: Drei Meta-Analysen finden denselben Effekt in derselben Größenordnung – Serban et al. (J Am Heart Assoc 2016, 7 RCTs, 587 Patienten) 3,04 mmHg systolisch, Huang et al. (Nutr Rev 2020, 17 RCTs, 896 Teilnehmer) 3,09 mmHg, Popiolek-Kalisz & Fornal (Curr Probl Cardiol 2022, 10 RCTs, 841 Teilnehmer) 2,38 mmHg. Ab 500 mg täglich liegt der Effekt bei 4,45 mmHg, darunter bei 1,59 mmHg und ist nicht mehr signifikant; die Autoren betonen aber, dass der direkte Vergleich der Dosisgruppen keinen signifikanten Unterschied ergab. Im Sport ist der Effekt statistisch vorhanden und praktisch belanglos: Pelletier et al. (2013) finden bei Trainierten 0,09 % bei einer Streuung von 2,15 %. Die senolytische Erzählung trägt die Seite nicht: In allen fünf Humanstudien stand Quercetin neben dem verschreibungspflichtigen Dasatinib, die einzige Phase-2-Studie (Farr et al., Nat Med 2024, 60 Frauen) verfehlte ihren primären Endpunkt, und bei Alzheimer-Patienten war Quercetin im Liquor gar nicht nachweisbar. Regulatorisch ist die Lage eindeutig: In der Unionsliste der zugelassenen gesundheitsbezogenen Angaben (Verordnung (EU) Nr. 432/2012) kommt Quercetin nicht vor; die EFSA hat 2011 vier Angaben dazu geprüft (ID 1647, 1844, 1845, 1846), keine steht heute auf der Positivliste.' },
  { id: 'pqq', view: 'supplement', evidenz: 4, mechanismus: 4, sicherheit: 4, hype: 3, anwendung: 5, richtung: 'gemischt',
    beleg: 'Drei placebokontrollierte Studien mit reinem PQQ-Dinatriumsalz (J Am Nutr Assoc 2022 mit 64 Teilnehmern, Adv Exp Med Biol 2016 mit 41, Food Funct 2023) fanden mit 20 bis 21,5 mg über 12 Wochen Verbesserungen in Teilbereichen von Gedächtnis und Aufmerksamkeit; alle sind klein, zwei haben Herstellerautoren. Die 34-Personen-Studie (J Nutr Health Aging 2024) testete ein Kombinationspräparat und verfehlte den primären Endpunkt im Gruppenvergleich. Die Mitochondrien-Neubildung ist in Zellkultur belegt; am Menschen stieg unter Training nur der Marker PGC-1α, die Leistung nicht (J Am Coll Nutr 2020). Die EFSA bewertete 20 mg pro Tag als sicher (Sicherheitsabstand 344), seit 2018 ist PQQ in der EU zugelassen; Langzeitdaten am Menschen fehlen.' },
  { id: 'probiotika', view: 'supplement', evidenz: 7, mechanismus: 7, sicherheit: 8, hype: 4, anwendung: 9, richtung: 'gemischt',
    beleg: 'Die Belege hängen am Stamm und an der Indikation, nicht an der Produktklasse. Gut abgesichert ist die Vorbeugung von Durchfall unter Antibiotika: 33 randomisierte Studien mit 6.352 Kindern, 8 gegenüber 19 Prozent, Number needed to treat 9; bei der Clostridioides-difficile-Diarrhö 31 Studien mit 8.672 Teilnehmern, 1,5 gegenüber 4,0 Prozent, der Nutzen aber nur bei einem Ausgangsrisiko über 5 Prozent und in einer nachträglichen Untergruppenanalyse. Die größte Einzelstudie, PLACIDE mit 1.470 und 1.471 ausgewerteten Klinikpatienten ab 65 Jahren, verfehlte beide primären Endpunkte. Derselbe Stamm wirkt nicht in jeder Indikation: Lactobacillus rhamnosus GG blieb beim akuten Magen-Darm-Infekt von 971 Kindern ohne Effekt. Für die Haut tragen die Daten nicht (39 Studien, 2.599 Teilnehmer, kein Unterschied bei patientenbewerteten Ekzemsymptomen), bei der Stimmung widersprechen sich die Meta-Analysen. Am Menschen ist die Zielstruktur bestätigt, aber individuell: Die Besiedlung der Schleimhaut ist person-, darmabschnitts- und stammspezifisch und am Stuhl nicht ablesbar; nach Antibiotika verzögerte ein mehrstämmiges Präparat die Rückkehr der angestammten Flora. Sicherheitsseitig ist die Datenlage breit: mehrere tausend Teilnehmer in kontrollierten Studien über Monate, dazu eine systematische Sammlung von 93 Infektionsfällen zwischen 1976 und 2018 mit einer Gesamtsterblichkeit von 19,6 Prozent und eine FDA-Warnung von 2023. Betroffen waren überwiegend schwerkranke Klinikpatienten an den Altersrändern, 33 Fälle über 60 Jahre und 25 unter einem Jahr — nicht überwiegend Immunsupprimierte; HIV, Immunsuppressiva und Organtransplantation waren in dieser Auswertung gerade nicht mit dem Tod assoziiert.' },
  { id: 'elektrolyte', view: 'supplement', evidenz: 7, mechanismus: 9, sicherheit: 8, hype: 5, anwendung: 9, richtung: 'gemischt',
    beleg: 'Der Natrium-Glukose-Kotransport zur Flüssigkeitsresorption ist etablierte Humanphysiologie, keine Marketing-Erzählung – der Nutzen ist aber an eine Bedingung geknüpft. Systematische Reviews zur Rehydration zeigen den Vorteil gegenüber reinem Wasser bei relevantem Schweißverlust, also Hitze oder Ausdauerbelastung über 60 bis 90 Minuten. Für normal aktive Menschen ohne solchen Verlust gibt es keine Evidenz für einen Zusatznutzen gegenüber Essen und Trinken. Gut dokumentiert sind sowohl die Hyponatriämie bei Ausdauersportlern als auch die Risiken bei eingeschränkter Nierenfunktion.' },
  { id: 'nac', view: 'supplement', evidenz: 8, mechanismus: 8, sicherheit: 9, hype: 4, anwendung: 10, richtung: 'gemischt',
    beleg: 'Zwei Welten in einem Eintrag, und die Trennlinie verläuft entlang des Rechtsstatus. NAC ist in Deutschland kein Nahrungsergänzungsmittel, sondern ein zugelassenes Arzneimittel: oral als Schleimlöser apothekenpflichtig und rezeptfrei, als Antidot verschreibungspflichtig. Die Zulassungsindikation ist der Maßstab, und sie ist ungewöhnlich gut vermessen: In der Auswertung des nationalen US-Multicenterprogramms (Smilkstein et al., N Engl J Med 1988, PMID 3059186) entwickelten von 2.540 oral behandelten Patienten 6,1 % der Risikopatienten eine Leberschädigung bei Behandlungsbeginn innerhalb von 10 Stunden, 26,4 % bei Beginn nach 10 bis 24 Stunden und 41 % bei Hochrisikopatienten nach 16 bis 24 Stunden; 11 Patienten starben. Das ist eine am Menschen quantifizierte Wirkkette, deshalb mechanismus 8 statt 7 - allerdings nur für diese Indikation. Bei COPD liegt eine Meta-Analyse über 14 RCTs mit 2.856 Patienten vor (Cai et al., PeerJ 2026, PMID 42473447): RR 0,87 (95 % KI 0,79 bis 0,96) für akute Exazerbationen, ohne Verbesserung von FEV1, FVC, Lebensqualität und Glutathionspiegel. PANTHEON (Zheng et al., Lancet Respir Med 2014, PMID 24621680) erreichte mit 1.006 Patienten den primären Endpunkt (1,16 gegenüber 1,49 Exazerbationen je Patientenjahr, RR 0,78), BRONCUS (Decramer et al., Lancet 2005, PMID 15866309) verfehlte mit 523 Patienten über drei Jahre beide primären Endpunkte, und eine Studie an 968 Patienten mit leichter bis mittelschwerer COPD (Zhou et al., Nat Commun 2024, PMID 39349461) verfehlte beide koprimären Endpunkte. Die Nationale VersorgungsLeitlinie COPD gibt deshalb nur eine offene Empfehlung (Empfehlung 5-8) und hält fest, dass für den Einsatz in der Akutsituation keine Evidenz vorliegt. Die Psychiatrie-Zahl aus dem Bestand stimmt (Peng et al., Gen Hosp Psychiatry 2024, PMID 39504621: 12 RCTs, 904 Patienten, SMD −0,24), bleibt aber klein; bei Zwangsstörung beruht die Meta-Analyse auf 6 RCTs mit 195 Patienten und erreicht nur im Fenster von fünf bis acht Wochen p = 0,05 (PMID 39376972), und beim Suchtverlangen war die größte Studie mit 302 Erwachsenen negativ (PMID 28623823). evidenz auf 8: Zulassung für eine klar umrissene Indikation plus konsistente Meta-Analytik bei COPD, aber nur kleine und uneinheitliche Daten für die beworbenen Biohacking-Anwendungen. anwendung auf 10, weil der Stoff seit Jahrzehnten unter Zulassung in der Notfallmedizin und rezeptfrei in der Selbstmedikation eingesetzt wird. hype bleibt 4: Der beworbene Kern, die breite Anhebung des Glutathionspiegels bei Gesunden, ist am Menschen nicht gezeigt - 6.000 mg täglich über 28 Tage erhöhten das Glutathion im Gehirn nicht signifikant (Coles et al., J Clin Pharmacol 2018, PMID 28940353), und die COPD-Meta-Analyse fand keine Veränderung der Glutathionspiegel. Die orale Bioverfügbarkeit liegt bei 4,0 bis 9,1 % (Olsson et al., Eur J Clin Pharmacol 1988, PMID 3360052). Leberschutz gegen Alkohol ist nicht belegt: Bei schwerer Alkoholhepatitis verfehlte Prednisolon plus NAC bei 174 Patienten die Sechsmonatssterblichkeit (27 % gegenüber 38 %, p = 0,07; PMID 22070475), bei akutem Leberversagen ohne Paracetamol-Bezug wurde das Gesamtüberleben verfehlt (70 % gegenüber 66 %; PMID 19524577). Bei Fruchtbarkeit stuft Cochrane die Lebendgeburtenrate als sehr niedrig vertrauenswürdig ein, und nach Ausschluss der Studien mit hohem Verzerrungsrisiko bleibt nichts Signifikantes (PMID 35506389). Bei Lungenfibrose ist die Datenlage klar negativ (PMID 24836309). Deshalb gemischt statt positiv.' },
  { id: 'apigenin', view: 'supplement', evidenz: 1, mechanismus: 3, sicherheit: 2, hype: 1, anwendung: 4, richtung: 'offen',
    beleg: 'Für isoliertes Apigenin als Nahrungsergänzungsmittel wurde keine belastbare Humanevidenz gefunden. Was als Beleg zitiert wird, sind Studien zu Kamillenextrakt – der Apigenin enthält, aber auch vieles andere; ein kausaler Rückschluss auf die Einzelsubstanz ist daraus nicht möglich. Die GABA-A-Bindung stammt aus Rezeptorstudien der 1990er in Zellkultur und Tier. Systematische Sicherheitsdaten für die isolierte, hochdosierte Form existieren nicht, ebenso wenig eine Behördenbewertung.' },
  { id: 'fisetin', view: 'supplement', evidenz: 4, mechanismus: 4, sicherheit: 3, hype: 1, anwendung: 4, richtung: 'offen',
    beleg: 'Der Abstand zwischen Maus und Mensch ist hier der ganze Befund: Die senolytische Wirkung ist in Zellkultur und Maus dokumentiert (Yousefzadeh 2018), wurde im unabhängigen Interventions Testing Program aber nicht bestätigt – keine Lebensverlängerung, kein Rückgang von p16 in Niere, Gehirn und Leber (Harrison, GeroScience 2024). Am Menschen gibt es inzwischen mehrere kleine RCTs mit Surrogatmarkern: IL-8 gesenkt bei 37 Darmkrebspatienten (Farsad-Naeimi 2018), IL-6 und HOMA-IR bei 44 Männern mit Adipositas (Alipour 2026), bessere NIHSS-Werte bei spät lysierten Schlaganfallpatienten (Wang 2019). Die randomisierte Arthrose-Studie NCT04210986 mit 75 Teilnehmern fand über im Mittel 12 Monate keinen Unterschied bei Nebenwirkungen (28 gegenüber 33 Betroffene) und seneszenzassoziierten Entzündungsmarkern; die oft genannte ROPE-Studie (NCT04770064) wurde dagegen zurückgezogen. Dass orale Gabe seneszente Zellen beim Menschen reduziert, ist nicht gezeigt; AFFIRM an der Mayo Clinic läuft seit 2018. Die Sicherheitsdaten beschränken sich auf kurze, intermittierende Schemata.' },
  { id: 'sulforaphan', view: 'supplement', evidenz: 5, mechanismus: 7, sicherheit: 6, hype: 3, anwendung: 6, richtung: 'gemischt',
    beleg: 'Die Nrf2-Aktivierung ist am Menschen pharmakologisch belegt: In einer RCT mit 291 Teilnehmern stieg über 12 Wochen die Ausscheidung von Benzol-Konjugaten um 61 % (Cancer Prev Res 2014), eine Folgestudie mit 170 Teilnehmern zeigte eine Dosis-Wirkungs-Beziehung (Am J Clin Nutr 2019). Bei Autismus fand eine Meta-Analyse über 6 RCTs mit 333 Teilnehmern (2025) eine Reduktion der Social Responsiveness Scale nach 4 bis 5 Wochen (SMD −0,98) und 8 bis 10 Wochen (SMD −1,11), ab 18 Wochen nicht mehr signifikant. Für Krebsprävention gibt es am Menschen nur Biomarker, bei Prädiabetes wurde der primäre Endpunkt verfehlt (Nat Microbiol 2025). Unerwünschte Ereignisse waren nicht häufiger als unter Placebo, Schilddrüsenwerte blieben über 84 Tage unverändert.' },
  { id: 'pterostilben', view: 'supplement', evidenz: 4, mechanismus: 4, sicherheit: 4, hype: 2, anwendung: 4, richtung: 'gemischt',
    beleg: 'Evidenz 4 statt 2, weil eine randomisierte, doppelblinde, placebokontrollierte Studie mit 80 Erwachsenen über 6 bis 8 Wochen Surrogatmarker misst (Riche 2014: LDL +17,1 mg/dl, Blutdruck −7,8/−7,3 mmHg in hoher Dosis) und kleine Studien hinzukommen (Otsuka 2025: 30 Männer, 12 Wochen, microRNA; Senguttuvan 2025: 44 Patientinnen, primärer Endpunkt Ki-67 ohne Unterschied); klinische Endpunkte fehlen, und die größeren Studien (Dellinger 2017, 120 Ältere; Dellinger 2023, 111 Patienten mit Fettleber, Hauptendpunkt verfehlt) testen nur die Kombination mit Nicotinamid-Ribosid. Mechanismus bleibt 4: Sirtuin- und AMPK-Aktivierung aus Zell- und Tierversuchen, der Bioverfügbarkeitsvorteil (etwa 80 % gegenüber 20 %) nur an Ratten (Kapetanovic 2011). Sicherheit 4 statt 3: kontrollierte Kurzzeitdaten bis 12 Wochen ohne Auffälligkeiten bei Leber, Niere und Zucker (Riche 2013), aber LDL-Anstieg, Plättchenhemmung in vitro (Huang 2021) und CYP2C9-Hemmung in Lebermikrosomen (Albassam 2021). Richtung gemischt statt offen, weil der Blutdruck sank, das LDL aber stieg – das Gegenteil des kardiovaskulären Werbeversprechens. In der EU nicht zugelassenes neuartiges Lebensmittel.' },
  { id: 'alpha-gpc', view: 'supplement', evidenz: 5, mechanismus: 6, sicherheit: 7, hype: 2, anwendung: 6, richtung: 'gemischt',
    berichtslage: { stufe: 1, kurz: 'Etwas Antrieb, klarerer Kopf', was: 'In einer Umfrage aus Nootropika-Foren (2014, 15 Bewertungen für Alpha-GPC) lag Alpha-GPC im Mittel bei 5,1 von 10, gut einen Punkt über dem einfachen Cholinsalz, das der Umfrageautor als Maßstab für den Placeboeffekt nimmt. Gesucht werden vor allem Antrieb und ein klarerer Kopf; oft wird es als Begleiter von Racetamen gegen Kopfschmerz genommen. Die Richtung deckt sich mit kleinen Studien an Gesunden, belegt aber nichts: Selbstauskunft, keine Placebokontrolle, sehr kleine Zahl.', quellen: 'Nootropika-Umfrage Slate Star Codex 2014 (nicht begutachtet)' },
    beleg: 'Der auffälligste Widerspruch im Supplementbereich: Ein RCT mit 100 Patienten mit leichter kognitiver Beeinträchtigung (BMC Geriatrics 2024) zeigt über zwölf Wochen einen Vorteil im ADAS-Cog – gleichzeitig fand eine koreanische Kohortenstudie mit über zwölf Millionen Personen und neun Jahren Nachbeobachtung (JAMA Network Open 2021) bei Alpha-GPC-Nutzern ein um 46 Prozent erhöhtes Schlaganfallrisiko mit Dosis-Wirkungs-Trend. Das ist eine Beobachtungsstudie, Confounding nicht ausgeschlossen, und als Mechanismus wird TMAO diskutiert. In der Werbung kommt dieses Signal praktisch nie vor. Eine zweite koreanische Kohorte (J Prev Alzheimers Dis 2025, 508.107 Menschen mit leichter kognitiver Beeinträchtigung) fand weniger Übergänge in eine Demenz und im gematchten Vergleich kein erhöhtes Schlaganfallrisiko. Die behördlich angeordneten Placebostudien in Korea (48 Wochen, leichte kognitive Beeinträchtigung) verfehlten 2026 laut Presseberichten den Primärendpunkt, die Per-Protocol-Analyse war positiv (67,8 gegenüber 60,1 Prozent); eine Publikation fehlt. Die EFSA sah im Mai 2026 bei Alpha-GPC als neuartigem Lebensmittel keine Sicherheitsbedenken bei begrenzter Tagesmenge.' },
  { id: 'citicolin', view: 'supplement', evidenz: 7, mechanismus: 6, sicherheit: 8, hype: 3, anwendung: 7, richtung: 'gemischt', berichtslage: { stufe: 2, kurz: 'Nootropika-Kreise berichten klaren Kopf', was: 'In Nootropika-Kreisen wird übereinstimmend ein spürbar klarerer Kopf berichtet, oft schon nach Tagen. Die Berichte sind zahlreich und untereinander ähnlich. Sie stammen allerdings aus einem Umfeld, in dem fast nie einzeln und fast nie gegen Placebo getestet wird, und sie betreffen Gesunde — also genau die Gruppe, für die keine belastbare Evidenz vorliegt. Die grosse Schlaganfallstudie sagt nichts über diese Anwendung, weder dafür noch dagegen.', quellen: 'Anwenderkreise' },
    beleg: 'Ein Lehrstück darüber, was passiert, wenn eine große Studie kommt: Eine frühere gepoolte Analyse kleinerer RCTs sah Vorteile beim Schlaganfall, die ICTUS-Studie (Lancet 2012) randomisierte dann 2.298 Patienten und fand keinen Unterschied im globalen Erholungsendpunkt nach 90 Tagen (OR 1,03; 95 % KI 0,86–1,25). Für die Nootropika-Anwendung bei Gesunden gibt es einzelne kleine, herstellerfinanzierte RCTs mit positiven Nebenbefunden, etwa zum episodischen Gedächtnis bei 100 Älteren über 12 Wochen, deren Hauptzielgröße aber verfehlt wurde; die EFSA sah 2024 keinen ausreichenden Beleg für eine Gedächtniswirkung. Daher gemischt statt negativ: Gegen den Schlaganfall-Nutzen sprechen die Daten klar, zur Anwendung bei Gesunden sind sie dünn, aber nicht negativ. Die Verträglichkeit ist aus Jahrzehnten klinischer Studien gut bekannt.' },
  { id: 'phosphatidylserin', view: 'supplement', evidenz: 6, mechanismus: 4, sicherheit: 6, hype: 4, anwendung: 7, richtung: 'gemischt',
    beleg: 'Human-Evidenz 6 statt 5: Es gibt mehrere RCTs, darunter eine Multicenterstudie mit 494 Patienten über 6 Monate, aber mit uneinheitlichem Ergebnis je nach Quelle. Die Übersichtsarbeit (Kang & Cui 2022) fasst 9 Studien mit 961 Teilnehmern zusammen – nur 5 davon sind RCTs, der Rest Vorher-Nachher-Vergleiche ohne Kontrolle. Der Effekt auf das Gedächtnis zeigt sich bei älteren Erwachsenen mit bestehender kognitiver Beeinträchtigung, gemessen an Testscores; die überzeugenden Studien nutzten PS aus Rinderhirn, die größte Studie mit der heutigen Soja-Form (120 Personen) blieb ohne Effekt. Mechanismus: Die Wirkkette vom Membranphospholipid zur Kognition stammt aus Zell- und Tiermodellen; die gedämpfte ACTH- und Cortisol-Antwort unter Belastung ist am Menschen gemessen, aber nur an 9 und 10 Männern. Sicherheit 6 statt 5: kontrollierte Daten über 12 Wochen (Soja-PS bis 600 mg, 120 Personen) und 6 Monate (494 Patienten). Hype: Für Fokus und Gedächtnis gesunder, jüngerer Nutzer gibt es keine Kognitionsstudien, und für den beworbenen Schlafeffekt keine kontrollierte Studie mit PS allein.' },
  { id: 'ginkgo', view: 'supplement', evidenz: 9, mechanismus: 5, sicherheit: 9, hype: 3, anwendung: 10, richtung: 'gemischt', berichtslage: { stufe: 1, kurz: 'Viel angewendet, wenig Konkretes berichtet', was: 'Bemerkenswert ist hier, wie wenig berichtet wird, gemessen daran wie viele es nehmen. Die Aussagen bleiben vage — etwas wacher, etwas klarer. Bei einem Mittel, das seit Jahrzehnten millionenfach eingenommen wird, wäre ein spürbarer Effekt längst in Form konkreter Beobachtungen aufgetaucht. Das Ausbleiben spezifischer Berichte ist hier selbst die Information, und es passt zu dem, was die grosse Präventionsstudie gemessen hat.', quellen: 'Anwenderkreise' },
    beleg: 'Ginkgo ist eines der wenigen Mittel, bei denen die Kernfrage wirklich beantwortet ist — zweimal unabhängig. GEM (DeKosky et al., JAMA 2008) randomisierte 3.069 Personen ab 75 Jahren über median 6,1 Jahre; 523 Demenzfälle, 277 unter Ginkgo und 246 unter Placebo, Hazard Ratio 1,12. GuidAge (Vellas et al., Lancet Neurol 2012) prüfte 2.854 Personen ab 70 Jahren über 5 Jahre; 61 gegen 73 Alzheimer-Fälle, Hazard Ratio 0,84. Beide verfehlten ihren primären Endpunkt, und bei kognitiv Gesunden liegen die Effektgrößen bei null (Laws et al. 2012). Das trägt die Richtung aber nur zur Hälfte: Bei bestehender Demenz findet die Meta-Analyse von Tan et al. (2015) über 2.561 Patienten bei 240 Milligramm täglich eine Kognitionsdifferenz von -2,86 sowie Vorteile bei Alltagsfunktionen und Gesamteindruck, und die S3-Leitlinie Demenzen führt Ginkgo in Empfehlung 69 mit dem Grad schwach dafür bei 97 Prozent Konsens. Deshalb steht hier gemischt und nicht negativ. Die Sicherheitsdatenlage ist breit: eine Meta-Analyse von 18 RCTs mit 1.985 Erwachsenen findet keinen signifikanten Effekt auf Gerinnungsparameter, während in GEM von 24 hämorrhagischen Schlaganfällen 16 unter Ginkgo und 8 unter Placebo auftraten und die IARC den Extrakt 2016 in Gruppe 2B einstufte. Der Mechanismus bleibt am Menschen unvollständig: Die Senkung der Blutviskosität ist gemessen, eine Zunahme der Hirndurchblutung nicht. Rechtlich ist Ginkgo-Trockenextrakt in Deutschland Arzneimittel — das Bundesverwaltungsgericht stufte 2022 schon 100 Milligramm pro Tag als Funktionsarzneimittel ein.' },
  { id: 'beta-alanin', view: 'supplement', evidenz: 7, mechanismus: 9, sicherheit: 6, hype: 6, anwendung: 7, richtung: 'positiv',
    beleg: 'Selten ist die Wirkkette so sauber am Menschen belegt: Muskelbiopsien zeigen einen dosis- und zeitabhängigen Carnosinanstieg (Harris 2006: +64,2 % nach 4 Wochen mit 6,4 g; Hill 2007: +80,1 % nach 10 Wochen), die Ansprechrate liegt bei 99,3 %. Die Meta-Analyse von Saunders et al. 2017 (40 Studien, 1461 Teilnehmer) findet eine Effektstärke von 0,18, moderiert von der Belastungsdauer; Hobson et al. 2012 sehen den klarsten Effekt bei 60 bis 240 Sekunden, aber auch darüber noch einen Vorteil, unter 60 Sekunden keinen. Georgiou et al. 2024 bestätigen den Nutzen bei 4 bis 10 Minuten (ES 0,55). Bei wiederholten Sprints zeigt eine Meta-Analyse über 17 RCTs keinen Effekt. Sicherheit: Dolan et al. 2019 (101 Humanstudien) fanden nur die Parästhesie als Nebenwirkung; das BfR bewertet die Datenqualität 2026 dennoch als schlecht, weil Nebenwirkungen kaum systematisch erfasst wurden, fast nur junge Männer teilnahmen und Daten über 24 Wochen fehlen, und hält nur Einzeldosen unter 400 mg und unter 1,2 g pro Tag für unbedenklich. Anwendung: seit den ersten Humanstudien 2006 breit im Sport, regulatorisch uneinheitlich (Polen mit Höchstmenge, Frankreich als Arzneimittel gegen Hitzewallungen).' },
  { id: 'citrullin', view: 'supplement', evidenz: 6, mechanismus: 7, sicherheit: 5, hype: 4, anwendung: 8, richtung: 'gemischt',
    beleg: 'Human-Evidenz 6 statt 5: Die aktuellste Meta-Analyse (Nutrients 2026) wertet 30 RCTs mit 644 Teilnehmern und 138 Effektgrößen aus und findet einen Gesamteffekt auf die Trainingsleistung von g = 0,16 bei einer Evidenzsicherheit, die die Autoren selbst als niedrig bis sehr niedrig einstufen; eine zweite Meta-Analyse (8 Studien, 137 Personen) findet 6,4 % mehr Wiederholungen. Das sind mehrere kleine, uneinheitliche RCTs mit Leistungsendpunkten, nicht nur Surrogatmarker. Mechanismus: Dass Citrullin Plasma-Arginin stärker hebt als Arginin selbst und NO-abhängige Signale steigert, ist am Menschen bestätigt (20 Probanden); eine akute Gefäßerweiterung ließ sich bei 6 und 12 g dagegen nicht messen. Sicherheit: gut verträglich bis 15 g als Einzeldosis, kontrollierte Daten aber nur bis 17 Wochen. Hype: Beworben werden Pump, Blutdruck und Erektion; das Pump-Gefühl lag in der einzigen Messung nicht über Placebo, und eine Blutdruck-Meta-Analyse von 2019 mit großem Effekt wurde zurückgezogen. Anwendung: in Frankreich seit 1991 als Arzneimittel zugelassen, als Sportsupplement verbreitet.' },
  { id: 'gaba', view: 'supplement', evidenz: 4, mechanismus: 3, sicherheit: 4, hype: 2, anwendung: 6, richtung: 'offen', berichtslage: { stufe: 2, kurz: 'Entspannung in 30 Minuten – nur anders', was: 'Ein aufschlussreicher Fall: Viele berichten binnen 20 bis 30 Minuten Wärmegefühl, Kribbeln und Entspannung – spezifisch genug, um ernst genommen zu werden. Zugleich gilt als weitgehend gesichert, dass GABA die Blut-Hirn-Schranke kaum überwindet. Beides zusammen legt nahe, dass der berichtete Effekt real ist, aber anders zustande kommt als beworben – etwa über Rezeptoren im Darm. Die Berichte sagen hier: da passiert etwas. Nicht: die Erklärung stimmt.', quellen: 'Anwenderkreise' },
    beleg: 'Ob orales GABA die Blut-Hirn-Schranke in relevanter Menge passiert, ist am Menschen nicht geklärt; als Alternative wird der Weg über das enterische Nervensystem diskutiert, ebenfalls unbestätigt. Messbar sind aber körperliche Effekte: Ein systematisches Review (Frontiers in Neuroscience 2020) über 14 placebokontrollierte Studien nennt die Evidenz für Stressreduktion begrenzt und für Schlaf sehr begrenzt, bei Industriebeteiligung in 11 Studien. Kleine RCTs zeigen eine systolische Blutdrucksenkung (80 bzw. 39 Teilnehmer) und einen deutlichen akuten Anstieg des Wachstumshormons nach 3 g (11 Männer); eine RCT mit 21 Männern fand mit Molkenprotein mehr fettfreie Masse. Kurzfristig gut verträglich (USP 2021), Langzeitdaten fehlen.' },
  { id: 'inositol', view: 'supplement', evidenz: 7, mechanismus: 7, sicherheit: 7, hype: 5, anwendung: 7, richtung: 'positiv',
    beleg: 'Für PCOS gut untersucht, mit begrenztem klinischem Nutzen. Eine Meta-Analyse über 26 RCTs mit 1.691 Patientinnen (Reprod Biol Endocrinol 2023) zeigt gegenüber Placebo häufiger einen regelmäßigen Zyklus (RR 1,79; 95 % KI 1,13–2,85) und Verbesserungen bei BMI, Testosteron, Nüchternglukose und Insulin; im direkten Vergleich mit Metformin beim Zyklus ohne klaren Unterschied, bei weniger Nebenwirkungen (7 statt 53 Prozent in 4 Studien); eine formale Nichtunterlegenheit ist das nicht, und laut Leitlinien-Meta-Analyse wirkt Metformin bei Hirsutismus und Taille-Hüft-Verhältnis besser. Die Meta-Analyse für die internationale PCOS-Leitlinie (30 Studien, 2.230 Teilnehmerinnen, J Clin Endocrinol Metab 2024) nennt die Evidenz begrenzt und nicht schlüssig; die Leitlinie 2023 empfiehlt keine bestimmte Form, Dosis oder Kombination – das 40:1-Verhältnis stützt sich auf Mausmodelle – und stuft Inositol bei Kinderwunsch als experimentell ein. Ein Cochrane-Review (7 RCTs, 1.319 Schwangere) findet weniger Schwangerschaftsdiabetes (RR 0,53) bei niedriger Evidenzsicherheit. Für Depression und Angststörungen zeigt eine Meta-Analyse (7 bzw. 4 RCTs) keinen signifikanten Effekt; die Panikdaten stammen aus 2 kleinen Crossover-Studien. Der Insulin-Signalweg als sekundärer Botenstoff ist am Menschen belegt. Die breite Vermarktung an stoffwechselgesunde Frauen und gegen Angst ist von dieser Evidenz nicht gedeckt.' },
  { id: 'tmg', view: 'supplement', evidenz: 6, mechanismus: 6, sicherheit: 7, hype: 4, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz 6, weil mehrere Meta-Analysen randomisierter Studien konsistent eine Homocystein-Senkung zeigen (McRae 2013: 5 RCTs, −1,23 µmol/l; Ashtary-Larky 2022: −1,30 µmol/l) und für Kraft einen kleinen Effekt finden (Zawieja 2024: 17 Studien, 317 Teilnehmende, SMD 0,47, Unterkörper 0,49), harte Endpunkte aber fehlen und Körperzusammensetzung (Ashtary-Larky 2022, Br J Nutr) sowie Fettleber (Abdelmalek 2009, 55 Patienten, 12 Monate) negativ ausfielen. Mechanismus bleibt 6: Der BHMT-Weg ist am Menschen bestätigt (Betain, Dimethylglycin und Methionin steigen, Homocystein sinkt), die Kette zur Kraft ist nicht aufgeklärt. Sicherheit 7 statt 6, weil Betain seit 2007 als Arzneimittel Cystadane in der EU zugelassen ist (EMA: Methionin-Anstieg, mögliches Hirnödem) und kontrollierte Daten über 12 Monate mit 20 g pro Tag vorliegen; der Cholesterin-Anstieg ab 4 g ist in 2 Meta-Analysen quantifiziert (Zawieja 2021: +0,34 mmol/l) und als EU-Pflichthinweis geregelt. Anwendung 7 statt 6 wegen Arzneimittelzulassung und reguliertem Health Claim (VO 432/2012). Hype bleibt 4: Beworben werden Leberschutz, Fettabbau und die Rolle als NMN-Partner, die am Menschen nicht belegt sind.' },
  { id: 'methylfolat', view: 'supplement', evidenz: 6, mechanismus: 7, sicherheit: 6, hype: 4, anwendung: 7, richtung: 'gemischt',
    beleg: 'Die Evidenz ist gut, aber sehr eng: Eine Meta-Analyse (Pharmacopsychiatry 2022) über 9 Studien mit insgesamt 6.707 Patienten zeigt als Zusatztherapie bei SSRI-resistenter Depression eine bessere Ansprechrate (RR 1,25 aus 3 Studien mit 483 Patienten) und Symptomreduktion (SMD −0,38), typischerweise mit 15 Milligramm täglich. Das ist eine Behandlung für eine diagnostizierte Erkrankung, keine Stimmungsoptimierung für Gesunde. Für den pauschalen Rat an alle MTHFR-Träger fehlt diese Datenbasis.' },
  { id: 'bor', view: 'supplement', evidenz: 4, mechanismus: 3, sicherheit: 5, hype: 2, anwendung: 6, richtung: 'gemischt',
    beleg: 'Evidenz 4 statt 2, weil mehrere kleine kontrollierte Humanstudien mit Surrogat- und Funktionsendpunkten vorliegen: Mineral- und Hormonstoffwechsel bei 12 Frauen (Nielsen 1987, positiv) und in einer Wiederholung (Beattie 1993, negativ), eine RCT mit 19 Bodybuildern ohne Effekt auf Testosteron und Kraft (Ferrando 1993), eine Einjahresstudie mit 17 Sportlerinnen und 11 inaktiven Studentinnen (Meacham 1994), EEG- und Kognitionsstudien zu borarmer Kost (Penland 1994) und zwei kurze RCTs mit Calciumfructoborat bei Kniebeschwerden (Pietrzkowski 2014, 60 Personen, herstellernah). Mechanismus bleibt 3: Eine spezifische Funktion beim Menschen ist nicht identifiziert, EFSA und NIH stufen Bor nicht als essenziell ein. Sicherheit bleibt 5: Grenzwerte sind definiert (EFSA-UL 10 mg, ADI 0,16 mg/kg, BfR-Vorschlag 0,5 mg pro NEM-Tagesdosis), beruhen aber auf Tierdaten zu Fötus und männlicher Fortpflanzung. Richtung gemischt statt offen: Testosteron bei Männern in der RCT negativ, Mineralhaushalt und Kniebeschwerden in kleinen Studien positiv.' },
  { id: 'chaga', view: 'supplement', evidenz: 2, mechanismus: 3, sicherheit: 2, hype: 1, anwendung: 6, richtung: 'offen',
    beleg: 'Evidenz 2 statt 1, weil zwei unkontrollierte, unverblindete Fallserien am Menschen existieren – 50 Psoriasis-Patienten 1973 und 58 Patienten mit Magengeschwür 1981 – und sonst keine kontrollierte Studie mit veröffentlichten Ergebnissen (Tee 2024; clinicaltrials.gov 30.09.2026: einzige abgeschlossene Studie mit Chaga-Arm NCT05508529 ohne hinterlegte Ergebnisse). Mechanismus 3 statt 2, weil zahlreiche Zell- und Tierstudien plausible Wege beschreiben (antioxidative Enzyme, PPAR-gamma, Blutzuckersenkung; Szychowski 2021), am Menschen aber keine Zielstruktur bestätigt ist; die ORAC-Werbung ist ohne Aussagekraft, die USDA zog die Datenbank 2012 zurück. Sicherheit bleibt 2: keine systematischen Sicherheitsstudien, dafür drei Fallberichte zu Oxalat-Nephropathie (Kikuchi 2014; Lee 2020 mit 14,2 g Oxalat pro 100 g Pulver und 420 bis 1.260 mg Oxalat pro Tag; Kwon 2022) und ein Rattenmodell (Lee 2026). Hype bleibt 1: Immun-, Anti-Aging- und Antioxidationsversprechen stützen sich auf Tradition und Labordaten. Anwendung bleibt 6 wegen langer Tradition und früherem Präparat Befungin in der Sowjetunion.' },
  { id: 'hyaluronsaeure', view: 'supplement', evidenz: 6, mechanismus: 4, sicherheit: 6, hype: 4, anwendung: 7, richtung: 'positiv',
    beleg: 'Eine Meta-Analyse über 7 RCTs (J Drugs Dermatol 2025) zeigt verbesserte Hautfeuchtigkeit, Elastizität und Faltentiefe; die größte Einzelstudie mit 150 gesunden Erwachsenen (Sci Rep 2025) bestätigt das nach 12 Wochen, mit 120 mg deutlicher als mit 60 mg. Bei Arthrose berichten 9 von 11 Studien mit 597 Patienten eine Besserung, die einjährige Placebostudie aber nur in der Untergruppe bis 70 Jahre. Gemessen wird mit kosmetischen Verfahren, und die größten Hautstudien stammen von Rohstoffherstellern. Dass das Molekül von Darmbakterien zerlegt, aufgenommen und in die Haut verteilt wird, ist nur an Ratten gezeigt.' },
  { id: 'glucosamin', view: 'supplement', evidenz: 8, mechanismus: 4, sicherheit: 9, hype: 4, anwendung: 9, richtung: 'negativ', berichtslage: { stufe: 2, kurz: 'Viele berichten Linderung am Knie', was: 'Glucosamin wird von Millionen Menschen genommen, und viele berichten, dass ihr Knie besser geworden ist. Genau diese Berichte hat eine Studie direkt geprüft: 137 Anwender, die ihre Besserung auf Glucosamin zurückführten, nahmen 6 Monate lang entweder weiter Glucosamin oder unbemerkt Placebo. Einen Schub hatten 45 % unter Glucosamin und 42 % unter Placebo. Zum Einordnen hilft auch die GAIT-Studie: Dort erreichten unter Placebo 60,1 % eine Schmerzbesserung von mindestens 20 %. Die Besserung ist also real erlebt, lässt sich in kontrollierten Vergleichen aber nicht der Substanz zuordnen.', quellen: 'LiverTox (NIH) · Cibere et al., Arthritis Rheum 2004 · GAIT, N Engl J Med 2006' },
    beleg: 'Human-Evidenz 8 statt 7: große RCTs (GAIT mit 1.583 Patienten über 24 Wochen, Folgestudien über 2 Jahre) und mehrere Meta-Analysen mit klinischen Endpunkten. Der Cochrane-Review (Towheed et al., CD002946) wertet 25 Studien mit 4.963 Arthrose-Patienten aus – und das Ergebnis hängt an Präparat und Studienqualität: Über 20 gepoolte Studien mit 2.570 Patienten war Glucosamin dem Placebo überlegen, mit 28 Prozent weniger Schmerz und 21 Prozent besserer Funktion im Lequesne-Index; die WOMAC-Werte für Schmerz, Funktion und Steifigkeit wurden dabei nicht signifikant. Beschränkt man die Auswertung auf die 8 Studien mit verdeckter Zuteilung, verschwindet der Vorteil bei Schmerz und WOMAC-Funktion. Überlegen war durchgehend nur das Rotta-Präparat; ob das an der Formulierung oder an der Finanzierung liegt, lässt sich aus den Daten nicht trennen – industrieunabhängige Studien zeigten kleinere Effekte (Wandel, BMJ 2010), und auch unabhängige Studien mit Glucosaminsulfat 1.500 mg einmal täglich blieben ohne Effekt. Die Gesamtschau von 19 Übersichtsarbeiten (2026) findet kleine Effekte an oder unter der Relevanzschwelle. Richtung bleibt negativ: Für den beworbenen, spürbaren Schmerznutzen sprechen die unabhängigen Daten dagegen. Die Sicherheit ist über Jahrzehnte und tausende Teilnehmer hervorragend untersucht und liegt auf Placeboniveau.' },
  { id: 'tongkat-ali', view: 'supplement', evidenz: 6, mechanismus: 3, sicherheit: 4, hype: 3, anwendung: 6, richtung: 'gemischt',
    beleg: 'Evidenz 6 und Mechanismus 3: Die Meta-Analyse von 2022 verrechnet 5 randomisierte Studien mit 232 Männern und findet einen signifikanten Anstieg, doch die Heterogenität liegt bei 87 Prozent, bei Gesunden ist der Effekt nicht signifikant, und der beworbene SHBG-Pfad blieb bei 32 jungen Männern samt LH und FSH unverändert, während die Aromatase-Hemmung nur an Leydig-Zellen aus Rattenhoden gezeigt ist. Sicherheit 4: Es liegen nur Kurzzeitdaten über 2 bis 12 Wochen vor, dazu ein Leberfall von 2024 und der Genotoxizitätshinweis, auf den die europäische Behörde 2021 ihre Ablehnung stützt. Hype 3: Geworben wird mit 37 Prozent aus einer herstellerfinanzierten Speichelstudie an 63 gemischtgeschlechtlichen Teilnehmern und mit einer Vorher-Nachher-Studie an 76 Männern ohne Placebogruppe, während die größte Studie an 109 Gesunden nichts zeigt. Anwendung 6: seit Jahrhunderten in Südostasien genutzt und weltweit im Handel, in der EU jedoch ohne Zulassung; die Richtung bleibt neutral, weil die Daten bei niedrigem Ausgangswert für und bei gesunden Männern gegen einen Effekt sprechen.' },
  { id: 'fadogia-agrestis', view: 'supplement', evidenz: 0, mechanismus: 2, sicherheit: 1, hype: 1, anwendung: 4, richtung: 'offen', berichtslage: { stufe: 2, kurz: 'Libido steigt, alle aus einer Quelle', was: 'Nach der Empfehlung in einem großen Podcast entstand binnen Monaten eine breite Anwenderbasis, die übereinstimmend gesteigerte Libido berichtet, meist innerhalb weniger Tage. Die Berichte sind zahlreich – unabhängig voneinander sind sie aber nicht, denn sie entstanden nahezu alle nach derselben Quelle. Auf der Risikoseite gibt es umgekehrt keine menschlichen Berichte, sondern Tierstudien mit Hodenschäden bei längerer Gabe. Der Nutzen wird berichtet, der Schaden nur vermutet.', quellen: 'Anwenderkreise (überwiegend nach einer gemeinsamen Empfehlungsquelle)' },
    beleg: 'Evidenz 0 und Mechanismus 2: Es existiert keine Humanstudie, eine PubMed-Suche liefert 10 Treffer mit 3 Rattenarbeiten aus einem einzigen Labor, und der beworbene LH-Pfad ist in der Rattenstudie von 2005 nicht einmal gemessen worden. Sicherheit 1: Am Menschen ist nichts systematisch untersucht; was vorliegt, sind Ratten, bei denen sich nach 28 Tagen die Hodenmarker in Richtung Schädigung verschoben und in der Folgearbeit von 2009 Hinweise auf geschädigte Zellmembranen in Leber und Niere auftraten. Hype 1: Gehandelt wird ein Testosteron-Booster auf Grundlage von 5 Tagen Rattenversuch, während 5 von 17 geprüften Produkten den Pflanzenstoff nicht einmal nachweisbar enthielten. Anwendung 4: Nach einer reichweitenstarken Empfehlung entstand binnen Monaten eine breite Anwenderbasis ohne jeden regulatorischen Rahmen, denn in der EU liegt nicht einmal ein Zulassungsantrag vor; die Richtung bleibt neutral, weil am Menschen keine Daten vorliegen, die in eine Richtung sprechen.' },
  { id: 'ca-akg', view: 'supplement', evidenz: 2, mechanismus: 4, sicherheit: 2, hype: 1, anwendung: 4, richtung: 'offen',
    beleg: 'Die vielzitierte Aussage, das biologische Alter sinke um acht Jahre, stammt aus einer retrospektiven Auswertung von 42 Anwendern eines Fertigprodukts (Aging 2021) – ohne Placebo, ohne Randomisierung, gemessen an einer epigenetischen Uhr, die selbst nicht als Endpunkt validiert ist. Die Autoren benennen das als Limitation. Die Lebensspannenverlängerung ist ein Mausbefund. Ein echtes RCT läuft (ABLE-Studie), Ergebnisse stehen aus. Systematische Sicherheitsdaten existieren nicht.' },
  { id: 'nicotinamid-ribosid', view: 'supplement', evidenz: 6, mechanismus: 6, sicherheit: 6, hype: 3, anwendung: 5, richtung: 'gemischt',
    beleg: 'Ungewöhnlich viele RCTs für ein Longevity-Supplement – mit einem klaren Muster: Der NAD+-Spiegel im Blut steigt zuverlässig und dosisabhängig (plus 22, 51 und 142 Prozent; Conze 2019), auch im Gehirn (NADPARK 2022). Eine kritische Übersicht über 25 Humanstudien (Science Advances 2023) findet wenige klinisch relevante Effekte und eine Tendenz, Befunde zu übertreiben; Insulinsensitivität (Clamp, 40 Männer, 12 Wochen; Dollerup 2018), Glukose, Körperzusammensetzung und Blutdruck blieben meist unbeeinflusst, der Blutdruckeffekt einer frühen Studie wurde nicht bestätigt. Für Entzündung gibt es Hinweise (NADPARK), aber keinen einheitlichen Befund (Remie 2020 ohne Effekt auf Entzündungsmarker). Für Alterung selbst existieren am Menschen keine Endpunktdaten; die Phase-III-Studie NOPARK mit 410 Parkinson-Patienten ist seit 17.06.2025 abgeschlossen, aber unveröffentlicht. Die Sicherheit ist über Wochen bis Monate ordentlich untersucht, auch mit 3000 mg über 4 Wochen (NR-SAFE 2023); die EFSA bewertete bis 300 mg am Tag als sicher (2019).' },
  { id: 'shilajit', view: 'supplement', evidenz: 4, mechanismus: 3, sicherheit: 3, hype: 3, anwendung: 6, richtung: 'gemischt',
    beleg: 'Es gibt wenige kontrollierte Humanstudien, alle klein: Pandit et al. (Andrologia 2016) randomisierten 96 Männer zwischen 45 und 55 Jahren und werteten 75 aus; das Gesamttestosteron stieg nach 90 Tagen um 20,45 Prozent und lag signifikant über Placebo. Keller et al. (2019) fanden bei 63 Männern unter 500 mg täglich weniger Kraftverlust nach Ermüdung, aber nur in der stärkeren Hälfte der Teilnehmer. Beide Studien finanzierte der Hersteller des Extrakts. Die 23,5 Prozent mehr Testosteron stammen dagegen aus einer Studie ohne Placebogruppe an 28 Männern mit Oligospermie (Biswas 2010). Symptome wie Libido oder Energie wurden nicht als Endpunkt gemessen. Der eigentliche Risikopunkt liegt im Produkt: Eine Untersuchung von 2025 fand Thallium in Rohshilajit und in Präparaten, teils mehr als im Rohstoff, und eine EU-Bewertung hält fest, dass Mumijo in Herkunft und Zusammensetzung nicht eindeutig definiert ist.' },
  { id: 'colostrum', view: 'supplement', evidenz: 5, mechanismus: 4, sicherheit: 6, hype: 3, anwendung: 6, richtung: 'gemischt',
    beleg: 'Eine Meta-Analyse über 5 RCTs mit 152 Trainierenden (BMC Sports Sci Med Rehabil 2016) fand über 8 bis 12 Wochen weniger Tage mit Atemwegssymptomen (Rate Ratio 0,56) und weniger Episoden (0,62), bei überwiegend moderatem bis hohem Verzerrungsrisiko. Eine Meta-Analyse über 10 Arbeiten (Dig Dis Sci 2024) zeigt einen gedämpften Anstieg der Darmdurchlässigkeit unter Belastung, gemessen mit Surrogatmarkern. Die klassischen Immunmarker ändern sich kaum (Nutrients 2020, 10 RCTs, 239 Teilnehmer); am Menschen verändert sich aber die Neutrophilenfunktion. Leistung verbesserte sich über 24 Wochen bei 28 Fußballern nicht, und IGF-1 im Blut stieg in RCTs über 12 Wochen nicht.' },
  { id: 'cistanche', view: 'supplement', evidenz: 4, mechanismus: 3, sicherheit: 3, hype: 2, anwendung: 5, richtung: 'offen', berichtslage: { stufe: 1, kurz: 'Libido, aber uneinheitlich und spät', was: 'Berichtet wird überwiegend gesteigerte Libido, allerdings deutlich weniger einheitlich als bei anderen Stoffen mit derselben Bewerbung und meist erst nach Wochen. Der lange Zeitraum macht die Zuordnung schwach.', quellen: 'Anwenderkreise' },
    beleg: 'Evidenz 4 statt 2, weil nicht nur eine, sondern zwei kleine randomisierte, doppelblinde Studien mit Cistanche allein und funktionellen Endpunkten vorliegen: 48 Männer über 8 Wochen mit stärkerem Kraftzuwachs und günstigeren Testosteron- und Cortisolwerten (Tao 2025, Nutrients; Sponsor und Lieferant des Prüfprodukts ist ein Hersteller) und 26 Personen über 12 Wochen mit besserer Gehgeschwindigkeit bei über 60-Jährigen ohne Veränderung der Muskelmasse (Inada 2021, p = 0,046). Dazu kommen drei RCTs mit einer Cistanche-Ginkgo-Kombination (Chen 2024: 100 Personen, 90 Tage; Kan 2021: 190 Personen, 60 Tage, laut Autoren möglicherweise klinisch unbedeutend; Gao 2026: 117 Personen, 30 Tage), alle mit Herstellerautoren. Beworben wird Cistanche vor allem für Libido und Langlebigkeit, dazu gibt es keine Humanstudie. Mechanismus bleibt 3: AMPK- und IGF-1-Signalwege nur aus Tier- und Zellstudien. Sicherheit 3 statt 2: kontrollierte Kurzzeitdaten bis 90 Tage ohne behandlungsbedingte Nebenwirkungen, aber keine systematischen Toxizitätsdaten am Menschen und CYP-Hemmung durch Echinacosid in Lebermikrosomen (Wu 2022). In der EU sind C. deserticola und C. tubulosa nicht zugelassene neuartige Lebensmittel.' },
  { id: 'tribulus', view: 'supplement', evidenz: 6, mechanismus: 3, sicherheit: 4, hype: 2, anwendung: 7, richtung: 'gemischt', berichtslage: { stufe: 2, kurz: 'Libido berichtet, Testosteron nicht gefunden', was: 'Berichte und Studien widersprechen sich hier nicht so, wie es aussieht: Berichtet wird überwiegend gesteigerte Libido, und tatsächlich waren drei von fünf Studien zur erektilen Funktion positiv. Nicht gefunden wurde der beworbene Testosteronanstieg. Die Anwender spüren also möglicherweise etwas Reales — nur nicht das, womit geworben wird. Das ist ein Unterschied, den die Werbung verwischt und die Berichte allein nicht auflösen können.', quellen: 'Anwenderkreise · teilweise deckungsgleich mit der Studienlage' },
    beleg: 'Zweigeteilt: Das Testosteron-Versprechen ist untersucht und hält nicht – ein systematisches Review über 10 Studien mit 483 Teilnehmern (Nutrients 2025) findet für Testosteron keine robuste Evidenz, 8 von 10 Studien zeigten keinen Effekt, zwei einen Anstieg von 60 bis 70 ng/dl, und das nur bei Hypogonadismus; auch die Meta-Analyse von 2026 sieht beim Testosteron keinen Unterschied zu Placebo. Für die erektile Funktion ist die Richtung dagegen positiv: Eine Meta-Analyse von 8 Studien (Int J Impot Res 2026) findet gegenüber Placebo IIEF-5 plus 3,23 Punkte (95-%-KI 1,89 bis 4,58), die größte RCT mit 180 Männern über 12 Wochen einen Unterschied von 2,70 Punkten (Maturitas 2017); eine kleine RCT mit 30 Männern über 30 Tage war negativ. Die Hälfte der Männerstudien hat niedrige methodische Qualität, die Frauenstudien (5 RCTs, 279 Teilnehmerinnen) sehr niedrige Gewissheit. Der Protodioscin-Pfad ist am Menschen nicht bestätigt.' },
  { id: 'ergothionein', view: 'supplement', evidenz: 5, mechanismus: 4, sicherheit: 7, hype: 2, anwendung: 3, richtung: 'offen',
    beleg: 'Ein seltener Fall, in dem die Sicherheit deutlich besser untersucht ist als die Wirkung: Die EFSA hat synthetisches L-Ergothionein 2016 bewertet, die EU es 2017 als neuartiges Lebensmittel zugelassen und 2018 auf weitere Lebensmittelkategorien ausgeweitet. Die Interventionsstudien bleiben dagegen klein und kurz: eine Pilot-RCT mit 19 Personen über ein Jahr (J Alzheimers Dis 2024) – bessere Lernleistung im RAVLT und stabile Neurofilament-Leichtketten als Surrogatmarker –, dazu Arbeiten mit 45 und 92 Teilnehmern; die bisher größte mit 147 Teilnehmern verfehlte ihren primären Endpunkt. Der Rest sind Beobachtungsdaten: niedrige Plasmaspiegel gehen mit kognitivem Abbau einher, was keine Kausalität zeigt.' },
  { id: 'glynac', view: 'supplement', evidenz: 3, mechanismus: 6, sicherheit: 3, hype: 2, anwendung: 3, richtung: 'offen',
    beleg: 'Die Behauptung, GlyNAC kehre Merkmale des Alterns um, geht auf eine Studie mit 24 älteren Erwachsenen über 16 Wochen zurück (Kumar et al., J Gerontol A 2023) – aus einer einzigen Arbeitsgruppe, ohne unabhängige Replikation. Verbessert waren Glutathionstatus, oxidativer Stress, Mitochondrienfunktion sowie Ganggeschwindigkeit und Griffkraft – letztere allerdings als Vorher-Nachher-Vergleiche innerhalb der Gruppen. Dass Glycin und Cystein die Glutathionsynthese speisen, ist etablierte Humanbiochemie; der Sprung von dort zu Aging-Hallmarks ist es nicht. Harte Endpunkte fehlen, Langzeitdaten über 16 Wochen hinaus ebenfalls.' },
  { id: 'lithium-orotat', view: 'supplement', evidenz: 3, mechanismus: 4, sicherheit: 3, hype: 3, anwendung: 3, richtung: 'offen', berichtslage: { stufe: 2, kurz: 'Weniger Reizbarkeit, binnen Tagen', was: 'Berichtet wird übereinstimmend eine Dämpfung von Reizbarkeit und Gedankenkreisen in niedriger Dosierung, oft innerhalb weniger Tage. Für Lithium in therapeutischer Dosis ist eine Stimmungswirkung unbestritten; offen ist, ob die hier üblichen Mengen – ein Bruchteil davon – dasselbe tun. Die Berichte behaupten es, geprüft wurde es nicht.', quellen: 'Anwenderkreise' },
    beleg: 'Hier steht die Rechtslage vor der Evidenzfrage: Lithium ist in Deutschland und der EU kein zulässiger Stoff für Nahrungsergänzungsmittel (Richtlinie 2002/46/EG, Anhang II), zugelassen ist nur Lithiumcarbonat als Arzneimittel (Verbraucherzentrale). Humandaten gibt es, aber keine Intervention mit Mikrodosis: Aron et al. (Nature 2025) fanden Lithium als einziges von 27 Metallen im Gehirn bei leichter kognitiver Störung vermindert; der Schutz durch Lithiumorotat ist nur an Mäusen gezeigt, dort ohne veränderte Nieren- und TSH-Werte. Bevölkerungsdaten sind uneinheitlich: Meta-Analyse von 15 ökologischen Studien mit inverser Suizid-Assoziation (Memon 2020), aber kein Zusammenhang bei 3,7 Millionen Dänen über 22 Jahre (Knudsen 2017); Demenz in Dänemark nichtlinear, oberhalb 15,0 µg/L IRR 0,83, bei 5,1–10,0 µg/L IRR 1,22 (Kessing 2017). Die Vermarktung überträgt Maus- und Bevölkerungsbefunde auf die Kapsel. Für therapeutisches Lithium ist die Wirkung bei bipolarer Störung gut belegt – bei enger therapeutischer Breite und ärztlicher Spiegelkontrolle.' },
  { id: 'exogene-ketone', view: 'supplement', evidenz: 6, mechanismus: 7, sicherheit: 4, hype: 3, anwendung: 5, richtung: 'gemischt',
    beleg: 'Die Ketosephysiologie ist gut verstanden und die Blutspiegelerhöhung am Menschen unstrittig – Ester auf 2,8 mM, Salze auf 1,0 mM (Stubbs 2017). Beim Beworbenen ist das Bild geteilt: Für sportliche Leistung finden zwei Meta-Analysen keinen Effekt (13 RCTs, Hedges g -0,05, Valenzuela 2020; 8 Studien, Brooks 2022). Für die Kognition zeigt eine Meta-Analyse aus 29 Protokollen mit 1.117 Teilnehmern einen kleinen Vorteil (SMD 0,29; Bonnechère 2026), bei Herzinsuffizienz steigen in 4 RCTs mit 94 Patienten Herzzeitvolumen und Auswurffraktion (Siddiqi 2026) – beides kurze Studien mit Surrogatendpunkten. Eine 28-Tage-Verträglichkeitsstudie mit 24 Personen liegt vor, Langzeitdaten nicht; die EFSA konnte 2022 die Sicherheit der BHB-Salze nicht feststellen. Magen-Darm-Beschwerden sind die häufigste berichtete Nebenwirkung.' },
  { id: 'citrus-bergamot', view: 'supplement', evidenz: 5, mechanismus: 6, sicherheit: 4, hype: 4, anwendung: 5, richtung: 'gemischt',
    berichtslage: { stufe: 1, kurz: 'Teils Senkung, teils gar nichts', was: 'Gemischt: In einer kleinen US-Bewertungssammlung (24 Bewertungen aus 2015 bis 2024) vergibt gut die Hälfte vier oder fünf Sterne und berichtet teils LDL-Senkungen von 10 bis 20 Prozent ohne Nebenwirkungen, fast vier von zehn vergeben einen Stern – kein Effekt oder steigende Werte. Dazu kommen Einzelberichte über niedrigen Blutdruck und Sonnenempfindlichkeit. Hintergrund: In Reddit-Diskussionen über Statine geht es in knapp der Hälfte um Alternativen (Liu 2026).', quellen: 'WebMD-Bewertungen (24, 2015–2024) · Liu 2026 (J Med Internet Res)' },
    beleg: 'Für einen Surrogatmarker konsistent, für den beworbenen Rahmen nicht: Mehrere kleinere Studien senken das LDL, in verblindeten Arbeiten außerhalb Italiens um rund 10 Prozent – auch diese mit Herstellerbeteiligung –, und zeigen damit dasselbe Muster. Die Meta-Analyse von Chambari 2026 über 9 randomisierte Studien mit 615 Teilnehmenden bestätigt die Richtung, stuft die Evidenz für LDL aber als sehr niedrig ein und findet in größeren Studien kleinere Effekte. Kardiovaskuläre Endpunkte – Herzinfarkt, Sterblichkeit – wurden nie untersucht. Genau darin liegt die Lücke der Bezeichnung als natürliches Statin: Statine sind über harte Endpunkte in großen Studien belegt, Bergamotte über Blutwerte in kleinen.' },
  { id: 'nattokinase', view: 'supplement', evidenz: 5, mechanismus: 5, sicherheit: 4, hype: 3, anwendung: 6, richtung: 'gemischt',
    berichtslage: { stufe: 2, kurz: 'Long Covid: viele berichten Besserung', was: 'In einer großen Online-Umfrage (PNAS 2025, 3.925 Menschen mit Long Covid oder ME/CFS, verteilt u. a. über Reddit) bewerteten 475 Menschen Nattokinase oder Lumbrokinase, als eine Gruppe gezählt: 55 Prozent besser, 7 Prozent schlechter. Zum Vergleich orales Vitamin C, das die Autoren mangels Placebo als Maßstab nutzen: 27 Prozent besser. Eine qualitative Social-Media-Analyse (LISTEN 2025) findet neben positiven Berichten viel Enttäuschung und Frust über die Kosten. Selbstauskunft, Auswahl über Patientengruppen, keine Placebokontrolle; Studien am Menschen zu Long Covid gibt es nicht.', quellen: 'Eckey 2025 (PNAS) · Martin 2025 (Front Big Data) · Baptista 2026 (Front Med)' },
    beleg: 'Beworben wird die Auflösung von Blutgerinnseln, gezeigt ist eine Blutdrucksenkung: Eine Meta-Analyse über 6 RCTs mit 546 Teilnehmenden (Li 2023, Rev Cardiovasc Med) findet −3,45 mmHg systolisch und −2,32 mmHg diastolisch, die Lipideffekte sind dosisabhängig und uneinheitlich. Keine Studie hat reduzierte thrombotische Ereignisse untersucht. Die fibrinolytische Aktivität ist über Biomarker wie D-Dimer und Fibrinogen belegt, der klinische Schritt nicht. Als konzentriertes Präparat ist Nattokinase deutlich schlechter charakterisiert als das traditionelle Natto; das Blutungsrisiko unter Gerinnungshemmern ist dokumentiert. Die einzige lange placebokontrollierte Studie (Hodis 2021, 265 Personen, median 3 Jahre) zeigt keinen Effekt auf Karotis-Wanddicke, Gefäßsteifigkeit, Blutdruck oder Gerinnungs- und Fibrinolysewerte. Die Plaque-Daten (Chen 2022, 1.062 Personen) stammen aus einer retrospektiven Aktenauswertung ohne Kontrollgruppe mit Herstellerbeteiligung.' },
  { id: 'serrapeptase', view: 'supplement', evidenz: 6, mechanismus: 2, sicherheit: 5, hype: 1, anwendung: 6, richtung: 'negativ',
    berichtslage: { stufe: 1, kurz: 'Berichte ja, aber nicht von Vitamin C zu unterscheiden', was: 'In der PNAS-Umfrage 2025 unter Menschen mit Long Covid oder ME/CFS bewerteten 104 Menschen Serrapeptase allein: 37,5 Prozent besser, 8,7 Prozent schlechter, statistisch nicht von oralem Vitamin C (27 Prozent besser) zu unterscheiden, das die Autoren mangels Placebo als Maßstab nutzen. In Kombination mit Nattokinase oder Lumbrokinase (430 Bewertungen) nannten 61 Prozent eine Besserung. Eine Social-Media-Analyse (LISTEN 2025) findet vereinzelt positive Berichte. Dagegen steht, dass der japanische Originalhersteller das Präparat 2011 vom Markt nahm, nachdem Doppelblindstudien keinen Unterschied zu Placebo zeigten.', quellen: 'Eckey 2025 (PNAS) · Martin 2025 (Front Big Data)' },
    beleg: 'Der aussagekräftigste Befund steht am Ende der Marktgeschichte: Nachdem die Behörde eine Neubewertung verlangt hatte, fand sich in placebokontrollierten Doppelblindstudien kein signifikanter Unterschied – der japanische Originalanbieter nahm die entzündungshemmende Formulierung 2011 vom Markt, statt neue Studien vorzulegen. Das systematische Review (Bhagat et al., Int J Surg 2013) findet für keine der beworbenen Anwendungen belastbare Evidenz. Dokumentiert sind seltene, aber schwere Reaktionen bis zur eosinophilen Pneumonitis. Dass ein großes Enzymprotein oral intakt wirkt, ist mechanistisch fraglich. 2026 kamen zwei Arbeiten hinzu: eine retrospektive Kohorte nach Liposuktion bei Lipödem (50 Frauen) ohne Effekt auf Fibrose und Schmerz (Bruno 2026) und eine nicht randomisierte Beobachtungsstudie bei Unfallpatienten (813 ausgewertet) mit schnellerer Schmerzlinderung, bei der die Ärzte über die Zuteilung entschieden (Hanif 2026).' },
  { id: 'safran', view: 'supplement', evidenz: 6, mechanismus: 5, sicherheit: 6, hype: 5, anwendung: 7, richtung: 'positiv',
    beleg: 'Die Datenlage ist besser als bei den meisten Pflanzenextrakten: Eine Meta-Analyse von 2026 über 34 placebokontrollierte RCTs (1.769 Teilnehmende) findet eine Besserung im Beck-Depressionsinventar (−4,39) und im Beck-Angstinventar (−5,06), aber keinen signifikanten Effekt in der ärztlich erhobenen Hamilton-Skala. Gegen SSRI zeigen 8 Studien keinen Unterschied (SMD 0,10), bei weniger Nebenwirkungen (Shafiee et al., Nutr Rev 2025). Die größte Einzelstudie (202 Erwachsene, 28 mg, 12 Wochen) erreichte ihren primären Endpunkt mit d = 0,39. Einschränkungen: Publikationsbias und geringe regionale Vielfalt (Marx 2019), uneinheitliche Ergebnisse zwischen Selbst- und Fremdbeurteilung. Mechanismus am Menschen kaum quantifiziert. Sicherheit: systematische Übersicht über 102 klinische Studien bis 12 Monate Dauer, Nebenwirkungen meist mild, zwischen 15 und 100 mg ohne erkennbaren Dosisanstieg; höhere Dosen nur kurz untersucht. Die WFSBP-CANMAT-Taskforce empfiehlt Safran bei Depression vorläufig (++).' },
  { id: 'magnesium-l-threonat', view: 'supplement', evidenz: 5, mechanismus: 3, sicherheit: 6, hype: 3, anwendung: 6, richtung: 'gemischt',
    beleg: 'Das gesamte Alleinstellungsmerkmal beruht auf einem unbestätigten Schritt: Dass diese Magnesiumform Magnesium ins Gehirn bringt, stammt aus dem Nervenwasser von Ratten – dort rund 7 % über Ausgangswert und rund 16 % über Kontrolle an Tag 24 – und wurde am lebenden Menschen in keiner der vorliegenden Studien gemessen. Drei randomisierte Studien mit 51, 80 und 100 Teilnehmern über 3 bis 12 Wochen berichten bessere kognitive Kompositscores und teils besseren Schlaf; alle drei sind von Herstellern oder Rohstofflieferanten finanziert, zwei wurden erst nach Abschluss der Datenerhebung registriert. Die vielzitierten 7,5 Jahre kognitives Alter sind in der Originalarbeit ausdrücklich als exploratorische Auswertung gekennzeichnet, und die beiden Schlafstudien widersprechen sich in den objektiven Messwerten desselben Schlafrings. Die Achse evidenz steigt von 4 auf 5, weil es drei und nicht zwei RCTs sind; anwendung steigt von 5 auf 6, weil der Stoff seit dem 7. November 2024 in der EU als neuartiges Lebensmittel zugelassen ist und seit dem 5. November 2025 in Anhang II der Richtlinie 2002/46/EG steht.' },
  { id: 'rote-bete-nitrat', view: 'supplement', evidenz: 7, mechanismus: 9, sicherheit: 7, hype: 5, anwendung: 7, richtung: 'positiv',
    beleg: 'Der am besten verstandene Mechanismus unter den Supplements: Der Weg von Nitrat über Nitrit zu Stickstoffmonoxid ist am Menschen direkt nachvollzogen, eine antiseptische Mundspülung hebt die Nitritbildung im Mund auf und ließ den Blutdruck bei Gesunden um 2 bis 3,5 mmHg steigen (Free Radic Biol Med 2013). Für die Leistung zeigt eine Meta-Analyse über 80 Crossover-RCTs einen kleinen, klaren Effekt (d = 0,174), der bei gut trainierten Ausdauerathleten verschwindet (Med Sci Sports Exerc 2020); der IOC-Konsens 2018 zählt Nitrat zu den wenigen gut belegten Supplements. Beim Blutdruck senkt Rote-Bete-Saft bei 349 Hypertonikern in 11 RCTs den systolischen Praxiswert um 5,31 mmHg, diastolisch und im 24-Stunden-Mittel ohne signifikanten Effekt, bei niedriger Evidenzsicherheit (Nutr Metab Cardiovasc Dis 2024); die RCT NITRATE-BP fand über 4 Wochen auch ambulant -7,7 mmHg. Harte kardiovaskuläre Endpunkte fehlen.' },
  { id: 'kupfer', view: 'supplement', evidenz: 5, mechanismus: 9, sicherheit: 8, hype: 3, anwendung: 8, richtung: 'gemischt',
    beleg: 'Als Enzymkofaktor für Superoxiddismutase, Caeruloplasmin und weitere Cuproenzyme ist Kupfer lückenlos verstanden, und der Mangel mit Anämie und Nervenschäden klar beschrieben – nur ist dieser Mangel bei Gesunden ohne Malabsorption, Magen-Darm-Operation oder Zinküberschuss selten; die Zufuhr in Deutschland liegt im Median bei 1,2 bis 1,8 mg am Tag. Für die Supplementierung von Nichtmangelnden ist der Nutzen nicht gezeigt; eine Alzheimer-Studie mit 68 Patienten und 8 mg täglich über 12 Monate veränderte nur einen Amyloid-Biomarker im Liquor ohne kognitiven Effekt (Kessler 2008). Die EU-Obergrenze liegt bei 5 mg pro Tag (SCF 2003; EFSA 2023: keine Retention bei 5 mg), der US-Wert bei 10 mg. Bei 9 Männern, die 129 Tage lang 7 mg zusätzlich zur Kost und danach 18 Tage 7,8 mg aufnahmen, wurden mehr als 0,6 mg pro Tag zurückgehalten, Kupferstatus-Marker stiegen und Immunwerte veränderten sich; die Bedeutung ist laut den Autoren unbekannt (Turnlund 2004, 2005).' },
  { id: 'semaglutide', view: 'experimental', evidenz: 10, mechanismus: 9, sicherheit: 9, hype: 7, anwendung: 9, richtung: 'positiv',
    berichtslage: { stufe: 3, kurz: 'Ruhe im Kopf — und Übelkeit', was: 'Anwender beschreiben vor allem, dass das ständige Denken ans Essen („Food Noise") leiser wird; eine herstellerfinanzierte Umfrage (n = 550) fand auf dem Food-Noise-Fragebogen im Median einen Rückgang von 13 auf 6 von 20 Punkten, allerdings mit erinnertem Ausgangswert. In 410.198 Reddit-Beiträgen nennen gut vier von zehn Selbstanwendern mindestens eine Nebenwirkung, vorn Übelkeit; neu auffällig sind Zyklusveränderungen und Temperaturbeschwerden. Häufig berichtet wird weniger Lust auf Alkohol — eine kleine RCT (n = 48) stützt das teilweise.', quellen: 'Hayashi 2026 (Nutr Diabetes) · Arnaut 2026 (Adv Ther, INFORM) · Plenn 2025 (Obes Sci Pract) · Sehgal 2026 (medRxiv, Vorabdruck) · Quddos 2023 (Sci Rep) · Hendershot 2025 (JAMA Psychiatry)' },
    beleg: 'Zugelassen auf Basis der STEP-Studien, kardiovaskulärer Nutzen in SELECT mit hartem Endpunkt, Wirkkette am Menschen quantifiziert, Pharmakovigilanz läuft. Abzug beim Hype-Abstand für den Graumarkt, der mit denselben Zahlen wirbt, ohne dasselbe Produkt zu verkaufen.' },
  { id: 'tirzepatide', view: 'experimental', evidenz: 10, mechanismus: 9, sicherheit: 8, hype: 7, anwendung: 8, richtung: 'positiv',
    beleg: 'Zugelassen auf Basis der SURMOUNT- und SURPASS-Programme; der doppelte Rezeptorangriff ist am Menschen belegt. Weniger Langzeitdaten als bei Semaglutid, weil jünger. Kostenübernahme durch die Kasse ist ausgeschlossen – das fällt in der Werbung unter den Tisch.' },
  { id: 'retatrutide', view: 'experimental', evidenz: 9, mechanismus: 8, sicherheit: 6, hype: 4, anwendung: 4, richtung: 'positiv',
    beleg: 'Die stärksten Gewichtsdaten, die je erhoben wurden, begutachtet bisher aber nur aus Phase 2: 338 Teilnehmende, 48 Wochen, 24,2 Prozent gegenüber 2,1 Prozent unter Placebo (NEJM 2023). Laut Hersteller randomisierte TRIUMPH-1 2.339 Teilnehmende über 80 Wochen und erreichte in der höchsten Dosis 28,3 Prozent, nach Auswertung aller Randomisierten 25,0 Prozent; TRIUMPH-4 kam mit 445 Teilnehmenden über 68 Wochen auf 28,7 Prozent gegenüber 2,1 Prozent unter Placebo. Eine begutachtete Vollpublikation zu TRIUMPH gibt es noch nicht, begutachtet in Phase 3 ist bisher nur die Diabetesstudie TRANSCEND-T2D-1 (Lancet 2026). Der Dreifach-Agonismus ist am Menschen belegt, der Anteil des Glukagon-Arms nicht getrennt geprüft. Der Preis steht in denselben Studien: Übelkeit bei bis zu 43,2 Prozent (höchste Dosis in TRIUMPH-4) und Studienabbruch wegen Nebenwirkungen bei bis zu 18,2 Prozent. Eine Zulassung besteht noch nicht; was heute im Graumarkt gehandelt wird, ist nicht der Studienwirkstoff.' },
  { id: 'bpc-157', view: 'experimental', evidenz: 1, mechanismus: 4, sicherheit: 2, hype: 1, anwendung: 5, richtung: 'offen', berichtslage: { stufe: 3, kurz: 'Heilung an Sehnen, seit Jahren gemeldet', was: 'Seit Jahren übereinstimmend aus mehreren unabhängigen Kreisen: Sport- und Reha-Praxen in den USA, behandelnde Ärzte, Anwender. Berichtet wird konsistent eine beschleunigte Heilung an Sehnen, Bändern und im Darm – eine auf ein Gewebe bezogene, spezifische Beobachtung, kein allgemeines Wohlbefinden. Das ist der Grund, warum die Substanz trotz fehlender veröffentlichter Studien so verbreitet ist.', quellen: 'Sport- und Reha-Praxen USA · behandelnde Ärzte · Anwenderkreise' }, belegLuecke: 'unveroeffentlicht',
    beleg: 'Der Fall zeigt den Unterschied zwischen „nie am Menschen versucht" und „versucht, Ergebnis nie veröffentlicht": Der kroatische Hersteller Pliva führte Phase-II-Studien (PL-14736) bei Colitis ulcerosa durch, die positive Effekte ohne Toxizität gezeigt haben sollen – die vollständigen Daten wurden nie als eigenständige klinische Arbeit publiziert und sind damit nicht überprüfbar. Eine Phase-I-Studie an 42 Gesunden (NCT02637284) wurde 2016 abgebrochen, ohne Ergebnisse. Eine publizierte randomisierte kontrollierte Humanstudie existiert bis heute zu keiner Indikation; die belastbare Datenlage besteht aus Nagermodellen. Die Anwendung ist dagegen real und umfangreich: In den USA wurde BPC-157 jahrelang in Compounding-Apotheken hergestellt und in Sport- und Reha-Praxen eingesetzt. Die FDA stufte es 2023 wegen Immunogenität und Verunreinigungen in Kategorie 2 ein und nahm es am 15. April 2026 dort wieder heraus. Am 23./24. Juli 2026 beriet ein Expertengremium der FDA, ob BPC-157 für Rezepturarzneien in den USA zugelassen werden soll. Die FDA-Fachleute rieten ab, das Gremium stimmte dennoch mehrheitlich dafür (Stimmen 8:6, 1 Enthaltung). Eine Entscheidung der FDA steht aus; ein formelles Verfahren dürfte frühestens 2027 beginnen. Legal herstellbar ist es derzeit nicht. Verkauft wird es als Reparaturmittel für nahezu jedes Gewebe. Die Anwendungserfahrung ist also erheblich – sie ersetzt die fehlende Evidenz nicht.' },
  { id: 'tb-500', view: 'experimental', evidenz: 1, mechanismus: 4, sicherheit: 2, hype: 1, anwendung: 3, richtung: 'offen',
    berichtslage: { stufe: 2, kurz: 'Heilung – nie allein angewendet', was: 'Die Berichte ähneln denen zu BPC-157 – beschleunigte Heilung an Sehnen und Bändern – und stammen weitgehend aus demselben Umfeld. Genau darin liegt ihre Schwäche: TB-500 wird fast immer zusammen mit BPC-157 angewendet. Die Berichte können deshalb nicht trennen, welcher der beiden Stoffe wirkt, falls einer wirkt. Verbreitet und übereinstimmend ja, zuordenbar nein.', quellen: 'Anwenderkreise · Sport- und Reha-Umfeld USA' },
    beleg: 'Die Humandaten betreffen Thymosin Beta-4 in klinischen Ansätzen, nicht das gehandelte Fragment; kontrollierte Studien zum Research-Produkt fehlen. Sicherheit unerforscht, Vermarktung als Regenerations-Wundermittel. Anwendung 3 (bisher 4): Die Anwendung ist nur aus Anwenderberichten bekannt; die FDA fand keine Daten zur Exposition am Menschen.' },
  { id: 'mk-677', view: 'experimental', evidenz: 6, mechanismus: 8, sicherheit: 5, hype: 3, anwendung: 4, richtung: 'gemischt',
    berichtslage: { stufe: 3, kurz: 'Hunger, IGF-1 und Magermasse messbar', was: 'Hier berichten Anwender übereinstimmend etwas sehr Spezifisches: heftigen Hunger binnen Stunden, Wassereinlagerung, tieferen Schlaf — und einen im Blutbild messbaren IGF-1-Anstieg, den viele selbst bestimmen lassen. Das ist keine Einbildung, und die Studien bestätigen es ausdrücklich, bis hin zur Magermasse: In zwei randomisierten Studien stieg die fettfreie Masse signifikant. Was die Studien nicht fanden, ist der Schritt danach: mehr Kraft, mehr Funktion, weniger Fett. Die Berichte belegen also mehr als den Mechanismus — aber nicht den beworbenen Nutzen.', quellen: 'Anwenderkreise · IGF-1-Selbstmessungen · deckungsgleich mit der Studienlage' },
    beleg: 'Hier gibt es echte Humanstudien, auch über Monate, und sie zeigen mehr als nur den Mechanismus: Wachstumshormon und IGF-1 steigen, und die fettfreie Masse nimmt messbar zu – bei 65 gesunden Älteren über ein Jahr um 1,1 kg gegenüber −0,5 kg unter Placebo (Nass et al., Ann Intern Med 2008), bei 24 adipösen Männern schon nach acht Wochen (Svensson et al., JCEM 1998). Was in beiden Studien ausblieb: mehr Kraft, bessere Funktion, weniger Fett. Was dazukam: eine Verschlechterung der Glukosetoleranz, Wassereinlagerung, Hunger. Eine weitere Studie an 123 älteren Hüftfrakturpatienten wurde vorzeitig beendet, weil sich ein Signal für Herzinsuffizienz zeigte (Adunsky et al. 2011). Belegt ist die Wirkung auf die Hormonachse und die Magermasse; nicht belegt ist der Nutzen, mit dem geworben wird.' },
  { id: 'cjc-ipamorelin', view: 'experimental', evidenz: 2, mechanismus: 6, sicherheit: 3, hype: 3, anwendung: 4, richtung: 'offen', berichtslage: { stufe: 2, kurz: 'Tieferer Schlaf, IGF-1 messbar hoch', was: 'Übereinstimmend berichtet werden tieferer Schlaf in den ersten Wochen, Wassereinlagerung und ein Kribbeln in den Händen. Dazu kommt ein Punkt, der über Gefühl hinausgeht: ein Anstieg des IGF-1 im Blutbild, den viele Anwender selbst messen lassen. Dass die Hormonachse anspringt, ist damit gut belegt. Ob daraus der beworbene Nutzen folgt, ist eine andere Frage – und die ist offen.', quellen: 'Anwenderkreise · IGF-1-Selbstmessungen' },
    beleg: 'Zur beliebten Kombination gibt es keine einzige Humanstudie; eine Übersicht von 2026 (Dominikowski) nennt die Praxis weitgehend anekdotisch begründet und stuft das meist verwendete CJC-1295 ohne DAC auf die unterste Evidenzstufe. Belegt sind die Bauteile auf Ebene der Hormonspiegel: Ipamorelin löst beim Menschen einen einzelnen GH-Puls aus (Gobburu 1999, 5 Stufen à 8 Männer) und war im Tier selektiv ohne ACTH- oder Cortisolanstieg (Raun 1998); CJC-1295 mit DAC hob GH und IGF-1 in zwei randomisierten Studien über Tage (Teichman 2006). Die Synergie von GHRH- und Ghrelin-Signal ist am Menschen für die Substanzklassen gezeigt (Bowers 1990). Die einzige Wirksamkeitsstudie zu Ipamorelin verfehlte ihren Endpunkt (Beck 2014, 114 Patienten), war aber gut verträglich. Für Schlaf, Muskel, Fett und Haut gibt es keine Humandaten, Langzeitsicherheit ist offen; die FDA führt Ipamorelin seit 2023 als Wirkstoff mit möglichen erheblichen Sicherheitsrisiken.' },
  { id: 'ghk-cu', view: 'experimental', evidenz: 4, mechanismus: 7, sicherheit: 6, hype: 4, anwendung: 5, richtung: 'gemischt',
    beleg: 'Ein geteilter Fall. Am Menschen gibt es eine randomisierte, verblindet ausgewertete Studie zu diabetischen Fußgeschwüren mit deutlich besserer Wundschließung (Mulder 1994: im Median 98,5 gegenüber 60,8 Prozent) und mehrere kleine Kosmetikstudien über 12 Wochen an Frauen um 50, die aber überwiegend als Kongressbeiträge oder Industrieberichte vorliegen. Systematische Übersichten von 2026 bewerten die Humanliteratur als dünn und bruchstückhaft, eine kleine Studie nach Laserbehandlung war in objektiven Endpunkten negativ. Für die injizierte Anwendung gibt es keine Humandaten, die FDA verweist auf begrenzte Daten und ein Immunrisiko. Die Genregulations-Erzählung stammt aus Zelllinien-Datenbanken und wird für beide Anwendungswege benutzt.' },
  { id: 'epitalon', view: 'experimental', evidenz: 0, mechanismus: 3, sicherheit: 2, hype: 1, anwendung: 5, richtung: 'offen', berichtslage: { stufe: 1, kurz: 'Viele Berichte, alle aus dem Anbieterkreis', was: 'Berichte gibt es reichlich, aber sie stammen fast vollständig aus dem Umfeld der Anbieter und aus Publikationen derselben russischen Arbeitsgruppe, die die Präparate entwickelt hat. Damit fehlt genau das, was Anwenderberichte sonst stark macht: Unabhängigkeit. Das macht die Berichte nicht falsch, aber schwach.', quellen: 'überwiegend Anbieterumfeld · Publikationen der Entwicklergruppe' },
    beleg: 'Das einzige Peptid der Gruppe mit einer unabhängigen Bestätigung – aber nur in der Petrischale: Al-Dulaimi et al. (Biogerontology 2025, Brunel University London, ohne Chawinson als Autor) zeigten in normalen menschlichen Zellen eine dosisabhängige Telomerverlängerung über hTERT und Telomerase, in Krebszellen ebenfalls, dort über den ALT-Weg. Die Originalarbeit (Chawinson et al., Bull Exp Biol Med 2003) war Zellkultur an fetalen Fibroblasten. Bei Mäusen stieg die maximale Lebensdauer um 12,3 Prozent, die mittlere nicht. Die Humandaten – weniger Todesfälle über 12 Jahre bei älteren Herzpatienten – betreffen den Zirbeldrüsen-Extrakt Epithalamin und stammen aus derselben Arbeitsgruppe; randomisierte Studien, Pharmakokinetik oder registrierte Studien mit dem Tetrapeptid selbst sind nicht veröffentlicht (Übersicht 2026). Deshalb Human-Evidenz 0: Für Epitalon selbst gibt es keine Humandaten, die Epithalamin-Daten zählen nicht für das Tetrapeptid. Die Sicherheit am Menschen ist damit nicht systematisch untersucht, und eine Zulassung des Tetrapeptids in irgendeinem Land ließ sich nicht belegen; es wird ohne regulatorischen Rahmen als Research-Ware gehandelt. Beworben wird die Telomerverlängerung gleichwohl als Verjüngung.' },
  { id: 'rapamycin', view: 'experimental', evidenz: 5, mechanismus: 9, sicherheit: 5, hype: 4, anwendung: 9, richtung: 'gemischt',
    beleg: 'Der mTOR-Weg ist einer der am besten verstandenen der Alternsforschung und in Modellorganismen überzeugend. Am Menschen gibt es zugelassene Anwendungen in der Transplantationsmedizin, aber keine Longevity-Endpunktdaten; die Off-Label-Nutzung läuft der Evidenz voraus.' },
  { id: 'dihexa', view: 'experimental', evidenz: 0, mechanismus: 4, sicherheit: 1, hype: 1, anwendung: 2, richtung: 'offen',
    beleg: 'Die mechanistische Schlüsselarbeit ist zurückgezogen, die Einführungsarbeit von 2013 steht unter Expression of Concern. Das nach demselben Prinzip entwickelte, chemisch andere Medikament Fosgonimeton ist in Phase 2/3 gescheitert. Zu Dihexa selbst gibt es am Menschen keinerlei Daten, auch keine registrierte klinische Studie. Sicherheit völlig unerforscht. Siehe Änderungsprotokoll.' },
  { id: 'metformin', view: 'experimental', evidenz: 8, mechanismus: 8, sicherheit: 9, hype: 5, anwendung: 10, richtung: 'gemischt',
    beleg: 'Für Typ-2-Diabetes seit Jahrzehnten zugelassen, mit Endpunktdaten und umfassender Pharmakovigilanz. Der Longevity-Anspruch ist etwas anderes: Die dafür entscheidende Studie ist nicht abgeschlossen, und es gibt Hinweise, dass Metformin Trainingsanpassungen dämpft.' },
  { id: 'testosteron', view: 'experimental', evidenz: 9, mechanismus: 9, sicherheit: 9, hype: 4, anwendung: 10, richtung: 'gemischt',
    berichtslage: { stufe: 3, kurz: 'Klare Effekte, auch ohne belegten Mangel', was: 'Kaum ein Thema hat so einheitliche Berichte: mehr Antrieb, bessere Stimmung, mehr Libido, oft schon nach zwei bis drei Wochen. Das ist spezifisch, kurzfristig und glaubwuerdig — und es deckt sich mit der Studienlage, denn bei diagnostiziertem Mangel ist die Wirkung unbestritten. Der Haken liegt woanders: Dieselben Effekte werden auch von Männern mit normalen Ausgangswerten berichtet, und für genau diese Gruppe gibt es keine Zulassungsstudie. Die Berichte belegen hier also, dass der Stoff wirkt — nicht, dass die Behandlung angezeigt war. Das ist der Unterschied, den die Werbung verwischt.', quellen: 'Anwenderkreise · Praxisberichte · deckungsgleich mit der Studienlage' },
    beleg: 'Die Substitution bei diagnostiziertem Hypogonadismus ist seit Jahrzehnten zugelassen und die Wirkkette am Menschen zweifelsfrei belegt – die Frage ist, wer behandelt wird. Die TRAVERSE-Studie (Lincoff et al., NEJM 2023) randomisierte 5.246 Männer, im Mittel 21,7 Monate behandelt und 33 Monate beobachtet: kardiovaskulär nicht unterlegen, aber mehr Vorhofflimmern (91 gegen 63 Fälle) und mehr akutes Nierenversagen. Das BfArM wies 2025 auf die stark steigende Verordnungshäufigkeit hin, die teils außerhalb der Zulassung erfolgt. Für Männer mit niedrig-normalen Werten ohne Diagnose gibt es keine Zulassungsstudie.' },
  { id: 'hgh', view: 'experimental', evidenz: 8, mechanismus: 9, sicherheit: 8, hype: 3, anwendung: 9, richtung: 'gemischt',
    beleg: 'Für Wachstumshormonmangel und definierte Syndrome liegen Phase-III- und Registerdaten aus vier Jahrzehnten vor – für die Anti-Aging-Anwendung nichts Vergleichbares. Die dafür stets zitierte Rudman-Arbeit (NEJM 1990) umfasste 21 Männer, 12 behandelte und 9 unbehandelte Vergleichspersonen, war nicht randomisiert und kurz. Bei gesunden Älteren zeigt die Übersicht von Liu 2007 nur eine moderat veränderte Körperzusammensetzung ohne Funktionsgewinn, bei mehr Nebenwirkungen. Bekannt sind bei supraphysiologischer Dosierung Ödeme, Karpaltunnelsyndrom und Insulinresistenz. Rechtlich ist Somatropin verschreibungspflichtig; Erwerb ohne Rezept ab der in der Dopingmittel-Mengen-Verordnung genannten Menge ist nach dem Anti-Doping-Gesetz strafbar.' },
  { id: 'tesamorelin', view: 'experimental', evidenz: 7, mechanismus: 8, sicherheit: 6, hype: 3, anwendung: 5, richtung: 'gemischt',
    beleg: 'In den USA seit 2010 zugelassen – aber für eine sehr spezielle Gruppe: die Reduktion viszeralen Fetts bei HIV-assoziierter Lipodystrophie, belegt durch Phase-III-Studien. In der EU existiert diese Zulassung nicht; der Antragsteller zog den Antrag bei der EMA zurück. Als GHRH-Analogon ist die Stimulation der körpereigenen Wachstumshormonausschüttung am Menschen bestätigt. Für Gesunde ohne Lipodystrophie – die beworbene Zielgruppe – wurde keine kontrollierte Studie gefunden. Sicherheit 6 (bisher 7): Langzeitdaten fehlen, beide Langzeit-Sicherheitsstudien wurden abgebrochen, und laut US-Fachinformation ist die langfristige kardiovaskuläre Sicherheit nicht belegt.' },
  { id: 'sermorelin', view: 'experimental', evidenz: 3, mechanismus: 7, sicherheit: 4, hype: 2, anwendung: 4, richtung: 'offen',
    berichtslage: { stufe: 2, kurz: 'Tieferer Schlaf, IGF-1 messbar hoch', was: 'Wie in der ganzen Gruppe der GH-Sekretagoga: übereinstimmend berichtet werden tieferer Schlaf und Wassereinlagerung in den ersten Wochen, dazu ein im Blutbild messbarer IGF-1-Anstieg. Belegt ist damit, dass die Hormonachse reagiert – nicht, dass daraus der beworbene Nutzen folgt.', quellen: 'Anwenderkreise · IGF-1-Selbstmessungen' },
    beleg: 'Das ursprünglich zugelassene Präparat wurde vom Markt genommen; die US-Behörde stellte 2013 ausdrücklich fest, dass dies nicht aus Sicherheits- oder Wirksamkeitsgründen geschah. Die alten Zulassungsdaten betreffen die pädiatrische Diagnostik, nicht die heute beworbene Anti-Aging-Anwendung bei Erwachsenen – dafür wurde keine belastbare aktuelle Humanevidenz gefunden. Die physiologische, pulsatile Stimulation ist am Menschen bestätigt. Seit dem Marktrückzug gibt es keine laufende Pharmakovigilanz.' },
  { id: 'cjc-1295-dac', view: 'experimental', evidenz: 4, mechanismus: 7, sicherheit: 3, hype: 3, anwendung: 3, richtung: 'offen', berichtslage: { stufe: 2, kurz: 'Tieferer Schlaf, IGF-1 messbar hoch', was: 'Wie in der ganzen Gruppe der GH-Sekretagoga: übereinstimmend berichtet werden tieferer Schlaf und Wassereinlagerung in den ersten Wochen, dazu ein im Blutbild messbarer IGF-1-Anstieg. Belegt ist damit, dass die Hormonachse reagiert – nicht, dass daraus der beworbene Nutzen folgt.', quellen: 'Anwenderkreise · IGF-1-Selbstmessungen' },
    beleg: 'Teichman et al. (J Clin Endocrinol Metab 2006) berichten zwei randomisierte, placebokontrollierte, doppelblinde Studien an Gesunden über 28 und 49 Tage: nach einer Gabe GH 2- bis 10-fach für 6 Tage oder länger, IGF-1 1,5- bis 3-fach für 9 bis 11 Tage, Halbwertszeit 5,8 bis 8,1 Tage, keine schweren Nebenwirkungen. Ionescu & Frohman (2006) zeigten, dass die Pulse erhalten bleiben und der Anstieg über den Talspiegel läuft (7,5-fach). Damit ist die Wirkkette bis IGF-1 am Menschen quantifiziert, klinische Endpunkte fehlen aber ganz: Die einzige Phase-2-Studie (NCT00267527) wurde 2006 nach einem Todesfall mit ungeklärtem Zusammenhang abgebrochen, Ergebnisse gibt es nicht, eine Zulassung gab es nie. Was dauerhaft erhöhtes IGF-1 langfristig bedeutet, ist nicht untersucht; die FDA nennt schwerwiegende Ereignisse wie erhöhten Puls und Gefäßerweiterungsreaktionen. In Deutschland kein verkehrsfähiges Arzneimittel, auf der WADA-Verbotsliste.' },
  { id: 'mod-grf-1-29', view: 'experimental', evidenz: 0, mechanismus: 5, sicherheit: 1, hype: 1, anwendung: 3, richtung: 'offen', berichtslage: { stufe: 2, kurz: 'Tieferer Schlaf, IGF-1 messbar hoch', was: 'Wie in der ganzen Gruppe der GH-Sekretagoga: übereinstimmend berichtet werden tieferer Schlaf und Wassereinlagerung in den ersten Wochen, dazu ein im Blutbild messbarer IGF-1-Anstieg. Belegt ist damit, dass die Hormonachse reagiert – nicht, dass daraus der beworbene Nutzen folgt.', quellen: 'Anwenderkreise · IGF-1-Selbstmessungen' },
    beleg: 'Zu dieser konkreten Verbindung wurden keine eigenen Humanstudien gefunden; eine klinische Übersicht von 2026 (Dominikowski) bestätigt das und stuft CJC-1295 ohne DAC in die unterste von vier Evidenzstufen ein, ohne veröffentlichte Halbwertszeit beim Menschen. Die gesamte Wirkannahme wird aus Daten zu Sermorelin und anderen GRF(1-29)-Analoga abgeleitet, etwa einer Studie, in der ein verwandtes Analogon bei 19 Älteren GH und IGF-1 über Wochen anhob (Khorram 1997) – das ist eine Übertragung, kein Beleg. Dass solche Übertragungen scheitern können, zeigt Aitman 1989: Ein im Tier superaktives GRF-Analogon war beim Menschen nicht wirksamer als das unveränderte Peptid. Sicherheitsdaten am Menschen existieren nicht. In Deutschland Forschungschemikalie ohne Arzneimittelstatus. Die zugehörige Podcastfolge wurde aus dem Bestand genommen, weil das Thema in einer späteren Folge sauberer behandelt wurde.' },
  { id: 'ghrp-2', view: 'experimental', evidenz: 4, mechanismus: 7, sicherheit: 4, hype: 2, anwendung: 3, richtung: 'gemischt', berichtslage: { stufe: 2, kurz: 'Tieferer Schlaf, kaum Hungerschub', was: 'Wie in der ganzen Gruppe der GH-Sekretagoga: übereinstimmend berichtet werden tieferer Schlaf, Wassereinlagerung und ein im Blutbild messbarer IGF-1-Anstieg. Der bei GHRP-6 typische Hungerschub wird hier deutlich seltener berichtet – ein Unterschied, den Anwender konsistent beschreiben.', quellen: 'Anwenderkreise · IGF-1-Selbstmessungen' },
    beleg: 'Dass GHRP-2 beim Menschen kräftig Wachstumshormon freisetzt, ist so sicher belegt, dass es in Japan als Diagnostikum dient (Chihara 2007, 77 Gesunde, 58 Patienten). Unter 30 Tagen Dauerinfusion bei gesunden Älteren stiegen GH und IGF-1 anhaltend (Bowers 2004, 17 Teilnehmer), bei kritisch Kranken normalisierte es IGF-1 (Van den Berghe 2002, RCT, 33 Männer). Die größte kontrollierte Studie verfehlte aber den klinischen Endpunkt: Bei 126 Kindern mit Wachstumshormonmangel stiegen über 48 Wochen weder Wachstum noch IGF-1 (Tanaka 2014, doppelblind). Gut belegt ist die Appetitsteigerung (Laferrère 2005, 35,9 % mehr Nahrung), ebenso der Mitanstieg von Prolaktin, ACTH und Cortisol (Arvat 1997). Für Muskelaufbau oder Fettabbau bei Gesunden gibt es keine Studie, Langzeitsicherheitsdaten fehlen, und die FDA führt GHRP-2 zur Injektion und als Nasenspray seit 2023 in Kategorie 2 der 503B-Übergangsregelung, als Wirkstoff mit möglichen erheblichen Sicherheitsrisiken.' },
  { id: 'ghrp-6', view: 'experimental', evidenz: 4, mechanismus: 6, sicherheit: 3, hype: 2, anwendung: 3, richtung: 'offen', berichtslage: { stufe: 3, kurz: 'Heftiger Hunger binnen Minuten', was: 'Ein Effekt wird nahezu ausnahmslos berichtet: ein heftiger Hungerschub binnen Minuten nach der Injektion. Er ist dosisabhängig, zeitlich eng an die Gabe gekoppelt und passt exakt zum Mechanismus am Ghrelin-Rezeptor. Spezifischer kann eine Anwenderbeobachtung kaum sein. Über den beworbenen Nutzen – Muskelaufbau, Regeneration – sagt sie allerdings nichts.', quellen: 'Anwenderkreise · deckungsgleich mit dem bekannten Mechanismus' },
    beleg: 'Evidenz 4 (bisher 2): Es gibt mehrere kleine Humanstudien, aber nur mit dem Zwischenschritt Wachstumshormon im Blut. Bei 18 gesunden Männern setzte GHRP-6 dosisabhängig Wachstumshormon frei, mit GHRH synergistisch (J Clin Endocrinol Metab 1990); als Kombinationstest mit GHRH trennte es in einer Lancet-Studie mit 125 Patienten und 125 Gesunden zuverlässig zwischen normaler Funktion und Wachstumshormonmangel (2000); die Pharmakokinetik ist an 9 gesunden Männern vermessen (2013). Kontrollierte Studien zu Muskelaufbau, Fettabbau, Regeneration oder Longevity gibt es nicht; eine Übersicht von 2026 stuft GHRP-6 als Wirkstoff mit Phase-1- und kleinen mechanistischen Humanstudien ohne kontrollierte Wirksamkeitsdaten ein. Mechanismus 6: Ghrelin-Rezeptor am Menschen beschrieben, GH-Freisetzung gemessen. Sicherheit 3 (bisher 2): nur Kurzzeit- und Einzelgabedaten ohne klinische Nebenwirkungen, Prolaktin und Cortisol steigen bei hohen Gaben, keine Langzeitdaten. Keine Zulassung, WADA-Verbotsliste. Korrektur am Bestand: Der frühere Beleg nannte eine kubanische Phase-I-Studie als einzige Humanstudie; tatsächlich gibt es mehrere, und die dort genannten Ereigniszahlen ließen sich an keiner zugänglichen Quelle prüfen.' },
  { id: 'hexarelin', view: 'experimental', evidenz: 4, mechanismus: 7, sicherheit: 3, hype: 2, anwendung: 2, richtung: 'gemischt',
    beleg: 'Für ein Graumarkt-Peptid ungewöhnlich viele Humandaten – alle aus den 1990ern von derselben Turiner Gruppe (Ghigo, Arvat) in J Clin Endocrinol Metab und anderen: Dosis-Wirkungs-Studien zur Wachstumshormonfreisetzung, kardiale Effekte bei Hypophyseninsuffizienz, akute Hämodynamik während Bypass-Operationen. Die klinische Entwicklung wurde nach den Arbeiten der Neunzigerjahre nicht weitergeführt; im US-Studienregister ist keine Studie eingetragen (Stand 24.09.2026). Die beworbene Kardioprotektion stützt sich auf Rattenmodelle und akute Surrogatparameter, nicht auf klinische Endpunkte.' },
  { id: 'igf-1-lr3', view: 'experimental', evidenz: 0, mechanismus: 5, sicherheit: 1, hype: 1, anwendung: 3, richtung: 'offen',
    beleg: 'Die Substanz wurde nie als Arzneimittel für Menschen entwickelt – sie entstand als Zellkultur-Reagenz, das die IGF-Bindungsproteine umgehen sollte. Kontrollierte Humanstudien wurden nicht gefunden. Die theoretischen Risiken – Unterzuckerung durch Kreuzreaktivität am Insulinrezeptor, Wachstumsstimulation von Tumorgewebe – ergeben sich aus der IGF-1-Physiologie und wurden für diese Verbindung am Menschen nie geprüft. Kein Arzneimittel in Deutschland; IGF-1-Analoga stehen auf der WADA-Verbotsliste.' },
  { id: 'enclomiphene', view: 'experimental', evidenz: 7, mechanismus: 9, sicherheit: 4, hype: 5, anwendung: 4, richtung: 'positiv',
    beleg: 'evidenz 7: Zwei parallele, randomisierte, doppelblinde Phase-3-Studien mit 256 Männern über 16 Wochen und eine Übersichtsarbeit über 10 RCTs mit 819 Männern – aber ausschließlich Surrogatendpunkte, GRADE mittel wegen breiter Konfidenzintervalle und hoher Heterogenität. mechanismus 9: Die Wirkkette ist am Menschen durchgehend quantifiziert – LH und FSH steigen mit p unter 0,001, Testosteron nach 16 Wochen 430 bis 445 ng/dl gegenüber 214 bis 236 ng/dl unter Placebo, Spermienkonzentration plus 11 bis 15 Prozent statt minus 33 bis 57 Prozent unter Gel. sicherheit 4: nur Kurzzeitdaten – 16 Wochen an 256 Männern, die Übersichtsarbeit nennt ihre Sicherheitsanalyse selbst unterpowert; zum Vergleich beobachtete TRAVERSE 5246 Männer über etwa 33 Monate. hype 5: Der beworbene Mechanismus stimmt und der Fertilitätsvorteil ist real, aber die Darstellung als zulassungsreife und sicherere TRT-Alternative ist doppelt überdehnt – beim Testosteronspiegel liegt der Unterschied zum Gel bei 5,4 ng/dl (p = 0,83), und zugelassen ist die Substanz nirgends. anwendung 4: verbreitet über Rezepturherstellung und Graumarkt, ohne regulatorischen Rahmen. richtung positiv statt „gemischt" (kein zulässiger Wert): Die vorliegenden Daten stützen die beanspruchten Effekte auf Testosteron, LH, FSH und Spermienerhalt; sie sprechen nicht dagegen. Offen – nicht widerlegt – bleibt der klinische Nutzen, da nur 2 von 10 Studien Symptome erhoben haben. Korrektur am Bestand: Die Ablehnung erfolgte am 1.12.2015 (nicht 2016) und wurde mit dem Studiendesign begründet, nicht mit kardiovaskulären Sicherheitsdaten; der Testosteronanstieg beträgt laut Skript 274 ng/dl (nicht 273,8), und die Übersichtsarbeit fasst Clomifen und Enclomifen gemeinsam zusammen.',
    berichtslage: { stufe: 2, kurz: 'Besser gefühlt – ohne Vergleichsgruppe', was: 'In Klinikauswertungen berichten die meisten Männer unter Clomifen über weniger Beschwerden; nach dem Wechsel auf Enclomifen klagen sie seltener über Libido, Energie und Stimmung. Das passt zum Mechanismus mit weniger östrogenartigem Isomer, ist aber nicht kontrolliert: In der einzigen placebokontrollierten Clomifen-Studie mit Beschwerde-Fragebogen besserte sich auch die Placebogruppe.', quellen: 'J Urol 2019 · Transl Androl Urol 2024 · Meta-Analyse Arch Endocrinol Metab 2025' } },
  { id: 'kisspeptin', view: 'experimental', evidenz: 5, mechanismus: 7, sicherheit: 3, hype: 2, anwendung: 2, richtung: 'offen', berichtslage: { stufe: 1, kurz: 'Wenige Berichte, kein Muster', was: 'Es gibt Berichte über gesteigerte Erregbarkeit kurz nach der Anwendung, aber wenige – die Anwenderbasis ist klein. Für ein Muster reicht das nicht.', quellen: 'vereinzelte Anwenderberichte' },
    beleg: 'Evidenz 5 (bisher 3): Es gibt mehrere kleine randomisierte Studien am Menschen, allerdings mit Einmalgaben und Surrogat- oder Sekundärendpunkten. In zwei doppelblinden Crossover-Studien veränderte eine einmalige Infusion von Kisspeptin-54 die Hirnverarbeitung sexueller Reize bei Frauen und Männern mit vermindertem sexuellem Verlangen (JAMA Netw Open 2022 und 2023, je 32 Abschlüsse); bei den Männern nahm die Erektion um bis zu 56 Prozent stärker zu als unter Placebo. Eine Crossover-Studie mit 95 gesunden Probanden (J Clin Endocrinol Metab 2025) bestätigt einen robusten LH-Anstieg ohne Effekt auf Angst, Cortisol, Blutdruck oder Herzfrequenz. Die längste kontrollierte Anwendung von Kisspeptin-10 lief über 12 Tage (Eur J Endocrinol 2026): Gaben mit Pausen hielten LH und FSH erhöht, eine Dauerinfusion über 5 Tage nicht. Zur wiederholten Selbstanwendung für Libido, zum Einsatz rund um eine Testosterontherapie oder zum Hormon-Restart existieren keine Daten. Korrektur am Bestand: Der frühere Beleg nannte für Libido keine Daten; die beiden JAMA-Network-Open-Studien belegen einen Effekt der einmaligen Infusion.' },
  { id: 'gonadorelin', view: 'experimental', evidenz: 6, mechanismus: 9, sicherheit: 7, hype: 4, anwendung: 8, richtung: 'gemischt',
    beleg: 'Die pulsatile Stimulation der Hypophysen-Gonaden-Achse ist am Menschen vollständig verstanden und seit Jahrzehnten diagnostisch und therapeutisch im Einsatz; Studien zur Pumpentherapie bei angeborenem hypogonadotropem Hypogonadismus zeigen eine frühere Spermatogenese als unter zyklischer Gonadotropintherapie. Der heute im Biohacking beworbene Einsatz ist ein anderer: als Zusatz zu einer Testosterontherapie bei sonst gesunden Männern. Für diese Kombination wurden keine kontrollierten Langzeitdaten gefunden.' },
  { id: 'hcg', view: 'experimental', evidenz: 8, mechanismus: 9, sicherheit: 9, hype: 4, anwendung: 9, richtung: 'gemischt',
    beleg: 'Seit Jahrzehnten zugelassen und mechanistisch klar: Über den LH-Rezeptor erhält hCG die Leydigzellfunktion. Eine Übersicht (Transl Androl Urol 2018) fasst Studien zusammen, in denen zuvor azoosperme Männer nach im Mittel vier Monaten wieder auf durchschnittlich 22 Millionen Spermien pro Milliliter kamen. Die Kombination mit einer Testosterontherapie zum Fertilitätserhalt ist mechanistisch gut begründet, aber Off-Label; am Menschen gestützt durch eine kleine randomisierte Studie zum Testosteron im Hoden (Coviello 2005) und eine retrospektive Auswertung, in der keiner von 26 Männern azoosperm wurde (Hsieh 2013), kontrollierte Fruchtbarkeitsdaten fehlen. Die als hCG-Diät verbreitete Anwendung zur Gewichtsreduktion ist dagegen widerlegt: 14 randomisierte Studien mit 605 Teilnehmern, in 12 davon kein Vorteil gegenüber Placebo oder Diät allein.' },
  { id: 'pt-141', view: 'experimental', evidenz: 6, mechanismus: 7, sicherheit: 6, hype: 3, anwendung: 4, richtung: 'gemischt',
    beleg: 'Zugelassen ist die Substanz seit 2019 in den USA – für prämenopausale Frauen mit erworbener Luststörung, belegt durch zwei randomisierte Phase-III-Studien des RECONNECT-Programms mit 1.267 Frauen (Kingsberg et al., Obstet Gynecol 2019) und eine offene Verlängerung über 52 Wochen ohne neue Sicherheitssignale (Simon 2019); der Effekt ist statistisch klar, im Ausmaß moderat. Beworben wird sie im Biohacking überwiegend für Männer. Dafür gibt es kein Zulassungsprogramm, aber kleinere kontrollierte Studien mit Erektionsantwort (Rosen 2004; Diamond 2005); die größte Männerstudie (Safarinejad 2008, 342 Männer) steht seit 2023 unter einer Expression of Concern der Zeitschrift. Die dokumentierten Nebenwirkungen stammen aus der Frauenpopulation: Übelkeit bei 40 Prozent, kurzzeitiger Blutdruckanstieg nach jeder Gabe und fokale Hyperpigmentierung bei 1 Prozent. In Deutschland nicht zugelassen.' },
  { id: 'tadalafil', view: 'experimental', evidenz: 10, mechanismus: 9, sicherheit: 9, hype: 7, anwendung: 10, richtung: 'positiv',
    beleg: 'Eine der am besten belegten Substanzen im gesamten Bestand: seit 2003 zugelassen für erektile Dysfunktion, dazu für die gutartige Prostatavergrößerung und die pulmonale arterielle Hypertonie, jeweils auf Basis umfangreicher Phase-III-Programme. Die PDE5-Hemmung ist am Menschen quantitativ verstanden. Über zwei Jahrzehnte Pharmakovigilanz liefern ein klares Warnprofil – Nitrat-Interaktion, Sehstörungen, Priapismus. Der Abzug betrifft nur die Randvermarktung als allgemeiner Gefäß-Longevity-Wirkstoff, für die es keine Zulassungsstudien gibt.' },
  { id: 'sildenafil', view: 'experimental', evidenz: 10, mechanismus: 9, sicherheit: 9, hype: 7, anwendung: 10, richtung: 'positiv',
    beleg: 'Seit 1998 zugelassen, auf Basis der Zulassungsstudien um Goldstein et al. (NEJM 1998) mit signifikanter Verbesserung der Erektionsfunktion gegenüber Placebo, später zusätzlich für die pulmonale arterielle Hypertonie. Die PDE5-Hemmung gehört zu den am besten charakterisierten Wirkketten der Pharmakologie. Über 25 Jahre Marktüberwachung liefern ein vollständiges Risikoprofil, einschließlich der Nitrat-Kontraindikation. Beworben wird zunehmend auch ein allgemeiner Durchblutungs- und Anti-Aging-Nutzen – dafür existieren keine Zulassungsdaten.' },
  { id: 'orforglipron', view: 'experimental', evidenz: 9, mechanismus: 9, sicherheit: 7, hype: 5, anwendung: 4, richtung: 'positiv',
    beleg: 'Die Phase-III-Studie ATTAIN-1 (NEJM 2025) randomisierte 3127 Teilnehmer über 72 Wochen: 11,2 Prozent Gewichtsreduktion in der höchsten Dosis gegenüber 2,1 Prozent unter Placebo; der Hersteller nennt 12,4 Prozent für Teilnehmer, die die Behandlung fortführten. Weitere Phase-III-Studien zeigen eine deutliche HbA1c-Senkung und eine Überlegenheit gegenüber oralem Semaglutid beim Blutzucker. Als erster oral verfügbarer nicht-peptidischer GLP-1-Rezeptoragonist ist die Wirkkette am Menschen über Studienendpunkte bestätigt, harte kardiovaskuläre Endpunkte stehen aus. Die Abbruchrate wegen Nebenwirkungen liegt dosisabhängig bei 5,3 bis 10,3 Prozent. Seit 1. April 2026 in den USA zugelassen, in der EU nicht.' },
  { id: 'cagrilintide', view: 'experimental', evidenz: 8, mechanismus: 8, sicherheit: 7, hype: 5, anwendung: 4, richtung: 'positiv',
    beleg: 'REDEFINE 1 (NEJM 2025) randomisierte 3.417 Teilnehmer über 68 Wochen und erreichte 20,4 Prozent Gewichtsreduktion gegenüber 3,0 Prozent unter Placebo, bei voller Therapietreue 22,7 Prozent. Bemerkenswert ist, was danach passierte: Das intern kommunizierte Ziel von 25 Prozent wurde verfehlt, was den Aktienkurs bewegte – die Zahl selbst bleibt eine der höchsten, die je in einer Adipositasstudie erreicht wurde. Die Kombination aus Amylin-Analogon und Semaglutid ist am Menschen bestätigt. Abbruch wegen Nebenwirkungen: 6 gegenüber 3,7 Prozent. Im direkten Vergleich mit Tirzepatid (REDEFINE 4, 84 Wochen) verfehlte CagriSema mit 23,0 gegenüber 25,5 Prozent die Nichtunterlegenheit.' },
  { id: 'amycretin', view: 'experimental', evidenz: 5, mechanismus: 8, sicherheit: 4, hype: 3, anwendung: 2, richtung: 'positiv',
    beleg: 'Die vielzitierten 24,3 Prozent Gewichtsreduktion stammen aus einer placebokontrollierten Phase-1b/2a-Studie mit 125 Teilnehmern über bis zu 36 Wochen (Lancet 2025), deren primärer Endpunkt die Sicherheit war – eine frühe, kleine Studie, keine Zulassungsevidenz. Alle Dosisstufen senkten das Gewicht signifikant stärker als Placebo; die Tablette erreichte in der ersten Studie am Menschen bis zu 13,1 Prozent nach 12 Wochen. Magen-Darm-Beschwerden waren häufig und dosisabhängig, 33 Prozent schieden aus der Studie aus (59 Prozent davon aus Gründen ohne Bezug zu Nebenwirkungen), es gab einen Fall einer Gallenstein-Pankreatitis. Die Phase-2-Daten bei Typ-2-Diabetes (448 Teilnehmer) liegen nur als Firmenmitteilung vor. Der Mechanismus als kombinierter GLP-1- und Amylin-Rezeptoragonist ist am Menschen bestätigt. Die Zahl wird in der Vermarktung regelmäßig ohne diesen Kontext zitiert, und Graumarkt-Angebote können das Originalmolekül nicht enthalten.' },
  { id: 'survodutide', view: 'experimental', evidenz: 8, mechanismus: 8, sicherheit: 6, hype: 4, anwendung: 3, richtung: 'gemischt',
    beleg: 'SYNCHRONIZE-1 (NEJM 2026) randomisierte 725 Teilnehmer über 76 Wochen: 12,2 bis 13,0 Prozent Gewichtsreduktion gegenüber 5,4 Prozent unter Placebo, beide primären Endpunkte erreicht. Bemerkenswert ist die hohe Placebo-Antwort, die den Abstand kleiner macht. SYNCHRONIZE-MASLD (Nat Med 2026, 216 Teilnehmer, 48 Wochen) erreichte beide co-primären Endpunkte: mindestens 30 Prozent weniger Leberfett bei 84,2 gegenüber 24,3 Prozent, und laut Mediationsanalyse der Phase-2-MASH-Studie ist die Wirkung auf Entzündung und Fibrose überwiegend nicht über die Gewichtsabnahme vermittelt – der stärkste Punkt dieser Substanz. Der auffällige Wert steht in der Sicherheitsspalte: Magen-Darm-Beschwerden bei 80,9 und 89,7 Prozent gegenüber 47,9 Prozent unter Placebo, und in der Phase-2-Studie beendeten nur 60,4 Prozent die 46 Wochen, in Wirkstoff- und Placebogruppe ähnlich. Konkrete Abbruchraten wegen Nebenwirkungen liegen nicht öffentlich vor (Volltexte nicht zugänglich, keine Registerergebnisse). Der duale Glukagon- und GLP-1-Rezeptoragonismus ist am Menschen bestätigt. Beworben wird Gleichrangigkeit mit Tirzepatid, obwohl ein direkter Vergleich nicht publiziert ist; ebenso fehlen die Ergebnisse der abgeschlossenen kardiovaskulären Studie mit 5531 Teilnehmern.' },
  { id: 'maritide', view: 'experimental', evidenz: 6, mechanismus: 8, sicherheit: 5, hype: 4, anwendung: 3, richtung: 'gemischt',
    beleg: 'Die Phase-II-Studie (NEJM 2025, NCT05669599) umfasste 592 Teilnehmer in 11 Gruppen über 52 Wochen und erreichte ihren primären Endpunkt: 12,3 bis 16,2 Prozent Gewichtsreduktion ohne Diabetes gegenüber 2,5 Prozent unter Placebo, mit Diabetes 8,4 bis 12,3 Prozent gegenüber 1,7 Prozent, HbA1c minus 1,2 bis minus 1,6 Prozentpunkte. Die oft zitierten Werte um 20 Prozent stehen so nicht in der Publikation – erreicht haben mindestens 20 Prozent Abnahme 23,4 bis 38,5 Prozent der Behandelten, unter Placebo niemand. Das Besondere ist die monatliche Gabe, ermöglicht durch die Kopplung von Peptid und Antikörper. Wenig beworben wird der Verlust an fettfreier Masse: 8,6 bis 11,6 Prozent, per DXA gemessen, gegenüber 2,1 Prozent unter Placebo. Phase III läuft breit, darunter eine kardiovaskuläre Endpunktstudie mit 12.800 geplanten Teilnehmern; publizierte Daten über ein Jahr hinaus und jeder direkte Vergleich mit Semaglutid oder Tirzepatid fehlen, zum zweiten Studienjahr gibt es bisher nur Herstellerangaben. Das Bequemlichkeitsargument wird beworben, bevor die Bestätigungsstudien vorliegen.' },
  { id: 'mazdutide', view: 'experimental', evidenz: 8, mechanismus: 8, sicherheit: 6, hype: 4, anwendung: 4, richtung: 'positiv',
    beleg: 'Vier publizierte Phase-3-Studien haben ihre primären Endpunkte erreicht: GLORY-1 (NEJM 2025) randomisierte 610 chinesische Erwachsene über 48 Wochen, mit 11,00 bis 14,01 Prozent Gewichtsreduktion gegenüber plus 0,30 Prozent unter Placebo; GLORY-2 (JAMA 2026) zeigte mit höherer Dosis 16,65 Prozent nach 60 Wochen, gegenüber minus 1,50 Prozent. Bei Typ-2-Diabetes senkte Mazdutide den HbA1c gegenüber Placebo (DREAMS-1, 320) und stärker als Dulaglutid (DREAMS-2, 731). In China ist die Substanz für Adipositas und Typ-2-Diabetes zugelassen. Der duale GLP-1- und Glukagon-Rezeptoragonismus ist am Menschen bestätigt, ein höherer Energieverbrauch nicht gemessen. Die Phase-3-Studien liefen ausschließlich in China, außerhalb gibt es eine US-Phase-2 mit 179 Teilnehmern; in Deutschland gibt es keine Zulassung – ein Punkt, den Vertriebsseiten regelmäßig auslassen.' },
  { id: 'tesofensin', view: 'experimental', evidenz: 5, mechanismus: 7, sicherheit: 4, hype: 3, anwendung: 3, richtung: 'gemischt', berichtslage: { stufe: 2, kurz: 'Appetit weg, oft am ersten Tag', was: 'Übereinstimmend berichtet wird eine deutliche Appetitdämpfung, häufig schon am ersten Tag. Das deckt sich mit der publizierten Phase-II-Studie und mit dem Wirkmechanismus als Wiederaufnahmehemmer – ein rasch spürbarer Effekt ist hier zu erwarten und kein Rätsel.', quellen: 'Anwenderkreise · deckungsgleich mit publizierter Studienlage' },
    beleg: 'Die belastbarste veröffentlichte Studie stammt aus dem Jahr 2008: Astrup et al. (Lancet) zeigten an 203 Patienten über 24 Wochen eine dosisabhängige Gewichtsreduktion von 4,5 bis 10,6 Prozent gegenüber 2,0 Prozent unter Placebo. Phase-3-Ergebnisse existieren laut Herstellerangaben, sind aber nicht als begutachtete Vollpublikation auffindbar – die Werbung stützt sich damit auf Pressemitteilungen, und eine behauptete Zulassung in Mexiko ist bislang nicht erteilt. Die Substanz wurde ursprünglich gegen Alzheimer entwickelt und blieb dort in einer Phase-IIb-Studie an 430 Patienten ohne Wirkung; der Puls stieg in der mittleren Dosis um 7,4 Schläge pro Minute. In Deutschland nicht zugelassen.' },
  { id: '5-amino-1mq', view: 'experimental', evidenz: 0, mechanismus: 5, sicherheit: 1, hype: 3, anwendung: 2, richtung: 'offen',
    beleg: 'Evidenz 0, weil es keine publizierte Humanstudie gibt und Abfragen der ClinicalTrials.gov-API zu 5-Amino-1MQ und zu NNMT-Inhibitoren keinen Registereintrag zurückgeben. Die gesamte Erzählung beruht auf Zellversuchen und Mausmodellen: NNMT-Knockdown im Fettgewebe (Kraus et al., Nature 2014), Wirkstoffgabe über 11 Tage mit 2,0 g Gewichtsverlust gegenüber 0,6 g Zunahme in der Kontrolle bei unverändertem Futterverzehr (Neelakantan et al. 2018), Kraftzuwachs alter Mäuse (2019, 2024) und bessere Glukosetoleranz über 28 Tage (Babula et al. 2024). Mechanismus 5, weil die Wirkkette in Zellkultur und Tier quantifiziert ist – 1-Methylnicotinamid runter, NAD+ und SAM rauf, Selektivität gegen verwandte Methyltransferasen geprüft –, am Menschen aber nichts davon bestätigt wurde; zudem trat in einer parallelen Substanzreihe die Glukosewirkung auch bei NNMT-Knockout-Mäusen auf (Ruf et al. 2022), der Effekt ist also nicht sicher allein NNMT zuzuordnen. Sicherheit 1, weil am Menschen nichts untersucht ist und die Pharmakokinetik aus Ratten stammt. Hype 3, weil die Vermarktung echte Mauszahlen ohne das Wort Maus weiterreicht und aus dem Griffkraft-Befund an 24 Monate alten Tieren ein besser als Sport macht. Anwendung 2, weil die Substanz nur in Studien und in Graumarktkreisen vorkommt. Korrektur am Bestand: Die Angabe -7 Prozent Fettmasse in 11 Tagen steht so nicht in der Originalarbeit (dort 2,0 g beziehungsweise 5,1 Prozent Körpergewicht, etwa 35 Prozent Bauchfett), und die im Eintrag verlinkte Nature-Scientific-Reports-DOI gehört zu einer themenfremden Arbeit.' },
  { id: 'slu-pp-332', view: 'experimental', evidenz: 0, mechanismus: 5, sicherheit: 1, hype: 1, anwendung: 3, richtung: 'offen', berichtslage: { stufe: 2, kurz: 'Ausdauer rasch spürbar, Zuordnung offen', was: 'Übereinstimmend berichtet wird ein rasch spürbarer Ausdauereffekt, teilweise an eigenen Zeiten gemessen. Ein schneller Effekt passt zum Mechanismus – im Tierversuch wirkte bereits eine einzelne Gabe eine Stunde vor dem Laufen. Offen bleibt die Zuordnung: Ob die in der Szene üblichen Mengen und Wege Wirkspiegel wie im Tierversuch erreichen, hat niemand gemessen, und über den Mund ist die Substanz laut ihren Entwicklern nicht bioverfügbar.', quellen: 'Anwenderkreise · Selbstmessungen' },
    beleg: 'Hier steht nicht „geprüft und widerlegt“, sondern „nicht geprüft“: Es gibt keine Humanstudie, nur Tier- und Zellarbeiten. Diese sind allerdings solide. Nach einer einzigen Gabe liefen Mäuse rund 70 % länger und 45 % weiter, übergewichtige Mäuse wogen nach 28 Tagen rund 12 % weniger (Billon 2023, 2024). Mechanismus 5, weil die Abhängigkeit vom Zielrezeptor genetisch gezeigt ist – ohne ERRα im Muskel kein Ausdauergewinn – und erste Daten an menschlichen Muskelvorläuferzellen vorliegen (Bonanni 2025); eine Bestätigung am lebenden Menschen fehlt. Evidenz 0 und Sicherheit 1, weil es weder klinische Wirksamkeits- noch Sicherheitsdaten gibt, im Tier nur Kurzzeitbefunde über 10 Tage. Die Entwickler halten selbst fest, dass SLU-PP-332 nicht oral bioverfügbar ist, und entwickelten deshalb SLU-PP-915 (Billon 2026) – verkaufte Tabletten haben damit keine Grundlage. Hype 1, weil „Sport in der Spritze“ als Versprechen für Menschen auftritt, obwohl die Daten nur von Mäusen stammen. Anwendung 3: in einer Nische als Research-Ware im Umlauf, ohne Studien am Menschen.' },
  { id: 'acarbose', view: 'experimental', evidenz: 8, mechanismus: 8, sicherheit: 9, hype: 4, anwendung: 9, richtung: 'gemischt',
    berichtslage: { stufe: 1, kurz: 'Flachere Kurve auf dem Sensor, Blähungen als Preis', was: 'In der einzigen Pilotstudie an Gesunden (12 Personen mit Glukosesensor, vom Anbieter finanziert) fiel der Zuckergipfel nach einer stärkereichen Mahlzeit um gut 17 Prozent niedriger aus, ohne Unterschied bei den Beschwerden. Auf einem amerikanischen Bewertungsportal (nur 7 Bewertungen, keine Statistik) sind Blähungen das wiederkehrende Thema, die bei manchen nachlassen; fünf der sieben vergeben 8 bis 10 von 10 Punkten. In der großen ACE-Studie blieb die Lebensqualität über Jahre unverändert. Eine publizierte Auswertung von Longevity-Anwendern fehlt.', quellen: 'Isman 2023 (Transl Med Aging) · drugs.com (7 Bewertungen) · Leal 2022 (J Diabetes)' },
    beleg: 'Ein seit Jahrzehnten zugelassenes Diabetesmedikament mit klar verstandener Wirkung – die Hemmung der Alpha-Glukosidase im Darm. Die ACE-Studie mit 6.522 Erwachsenen über im Mittel fünf Jahre senkte die Diabetesinzidenz von 16 auf 13 Prozent, verfehlte den kardiovaskulären Hauptendpunkt aber vollständig: Hazard Ratio 0,98 bei einem p-Wert von 0,73. In der Longevity-Szene wird die Substanz als Kalorienrestriktions-Mimetikum gehandelt – eine Extrapolation aus Mausdaten.' },
  { id: 'canagliflozin', view: 'experimental', evidenz: 9, mechanismus: 9, sicherheit: 9, hype: 3, anwendung: 8, richtung: 'gemischt',
    beleg: 'Seit 2013 in der EU zugelassen, mit dem CANVAS-Programm (NEJM 2017) als kardiovaskulärer Endpunktstudie – die Wirkung über die renale Glukoseausscheidung ist vollständig verstanden. Genau diese hervorragende Datenlage macht den Punkt: In CANVAS traten unter Canagliflozin mehr Amputationen an Zehen und Unterschenkeln sowie mehr Frakturen auf, dazu genitale Pilzinfektionen und selten Ketoazidosen. Der Gewichtseffekt liegt bei zwei bis drei Prozent. Im Longevity-Marketing als Kalorienrestriktions-Mimetikum kommen diese dokumentierten Risiken praktisch nie vor.' },
  { id: 'glp-3', view: 'experimental', evidenz: 2, mechanismus: 8, sicherheit: 1, hype: 1, anwendung: 4, richtung: 'offen',
    beleg: 'Hier ist die Trennung zwischen Wirkprinzip und Produkt entscheidend: Bewertet wird die als „GLP-3“ verkaufte Graumarkt-Ware, nicht das pharmazeutische Retatrutid von Eli Lilly. Das Prinzip, der Dreifach-Agonismus an GLP-1-, GIP- und Glucagon-Rezeptoren, ist am Menschen sehr gut belegt: Retatrutid erreichte in Phase 2 bis zu 24,2 Prozent Gewichtsverlust nach 48 Wochen (Jastreboff 2023) und laut Hersteller in TRIUMPH-1 mit 2.339 Teilnehmern bis zu 28,3 Prozent nach 80 Wochen, in TRIUMPH-2 bei Typ-2-Diabetes bis zu 20,8 und in TRIUMPH-3 bei schwerer Adipositas mit Herz-Kreislauf-Erkrankung bis zu 22,6 Prozent; deshalb steht der Mechanismus hoch, die Bewertung des Wirkstoffs findet sich beim Eintrag Retatrutid. Ein Hormon namens GLP-3 existiert nicht, der Name ist ein Szene-Spitzname, und die Ware ist weder chargenkontrolliert noch identisch mit dem Studienwirkstoff. Zu ihr gibt es inzwischen erste Humandaten, beide nicht begutachtet: In US-Patientenakten verloren Graumarkt-Nutzer im Mittel 7,2 Prozent nach 6 bis 12 Monaten, Studienteilnehmer 15,5 Prozent, bei mehr Herz-Kreislauf-Beschwerden (Murugadoss 2026), und eine Reddit-Auswertung zählte 13.589 Anwender (Sehgal 2026). Die Nutzung ist damit verbreitet und wächst, eine kontrollierte Studie oder Sicherheitsbewertung für die Ware gibt es nicht.' },
  { id: 'adipotide', view: 'experimental', evidenz: 0, mechanismus: 4, sicherheit: 1, hype: 0, anwendung: 0, richtung: 'offen',
    beleg: 'Die beste vorliegende Evidenz ist eine Primatenstudie (Barnhart et al., Science Translational Medicine 2011), in der 10 von 15 adipösen Rhesusaffen über 4 Wochen 7,4 bis 14,7 Prozent Gewicht und im Mittel 38,7 Prozent Körperfett verloren – und in derselben Studie eine dosisabhängige Störung der Nierenkanälchen entwickelten, die sich nach dem Absetzen größtenteils zurückbildete. Eine begutachtete Humanstudie existiert nicht: Die 2012 begonnene Phase-1-Studie NCT01262664 wurde auf Wunsch des Studienleiters abgebrochen, zählte 4 Teilnehmer und stellte keine Ergebnisse ein. Der Mechanismus ist auch im Tier offen, weil die Tiere weniger fraßen und schlanke Tiere kein Gewicht verloren. Die Primatenstudie stammt von einer Gruppe mit Patenten und Firmenanteilen an der Substanz und wurde nie unabhängig wiederholt. Beworben werden die Affenergebnisse, die dokumentierte Nierenwirkung wird dabei regelmäßig weggelassen.' },
  { id: 'aod-9604', view: 'experimental', evidenz: 5, mechanismus: 5, sicherheit: 5, hype: 1, anwendung: 2, richtung: 'negativ',
    beleg: 'Hier gibt es eine große Studie – und sie ist negativ: Die Phase-IIb-Studie mit 534 Teilnehmern über 24 Wochen verfehlte 2007 ihren primären Endpunkt, es gab keinen signifikanten Gewichtsunterschied zu Placebo – nach Firmenangaben; begutachtet veröffentlicht wurde die Studie nie. Die Entwicklung wurde eingestellt, eine Phase III nie begonnen. Werbeseiten zitieren fast ausschließlich die frühe positive Pilotstudie und verschweigen das gescheiterte größere Programm. Sicherheit 5 (bisher 4): Die Sicherheitsdaten der 6 randomisierten Studien erschienen 2013 als gepoolte Auswertung in einer Fachzeitschrift, mitverfasst vom Entwickler.' },
  { id: 'bimagrumab', view: 'experimental', evidenz: 6, mechanismus: 8, sicherheit: 6, hype: 4, anwendung: 3, richtung: 'gemischt',
    beleg: 'Evidenz 6: mehrere randomisierte, doppelblinde Phase-2-Studien mit konsistentem Effekt auf die Körperzusammensetzung. Bei 75 Erwachsenen mit Typ-2-Diabetes sank die Fettmasse über 48 Wochen um 20,5 Prozent (Placebo 0,5), die Magermasse stieg um 3,6 Prozent (JAMA Netw Open 2021). Mit Semaglutid kombiniert verloren 507 Teilnehmer mehr Gewicht als unter Semaglutid allein, bei weitgehend erhaltener Magermasse (Nat Med 2026). Die wichtigere Einschränkung: Bei Sarkopenie (JAMA Netw Open 2020), nach Hüftfraktur (Lancet Healthy Longevity 2021) und bei Einschlusskörpermyositis (Lancet Neurol 2019) nahm die Muskelmasse zu, ohne dass sich Gehen oder Körperfunktion stärker besserten als unter Placebo. Muskelmasse ist nicht dasselbe wie Muskelfunktion. Mechanismus 8: Blockade des Aktivin-Rezeptors, Wirkung auf Fett- und Magermasse am Menschen gemessen. Sicherheit 6 (bisher 5): kontrollierte Daten über 48 Wochen, Verlängerung bis 72 Wochen, eigene Herz-MRT-Studie ohne Auffälligkeit, Meta-Analyse mit mehr Abbrüchen, Muskelkrämpfen, Durchfall und LDL-Anstieg.' },
  { id: 'rad140', view: 'experimental', evidenz: 2, mechanismus: 6, sicherheit: 3, hype: 0, anwendung: 4, richtung: 'offen', berichtslage: { stufe: 3, kurz: 'Muskeln rauf, Testosteron runter', was: 'Berichtet wird übereinstimmend und in beide Richtungen. Auf der Wirkungsseite Kraft- und Muskelzuwachs innerhalb weniger Wochen, häufig mit eigenen Trainingsprotokollen unterlegt. Auf der Schadensseite eine unterdrückte körpereigene Testosteronproduktion, die sich im Blutbild nachmessen lässt, und publizierte Fallberichte über schwere Leberschäden. Beide Seiten sind spezifisch und messbar – das hebt diese Berichtslage deutlich über allgemeines Erfahrungsgefühl.', quellen: 'Anwenderkreise · Blutbild-Selbstmessungen · publizierte Fallberichte (Journal of Medical Case Reports 2023)' },
    beleg: 'Beworben wird die Substanz als nebenwirkungsarme Alternative zu Anabolika – kontrollierte Wirksamkeitsstudien zum Muskelaufbau am Menschen gibt es nicht. Die einzige klinische Humanstudie ist eine offene Phase 1 an 22 Frauen mit metastasiertem Brustkrebs (LoRusso, Clin Breast Cancer 2022): Die Rezeptorwirkung ist über SHBG (gesunken bei 18 von 18), PSA (gestiegen bei 16 von 20) und Tumorbiopsien bestätigt, Muskelmasse wurde nicht gemessen; häufigste Nebenwirkungen waren AST- und ALT-Anstiege (59,1 und 45,5 %), Grad-3/4-Ereignisse traten bei 72,7 % auf. Dazu kommen Mikrodosis-Studien für die Dopinganalytik und mehrere Fallberichte über Leberschäden (u. a. J Med Case Rep 2023) sowie Herzmuskelentzündung. Achsensuppression und HDL-Senkung sind für den verwandten SARM LGD-4033 placebokontrolliert gezeigt. Die FDA warnt für die gesamte SARM-Klasse vor Leberversagen, Herzinfarkt, Schlaganfall und Unfruchtbarkeit. Nur 52 % online verkaufter SARM-Produkte enthielten überhaupt einen SARM (JAMA 2017). Kein zugelassenes Arzneimittel, WADA-Liste 2026 namentlich.' },
  { id: 'follistatin', view: 'experimental', evidenz: 3, mechanismus: 7, sicherheit: 2, hype: 1, anwendung: 2, richtung: 'offen',
    beleg: 'Drei sehr verschiedene Dinge tragen denselben Namen. Die Gentherapie wurde in kleinen Phase-1/2a-Studien bei Muskeldystrophie und Einschlusskörperchen-Myositis geprüft; der Myostatin-Antikörper Apitegromab erreichte in Phase III bei spinaler Muskelatrophie seinen Endpunkt und ist seit September 2026 in den USA dafür zugelassen. Beides sind Behandlungen schwerer Erkrankungen. Zu dem als Follistatin-344 verkauften injizierbaren Peptid wurden keine Humanstudien gefunden. Genau diese Vermischung ist das Problem: Seriöse Krankheitsstudien werden als Beleg für ein anderes, ungeprüftes Produkt herangezogen.' },
  { id: 'selank', view: 'experimental', evidenz: 4, mechanismus: 4, sicherheit: 3, hype: 2, anwendung: 4, richtung: 'offen', berichtslage: { stufe: 2, kurz: 'Angstlösend binnen Minuten', was: 'Wie bei Semax wird ein binnen Minuten nach der Nasenanwendung spürbarer Effekt berichtet, hier angstlösend und ohne Sedierung. Die Berichte stammen aus demselben eng vernetzten Kreis und aus russischer klinischer Anwendung, deren Publikationen westlichen Standards nicht genügen.', quellen: 'Anwenderkreise · russische klinische Anwendung' },
    beleg: 'Für ein Szene-Peptid ungewöhnlich viele Humandaten, aber klein und fast vollständig aus russischsprachigen Fachzeitschriften: Zozulia et al. 2008 verglich bei 62 Patienten mit Angststörung Selank mit Medazepam, Medvedev et al. 2014 bei 60 Patienten mit Phenazepam, Medvedev et al. 2015 bei 70 Patienten Phenazepam allein gegen Phenazepam plus Selank. Die angstlösende Wirkung war vergleichbar, als Zusatz sanken Benzodiazepin-Nebenwirkungen. Verglichen wurde stets gegen ein Benzodiazepin, nicht gegen Placebo – ein Design, das Wirksamkeit nicht sicher beweisen kann. Eine unabhängige westliche Replikation wurde nicht gefunden. Die GABA-Modulation und die BDNF-Beteiligung stammen aus Tiermodellen. Die Verträglichkeit ist nur kurzzeitig in diesen Patientenstudien erfasst; in Deutschland kein zugelassenes Arzneimittel.' },
  { id: 'semax', view: 'experimental', evidenz: 3, mechanismus: 4, sicherheit: 2, hype: 2, anwendung: 5, richtung: 'offen',
    berichtslage: { stufe: 2, kurz: 'Wach und fokussiert binnen Minuten', was: 'Übereinstimmend berichtet wird ein binnen Minuten nach der Nasenanwendung spürbarer Effekt auf Wachheit und Fokus. Die kurze Latenz ist das Belastbare daran. Die Berichte stammen allerdings aus einem eng vernetzten Kreis, und ein Vergleich mit einem Placebo-Spray fehlt vollständig. In Russland gibt es jahrzehntelange klinische Anwendung, deren Publikationen westlichen Standards nicht genügen. Welche Fassung (Semax oder NA-Semax Amidat) gesprüht wird, geht aus den Berichten meist nicht hervor. Das berichtete Zeitfenster deckt sich mit dem Messfenster der einzigen placebokontrollierten fMRT-Studie (5–20 min).', quellen: 'Anwenderkreise · russische klinische Anwendung' },
    beleg: 'In Russland als Arzneimittel registriert, im Westen nicht – und die Evidenz erklärt, warum: Die auffindbaren klinischen Studien, etwa Gusev et al. 1997 mit 30 Patienten nach ischämischem Schlaganfall gegen 80 Kontrollen und 2005 mit 187 Patienten mit chronischer Minderdurchblutung des Gehirns, sind fast ausschließlich russischsprachig und stammen im Wesentlichen aus denselben zwei Arbeitsgruppen. Eine unabhängige Doppelblind-Replikation in einem internationalen Journal wurde nicht gefunden. Die BDNF-Erhöhung als Wirkmechanismus ist vorklinisch gezeigt und am Menschen nur in einer nicht randomisierten Studie gemessen (Gusev 2018, BDNF im Blut), der klinische Nutzen daraus nicht. Keine westliche Pharmakovigilanz. Und die Studienlage gilt für Semax, nicht für das im Handel übliche NA-Semax Amidat. Einzige gefundene placebokontrollierte Humanarbeit: Lebedeva 2018 (24 Gesunde, 14 Semax/10 Placebo, fMRT nach 5 und 20 min, Veränderung im Default-Mode-Netzwerk; Surrogat, Entwickler als Koautor). FDA-Briefing 2026: ischämiebezogene Literatur nur auf Russisch, unkontrollierte Migränestudie, „insufficient evidence of effectiveness“, keine Akut- oder Wiederholungstoxizitätsstudien vorgelegt.' },
  { id: 'cerebrolysin', view: 'experimental', evidenz: 6, mechanismus: 4, sicherheit: 5, hype: 2, anwendung: 7, richtung: 'negativ',
    berichtslage: { stufe: 2, kurz: 'Kliniken Osteuropas berichten Fortschritte', was: 'Aus Kliniken in Russland, Osteuropa und China gibt es seit Jahrzehnten Berichte über Fortschritte in der Rehabilitation nach Schlaganfall, und dort ist das Präparat im Markt. Diese Berichte sind zahlreich, aber sie stammen überwiegend aus demselben Versorgungssystem, das das Mittel einsetzt. Die Cochrane-Bewertung hat dieselbe Frage kontrolliert untersucht und keinen klaren Nutzen gefunden, dafür mehr schwerwiegende Ereignisse. In einer Umfrage aus Nootropika-Foren (Slate Star Codex 2016, n = 22 Anwender) gab fast jeder Vierte die Höchstnote, der Mittelwert lag mit 5,6 von 10 im Mittelfeld; der Autor der Umfrage hält den hohen Anteil an Höchstnoten bei so wenigen Antworten für Zufall. Die Fachinformation nennt eine erwünschte antriebssteigernde Wirkung, selten Unruhe und Schlaflosigkeit.', quellen: 'Kliniken in Osteuropa · Anwenderkreise · Nootropika-Umfrage 2016 · Fachinformation AT' },
    beleg: 'Anders als bei den meisten Peptiden gibt es hier eine Cochrane-Bewertung – und sie fällt ungünstig aus: Für den akuten ischämischen Schlaganfall findet der Review 2023 keinen klaren Nutzen und zusätzlich eine höhere Rate schwerwiegender unerwünschter Ereignisse mit Krankenhausaufnahme. Für vaskuläre Demenz sehen die Cochrane-Autoren eine mögliche kognitive Verbesserung, fordern aber wegen niedriger Evidenzqualität ausdrücklich bessere Studien. In Russland, Osteuropa und China ist das Präparat im Markt, in den USA nicht zugelassen; für Deutschland wurde keine Zulassung ermittelt.' },
  { id: 'mots-c', view: 'experimental', evidenz: 0, mechanismus: 4, sicherheit: 1, hype: 1, anwendung: 4, richtung: 'offen',
    beleg: 'Alle Humandaten sind Messungen des körpereigenen Spiegels: nach dem Training stieg MOTS-c bei 10 jungen Männern im Muskel 11,9-fach (Reynolds, Nat Commun 2021), im Blut ist es bei 70- bis 81-Jährigen um 21 % niedriger, im Muskel dagegen höher (D\'Souza, Aging 2020), bei 107 Patienten nach Herz-Lungen-Maschine gingen niedrigere Werte mit Lungenschädigung einher. Eine abgeschlossene klinische Studie mit Gabe von MOTS-c am Menschen gibt es nicht (USADA); eine placebokontrollierte Phase-2a-Studie mit 120 geplanten Teilnehmern rekrutiert seit Februar 2026 (NCT07505745). Insulinsensitivität, Ausdauer und Gewichtseffekte stammen aus Maus- und Zellmodellen (Lee, Cell Metab 2015; Kim, Cell Metab 2018). Die Verbindung zu Hundertjährigen ist ein Hypothesenpapier zu einer Genvariante (Fuku, Aging Cell 2015). Sicherheitsdaten existieren praktisch nicht. Die Anwendung ist trotzdem verbreitet: Laut USADA wird MOTS-c von Anti-Aging-Kliniken und in sozialen Medien breit beworben; seit 2024 steht es auf der WADA-Liste.' },
  { id: 'ss-31', view: 'experimental', evidenz: 5, mechanismus: 7, sicherheit: 6, hype: 2, anwendung: 3, richtung: 'gemischt',
    beleg: 'Viel geprüft, wenig Ergebnis – und am Ende doch eine Zulassung: Die Phase-III-Studie MMPOWER-3 bei primärer mitochondrialer Myopathie (Neurology 2023) verfehlte beide gleichrangigen Hauptendpunkte. Im September 2025 hat die US-Behörde Elamipretid dennoch für das Barth-Syndrom zugelassen, bei einer Krankheit, die etwa 1 von 350.000 Menschen betrifft: Die randomisierte Crossover-Studie mit 12 Patienten verfehlte ihre Hauptendpunkte, die beschleunigte Zulassung (ab 30 kg) stützt sich auf die Kniestreckerkraft in der offenen Verlängerung mit 10 Patienten; eine Bestätigungsstudie mit 48 Patienten läuft seit Juli 2026. Zur trockenen Makuladegeneration verfehlte eine Phase-2-Studie mit 176 Patienten ihre Hauptendpunkte, eine Phase-3-Studie läuft. Die Stabilisierung der mitochondrialen Membran über Cardiolipin ist mechanistisch plausibel und die Verträglichkeit gut untersucht. Verkauft wird die Substanz trotzdem als belegter Mitochondrien-Fix.' },
  { id: 'humanin', view: 'experimental', evidenz: 1, mechanismus: 4, sicherheit: 1, hype: 1, anwendung: 1, richtung: 'offen',
    beleg: 'Es existiert keine publizierte Studie, in der Humanin Menschen als Wirkstoff verabreicht wurde. Was es gibt, sind Messungen des körpereigenen Spiegels in verschiedenen Zusammenhängen. Das sind Biomarker, keine Therapieeffekte. Die zytoprotektive Wirkung stammt aus Zell- und Tiermodellen. Sicherheitsdaten fehlen, weil es keine Interventionsstudien gibt.' },
  { id: 'p21', view: 'experimental', evidenz: 0, mechanismus: 4, sicherheit: 1, hype: 1, anwendung: 0, richtung: 'offen',
    beleg: 'Es wurden keine publizierten Humanstudien gefunden. Die Substanz (P021) stammt aus der Alzheimer-Forschung der Arbeitsgruppe um Khalid Iqbal: ein kurzes, vom Nervenwachstumsfaktor CNTF abgeleitetes Peptid mit Adamantan-Endgruppe, das in Mäusen auch oral wirkt. In Tiermodellen des Alterns, der Alzheimer-Krankheit und des Down-Syndroms förderte es Neurogenese und Synapsen und verbesserte Gedächtnisleistungen (Bolognin 2014; Kazim 2014; Kazim 2017). Damit wird eine Verbindung, die das Präklinik-Stadium nie verlassen hat, als anwendungsreifes Nootropikum vermarktet. Sicherheitsdaten am Menschen existieren praktisch nicht. In Deutschland kein zugelassenes Arzneimittel.' },
  { id: 'dsip', view: 'experimental', evidenz: 4, mechanismus: 3, sicherheit: 3, hype: 2, anwendung: 3, richtung: 'gemischt', berichtslage: { stufe: 1, kurz: 'Die Hälfte merkt gar nichts', was: 'Die Berichte sind auffällig uneinheitlich: Ein Teil beschreibt tieferen Schlaf, ein ähnlich großer Teil gar keinen Effekt. Bei einem Stoff, der ausdrücklich als Schlafpeptid verkauft wird, ist diese Streuung selbst die Aussage.', quellen: 'Anwenderkreise' },
    beleg: 'Vier kleine doppelblinde Humanstudien mit Polysomnographie liegen vor, alle aus den Jahren 1981 bis 1992, und sie widersprechen sich. Aus dem Umfeld der Entdecker: 6 Gesunde mit 59 % mehr Schlaf innerhalb von 130 Minuten ohne klassische Sedierung (Schneider-Helmert 1981) und 14 chronisch Schlaflose mit besserem Nachtschlaf und besserer Tagesleistung über 7 Nächte (Schneider-Helmert 1987). Unabhängig: Monti 1987 fand Zugewinne nur im Leichtschlaf, schon in den Ausgangswerten vorhanden, Tiefschlaf unverändert; Bes 1992 (16 Patienten) schwache, teils zufällige Effekte ohne therapeutischen Nutzen. Entzug und Schmerz nur als unkontrollierte Serien. Der Mechanismus ist ungeklärt: Gen, Vorläufer und Rezeptor wurden nie gefunden (Kovalzon & Strekalova 2006), DSIP selbst wirkte bei Ratten wegen schnellen Abbaus nicht, und beim Menschen korreliert der DSIP-Spiegel eher negativ mit Tiefschlaf (Friedman 1994). Keine Zulassung, keine moderne systematische Sicherheitsprüfung.' },
  { id: 'oxytocin', view: 'experimental', evidenz: 6, mechanismus: 7, sicherheit: 8, hype: 3, anwendung: 10, richtung: 'gemischt',
    beleg: 'Zwei Anwendungen, zwei völlig verschiedene Datenlagen. In der Geburtshilfe ist Oxytocin seit Jahrzehnten zugelassen und in breitem Einsatz. Die im Biohacking beworbene Nutzung als Bindungs- und Anti-Angst-Hormon ist Off-Label und die Evidenz uneinheitlich: Der berühmte Vertrauensbefund von 2005 ließ sich laut einer kritischen Übersicht nicht gut wiederholen, die größte Autismus-Studie mit 290 Kindern und Jugendlichen fand nach 24 Wochen keinen Unterschied zu Placebo, eine kleinere Studie nur einen Hinweis bei Drei- bis Fünfjährigen. Die Longevity-Idee stützt sich auf Mausdaten zur Muskelregeneration; Humanstudien dazu fehlen.' },
  { id: 'methylene-blue', view: 'experimental', evidenz: 6, mechanismus: 6, sicherheit: 7, hype: 2, anwendung: 9, richtung: 'gemischt',
    beleg: 'Als Notfallmedikament gegen Methämoglobinämie zugelassen und gut charakterisiert – als Alltags-Nootropikum ist es etwas anderes: Eine randomisierte, placebokontrollierte Studie an 26 Gesunden zeigte nach einer niedrigen Einzeldosis mehr Hirnaktivität und 7 Prozent mehr richtige Antworten beim Gedächtnisabruf, Daten zu regelmäßiger Einnahme fehlen. Das verwandte Molekül LMTM verfehlte in einer Phase-3-Studie an 891 Alzheimer-Patienten die primären Endpunkte. Das entscheidende Sicherheitsdetail wird in der Szene selten genannt: Methylenblau hemmt MAO-A stark, die US-Fachinformation warnt vor schwerem Serotonin-Syndrom in Kombination mit serotonergen Mitteln. Bei G6PD-Mangel droht Hämolyse.' },
  { id: 'ara-290', view: 'experimental', evidenz: 4, mechanismus: 5, sicherheit: 3, hype: 3, anwendung: 2, richtung: 'gemischt',
    beleg: 'Es gibt echte Phase-II-Daten, aber die Entwicklung kam nie weiter: Eine kleine verblindete, placebokontrollierte Studie bei Sarkoidose-assoziierter Small-Fiber-Neuropathie zeigte über 28 Tage weniger neuropathische Beschwerden und eine höhere corneale Nervenfaserdichte (Dahan 2013), eine publizierte Phase 2 bei Typ-2-Diabetes mit Neuropathie bessere PainDetect-Werte, HbA1c und Blutfette (Brines 2015). Die größte und strengste Studie widerspricht dem teilweise: In NCT02039687 (64 Teilnehmer, vierfach verblindet, 3 Dosen gegen Placebo, 28 Tage) war Placebo bei den Symptomfragebögen und der Nervenfaserdichte in der Hautbiopsie gleich gut oder besser, der primäre Endpunkt Hornhautnervenfaserfläche liegt nur als Mittelwert mit sehr großer Streuung ohne statistische Auswertung vor, und eine Publikation dazu existiert nicht. Die Prüfung bei depressiven Symptomen hat nie Ergebnisse eingestellt, die Studie beim diabetischen Makulaödem wurde mit 9 Teilnehmern vorzeitig beendet und zeigte keine Wirkung auf Sehschärfe oder Netzhautdicke. Eine Phase III und damit eine Zulassung gab es nie; im Register läuft am 30.09.2026 keine Studie mehr. Die gewebeschützende Wirkung über den Erythropoetin-Rezeptor ohne Blutbildungseffekt ist in kleinen Studien angedeutet, nicht bestätigt. Beworben wird Regeneration – und zugleich fälschlich Unbedenklichkeit im Sport: Nach dem Wortlaut der WADA-Liste 2026 fällt ARA-290 unter S2.1.5, Agonisten des körpereigenen Reparatur-Rezeptors einschließlich Substanzen ähnlicher Wirkung.' },
  { id: 'vip', view: 'experimental', evidenz: 4, mechanismus: 6, sicherheit: 4, hype: 2, anwendung: 3, richtung: 'gemischt',
    beleg: 'Evidenz 4: Die Gefäßwirkung ist am Menschen belegt, die Kombination aus Aviptadil und Phentolamin ist als Schwellkörperinjektion unter anderem in Deutschland national zugelassen (Liste der Europäischen Arzneimittel-Agentur 2022). Für die beworbene Entzündungshemmung ist das Bild gemischt: Die größte randomisierte Studie (TESICO, Lancet Respir Med 2023, 461 Patienten, intravenös bei COVID-19) verfehlte ihren Endpunkt und wurde abgebrochen, eine Meta-Analyse von 2025 fand keinen Überlebensvorteil, eine kleinere doppelblinde Inhalationsstudie mit 80 Patienten verkürzte den Klinikaufenthalt knapp signifikant. Für das Nasenspray gegen CIRS gibt es nur eine offene Studie mit 20 Patienten ohne Kontrollgruppe (Shoemaker 2013). Mechanismus 6, weil Gefäßerweiterung und Immunwirkung (weniger TNF-alpha, mehr regulatorische T-Zellen bei Sarkoidose) am Menschen gemessen sind. Sicherheit 4: kurze kontrollierte Studien, Flush als häufigste Nebenwirkung. Richtung gemischt statt offen, weil kontrollierte Daten in beide Richtungen vorliegen.' },
  { id: 'foxo4-dri', view: 'experimental', evidenz: 0, mechanismus: 4, sicherheit: 0, hype: 0, anwendung: 0, richtung: 'offen',
    beleg: 'Die Ursprungsarbeit ist berühmt und eindeutig eine Tierstudie: Baar et al. (Cell 2017) zeigten an schnell alternden und natürlich gealterten Mäusen, dass die gezielte Störung der Bindung zwischen FOXO4 und p53 seneszente Zellen entfernt und Fitness, Felldichte und Nierenfunktion wiederherstellt. Unabhängige Gruppen haben das an Hoden, Lunge und Aorta von Mäusen wiederholt, an menschlichen Knorpelzellen und Keloidgewebe wirkte es im Labor selektiv, und 2025 wurde die Bindung an p53 strukturell aufgeklärt. Eine Studie am Menschen gibt es nicht, auch keine registrierte klinische Prüfung, und damit keinerlei Sicherheits- oder Pharmakokinetikdaten. Eine Übersicht von 2026 nennt FOXO4-DRI präklinisch senolytisch, klinisch nicht validiert, und fordert zuerst Langzeittoxikologie und eine Prüfung der p53-abhängigen Tumorüberwachung. Selbstversuche aus der Szene sind Einzelfälle ohne Messwerte.' },
  { id: 'senolytic-dq', view: 'experimental', evidenz: 5, mechanismus: 7, sicherheit: 4, hype: 3, anwendung: 2, richtung: 'negativ',
    beleg: 'evidenz 5: Am Menschen liegen zwar mehrere Studien vor, aber nur zwei davon sind randomisiert und kontrolliert – 12 Teilnehmer bei Lungenfibrose und 60 Frauen über 20 Wochen –, der Rest sind unkontrollierte Serien mit 9, 14 und 5 Teilnehmern, durchweg auf Surrogat- und Funktionsmarker angelegt. mechanismus 7: Die Zielstruktur ist am Menschen bestätigt, nicht nur plausibel – Biopsien nach 3 Tabletten-Tagen zeigten 35 % weniger seneszente Zellen im Fettgewebe, einen weiteren Marker −62 % und gesunkene Entzündungsstoffe im Blut; die Kette bis zum klinischen Ergebnis ist jedoch nicht quantifiziert. sicherheit 4: nur Kurzzeitdaten für diese Anwendung – 60 Frauen über 20 Wochen, wenige Dutzend Menschen über wenige Wochen, 16 Affen; das Dasatinib-Profil (Pleuraerguss, Knochenmarksuppression, Blutungen) stammt aus der Dauertherapie bei Leukämie. hype 3: Zitiert wird die offene Lungenfibrose-Studie, die kontrollierte Wiederholung mit dem Nullergebnis kaum – ein Einzelbefund wird zur Gesamtaussage. anwendung 2: Anwendung nur in Studien und kleinen Graumarktkreisen, für Altern existiert keine Zulassung, nur die Off-Label-Verordnung in ärztlicher Verantwortung. richtung negativ statt „gemischt" (kein zulässiger Wert): Beide Male, wenn ein Placebo danebenstand, wurde der Nutzen kleiner oder verschwand – bei der Lungenfibrose vollständig, beim Knochenstoffwechsel auf dem primären Endpunkt (−4,1 % gegen −7,7 %, p = 0,61).' },
  { id: 'larazotide', view: 'experimental', evidenz: 6, mechanismus: 5, sicherheit: 6, hype: 2, anwendung: 3, richtung: 'negativ',
    beleg: 'Ein Fall, in dem die Studien vorliegen und das Ergebnis eindeutig ist: Nach mehreren Phase-II-Studien und einer Phase-III-Studie bei Zöliakie stellte der Entwickler 2022 das Programm ein, weil eine ausreichende Wirksamkeit gegenüber Placebo nicht mehr wahrscheinlich erschien. Gescheitert ist es an der Wirksamkeit, nicht an der Sicherheit – das Nebenwirkungsprofil ist aus großen Kollektiven gut charakterisiert. Beworben wird die Substanz heute als Darmbarriere-Reparatur für ein weit breiteres Spektrum, als je geprüft wurde.' },
  { id: 'melanotan-2', view: 'experimental', evidenz: 3, mechanismus: 6, sicherheit: 3, hype: 3, anwendung: 4, richtung: 'offen', berichtslage: { stufe: 3, kurz: 'Bräunung sicher – und Muttermale', was: 'An der Wirkung besteht kein Zweifel: Bräunung ohne Sonne, dazu Übelkeit, Flush und weitere melanokortin-typische Effekte – spezifisch, sichtbar, vielfach unabhängig berichtet. Dieselbe Berichtslage umfasst aber auch die unangenehme Seite: publizierte Fallberichte zu Melanomen und neu aufgetretenen atypischen Muttermalen. Berichte zeigen hier in beide Richtungen, und beide zählen.', quellen: 'Anwenderkreise · publizierte Fallberichte in dermatologischen Zeitschriften' },
    beleg: 'Keine Zulassungsstudie, aber echte, sehr kleine Humandaten: eine Phase-1-Pilotstudie mit 3 Männern zeigte 1996 Bräunung ohne Sonne, doppelblinde placebokontrollierte Überkreuzstudien mit je 10 Männern zeigten Erektionen und mehr sexuelles Verlangen (Wessells 1998 und 2000). Die Wirkung an MC1R und MC4R ist damit am Menschen bestätigt; zwei Abkömmlinge sind zugelassen. Dazu kommt eine ungewöhnlich dichte Sammlung von Schadensberichten: publizierte Fälle zu Melanomen und neu aufgetretenen oder dunkler werdenden Muttermalen, unter anderem im BMJ 2009, im British Journal of Dermatology 2011, im Irish Medical Journal 2013, in Dermatology 2014 und in JAAD Case Reports 2026, dazu Fallberichte zu Priapismus. Ob die Substanz Melanome verursacht, ist ungeklärt – die Assoziation mit Pigmentveränderungen ist gut dokumentiert. Das BfArM hat 2010 ausdrücklich abgeraten. Reine Schwarzmarktsubstanz.' },
  { id: 'melanotan-1', view: 'experimental', evidenz: 9, mechanismus: 9, sicherheit: 9, hype: 4, anwendung: 5, richtung: 'gemischt',
    beleg: 'Evidenz 9: Für die zugelassene Indikation liegen zwei randomisierte, doppelblinde, placebokontrollierte Studien mit 74 und 94 Patienten vor, mit dem Endpunkt schmerzfreie Sonnenexposition (69,4 gegenüber 40,8 Stunden nach 6 Monaten; 6,0 gegenüber 0,8 Stunden nach 9 Monaten; 77 statt 146 Lichtreaktionen), und zwei Behörden haben zugelassen: die EU am 22. Dezember 2014 unter besonderen Bedingungen, die USA am 8. Oktober 2019 auf Grundlage von 3 Studien mit 244 Patienten an 22 Zentren. Keine 10, weil die EU-Zulassung ausdrücklich unter besonderen Bedingungen erteilt wurde und weil die Anwendung, für die die Substanz in der Szene gesucht wird – kosmetische Bräunung –, nur auf einer placebokontrollierten Studie von 1991 mit 28 Männern über 12 Tage ruht. Mechanismus 9, weil die Wirkkette am Menschen quantifiziert ist: MC1R-Aktivierung, Eumelaninbildung, verringerte Lichtdurchdringung, dazu die Genetik der MC1R-Varianten. Sicherheit 9 statt 8, weil neben den Zulassungsstudien Langzeitdaten aus der Versorgung vorliegen (115 Patienten, 1.023 Implantate, bis zu 8 Jahre) und die Zulassung an ein EU-Register und eine Sicherheitsstudie nach Zulassung gebunden ist, deren deutscher Teil 200 Patienten erfasst hat. Hype 4, weil die Zulassung im Graumarkt als Beleg für die Sicherheit des nicht zugelassenen Melanotan 2 verwendet wird und weil die kosmetische Bräunung mit Daten beworben wird, die einer Krankheitsbehandlung entstammen. Anwendung 5, weil das Präparat außerhalb weniger Spezialzentren nicht in der Breite eingesetzt wird und die verbreitete Nutzung Graumarktware ist. Korrektur am Bestand: Der bisherige Beleg nennt Januar 2015 als EU-Zulassung, richtig ist der 22. Dezember 2014; die Angabe, das Molekül sei rund zehnmal potenter als alpha-MSH, lautet in der Originalarbeit 26-fach im Adenylatzyklase-Test.' },
  { id: 'peptid-stacks', view: 'experimental', evidenz: 2, mechanismus: 4, sicherheit: 0, hype: 2, anwendung: 4, richtung: 'offen',
    beleg: 'Evidenz 2 statt 0, weil für eine Kombination Humandaten vorliegen: An 18 gesunden Männern setzte ein Wachstumshormon-freisetzendes Peptid gemeinsam mit einem Releasing-Hormon mehr Wachstumshormon frei als jede Substanz allein (Bowers et al., J Clin Endocrinol Metab 1990), und eine Arbeit an 47 Männern hat diese Synergie näher bestimmt (Veldhuis und Bowers 2009). Beides sind Surrogatendpunkte nach einmaliger Gabe, und für die vermarkteten Blends existiert keine einzige Kombinationsstudie – gerade Synergie, das Verkaufsargument, wurde dort nie gemessen. Mechanismus 4, weil die Kombinationslogik für diese eine Paarung am Menschen quantifiziert ist, inklusive der Erkenntnis, dass Bauchfett, IGF-1 und IGFBP-3 zusammen 60 Prozent der Unterschiede erklären, für alle anderen Kombinationen aber nur Plausibilität vorliegt. Sicherheit 0, weil Interaktionsdaten vollständig fehlen und die Sicherheitslage der Einzelbestandteile höchst unterschiedlich ist: Die FDA nennt für Ipamorelin schwerwiegende Ereignisse bis zum Tod bei intravenöser Gabe, für Melanotan II Fallberichte über Melanom, ein Enzephalopathiesyndrom und Priapismus, für Ibutamoren ein Signal für Herzinsuffizienz, und für zahlreiche weitere Peptide gar keine Sicherheitsinformationen. Hype 2, weil die Synergie-Erzählung für eine Substanzklasse zutrifft und daraus eine Aussage über beliebige Mischungen gemacht wird. Anwendung 4, weil Stacking verbreitet ist und dabei vollständig außerhalb eines regulatorischen Rahmens stattfindet, wie die Übersichtsarbeit von 2026 zum unregulierten Peptidgebrauch beschreibt. Korrektur am Bestand: Das bisher zitierte Protokoll-Wiki ist keine Fachquelle, und die am Menschen gemessene Synergie betrifft die Substanzklassen, nicht die konkrete Handelskombination CJC-1295 plus Ipamorelin.' },
  { id: 'glow-stack', view: 'experimental', evidenz: 0, mechanismus: 3, sicherheit: 0, hype: 1, anwendung: 3, richtung: 'offen',
    beleg: 'Es wurde keine einzige Studie zu dieser Kombination gefunden; der behauptete Kombinationseffekt ist eine Addition von Einzelbefunden. Am besten belegt ist GHK-Cu als Creme: Eine systematische Übersicht von 2026 fand 20 Studien, davon 18 präklinisch und 2 randomisierte Studien mit weniger Falten gegenüber Kontrollen – für die Injektion gibt es keine Daten. BPC-157 stützt sich auf 36 Studien, davon 35 präklinisch, ohne klinische Sicherheitsdaten (Vasireddi 2025); TB-500 hat nur Daten der Muttersubstanz Thymosin Beta-4. Mechanismus 3, weil jede Zutat eine plausible Zell- und Tierbasis hat, das Zusammenspiel aber ungeprüft ist. Sicherheit 0, weil zur injizierten Mischung nichts systematisch untersucht ist; die FDA nennt Immunreaktionen, Zusammenlagerung und Verunreinigungen als Risiken und führt alle drei Stoffe auf ihrer Risikoseite unter zurückgezogenen Nominierungen (früher Kategorie 2); über BPC-157 und TB-500 beriet im Juli 2026 ein FDA-Gremium, eine Entscheidung der FDA steht aus. Hype 1: Die Einzelteile haben eine Grundlage, die Übertragung auf die injizierte Kombination als „Hautverjüngung von innen“ nicht. Anwendung 3: in der Szene verbreitet als Fertig-Blend, ohne Studien.' },
  { id: 'klow-stack', view: 'experimental', evidenz: 0, mechanismus: 3, sicherheit: 0, hype: 0, anwendung: 3, richtung: 'offen',
    beleg: 'Dieselbe Lücke wie beim GLOW-Stack, nur mit einer vierten Komponente: Zur Kombination wurde keine Studie gefunden. KPV hat keine klinische Studie am Menschen; die Daten stammen aus menschlichen Zellkulturen und Mausmodellen – in der zentralen Arbeit (Gastroenterology 2008) hemmte es NF-κB in Darm- und Immunzellen und milderte oral gegeben die Colitis in 2 Mausmodellen, in menschlichen Keratinozyten (J Invest Dermatol 2004) zeigte sich kein cAMP-, aber ein Calcium-Signal. BPC-157 ist präklinisch breit untersucht (36 Studien, 35 präklinisch), TB-500 direkt kaum. Vier Substanzen mit jeweils dünner Humandatenlage werden zu einem Protokoll addiert, dessen Gesamtwirkung und Stabilität nie geprüft wurden. Verbreitet als Fertig-Vial in der Szene, ohne regulatorischen Rahmen.' },
  { id: 'pentadeca-arginate', view: 'experimental', evidenz: 1, mechanismus: 3, sicherheit: 1, hype: 0, anwendung: 4, richtung: 'offen',
    beleg: 'Zu Pentadeca Arginate selbst gibt es keine Publikation – keine Humanstudie, keine Tierstudie. Es ist dieselbe Sequenz wie BPC-157 als Arginat-Salz; die gesamte Wirkbehauptung stützt sich auf die BPC-157-Forschung. Diese ist präklinisch breit (systematischer Review 2025: 36 Studien, davon 35 präklinisch, mit besserer Heilung von Muskel, Sehne, Band und Knochen im Tier) und mechanistisch plausibel (VEGFR2, Fibroblasten, NO; 2026 erste Bestätigung an menschlichem Arteriengewebe ex vivo). Am Menschen liegen nur 3 unkontrollierte Pilotstudien mit zusammen weniger als 30 Personen vor, klinische Sicherheitsdaten fehlen. Die beworbenen Vorteile der Arginat-Form (Stabilität, Aufnahme) sind nicht publiziert. Verwendet wird PDA in Szene und US-Praxen ohne regulatorischen Rahmen.' },
  { id: 'kpv', view: 'experimental', evidenz: 0, mechanismus: 5, sicherheit: 1, hype: 3, anwendung: 2, richtung: 'offen',
    beleg: 'Evidenz 0, weil keine Studie am Menschen existiert: Die FDA hat im Verfahren zu Ausgangsstoffen für Rezepturarzneien festgehalten, dass sie zu KPV keinerlei Daten zur Anwendung am Menschen gefunden hat, über keinen Verabreichungsweg; eine eigene Suche in Europe PMC und ClinicalTrials.gov bestätigt das. Die humanbezogenen Arbeiten sind Zellversuche: Elliott et al. 2004 an menschlichen Keratinozyten, die den erwarteten cAMP-Anstieg nicht fand, und Sung et al. 2025, die an HaCaT-Zellen und einem 3D-Hautmodell Schutz vor Feinstaubschäden zeigte. Mechanismus 5, weil die Wirkkette präklinisch sauber gezeigt ist – Aufnahme über PepT1, Hemmung von NF-kappa-B und MAP-Kinasen in menschlichen Darm- und Immunzellen, milderer Verlauf in zwei Mausmodellen der Colitis, teils unabhängig vom MC1-Rezeptor – am lebenden Menschen aber nichts davon bestätigt wurde. Sicherheit 1, weil eine systematische Untersuchung am Menschen fehlt und die FDA ausdrücklich erklärt, ihr fehlten wichtige Informationen zu Sicherheitsfragen. Hype 3, weil die Vermarktung echte Zell- und Mausbefunde zu Darmbarriere, Akne und Anti-Aging als Aussagen über Menschen weiterreicht, die Zahlen selbst aber meist korrekt sind. Anwendung 2, weil KPV allein in Graumarktkreisen und in Studien vorkommt. Korrektur am Bestand: Die beiden im Eintrag geführten PMIDs 18497332 und 10673523 gehören zu themenfremden Arbeiten (Gallensäuretransport, Kinderonkologie); richtig sind 18061177 und 10670585.' },
  { id: 'll-37', view: 'experimental', evidenz: 4, mechanismus: 5, sicherheit: 1, hype: 1, anwendung: 1, richtung: 'offen',
    beleg: 'Am Menschen untersucht ist die äußerliche Anwendung auf offenen Wunden: eine kleinere Studie von 2014, eine placebokontrollierte Studie mit 148 Patienten über 13 Wochen, die ihren Hauptendpunkt verfehlte, und eine Studie an diabetischen Fußwunden. Gespritzt wurde LL-37 am Menschen bisher nur in einem ganz anderen Kontext: in einer Phase-I-Studie direkt in Hautmetastasen von Melanompatienten. Daraus stammt ein Fallbericht (Dolkar et al., Journal of Cutaneous Pathology 2018) über eine Patientin, die 8 wöchentliche Injektionen erhielt und danach Hautveränderungen als Nebenwirkung entwickelte. Zur subkutanen oder systemischen Injektion bei Gesunden zum Immun-Boost wurde nichts gefunden. Antimikrobielle Wirkung, Immunmodulation und Wundheilung sind gut belegt – nur eben nicht für die beworbene Anwendung.' },
  { id: 'thymosin-alpha-1', view: 'experimental', evidenz: 7, mechanismus: 7, sicherheit: 7, hype: 3, anwendung: 6, richtung: 'gemischt',
    beleg: 'Das am besten belegte Immun-Peptid unter den Research-Peptiden: In über 30 Ländern als Thymalfasin zugelassen, vor allem bei chronischer Hepatitis. Am stärksten sind die Daten zur Immunstütze in der Krebsbegleitung: In der Phase-2-Studie GASTO-1043 sank schwere Lymphopenie unter Strahlenchemotherapie auf 19,1 gegenüber 62,1 Prozent, in einer randomisierten Melanom-Studie mit 488 Patienten gab es mehr Tumoransprechen ohne zusätzliche Toxizität. Die große placebokontrollierte Sepsis-Studie TESTS (BMJ 2025, 1106 Patienten) fand dagegen keinen Überlebensvorteil (23,4 vs. 24,1 Prozent), die frühere ETASS-Studie (Critical Care 2013) war nur grenzwertig. Die seit 2016 erschienene onkologische Literatur ist überwiegend retrospektiv und zu 80,8 Prozent chinesisch, der Cochrane-Review 2026 zu Hepatitis B bewertet die Evidenz als sehr niedrig. Die Sicherheitsdatenlage ist dank placebokontrollierter Studien und langjähriger Zulassung gut. Eine EU-weite Zulassung besteht nicht, wohl aber eine nationale in Italien; in Deutschland ist es nicht zugelassen; die Vermarktung als allgemeines Immun-Superpeptid für Gesunde geht über die geprüften Indikationen hinaus.' },
  { id: 'thymosin-beta-4', view: 'experimental', evidenz: 5, mechanismus: 4, sicherheit: 4, hype: 1, anwendung: 3, richtung: 'gemischt', berichtslage: { stufe: 2, kurz: 'Heilung – nie allein angewendet', was: 'Dieselbe Berichtslage wie bei TB-500, das ein Fragment dieses Proteins ist: Heilungsberichte an Sehnen und Bändern, fast immer in Kombination mit BPC-157 angewendet. Was davon worauf zurückgeht, lässt sich aus den Berichten nicht ablesen.', quellen: 'Anwenderkreise · Sport- und Reha-Umfeld USA' },
    beleg: 'Evidenz 5, weil es mehrere kleine kontrollierte Studien mit dem vollständigen Protein gibt: Augentropfen bei trockenem Auge (Phase 2, 72 Teilnehmer, Hauptendpunkte verfehlt, Nebenendpunkte besser), bei nicht heilenden Hornhautdefekten (Phase 3, 6 von 10 gegen 1 von 8 vollständig geheilt, knapp nicht signifikant) und eine Infusion nach Herzinfarkt (96 Patienten, Effekt nur in der Teilgruppe mit früher Gabe). Keine davon betrifft Sehnen, Bänder oder Muskeln, und keine hat ihren Hauptendpunkt klar gewonnen. Mechanismus 4: Aktinbindung und Zellwanderung sind biochemisch gesichert, die Heilwirkung stammt aus Tiermodellen. Sicherheit 4: eine randomisierte Phase-1-Studie an Gesunden über bis zu 10 Tage und Augentropfen-Studien über Wochen, keine Langzeitdaten. Hype 1, weil die Szene systemische Regeneration verspricht, die Daten aber Auge, Haut und Herz betreffen. Anwendung 3: nur in Studien und im Graumarkt. Korrektur am Bestand: Der frühere Beleg nannte keine Humanstudie – das trifft auf TB-500 zu, nicht auf das vollständige Protein.' },
  { id: 'thymalin', view: 'experimental', evidenz: 4, mechanismus: 5, sicherheit: 2, hype: 1, anwendung: 7, richtung: 'offen', berichtslage: { stufe: 1, kurz: 'Viele Berichte, alle aus dem Anbieterkreis', was: 'Berichte gibt es reichlich, aber sie stammen fast vollständig aus dem Umfeld der Anbieter und aus Publikationen derselben russischen Arbeitsgruppe, die die Präparate entwickelt hat. Damit fehlt genau das, was Anwenderberichte sonst stark macht: Unabhängigkeit. Das macht die Berichte nicht falsch, aber schwach.', quellen: 'überwiegend Anbieterumfeld · Publikationen der Entwicklergruppe' },
    beleg: 'In Russland seit Sowjetzeiten als Arzneimittel eingesetzt, mit Publikationen fast ausschließlich aus der Gruppe um Wladimir Khavinson in St. Petersburg – eine unabhängige, nicht-russische Replikation wurde nicht gefunden. Die Langlebigkeitsbehauptung stützt sich auf eine Arbeit: Khavinson & Morozov (Neuro Endocrinol Lett 2003) beobachteten 266 ältere Menschen über 6 bis 8 Jahre und berichten 2,0- bis 2,1-fach niedrigere Sterblichkeit unter Thymalin, 2,5-fach mit Epithalamin, 4,1-fach nur in einer gesondert jährlich behandelten Gruppe. Randomisierung, Verblindung, Gruppengrößen und Erfassung der Sterbefälle sind nicht nachvollziehbar beschrieben. Dazu kommt eine kleine randomisierte, einfach verblindete Studie bei schwerem COVID-19 (Kuznik 2021, 36 vs. 44 Patienten, Khavinson Koautor): klinische Besserung 80,5 vs. 59 %, Zeit bis zur Besserung und CT unverändert, Krankenhaussterblichkeit 19,4 vs. 40,9 % als Nebenziel bei ungleich verteilter invasiver Beatmung. Die Studie zu menschlichen Stammzellen von 2020 ist trotz des Titels eine Zellkulturarbeit. Systematische Sicherheitsdaten fehlen.' },
  { id: 'bronchogen-chonluten', view: 'experimental', evidenz: 1, mechanismus: 3, sicherheit: 0, hype: 2, anwendung: 3, richtung: 'offen', berichtslage: { stufe: 1, kurz: 'Viele Berichte, alle aus dem Anbieterkreis', was: 'Berichte gibt es reichlich, aber sie stammen fast vollständig aus dem Umfeld der Anbieter und aus Publikationen derselben russischen Arbeitsgruppe, die die Präparate entwickelt hat. Damit fehlt genau das, was Anwenderberichte sonst stark macht: Unabhängigkeit. Das macht die Berichte nicht falsch, aber schwach.', quellen: 'überwiegend Anbieterumfeld · Publikationen der Entwicklergruppe' },
    beleg: 'Evidenz 1: Es existiert keine klinische Studie am Menschen zu Bronchogen oder Chonluten, und Abfragen der ClinicalTrials.gov-API zu beiden Namen sowie zu Khavinson und peptide bioregulator ergeben keinen passenden Registereintrag. Befunde an menschlichem Material gibt es nur in Zellkultur: Chonluten senkte in THP-1-Monozyten die TNF-Freisetzung (Avolio et al., Int J Mol Sci 2022, Khavinson als Ko-Autor), und das Bronchogen-Tetrapeptid veränderte in Kulturen menschlichen Bronchialepithels Proliferationsmarker und Differenzierungsgene und band im Laborversuch an DNA (Lung 2014). Die Wirksamkeitsbefunde stammen aus zwei Rattenarbeiten am NO2-Modell mit Surrogatendpunkten: Rückgang der Umbauzeichen, Wiederherstellung der Flimmerzellen, Anstieg von sekretorischem IgA und Surfactant-Protein B (Bull Exp Biol Med 2015; Ross Fiziol Zh 2017). Ein Teil der Literatur zum Tetrapeptid betrifft Tabakwurzelzellen. Mechanismus 3, weil die epigenetische Wirkkette in Zellkultur und Modellrechnung plausibel, am Menschen aber nicht bestätigt ist. Sicherheit 0, weil systematische Daten fehlen und die Verträglichkeitsaussage aus dem Kreis der Entwickler und Anbieter kommt. Hype 2 statt 0, weil die beworbenen Effekte den im Tiermodell gemessenen Größen entsprechen und damit nicht frei erfunden sind; unbelegt bleibt der Sprung zum Menschen. Anwendung 3, weil die Präparate außerhalb Russlands nur als Research-Ware zirkulieren. Korrektur am Bestand: Die bisher geführten Blogquellen sind keine Fachquellen und eine von ihnen verwechselt Chonluten mit einem Knorpelpeptid; die Molmasse von etwa 446 g/mol ließ sich nicht belegen und ist entfernt.' },
  { id: 'prostamax', view: 'experimental', evidenz: 2, mechanismus: 3, sicherheit: 0, hype: 0, anwendung: 3, richtung: 'offen', berichtslage: { stufe: 1, kurz: 'Viele Berichte, alle aus dem Anbieterkreis', was: 'Berichte gibt es reichlich, aber sie stammen fast vollständig aus dem Umfeld der Anbieter und aus Publikationen derselben russischen Arbeitsgruppe, die die Präparate entwickelt hat. Damit fehlt genau das, was Anwenderberichte sonst stark macht: Unabhängigkeit. Das macht die Berichte nicht falsch, aber schwach.', quellen: 'überwiegend Anbieterumfeld · Publikationen der Entwicklergruppe' },
    beleg: 'Die ausführlichsten Daten stehen in der Patentschrift der Entwickler (EP1353939): ein Rattenversuch zur bakteriellen Prostatitis mit milderem Entzündungsgrad (1,81 gegenüber 2,91 Punkten, je 11 Tiere) und zwei Patientenserien, 35 Männer mit chronischer Prostatitis und 19 mit gutartiger Prostatavergrößerung, jeweils mit konventionell behandelten Kontrollen, aber weder randomisiert noch verblindet und ohne Vergleichszahlen für die Kontrollgruppen. Begutachtet veröffentlicht sind nur Laborbefunde: Chromatinveränderungen in Lymphozytenkulturen alter Menschen (Dzhokhadze 2012) und DNA-Bindungsversuche. Die Literatur stammt fast vollständig aus Russland und Georgien und aus dem Umfeld der Entwickler; eine unabhängige Bestätigung und eine Studie mit PSA, Prostatavolumen oder Symptomscore fehlen. Systematische Sicherheitsdaten am Menschen existieren nicht.' },
  { id: 'argireline', view: 'experimental', evidenz: 4, mechanismus: 4, sicherheit: 6, hype: 3, anwendung: 8, richtung: 'gemischt',
    beleg: 'Zwei Anwendungsformen mit völlig verschiedener Datenlage. Topisch ist Acetyl-Hexapeptid-8 ein Kosmetikinhaltsstoff mit echten Humandaten: eine randomisierte, placebokontrollierte Studie an 60 Teilnehmern über 4 Wochen mit objektiv geringerer Hautrauheit um die Augen (Wang 2013) und eine doppelblinde Halbseitenstudie an 52 Frauen, in der das Peptid im Mikronadelpflaster die Falten stärker verbesserte als das Pflaster allein (An 2019). Dem steht ein doppelblinder Halbseitenvergleich an 19 Frauen gegenüber, der keinen Unterschied zur Seite ohne Wirkstoff fand (Henseler 2023); in einer Meta-Analyse über 19 RCTs war der Falteneffekt von Peptiden insgesamt klein und ging überwiegend auf oral eingenommene Polypeptide zurück. In der einzigen direkten Vergleichsstudie (Aruan 2023, 21 Frauen, 8 Wochen, Vorstudie) schnitt Palmitoyl-Pentapeptid-4 besser ab als Acetyl-Hexapeptid-3. Die postulierte SNARE-Hemmung ist in Zellsystemen gezeigt, die Dämpfung der Mimikmuskulatur am Menschen nicht; ob das wasserliebende, relativ große Peptid die Hornschicht ausreichend durchdringt, ist umstritten. Injizierbar wurde keine Wirksamkeitsstudie am Menschen gefunden – im Rattenmodell blieb gespritztes Argireline ohne nachweisbare Gewebewirkung, und ein Fallbericht dokumentiert eine Infektion mit Mycobacterium abscessus nach Gesichtsinjektionen. Ein Kosmetikrohstoff ist nicht steril-pharmazeutisch hergestellt.' },
  { id: 'snap-8', view: 'experimental', evidenz: 3, mechanismus: 4, sicherheit: 5, hype: 3, anwendung: 7, richtung: 'gemischt',
    beleg: 'Als Kosmetikinhaltsstoff zugelassen, aber die eigenständigen Belege sind dünn: Die vorhandenen Studien untersuchen SNAP-8 fast immer in Mehrwirkstoff-Formulierungen, etwa in auflösenden Mikronadel-Pflastern (Ann Dermatol 2024) mit verbesserter Faltentiefe und Elastizität gegenüber Placebo – dabei lässt sich der Effekt nicht der Einzelsubstanz zuordnen. Eine kontrollierte Studie zu SNAP-8 allein ist kaum auffindbar, zur injizierbaren Anwendung gar keine. Die Wirkannahme entspricht der von Argireline, mit denselben offenen Fragen zur Hautdurchdringung.' },
  { id: 'matrixyl', view: 'experimental', evidenz: 6, mechanismus: 5, sicherheit: 5, hype: 4, anwendung: 8, richtung: 'gemischt',
    beleg: 'Von den Kosmetikpeptiden das am besten belegte – topisch und für die ältere Variante: Robinson et al. (Int J Cosmet Sci 2005) prüften doppelblind, placebokontrolliert und halbseitig an 93 Frauen über 12 Wochen eine Creme mit 3 ppm Palmitoyl-KTTKS gegen dieselbe Creme ohne Peptid und fanden signifikant weniger Falten und feine Linien in technischer Bildanalyse und Beurteilerbewertung. In einer kleinen doppelblinden Vergleichsstudie (Aruan 2023, 21 Frauen, 8 Wochen) schnitt Palmitoyl-Pentapeptid-4 besser ab als Acetyl-Hexapeptid-3 und Placebo. Die Kollagenstimulation über das Signalpeptid-Prinzip ist in Zellkultur reproduziert, am Menschen aber nicht gemessen: Eine Massenspektrometrie-Arbeit an 3 Freiwilligen zeigt die Peptide in allen Schichten der Hornschicht, offenbar auf den Zelloberflächen statt in den Zellen (Trzaska 2026). Zwei Lücken bleiben: Für Matrixyl 3000 (Palmitoyl-Tripeptid-1 plus Tetrapeptid-7), die heute meistverkaufte Variante, wurde keine eigene randomisierte Studie am Menschen gefunden, und zur injizierbaren Anwendung existiert keine Humanstudie. Genau dort liegt das Problem: Solide topische Evidenz zu einem Molekül wird auf andere Moleküle und auf eine ungeprüfte Anwendungsform übertragen.' },
  { id: 'kh-pinealon', view: 'khavinson', evidenz: 2, mechanismus: 3, sicherheit: 1, hype: 2, anwendung: 4, richtung: 'offen', berichtslage: { stufe: 1, kurz: 'Viele Berichte, alle aus dem Anbieterkreis', was: 'Berichte gibt es reichlich, aber sie stammen fast vollständig aus dem Umfeld der Anbieter und aus Publikationen derselben russischen Arbeitsgruppe, die die Präparate entwickelt hat. Damit fehlt genau das, was Anwenderberichte sonst stark macht: Unabhängigkeit. Das macht die Berichte nicht falsch, aber schwach.', quellen: 'überwiegend Anbieterumfeld · Publikationen der Entwicklergruppe' },
    beleg: 'Evidenz 2 statt 1: Es gibt mehr Humanbeobachtungen als bisher erfasst, alle aus Russland und ohne erkennbare Randomisierung oder Verblindung. Eine Übersicht der Entwicklergruppe (Molecules 2020) referiert 72 Patienten nach Schädel-Hirn-Trauma mit besserem Gedächtnis unter Pinealon zusätzlich zur Standardtherapie; Myakotnykh et al. (2016) verglichen an 110 Personen mehrere Geroprotektionsmethoden, die Kombination mit Vesugen wirkte am stärksten auf das biologische Alter; dazu Lkw-Fahrer (Bashkireva 2012), Lokführer (Nazimko 2012) und 32 multimorbide Patienten (Meshchaninov 2015). ClinicalTrials.gov führt keinen Eintrag. Erstmals liegt ein unabhängiger Tierversuch vor: ein Preprint von 2026 mit je 5 Mäusen fand einen nicht signifikanten Trend zu besserem Arbeitsgedächtnis ohne Nebenwirkungen. Mechanismus bleibt 3: konsistente Neuroprotektion in Zellkultur und Tier, Aufnahme in den Zellkern gezeigt, am Menschen nicht bestätigt. Sicherheit bleibt 1. Hype 2 statt 1: Die Tierbefunde im Eintrag stimmen, Werbeaussagen zu Brain-Fog und Schlaf gehen über die Daten hinaus. Anwendung bleibt 4.' },
  { id: 'kh-cortexin', view: 'khavinson', evidenz: 5, mechanismus: 4, sicherheit: 5, hype: 2, anwendung: 7, richtung: 'offen', berichtslage: { stufe: 1, kurz: 'Viele Berichte, alle aus dem Anbieterkreis', was: 'Berichte gibt es reichlich, aber sie stammen fast vollständig aus dem Umfeld der Anbieter und aus Publikationen derselben russischen Arbeitsgruppe, die die Präparate entwickelt hat. Damit fehlt genau das, was Anwenderberichte sonst stark macht: Unabhängigkeit. Das macht die Berichte nicht falsch, aber schwach.', quellen: 'überwiegend Anbieterumfeld · Publikationen der Entwicklergruppe' },
    beleg: 'Evidenz 5, weil es mehrere randomisierte Humanstudien gibt, aber fast alle ohne Placebo oder Verblindung und ausschließlich in russischen Zeitschriften: eine doppelblinde Placebo-Studie mit 62 Schlaganfallpatienten (Skoromets et al. 2008, ohne Effektgrößen in der Zusammenfassung), eine randomisierte Studie mit 189 Patienten mit chronischer Hirnischämie in 3 Armen (Fedin et al. 2018), die DIACORT-Studie mit 110 Diabetespatienten (2026) und ein Vergleich zweier Darreichungsformen an 490 Schlaganfallpatienten ohne Arm ohne Cortexin (Fedin et al. 2025). Eine unabhängige systematische Übersicht (Alsulaimani & Quinn 2021) fand nur eine verwertbare Studie mit 80 Patienten und stufte die Aussagesicherheit als niedrig bis sehr niedrig ein; ein unabhängiger, verblindeter Rattenversuch fand keinen Nutzen (Zhang, Chopp et al. 2019). Mechanismus 4, weil Caspase-8-Hemmung, Rezeptorbindung und Hirngängigkeit bei Mäusen gezeigt sind, eine Zielstruktur am Menschen aber nicht; auch russische Autoren nennen den Mechanismus unklar. Sicherheit 5, weil kontrollierte Nebenwirkungsdaten bis 90 Tage an mehreren hundert Patienten und eine 12-Monats-Studie ohne Auffälligkeiten vorliegen, Pharmakovigilanz und Toxikologie aber nicht zugänglich sind. Hype 2 bleibt unverändert; für Einsätze außerhalb der untersuchten Erkrankungen, etwa als Nootropikum bei Gesunden oder gegen das Altern, gibt es keine Daten. Anwendung 7, weil es in Russland seit vielen Jahren als zugelassenes Arzneimittel breit eingesetzt wird.' },
  { id: 'kh-vilon', view: 'khavinson', evidenz: 3, mechanismus: 3, sicherheit: 1, hype: 2, anwendung: 4, richtung: 'offen', berichtslage: { stufe: 1, kurz: 'Viele Berichte, alle aus dem Anbieterkreis', was: 'Berichte gibt es reichlich, aber sie stammen fast vollständig aus dem Umfeld der Anbieter und aus Publikationen derselben russischen Arbeitsgruppe, die die Präparate entwickelt hat. Damit fehlt genau das, was Anwenderberichte sonst stark macht: Unabhängigkeit. Das macht die Berichte nicht falsch, aber schwach.', quellen: 'überwiegend Anbieterumfeld · Publikationen der Entwicklergruppe' },
    beleg: 'Evidenz 3 statt 1: Neben den Laborbefunden an Lymphozyten alter Menschen (Lezhava et al. 2004) gibt es drei kleine klinische Arbeiten aus Russland und Belarus: Kuznik et al. 2006 (in PubMed als randomisierte Studie indexiert) fanden bei Typ-1-Diabetes eine verringerte chronische Gerinnungsaktivierung, Kuznik et al. 2007 mehr Antithrombin III und Protein C und meist geringeren Insulinbedarf, Iaskevich et al. 2005 vorläufig günstige Ergebnisse als Zusatz bei älteren Darmkrebspatienten. Alle nennen im Abstract keine Fallzahl, messen Laborwerte und sind nicht unabhängig bestätigt; ClinicalTrials.gov führt keine Vilon-Studie. Präklinisch: längere Lebensdauer weiblicher Mäuse ab dem 6. Lebensmonat (Khavinson et al. 2000), weniger chemisch ausgelöste Blasen- und Darmtumoren (56 statt 75,5 bzw. 14,3 statt 60 Prozent), aber bei HER2/neu-Mäusen häufiger Mehrfachtumoren (95 gegenüber 75 Prozent). Mechanismus bleibt 3 (Zell- und Tierdaten, am Menschen nicht bestätigt), Sicherheit bleibt 1 (keine systematische Auswertung am Menschen). Hype 2 statt 1: Die Immun-Werbung übertreibt – T-Helfer-Effekte sind nur in Zellkultur gezeigt, eine Netzhautwirkung ist nicht belegt –, hat aber eine reale präklinische Grundlage. Anwendung bleibt 4.' },
  { id: 'kh-vesugen', view: 'khavinson', evidenz: 2, mechanismus: 3, sicherheit: 1, hype: 2, anwendung: 3, richtung: 'offen', berichtslage: { stufe: 1, kurz: 'Viele Berichte, alle aus dem Anbieterkreis', was: 'Berichte gibt es reichlich, aber sie stammen fast vollständig aus dem Umfeld der Anbieter und aus Publikationen derselben russischen Arbeitsgruppe, die die Präparate entwickelt hat. Damit fehlt genau das, was Anwenderberichte sonst stark macht: Unabhängigkeit. Das macht die Berichte nicht falsch, aber schwach.', quellen: 'überwiegend Anbieterumfeld · Publikationen der Entwicklergruppe' },
    beleg: 'Evidenz 2 statt 0: Entgegen dem bisherigen Beleg gibt es kleine Humanarbeiten, alle ohne erkennbare Kontrollgruppe und nur russisch publiziert. Meshchaninov et al. (Adv Gerontol 2015) beschreiben bei 32 multimorbiden Patienten zwischen 41 und 83 Jahren ein langsameres biologisches Altern unter Vesugen und Pinealon; Kitachev et al. (Adv Gerontol 2014, mit Khavinson) fanden bei 41 Männern mit gefäßbedingter Erektionsstörung einen besseren Doppler-Blutfluss vorher gegenüber nachher. In Kombination mit Pinealon kommen ein Methodenvergleich an 110 Personen (Myakotnykh et al. 2016) und eine Arbeit an Lkw-Fahrern (Bashkireva und Artamonova 2012) hinzu. ClinicalTrials.gov führt keinen Eintrag. Mechanismus bleibt 3: Endothelin-1, Connexin, SIRT1, Ki67 und VEGF reagieren in Zellkultur (Kozlov et al. 2016; Cells 2022), in menschlichen Stammzellen sanken p16 und p21 um das 1,82- bis 3,23-Fache, am lebenden Menschen ist die Kette nicht bestätigt. Sicherheit 1: nicht systematisch untersucht, die Beobachtung von 2015 meldet zudem prooxidative Aktivität und weniger CD34-positive Blutstammzellen. Hype 2: Zellbefunde und Vorher-nachher-Daten werden zur Atherosklerose-Therapie verallgemeinert; Tierdaten zu Gefäßelastizität oder Plaque, wie im Bestand behauptet, ließen sich nicht finden. Anwendung bleibt 3.' },
  { id: 'kh-chelohart', view: 'khavinson', evidenz: 0, mechanismus: 3, sicherheit: 0, hype: 0, anwendung: 3, richtung: 'offen', berichtslage: { stufe: 1, kurz: 'Viele Berichte, alle aus dem Anbieterkreis', was: 'Berichte gibt es reichlich, aber sie stammen fast vollständig aus dem Umfeld der Anbieter und aus Publikationen derselben russischen Arbeitsgruppe, die die Präparate entwickelt hat. Damit fehlt genau das, was Anwenderberichte sonst stark macht: Unabhängigkeit. Das macht die Berichte nicht falsch, aber schwach.', quellen: 'überwiegend Anbieterumfeld · Publikationen der Entwicklergruppe' },
    beleg: 'Zu Chelohart unter diesem Namen gibt es weiterhin nur eine Arbeit: Ryzhak et al. (Adv Gerontol 2015) zeigten in Gewebekulturen junger und alter Ratten, dass der Kälberherz-Extrakt gewebespezifisch das Wachstum förderte, mit mehr PCNA und weniger p53. Neu gefunden wurde die ältere Forschungslinie derselben Gruppe zu Herz-Peptidextrakten aus Rinderherz (Cordialin/Cardiolin, 1987 bis 1993): weniger Frühschaden im Infarktmodell an 25 Ratten, bessere Energiebilanz der Herzmuskelzellen unter Hypoxie, Aktivierung ATP-abhängiger Kaliumkanäle, aber auch verzögerte Narbenbildung und Hemmung des Herzmuskels bei hohen Konzentrationen. Deshalb Mechanismus 3 statt 2: plausibel aus Zellkultur und Tier, wobei die Identität mit dem heutigen Produkt nicht dokumentiert ist. Evidenz 0: keine Studie am Menschen, kein Eintrag in ClinicalTrials.gov. Sicherheit 0: keine Humandaten. Hype 0: Anbieter bewerben koronare Herzkrankheit, Bluthochdruck und die Zeit nach Infarkt und verweisen auf nicht veröffentlichte klinische Studien. Anwendung 3: Vertrieb als Nahrungsergänzung über Online-Händler.' },
  { id: 'kh-livagen', view: 'khavinson', evidenz: 2, mechanismus: 3, sicherheit: 1, hype: 2, anwendung: 3, richtung: 'offen', berichtslage: { stufe: 1, kurz: 'Viele Berichte, alle aus dem Anbieterkreis', was: 'Berichte gibt es reichlich, aber sie stammen fast vollständig aus dem Umfeld der Anbieter und aus Publikationen derselben russischen Arbeitsgruppe, die die Präparate entwickelt hat. Damit fehlt genau das, was Anwenderberichte sonst stark macht: Unabhängigkeit. Das macht die Berichte nicht falsch, aber schwach.', quellen: 'überwiegend Anbieterumfeld · Publikationen der Entwicklergruppe' },
    beleg: 'Evidenz 2 statt 1: Neben den Laborbefunden an entnommenen Blutzellen alter Menschen (Khavinson und Lezhava 2002 und 2004, Tifliser Gruppe bis 2023) enthält das Patent EP1325026 eine Fallserie mit 23 Patienten zwischen 32 und 53 Jahren mit chronischer Hepatitis: Nach Injektionsbehandlung sanken ALT von 53,1 auf 40,8 und IgM von 3,80 auf 1,50 g/l. Eine Kontrollgruppe von 12 Patienten wird erwähnt, aber nicht ausgewertet; Randomisierung und Verblindung fehlen, begutachtet ist die Serie nicht. Mechanismus bleibt 3: mehr Proteinsynthese in alten Rattenhepatozyten (Brodskii 2001), weniger Leberverfettung im Vergiftungsmodell (Patent), Stabilität gegen Darm-Peptidasen (Timofeeva 2005); am lebenden Menschen nicht bestätigt. Sicherheit 1: Tiertoxikologie der Entwickler bis 6 Monate, keine Humandaten. Hype 2: Die Lebertiermodelle stützen den Grundgedanken, Fettleber, Alkoholschäden und Chromatin in Hepatozyten sind aber Verallgemeinerungen. Anwendung bleibt 3.' },
  { id: 'kh-pancragen', view: 'khavinson', evidenz: 3, mechanismus: 4, sicherheit: 1, hype: 3, anwendung: 3, richtung: 'offen', berichtslage: { stufe: 1, kurz: 'Viele Berichte, alle aus dem Anbieterkreis', was: 'Berichte gibt es reichlich, aber sie stammen fast vollständig aus dem Umfeld der Anbieter und aus Publikationen derselben russischen Arbeitsgruppe, die die Präparate entwickelt hat. Damit fehlt genau das, was Anwenderberichte sonst stark macht: Unabhängigkeit. Das macht die Berichte nicht falsch, aber schwach.', quellen: 'überwiegend Anbieterumfeld · Publikationen der Entwicklergruppe' },
    beleg: 'Evidenz 3, weil es zwei kleine Humanarbeiten gibt, beide mit Khavinson als Ko-Autor: Korkushko et al. (Bull Exp Biol Med 2011) mit 30 gesunden Älteren und 33 mit Typ-2-Diabetes, bei denen Nüchternglukose, Glukose im Belastungstest, Insulin und Insulinresistenz unter Pancragen sanken, während Unbehandelte unverändert blieben; und Korkushko et al. (Adv Gerontol 2013) mit 12 Älteren mit gestörter Glukosetoleranz, von denen 50 Prozent nach 4 Wochen ansprachen, ohne Kontrollgruppe. Randomisierung und Verblindung sind in keiner Zusammenfassung erwähnt, Endpunkte sind nur Laborwerte. Dazu kommen Versuche an alten Rhesusaffen über 10 Tage, darunter ein Vergleich mit Glimepirid an 9 Tieren (Goncharova et al. 2014, 2015). Mechanismus 4, weil Zellkulturen mit menschlichen Pankreaszellen, Ratten und Affen ein schlüssiges Bild ergeben, die epigenetische Zielstruktur aber nur modelliert ist. Sicherheit 1, weil keine Nebenwirkungserfassung, Toxikologie oder Pharmakokinetik am Menschen veröffentlicht ist. Hype 3, weil die Vermarktung bei Prädiabetes und Typ-2-Diabetes auf zwei kleinen Laborwert-Studien aufbaut, also ein dünner Befund zur Gesamtaussage wird. Anwendung 3, weil Pancragen außerhalb dieser Studien nur als Bioregulator-Präparat im Graumarkt vorkommt. Von 10 PubMed-Einträgen tragen 9 Khavinsons Namen, ClinicalTrials.gov führt keine Studie; eine unabhängige Wiederholung steht aus.' },
  { id: 'kh-testagen', view: 'khavinson', evidenz: 0, mechanismus: 2, sicherheit: 0, hype: 0, anwendung: 5, richtung: 'offen', berichtslage: { stufe: 1, kurz: 'Viele Berichte, alle aus dem Anbieterkreis', was: 'Berichte gibt es reichlich, aber sie stammen fast vollständig aus dem Umfeld der Anbieter und aus Publikationen derselben russischen Arbeitsgruppe, die die Präparate entwickelt hat. Damit fehlt genau das, was Anwenderberichte sonst stark macht: Unabhängigkeit. Das macht die Berichte nicht falsch, aber schwach.', quellen: 'überwiegend Anbieterumfeld · Publikationen der Entwicklergruppe' },
    beleg: 'Evidenz 0 statt 1: Die bisher als Humanevidenz geführten Lymphozyten-Arbeiten der Tifliser Gruppe (Meskhi et al. 2004, Kiladze et al. 2009) untersuchen Prostamax, ein anderes Peptid mit der Sequenz Lys-Glu-Asp-Pro (Dzhokhadze et al. 2012). Zu Testagen (Lys-Glu-Asp-Gly) gibt es keine Humandaten, auch keine an menschlichen Zellen, und keine einzige Studie zu Hoden, Prostata, Spermien oder Testosteron; die russischen Prostata-Studien betreffen Prostatilen und Chitomur. Mechanismus 2 statt 3: Belegt ist KEDG als Peptid aus dem Hypophysenvorderlappen, das bei hypophysektomierten Vögeln Thyreotropin, T3, T4, Schilddrüse und Thymus normalisierte (Kuznik et al. 2008 bis 2013), und die Aufnahme in den Zellkern (Fedoreyeva et al. 2011); für die beworbene Wirkung auf Hoden und Prostata ist das eine Erzählung ohne Daten. Die im alten Beleg genannte Kupfer-Arbeit von 2025 untersucht übrigens genau dieses Peptid, als Testagen gekauft, nur zu materialwissenschaftlichem Zweck; die echte Namensverwechslung betrifft ein Testosteron-Präparat gleichen Namens (NCT02733133). Sicherheit 0, Hype 0 und Anwendung 5 bleiben.' },
  { id: 'kh-cytomax-complex', view: 'khavinson', evidenz: 0, mechanismus: 1, sicherheit: 0, hype: 0, anwendung: 3, richtung: 'offen', berichtslage: { stufe: 1, kurz: 'Viele Berichte, alle aus dem Anbieterkreis', was: 'Berichte gibt es reichlich, aber sie stammen fast vollständig aus dem Umfeld der Anbieter und aus Publikationen derselben russischen Arbeitsgruppe, die die Präparate entwickelt hat. Damit fehlt genau das, was Anwenderberichte sonst stark macht: Unabhängigkeit. Das macht die Berichte nicht falsch, aber schwach.', quellen: 'überwiegend Anbieterumfeld · Publikationen der Entwicklergruppe' },
    beleg: 'Zu den als Cytomax oder Cytogen vermarkteten Kombinationsprodukten gibt es keine veröffentlichte Studie; für Endoluten, Vladonix, Cerluten, Pielotax und Glandokort findet PubMed keinen einzigen Eintrag, ClinicalTrials.gov keine Studie (Abfrage 30.09.2026). Zu Einzelbestandteilen gibt es vereinzelt Arbeiten: Chelohart in einer Organkultur-Studie mit Kälberextrakten (Ryzhak et al. 2015), Sigumir in einer unkontrollierten Beobachtung an 62 älteren Patienten mit Kiefergelenkerkrankungen, bei der es nur ein Teil eines Behandlungspakets war (Iordanishvili et al. 2012). Die klinischen Daten zu Thymalin und Epithalamin (Khavinson & Morozov 2003) betreffen russische Arzneimittel-Extrakte, deren Gleichheit mit den frei verkäuflichen Komplexen nicht belegt ist. Deshalb bleiben Evidenz und Sicherheit bei 0; Mechanismus 1, weil die Gewebespezifität nur für Einzelextrakte in Zellkultur gezeigt ist und die Stack-Logik eine reine Übertragung ist; Hype 0, weil die Produkte als organspezifisches Longevity-System vermarktet werden, ohne dass eines davon geprüft ist; Anwendung 3, weil die Nutzung ohne regulatorischen Rahmen und ohne dokumentierte Studienanwendung stattfindet.' },
  { id: 'alkohol-reduktion', view: 'behandlungen', evidenz: 9, mechanismus: 9, sicherheit: 8, hype: 8, anwendung: 10, richtung: 'positiv',
    beleg: 'Die beste Datenlage aller Anwendungen: 107 Kohortenstudien mit über 4,8 Millionen Teilnehmern (Zhao et al., JAMA Network Open 2023) plus eine randomisierte Studie mit klinischem Endpunkt – bei Vorhofflimmern senkte sechsmonatige Abstinenz die Rezidivrate deutlich (Voskoboinik et al., NEJM 2020). Die Wirkkette ist vom Molekül bis zum Krankheitsendpunkt geschlossen. Die Überhöhung lief historisch in die andere Richtung: Der Rotwein-Schutzeffekt war ein Artefakt der Abstinenzler-Verzerrung; die DGE hat ihre Position 2024 revidiert.' },
  { id: 'zone2-vo2max', view: 'behandlungen', evidenz: 7, mechanismus: 7, sicherheit: 8, hype: 4, anwendung: 9, richtung: 'gemischt',
    beleg: 'Zwei Ebenen, die oft vermengt werden. Die VO2max als Marker ist hervorragend belegt (Kodama et al., JAMA 2009, 33 Kohorten, rund 103.000 Personen) – aber beobachtend. Die Interventionsstudie Generation 100 (Stensvold et al., BMJ 2020, 1.567 Ältere, fünf Jahre) verfehlte ihren primären Endpunkt Gesamtmortalität. Und für Zone 2 speziell fällt der direkte Vergleich eher zugunsten höherer Intensitäten aus. Trainieren ist richtig; die Sonderstellung von Zone 2 ist nicht belegt.' },
  { id: 'bfr-training', view: 'behandlungen', evidenz: 7, mechanismus: 8, sicherheit: 7, hype: 6, anwendung: 6, richtung: 'positiv',
    beleg: 'Die belastbarste Anwendung im Trainingsbereich: Eine Meta-Analyse (Geng et al., Sports Medicine Open 2024) verglich BFR mit schwerem Krafttraining in 51 Studien mit 1.164 Teilnehmenden für die Kraft und in 28 Studien mit 703 Teilnehmenden für die Muskelmasse; die Hypertrophie war vergleichbar, bei Untrainierten brachte schweres Training mehr Kraft. In der Reha steigerte BFR die Kraft gegenüber leichtem Training ohne Manschette (20 Studien, Hedges g 0,523). Der Mechanismus ist am Menschen im Zielgewebe gemessen (mTORC1-Aktivierung in der Muskelbiopsie, Fry et al. 2010). Die Sicherheitsdaten beruhen großteils auf Fallberichten und Umfragen, viele Trainingsstudien erfassten Nebenwirkungen nicht.' },
  { id: 'schlaf', view: 'behandlungen', evidenz: 7, mechanismus: 7, sicherheit: 7, hype: 5, anwendung: 10, richtung: 'gemischt',
    beleg: 'Zwei Ebenen: Kohortendaten zeigen eine U-förmige Verbindung von Schlafdauer und Sterblichkeit, die Autoren halten Umkehrkausalität selbst für die plausiblere Erklärung. Auf der Interventionsseite ist die kognitive Verhaltenstherapie bei Insomnie mit 87 RCTs sehr gut belegt – aber für Insomnie-Endpunkte, nicht für Lebensverlängerung. Dass Schlafoptimierung bei Gesunden das Leben verlängert, ist durch keine Interventionsstudie belegt. Tracker-Versprechen zu Tiefschlaf und Schlafscore gehen deutlich über die Messgenauigkeit hinaus.' },
  { id: 'sauna-kaelte', view: 'behandlungen', evidenz: 6, mechanismus: 6, sicherheit: 6, hype: 5, anwendung: 9, richtung: 'gemischt',
    beleg: 'Die einzige Anwendung mit harten Endpunkten – aber beobachtend: In der finnischen KIHD-Kohorte (Laukkanen et al., JAMA Internal Medicine 2015, 2.315 Männer, rund 21 Jahre) war häufige Saunanutzung mit deutlich niedrigerer Sterblichkeit verbunden. Interventionsstudien sind klein. Bei Kälte zeigt die Meta-Analyse von elf RCTs (Cain et al., PLOS ONE 2025) unmittelbar erhöhte statt gesenkte Entzündungsmarker. Ausdrücklicher Widerspruch: Kälte direkt nach dem Krafttraining dämpft den Muskelaufbau.' },
  { id: 'ems', view: 'behandlungen', evidenz: 6, mechanismus: 7, sicherheit: 7, hype: 3, anwendung: 8, richtung: 'gemischt',
    beleg: 'Die Meta-Analyse von Kemmler et al. (Frontiers in Physiology 2021, 16 Studien, 897 Personen) zeigt große Effekte auf Muskelmasse und Kraft – auf die Fettmasse jedoch keinen signifikanten Effekt, also genau auf den meistbeworbenen Endpunkt nicht. Bei Sportlern fand eine Meta-Analyse von 12 Studien keinen Zusatznutzen für Sprung, Sprint und Wendigkeit. Ein Großteil der Studien und die Sicherheitsleitlinie stammen aus derselben Arbeitsgruppe. Ungewöhnlich: Die Sicherheitsforschung ist gut entwickelt – schon eine einzelne Einheit kann bei Einsteigern Muskelschadensmarker stark erhöhen, Fallberichte beschreiben Rhabdomyolyse; daraus entstanden eine internationale Sicherheitsleitlinie (2016, aktualisiert 2023) und die Fachkundepflicht nach NiSV seit 31.12.2022.' },
  { id: 'chelat-therapie', view: 'behandlungen', evidenz: 7, mechanismus: 3, sicherheit: 7, hype: 1, anwendung: 7, richtung: 'negativ', berichtslage: { stufe: 1, kurz: 'Praxisberichte bleiben unspezifisch', was: 'Aus Praxen, die das Verfahren anbieten, gibt es Berichte über mehr Belastbarkeit und Wohlbefinden. Sie bleiben unspezifisch und stammen aus dem wirtschaftlichen Umfeld der Behandlung. Zwei grosse randomisierte Studien mit harten Endpunkten haben dieselbe Frage gestellt und nichts gefunden. Was messbar funktioniert, ist die Chelierung selbst — nicht der klinische Nutzen.', quellen: 'Praxisberichte · Anwenderkreise' },
    beleg: 'Ein Sonderfall, der zeigt, was diese Achsen messen: Die Human-Evidenz ist hoch, weil zwei große randomisierte Studien mit harten Endpunkten vorliegen – und die entscheidende fiel negativ aus. TACT (JAMA 2013, 1.708 Patienten, 134 Zentren) zeigte 26 gegenüber 30 Prozent beim kombinierten Endpunkt, Hazard Ratio 0,82, p = 0,035 bei einer wegen Zwischenauswertungen auf 0,036 gesetzten Schwelle, ohne Wirkung auf die Gesamtsterblichkeit, und mit 289 Einwilligungsrücknahmen (17 Prozent), ungleich auf die Gruppen verteilt. Die vorab festgelegte Diabetes-Untergruppe (633 Teilnehmer) sah deutlich besser aus: 25 gegenüber 38 Prozent, Hazard Ratio 0,59, 6,5 Behandlungen über 5 Jahre je verhindertes Ereignis, während bei den 1.075 Teilnehmern ohne Diabetes kein Effekt bestand. TACT2 (JAMA 2024) prüfte genau diese Gruppe: 88 Zentren, 1.000 Zuteilungen, 959 Behandelte, 40 wöchentliche Infusionen, Trennschärfe über 85 Prozent für eine Senkung um 30 Prozent. Ergebnis: 35,6 gegenüber 35,7 Prozent, Hazard Ratio 0,93 (0,76 bis 1,16), p = 0,53; Gesamtsterblichkeit 17,4 gegenüber 17,6 Prozent bei je 84 Todesfällen. Der Bleispiegel sank dabei zuverlässig von 9,03 auf 3,46 Mikrogramm je Liter (Placebo 9,3 auf 8,7, p < 0,001): Die Chelierung funktioniert, der klinische Nutzen fehlt. Auch der zweite Studienarm war negativ: hochdosierte Vitamine und Mineralstoffe mit 28 Bestandteilen, 175 Ereignisse in beiden Gruppen, Hazard Ratio 0,99, und die Kombination nicht besser als doppeltes Placebo (JAMA Internal Medicine 2025). Deshalb bleibt Mechanismus 3: Er erklärt, warum eine Zahl sinkt, nicht einen Nutzen. Dokumentiert sind zudem 3 Todesfälle durch Hypokalzämie nach Verwechslung der EDTA-Salze (CDC 2006). Wichtige Präzisierung gegenüber dem bisherigen Beleg: Für beschwerdefreie Menschen mit behaupteter Schwermetallbelastung liegt keine Studie mit harten Endpunkten vor – dort ist das Verfahren nicht widerlegt, sondern ungeprüft.' },
  { id: 'vagus-stimulation', view: 'behandlungen', evidenz: 5, mechanismus: 6, sicherheit: 7, hype: 3, anwendung: 6, richtung: 'gemischt',
    beleg: 'Viele kleine randomisierte Studien mit Skalen-Endpunkten, wenig Langzeitdaten. Die größte und sauberste Studie, RECOVER (493 Teilnehmende mit schwer behandelbarer Depression, zwölf Monate, doppelblind scheinkontrolliert, Brain Stimulation 2025), verfehlte ihren primären Endpunkt, zeigte aber Vorteile bei vorab festgelegten Nebenendpunkten (ärztlicher Gesamteindruck p = 0,004). Bei Gesunden stieg in einer verblindeten Überkreuzstudie mit 28 Teilnehmenden die maximale Sauerstoffaufnahme um 3,8 Prozent (European Heart Journal 2025), der Mechanismus ist offen. Die Sicherheitsauswertung ist die gründlichste im Anwendungsbereich (177 Studien, 6.322 Probanden), auch wenn gut die Hälfte gar keine Nebenwirkungsdaten berichtete. Wichtig für die Einordnung: Die als Beleg vermarktete HRV-Steigerung hält nicht – eine bayesianische Meta-Analyse über 16 verblindete Studien (Wolf et al., Psychophysiology 2021) fand starke Evidenz für die Nullhypothese. Beworben wird das Verfahren dennoch für ein sehr breites Indikationsspektrum.' },
  { id: 'rotlicht-pbm', view: 'behandlungen', evidenz: 5, mechanismus: 5, sicherheit: 5, hype: 4, anwendung: 7, richtung: 'gemischt',
    beleg: 'Die meisten Studien aller Anwendungen: Ein Umbrella-Review über 15 Meta-Analysen mit 204 RCTs und mehr als 9.000 Teilnehmern (Yon et al., Systematic Reviews 2025) – aber kein einziger Endpunkt erreichte hohe Ergebnissicherheit, über die Hälfte war niedrig oder sehr niedrig. Am besten belegt ist die Haardichte bei androgenetischer Alopezie. Kernproblem: Wellenlänge, Dosis und Bestrahlungsstärke schwanken so stark, dass Photobiomodulation keine einheitliche Anwendung ist. Ganzkörperpanels werben mit Longevity, belegt sind Haut, Haar und lokaler Schmerz.' },
  { id: 'prp', view: 'behandlungen', evidenz: 5, mechanismus: 4, sicherheit: 6, hype: 3, anwendung: 7, richtung: 'negativ', berichtslage: { stufe: 2, kurz: 'Besserung berichtet — Scheinspritze auch', was: 'Aus orthopädischen Praxen und von Patienten kommen zahlreiche Berichte deutlicher Besserung nach der Behandlung. Sie sind der Grund, warum das Verfahren so verbreitet ist. Die entscheidende Zahl steht daneben: In der verblindeten Studie ging es der Kochsalzgruppe genauso gut. Eine Spritze ins Knie ist eine der wirksamsten Scheinbehandlungen, die die Medizin kennt — die Besserung ist echt, die Zuordnung zum Eigenblut ist es nicht.', quellen: 'Patientenberichte · orthopädische Praxen' },
    beleg: 'Gut untersucht und überwiegend negativ, sobald sauber verblindet wird: Die RESTORE-Studie (JAMA 2021, n=288, zwölf Monate) fand weder beim Schmerz noch beim Knorpelvolumen einen Unterschied zu Kochsalz, und 29 von 31 sekundären Endpunkten blieben ohne Unterschied. Beim Tennisellenbogen war PRP in 6 randomisierten Studien nicht besser als Placebo, langfristig aber besser als Kortison; ein Cochrane-Review zu Weichteilverletzungen fand keine klinisch relevanten Vorteile. Bei der Haardichte gibt es positive Studien mit mäßiger Evidenz. Zusatzrisiko liegt in der Verarbeitung, nicht im Produkt: Die US-Gesundheitsbehörde dokumentierte 2024 HIV-Übertragungen nach unsteriler kosmetischer Anwendung. Die deutsche Orthopädie-Fachgesellschaft empfiehlt PRP bei Kniearthrose derzeit nicht.' },
  { id: 'cgm', view: 'behandlungen', evidenz: 4, mechanismus: 5, sicherheit: 6, hype: 3, anwendung: 8, richtung: 'negativ',
    berichtslage: { stufe: 2, kurz: 'Anwender berichten echte Aha-Momente', was: 'Was Anwender berichten, ist nicht der gemessene Endpunkt: Sie beschreiben, dass sie zum ersten Mal gesehen haben, was ein bestimmtes Frühstück bei ihnen tut, und ihr Verhalten daraufhin geändert haben. Das ist spezifisch und plausibel — ein Sensor zeigt tatsächlich etwas, das man sonst nicht sieht. Die Studien haben eine andere Frage gestellt, nämlich ob sich daraus bei Stoffwechselgesunden ein gesundheitlicher Vorteil ergibt. Dass die Sensoren bei Gesunden systematisch überschätzen, macht die Aha-Momente allerdings angreifbar.', quellen: 'Anwenderkreise · Selbstmessungen' },
    beleg: 'Für Stoffwechselgesunde – die beworbene Zielgruppe – ist der Nutzen nicht gezeigt: Die Meta-Analyse über 23 Studien mit 1.074 Nichtdiabetikern fand den glykämischen Vorteil nur bei Prädiabetes, bei Normoglykämen keinen. Dazu ein Messproblem: Eine Untersuchung der University of Bath (Am J Clin Nutr 2025) zeigte, dass die Sensoren bei Gesunden systematisch überschätzen und die Zeit oberhalb der Schwelle um fast das Vierfache zu hoch angaben. Harte Endpunkte wurden nirgends untersucht.' },
  { id: 'hbot', view: 'tipps', evidenz: 4, mechanismus: 6, sicherheit: 7, hype: 3, anwendung: 8, richtung: 'gemischt',
    beleg: 'Am ehesten belegt ist das diabetische Fußulkus, und dort für den Sechs-Wochen-Endpunkt (Cochrane 2015: 12 Studien, 577 Teilnehmer, relatives Risiko 2,35; nach einem Jahr kein Vorteil mehr); in Deutschland ist die Therapie dafür seit dem G-BA-Beschluss 2017 auch ambulant Kassenleistung. Für die meistgenannte Indikation Kohlenmonoxidvergiftung fand die Cochrane-Auswertung (6 Studien, 1.361 Patienten) keinen signifikanten Vorteil. Die Longevity-Anwendung stützt sich auf eine israelische Studie ohne Kontrollgruppe (35 Teilnehmer, 60 Sitzungen), deren Telomer-Befund unabhängig nicht bestätigt ist, und auf zwei kleine randomisierte Studien derselben Gruppe mit je 63 Älteren, die Verbesserungen bei Kognition und maximaler Sauerstoffaufnahme zeigten – gegen Nichtstun, nicht gegen Scheinbehandlung.' },
  { id: 'zyklus-biohacking', view: 'behandlungen', evidenz: 4, mechanismus: 5, sicherheit: 6, hype: 4, anwendung: 5, richtung: 'gemischt',
    beleg: 'Die Evidenz zur Leistung ist offen widersprüchlich, und das sollte man nicht glattbügeln: Die große Meta-Analyse von McNulty et al. (Sports Med 2020, 78 Studien) findet nur triviale Phaseneffekte bei niedriger Studienqualität, eine kontrollierte Überkreuzstudie zeigt keine phasenabhängige Muskelproteinsynthese (J Physiol 2025); eine Meta-Analyse zur Maximalkraft (Niering et al., Sports 2024, 22 Studien) findet dagegen einen mittleren Vorteil der späten Follikelphase – bei einer Heterogenität von 95 Prozent. Gut belegt ist, dass sich der Zyklus in Temperatur und HRV abbildet (HRV-Unterschiede von 3 bis 9 Prozent über 16 Wearable-Studien) und dass Wearables das fruchtbare Fenster mit einer gepoolten Genauigkeit von 0,88 erkennen. Der luteale Mehrverbrauch liegt nach aktueller Übersicht nur bei etwa 30 bis 120 kcal am Tag. Phasenspezifische Trainingspläne sind nicht belegt.' },
  { id: 'hrv-messung', view: 'behandlungen', evidenz: 6, mechanismus: 6, sicherheit: 8, hype: 3, anwendung: 8, richtung: 'gemischt',
    beleg: 'Die Messgröße selbst ist gut untersucht: zwei Framingham-Kohorten mit 736 und 2.501 Personen, eine Normwert-Übersicht über 21.438 Teilnehmer und Biofeedback-Meta-Analysen über 58 randomisierte Studien. Nicht belegt ist die Anwendung als tägliches Steuerinstrument – die Meta-Analyse über acht RCTs mit zusammen nur 190 Teilnehmern fand keinen Vorteil HRV-gesteuerten gegenüber vorgeplantem Training, brauchbare Normwerte gibt es nicht, und die Ruhe-HRV trägt das Übertrainings-Signal nicht. Die vagale Seite ist gut verstanden, die sympathische nicht: Für sie gibt es im Kurzzeit-EKG kein sauberes Maß, und das verbreitete LF/HF-Verhältnis gilt als überholt. Beworben wird eine Entscheidungsvalidierung, vorliegt eine Messvalidierung.' },
  { id: 'floating', view: 'behandlungen', evidenz: 5, mechanismus: 4, sicherheit: 5, hype: 4, anwendung: 6, richtung: 'gemischt',
    beleg: 'Eine systematische Übersicht (BMC Complement Med Ther 2025) führt 63 Studien mit 1.838 Teilnehmenden, die meisten klein. Es gibt mehrere kleine randomisierte Studien mit klinischen Endpunkten: bei generalisierter Angst 37 Prozent Remission gegenüber Warteliste (n = 50), bei Magersucht weniger Körperunzufriedenheit nach 6 Monaten (n = 68). Die methodisch sauberste Arbeit, ein RCT mit nicht unterscheidbarem Placebo im selben Tank (JAMA Network Open 2021, n = 99, chronischer Schmerz), verfehlte ihren primären Endpunkt – die Besserung trat auch unter Placebo ein. Sicherheit über mehrere Sitzungen ist in einer Machbarkeitsstudie mit 75 Teilnehmenden (PLoS One 2024) ohne schwere Nebenwirkungen belegt. Beworben werden Blutdrucksenkung, Entgiftung und Magnesiumaufnahme über die Haut – dafür reicht die Datenlage nicht.' },
  { id: 'vibrationstraining', view: 'behandlungen', evidenz: 6, mechanismus: 5, sicherheit: 4, hype: 3, anwendung: 7, richtung: 'gemischt',
    beleg: 'Der beworbene Knochen-Nutzen ist der am schlechtesten belegte: Eine Übersicht über 15 systematische Reviews bei Frauen nach der Menopause fand keinen signifikanten Vorteil für die Knochendichte, 13 der 15 Reviews wurden methodisch als kritisch niedrig eingestuft (BMC Womens Health 2024); Frakturdaten lieferte in einer Meta-Analyse nur 1 Studie. Besser belegt und weniger beworben ist der funktionelle Nutzen: In einer Meta-Analyse randomisierter Studien sank die Sturzrate bei Erwachsenen ab 50 (Rate Ratio 0,67, 4 Studien, 746 Teilnehmende, mittlere Evidenzqualität; BMJ Open 2017), und eine Netzwerk-Meta-Analyse von 27 Studien mit 1.608 Teilnehmenden zeigte Verbesserungen bei Gleichgewicht und Gang. Nur 5 der 15 Reviews erfassten Nebenwirkungen überhaupt.' },
  { id: 'neurostimulation', view: 'behandlungen', evidenz: 6, mechanismus: 6, sicherheit: 6, hype: 3, anwendung: 7, richtung: 'gemischt',
    beleg: 'Zwei sehr ungleiche Verfahren in einem Eintrag. Die repetitive Magnetstimulation ist bei Depression gut untersucht (Netzwerk-Meta-Analyse, 81 RCTs, 4.233 Patienten, JAMA Psychiatry 2017) und in der Nationalen Versorgungsleitlinie bei therapieresistenten Episoden empfohlen. Die im Biohacking genutzte Gleichstromstimulation zeigt bei Depression in einer Auswertung individueller Patientendaten (18 Studien, 1.246 Teilnehmende, Br J Psychiatry 2026) nur einen kleinen Effekt ohne mehr Remissionen; die deutsche DepressionDC-Studie (Lancet 2023, n = 160) verfehlte ihren primären Endpunkt, die Leitlinie spricht keine Empfehlung aus. Für kognitive Effekte bei Gesunden nach Einzelsitzungen fand ein quantitatives Review in 59 Analysen keinen Nachweis. Consumer-Geräte leihen sich Glaubwürdigkeit von einem anderen Verfahren.' },
  { id: 'fasten-autophagie', view: 'behandlungen', evidenz: 6, mechanismus: 5, sicherheit: 4, hype: 4, anwendung: 8, richtung: 'gemischt',
    beleg: 'Viel Evidenz für Surrogatmarker, keine für harte Endpunkte: Ein Umbrella-Review über 23 Meta-Analysen (Sun et al., eClinicalMedicine 2024) fand hohe Ergebnissicherheit nur für 12 Prozent der Zusammenhänge – Taillenumfang, Blutfette, Nüchterninsulin. Sterblichkeit und kardiovaskuläre Ereignisse wurden gar nicht untersucht. Der wiederkehrende Befund: Intervallfasten wirkt etwa so gut wie klassische Kalorienrestriktion, nicht besser. Die populäre Aussage, ab einer bestimmten Stundenzahl schalte die Autophagie an, ist am Menschen nicht belegt.' },
  { id: 'tpe-plasmaaustausch', view: 'behandlungen', evidenz: 3, mechanismus: 4, sicherheit: 6, hype: 3, anwendung: 5, richtung: 'offen',
    berichtslage: { stufe: 2, kurz: 'Deutliche Besserung – und Rückfall', was: 'Aus dem Umfeld von Long-COVID und ME/CFS gibt es zahlreiche, teils sehr detaillierte Berichte über deutliche Besserung nach mehreren Behandlungen – und ebenso über Rückfälle nach einigen Wochen. Beides zusammen, Ansprechen und Wiederkehr, ist eine spezifischere Beobachtung als bloße Besserung. Erklärt ist damit nichts, und die Selbstauswahl ist erheblich: Wer die Kosten selbst trägt, berichtet anders als wer nicht behandelt wurde. In scheinkontrollierten Studien (Spanien 2025, Mainz 2026 mit einem verwandten Filterverfahren, Suriname 2026 als Vorabdruck) schnitten die Scheingruppen nicht schlechter ab; in Suriname halbierte sich der Erschöpfungswert in beiden Gruppen.', quellen: 'Patientenkreise Long-COVID/ME-CFS · Praxisberichte · BMJ 2022 (Reportage) · Stein 2025 (Charité, Immunadsorption: 7 von 20 nach Ansprechen verschlechtert) · Wossidlo 2026 (Antikörper nach 3–6 Monaten zurück) · España-Cueto 2025 (Nat Commun) · Stortz 2026 (Lancet Reg Health Eur) · Suriname-Vorabdruck 2026 (F1000Research)' },
    beleg: 'Für den Anti-Aging-Einsatz existiert genau eine kontrollierte Studie (Fuentealba et al., Aging Cell 2025, n=42, einfach verblindet) mit einem Surrogatendpunkt – epigenetische Uhren sind selbst nicht als Endpunkt validiert –, und die Interessenkonflikte sind erheblich. Die Sicherheit ist vergleichsweise gut fundiert, aber aus anderen Indikationen: Für die wiederholte Anwendung bei Gesunden über Jahre gibt es keine Daten. Eine frühere Arbeit mit 8 Personen hatte keine Kontrollgruppe. Aus rund minus 1,3 Jahren auf einer Uhr wird Verjüngung gemacht – nach sechs Sitzungen war in keiner Gruppe mehr ein Unterschied zur Scheingruppe messbar.' },
  { id: 'ozontherapie', view: 'behandlungen', evidenz: 4, mechanismus: 3, sicherheit: 2, hype: 1, anwendung: 7, richtung: 'gemischt', berichtslage: { stufe: 1, kurz: 'Viel Anwendung, nichts Greifbares', was: 'Trotz jahrzehntelanger Anwendung in vielen Praxen bleiben die Berichte unspezifisch – Wohlbefinden, Energie, Infektanfälligkeit. Die schiere Zahl ersetzt die fehlende Spezifität nicht.', quellen: 'Praxisberichte · Anwenderkreise' },
    beleg: 'Mehr als Fallberichte, aber nicht viel mehr: Ein Umbrella-Review (Med Sci 2026) fand 7 Meta-Analysen randomisierter Studien zu 4 Anwendungen und stufte die Evidenzsicherheit für alle Endpunkte als niedrig oder sehr niedrig ein. Beim diabetischen Fuß war Ozon nicht überlegen (RR 1,69, Konfidenzintervall 0,90 bis 3,17), bei COVID-19 besserte sich nur ein Surrogat. Am besten schneiden örtliche Injektionen ab: 7 kontrollierte Studien mit 409 Menschen mit Kniearthrose zeigten stärkere Schmerzlinderung als Kortison. Für die meistverkaufte systemische Eigenbluttherapie bei Long-/Post-COVID fand der IGeL-Monitor 2023 keine Studie. Der Hormesis-Mechanismus stützt sich auf Zell- und Tierdaten. Dokumentiert sind Gasembolien mit Schlaganfall, Blutzerfall und Infektionen; ein Register für Zwischenfälle gibt es nicht.' },
  { id: 'exosomen', view: 'behandlungen', evidenz: 2, mechanismus: 3, sicherheit: 1, hype: 1, anwendung: 3, richtung: 'offen',
    berichtslage: { stufe: 2, kurz: 'Hohe Zufriedenheit nach Serum mit Microneedling', was: 'In Klinikauswertungen berichten Behandelte hohe Zufriedenheit (Südkorea, 40 Personen: 87,5 % zufrieden, 85 % würden weiterempfehlen). Im ersten doppelblinden Vergleich beim Haar besserte sich die Lebensqualität aber auch ohne Exosomen, nur durch Microneedling. Nach Injektionen außerhalb von Arztpraxen sind hartnäckige Entzündungen und Narben beschrieben. Eine systematische Auswertung von Forenbeiträgen gibt es nicht.', quellen: 'Cho 2026 · Luna-Garza 2026 · Park 2025' },
    beleg: 'Die Quellenlage widerspricht sich offen: Die ausgewertete Übersicht (Queen und Avram 2025) sichtete 48 Arbeiten; klinische Studien gibt es fast nur zum Haarausfall, 9 Arbeiten mit zusammen 125 Patienten, überwiegend ohne Kontrollgruppe. Bei der Haut zeigte eine randomisierte Gesichtshälften-Studie (Park 2023, 28 Personen, Microneedling mit Exosomen gegen Microneedling mit Kochsalz) Vorteile bei Falten, Elastizität und Pigmentierung. Die erste doppelblinde, kochsalzkontrollierte Studie beim Haar (Luna-Garza 2026, JEADV, 48 Personen, Microneedling mit oder ohne Fettstammzell-Exosomen, 12 Wochen; zitiert nach der Übersicht Tang 2026) fand keinen Unterschied in den Haarwerten; die Lebensqualität besserte sich in beiden Armen. Eine Metaanalyse (Stack 2026, 39 Studien) poolt überwiegend Vorher-nachher-Veränderungen. Für eine Infusion gegen Altern gibt es keine Humanstudie. Systemisch geprüft wurde eine Knochenmark-EV-Infusion bei COVID-ARDS (Phase 2, 102 Patienten, primärer Endpunkt verfehlt, Post-hoc-Untergruppe positiv); Phase 3 (NCT05354141, 970 geplant) läuft bis voraussichtlich Ende 2027. Die Sicherheit ist von allen Anwendungen am schlechtesten untersucht. Die US-Behörde stellt klar, dass kein Exosomen-Produkt zugelassen ist.' },
  { id: 'stammzelltherapie', view: 'behandlungen', evidenz: 4, mechanismus: 4, sicherheit: 3, hype: 1, anwendung: 4, richtung: 'gemischt',
    beleg: 'Für Anti-Aging bei Gesunden gibt es keine kontrollierte Studie. Was vorliegt, betrifft Kranke: bei Altersgebrechlichkeit eine Phase-II-Studie mit 30 Teilnehmenden, primär auf Sicherheit angelegt, mit Verbesserungen nur in der niedrigeren Dosisgruppe; bei Kniearthrose 28 randomisierte Studien mit Schmerzlinderung gegenüber Kontrollen, aber die größte (Nature Medicine 2023, 480 Patienten) fand nach 12 Monaten keinen Vorteil gegenüber Kortison und keine Strukturveränderung, und gegenüber Placebo gehen rund 63 Prozent der Schmerzlinderung auf Kontexteffekte zurück. Dokumentiert sind schwere Schäden nach ungeprüften Behandlungen bis zur dauerhaften Erblindung und Todesfälle; in Deutschland wurde 2011 eine Klinik nach dem Tod eines Kindes geschlossen. EMA und Paul-Ehrlich-Institut warnten im März 2025 gemeinsam vor kommerziellen Angeboten mit nicht zugelassenen Zelltherapien.' },
  { id: 'nad-infusion', view: 'behandlungen', evidenz: 3, mechanismus: 3, sicherheit: 3, hype: 2, anwendung: 4, richtung: 'offen', berichtslage: { stufe: 2, kurz: 'Druck auf der Brust bei der Infusion', was: 'Ein Effekt wird nahezu ausnahmslos berichtet und ist unverwechselbar: Druck auf der Brust, Übelkeit und Hitzegefühl während der Infusion, die verschwinden, sobald die Tropfgeschwindigkeit gesenkt wird. Das ist eine spezifische, dosisabhängige Beobachtung – sie belegt allerdings nur, dass der Stoff ankommt. Die Berichte zum eigentlichen Zweck, mehr Energie in den Tagen danach, sind demgegenüber unspezifisch.', quellen: 'Anwenderkreise · Praxisberichte aus Infusionszentren' },
    beleg: 'Evidenz 3: Für die beworbenen Zwecke Energie, Fokus und Anti-Aging gibt es keine kontrollierte Studie; eine systematische Übersicht von 2026 fand keine Endpunktstudie zu NAD+ über Vene oder Muskel. Am Menschen liegen eine Pilotstudie mit 11 Männern (Grant 2019), ein randomisierter Vergleich als herstellerfinanzierter Preprint (Hawkins 2024) und eine Kundenauswertung mit 14 Personen (Reyna 2026) vor; dazu kommt eine randomisierte Studie mit 180 Herzschwäche-Patienten aus China, in der die Auswurfleistung nach 1 Monat mit 45,44 gegenüber 42,44 Prozent stärker stieg (Yu 2026) – ein Krankheitsbefund an einem Zentrum mit Ultraschall-Endpunkt. Mechanismus 3: Die Biologie von NAD+ ist gut verstanden, aber infundiertes NAD+ verschwand in den ersten 2 Stunden vollständig aus dem Plasma, und im Vollblut stieg es erst nach 24 Stunden um 2 Prozent; ob es in den Zielzellen ankommt, ist nicht gemessen. Sicherheit 3: nur Kurzzeitdaten aus kleinen Studien; alle 6 NAD+-Empfänger der Kundenauswertung hatten mittelschwere bis schwere Beschwerden während der Infusion, im Preprint stiegen die Neutrophilen. Hype 2, weil Anbieter mit Zellreparatur und Verjüngung werben, wofür es keine Humandaten gibt. Anwendung 4: verbreitet in Praxen und Wellness-Zentren ohne zugelassene Indikation in der EU und den USA; nur in China als Arzneimittel registriert.' },
  { id: 'iv-vitamintherapie', view: 'behandlungen', evidenz: 3, mechanismus: 2, sicherheit: 3, hype: 1, anwendung: 6, richtung: 'offen',
    beleg: 'Es existiert im Wesentlichen eine placebokontrollierte Pilotstudie zum Myers-Cocktail (34 Fibromyalgie-Patienten, J Altern Complement Med 2009): Beide Gruppen besserten sich, ein Unterschied zwischen Infusion und Salzlösung zeigte sich in keinem Endpunkt. Die meistzitierte weitere Quelle ist ein Praxisbericht. Die Kernprämisse – Gesunde profitierten von supraphysiologischen Vitaminspiegeln – ist nicht belegt; bei Sepsis erhöhte hochdosiertes IV-Vitamin C sogar das Risiko für Tod oder Organversagen (LOVIT, NEJM 2022, 872 Patienten). Dokumentierte Risiken hochdosierten Vitamin C sind Hämolyse bei G6PD-Mangel und Oxalat-Nierenschäden; ein Screening findet in der Praxis nicht immer statt. Beworben werden Immunstärkung, Energie und Anti-Aging.' },
  { id: 'grounding-earthing', view: 'behandlungen', evidenz: 4, mechanismus: 1, sicherheit: 1, hype: 1, anwendung: 5, richtung: 'offen',
    beleg: 'Es gibt Humandaten, aber nur kleine: In einer randomisierten, scheinkontrollierten Studie mit 32 Männern (Open Access J Sports Med 2015) stieg die Kreatinkinase nach Kniebeugen nur ohne echte Erdung, beim Schmerz gab es keinen Vorteil. Kleine scheinkontrollierte Studien berichten bessere Schlafwerte, eine davon bei 15 Menschen mit leichter Alzheimer-Demenz, eine mit 56 Teilnehmenden war herstellerfinanziert und berichtet Verbesserungen gegenüber dem Ausgangswert. Endpunkte sind Blutwerte und Fragebögen, keine Krankheitsverläufe. Die postulierte Wirkkette, Elektronen aus dem Erdboden neutralisierten freie Radikale, ist am Menschen nicht belegt. Kontrollierte Sicherheitsstudien existieren nicht. Zentrale Arbeiten stammen aus einem engen Kreis von Befürwortern.' },
  { id: 'hyperthermie', view: 'behandlungen', evidenz: 5, mechanismus: 6, sicherheit: 5, hype: 3, anwendung: 7, richtung: 'gemischt',
    beleg: 'Für die milde Ganzkörperhyperthermie gibt es zwei kleine, scheinkontrollierte randomisierte Studien mit erreichtem primärem Endpunkt: bei Fibromyalgie (41 Patienten, weniger Schmerz in Woche 4 und Woche 30, J Clin Med 2023) und bei Depression (34 randomisiert, eine Sitzung, Besserung über 6 Wochen, JAMA Psychiatry 2016). Eine zweite Depressionsstudie mit Psychotherapie fand keinen Vorteil gegenüber Schein (2025). Der starke onkologische Beleg – längeres Überleben beim Weichteilsarkom in einer Phase-3-Studie mit 341 Patienten – betrifft die regionale Hyperthermie zusätzlich zur Chemotherapie, nicht die milde Ganzkörperform. Für die in Privatpraxen beworbenen Anwendungen Entgiftung, chronische Infekte und Immunstärkung gibt es keine kontrollierten Daten. Die Sicherheitsdaten sind kurzfristig: In 855 Sitzungen bei Krebspatienten keine schweren Zwischenfälle, aber häufig Kopfschmerz; Kreislaufbelastung ist das Hauptthema.' },

  // ---------- Tipps ----------
  // Nachgetragen 30.08.2026. Bis dahin waren die 57 Tipps die einzige Kategorie
  // ohne BK-Score – obwohl gerade hier Zahlen im Umlauf sind, die aus einer
  // einzigen kleinen Studie stammen. Dieselben fuenf Achsen, dieselbe Regel:
  // bewertet wird der Wissensstand, nicht der Nutzen.
  { id: 'schlaf-dunkel', view: 'tipps', evidenz: 7, mechanismus: 9, sicherheit: 9, hype: 6, anwendung: 9, richtung: 'positiv',
    beleg: 'Dass Licht am Abend die Melatonin-Ausschüttung dämpft, ist am Menschen mehrfach im Schlaflabor gemessen worden, die Wirkkette über die Ganglienzellen der Netzhaut ist bekannt. Der Hype-Abzug betrifft die Dosis: Die Studien arbeiten mit Raumlicht, nicht mit der Standby-Leuchte am Fernseher.' },
  { id: 'schlaf-temperatur', view: 'tipps', evidenz: 6, mechanismus: 8, sicherheit: 9, hype: 7, anwendung: 9, richtung: 'positiv',
    beleg: 'Die Thermoregulation des Einschlafens ist gut verstanden und in Schlaflabor-Studien untersucht. Die konkrete Spanne 16–18 °C ist allerdings eine Faustregel, keine studienbelegte Optimalzone.' },
  { id: 'schlaf-blaulicht', view: 'tipps', evidenz: 5, mechanismus: 8, sicherheit: 9, hype: 4, anwendung: 8, richtung: 'gemischt',
    beleg: 'Die Melatonin-Unterdrückung durch kurzwelliges Licht ist belegt. Ob Blaulichtfilter und Brillen daraus messbar besseren Schlaf machen, zeigen die Studien uneinheitlich – sie sind klein und schwer zu verblinden.' },
  { id: 'schlaf-zeit', view: 'tipps', evidenz: 7, mechanismus: 7, sicherheit: 10, hype: 8, anwendung: 10, richtung: 'positiv',
    beleg: 'Grosse Kohorten zeigen: Die Regelmässigkeit der Schlafzeiten sagt Sterblichkeit besser vorher als die Schlafdauer. Kausal belegt ist das nicht, aber der Zusammenhang ist konsistent und der Rat kostet nichts.' },
  { id: 'schlaf-koffein', view: 'tipps', evidenz: 8, mechanismus: 9, sicherheit: 9, hype: 8, anwendung: 10, richtung: 'positiv',
    beleg: 'Die Halbwertszeit von etwa vier Stunden stammt aus publizierten pharmakokinetischen Messungen, nicht aus Schlafstudien, und der Adenosin-Antagonismus ist am Menschen quantifiziert. Die Uhrzeit 14 Uhr ist daraus abgeleitet – individuell verschieden, je nach Abbaugeschwindigkeit (CYP1A2) und Rezeptorempfindlichkeit (ADORA2A).' },
  { id: 'licht-morgen', view: 'tipps', evidenz: 8, mechanismus: 9, sicherheit: 9, hype: 6, anwendung: 9, richtung: 'positiv',
    beleg: 'Die Phasenverschiebung der inneren Uhr durch Morgenlicht gehört zu den am besten untersuchten chronobiologischen Effekten überhaupt. Der Abzug beim Hype-Abstand gilt dem Cortisol: Die Aufwachreaktion wird vom Licht moduliert, nicht von ihm gesetzt.' },
  { id: 'licht-rot', view: 'tipps', evidenz: 4, mechanismus: 5, sicherheit: 7, hype: 3, anwendung: 6, richtung: 'gemischt',
    beleg: 'Es gibt viele kleine Humanstudien zu Haut, Muskelregeneration und Wundheilung, aber sehr unterschiedliche Geräte, Wellenlängen und Dosen – vergleichbar sind sie kaum. Der Mechanismus über Cytochrom-c-Oxidase ist plausibel, am Menschen aber nicht quantifiziert.' },
  { id: 'licht-mittag', view: 'tipps', evidenz: 8, mechanismus: 9, sicherheit: 7, hype: 6, anwendung: 10, richtung: 'gemischt',
    beleg: 'Dass UVB in der Haut Vitamin D bildet, ist gesicherte Physiologie. Gemischt ist die Richtung wegen der Kehrseite: Dieselbe Strahlung ist der wichtigste Risikofaktor für Hautkrebs – die Dosis entscheidet, und dafür gibt es keine allgemeingültige Zahl.' },
  { id: 'kaltduschen', view: 'tipps', evidenz: 4, mechanismus: 5, sicherheit: 7, hype: 3, anwendung: 8, richtung: 'gemischt',
    beleg: 'Die viel zitierte Dopamin-Verdreifachung stammt aus einer Untersuchung an einer sehr kleinen Gruppe junger Männer im 14-°C-Wasser, nicht aus der Dusche. Die Immundaten kommen aus einer niederländischen Studie, in der Kaltduscher sich seltener krankmeldeten – aber nicht seltener krank waren; eine Meta-Analyse über elf RCTs fand gar keinen Immuneffekt.' },
  { id: 'eisbad', view: 'tipps', evidenz: 4, mechanismus: 6, sicherheit: 5, hype: 3, anwendung: 7, richtung: 'gemischt',
    beleg: 'Die akute Katecholamin-Antwort ist gut messbar, langfristige Effekte auf Stoffwechsel und Gesundheit sind es nicht. Die Sicherheits-Datenlage ist der schwächste Wert: Kälteschock und Herzrhythmus sind bei Vorerkrankungen nie systematisch untersucht worden.' },
  { id: 'sauna', view: 'tipps', evidenz: 6, mechanismus: 6, sicherheit: 8, hype: 4, anwendung: 10, richtung: 'gemischt',
    beleg: 'Die finnische Kuopio-Kohorte begleitete über 2.300 Männer mehr als zwanzig Jahre – häufige Saunagänger starben seltener an Herzerkrankungen. Das ist eine Beobachtung an Menschen, die sich auch sonst unterscheiden, keine randomisierte Studie. Die verbreitete Prozentzahl beschreibt einen Zusammenhang, keine Wirkung.' },
  { id: 'box-breathing', view: 'tipps', evidenz: 5, mechanismus: 7, sicherheit: 9, hype: 6, anwendung: 9, richtung: 'positiv',
    beleg: 'Dass langsames Atmen um sechs Atemzüge pro Minute die Herzratenvariabilität und den Vagustonus akut erhöht, ist gut gemessen – Box Breathing mit 4-4-4-4 liegt allerdings nicht in diesem Resonanzbereich, und die einzige HRV-Messung dazu fand keine Veränderung. Über die akute Wirkung hinaus – Angst, Leistung, Stressresistenz – sind die Studien klein und kurz.' },
  { id: 'wim-hof-atmung', view: 'tipps', evidenz: 4, mechanismus: 6, sicherheit: 4, hype: 3, anwendung: 7, richtung: 'gemischt',
    beleg: 'Die Endotoxin-Studie aus Nijmegen mit zwölf trainierten Teilnehmern wurde von derselben Gruppe mit 48 gesunden Männern reproduziert – darüber hinaus gibt es kaum etwas, und alle Teilnehmer waren jung, männlich und gesund. Die Sicherheits-Datenlage ist der niedrigste Wert dieser Liste: Hyperventilation mit anschliessendem Luftanhalten hat im Wasser wiederholt zu Todesfällen geführt, und an Land fällt die Sättigung auf rund 60 %.' },
  { id: 'nasenatmung', view: 'tipps', evidenz: 5, mechanismus: 7, sicherheit: 9, hype: 6, anwendung: 10, richtung: 'positiv',
    beleg: 'Dass die Nasennebenhöhlen Stickstoffmonoxid abgeben und die Nase die Atemluft anfeuchtet und filtert, ist gesichert. Die weitergehenden Versprechen – besserer Schlaf, mehr Ausdauer – stützen sich auf kleine Studien und Selbstberichte.' },
  { id: 'atmung-buteyko', view: 'tipps', evidenz: 5, mechanismus: 4, sicherheit: 7, hype: 4, anwendung: 7, richtung: 'gemischt',
    beleg: 'Kontrollierte Studien bei Asthma zeigen weniger Symptome und weniger Bedarfsmedikation – die objektive Lungenfunktion ändert sich aber nicht. Der CO2-Anstieg durch Atemumschulung ist messbar und hat einen eigenen Anteil am Effekt; die weitergehende Buteyko-Annahme, chronische Hyperventilation sei die Ursache von Asthma, ist dagegen nicht belegt.' },
  { id: 'co2-tolerance', view: 'tipps', evidenz: 2, mechanismus: 4, sicherheit: 6, hype: 3, anwendung: 5, richtung: 'offen',
    beleg: 'Der CO2-Toleranztest ist ein Messwert aus der Tauch- und Atemszene, kein validierter Parameter. Dass ein Training darauf die Sauerstoffverwertung verbessert, ist am Menschen nicht gezeigt.' },
  { id: 'intervallfasten', view: 'tipps', evidenz: 7, mechanismus: 5, sicherheit: 8, hype: 4, anwendung: 9, richtung: 'gemischt',
    beleg: 'Es gibt zahlreiche randomisierte Studien. Ihr gemeinsames Ergebnis: Zeitfenster-Essen wirkt so gut wie eine gleich grosse Kalorienreduktion – nicht besser. Die Autophagie ist der Hype-Abzug: Sie ist beim fastenden Menschen nie direkt gemessen worden.' },
  { id: 'proteine-morgen', view: 'tipps', evidenz: 7, mechanismus: 8, sicherheit: 9, hype: 7, anwendung: 10, richtung: 'positiv',
    beleg: 'Sättigungswirkung und Muskelproteinsynthese sind am Menschen gut untersucht; die Grössenordnung von 25–35 g pro Mahlzeit ist eine Zusammenfassung mehrerer Dosis-Wirkungs-Studien, keine unmittelbar gemessene Zahl. Dass ausgerechnet das Frühstück entscheidend wäre, ist dagegen nicht belegt.' },
  { id: 'apfelessig', view: 'tipps', evidenz: 4, mechanismus: 5, sicherheit: 7, hype: 3, anwendung: 8, richtung: 'gemischt',
    beleg: 'Die Prozentzahl stammt aus kleinen Crossover-Versuchen mit oft weniger als zwanzig Teilnehmern und einer definierten Testmahlzeit. Für den Alltag lässt sich daraus keine verlässliche Grösse ableiten; der Zahnschmelz leidet dagegen messbar.' },
  { id: 'low-carb-abend', view: 'tipps', evidenz: 3, mechanismus: 4, sicherheit: 8, hype: 4, anwendung: 8, richtung: 'offen',
    beleg: 'Zur Verteilung der Kohlenhydrate über den Tag gibt es einzelne kleine Studien mit widersprüchlichen Ergebnissen – eine fand bei abendlicher Kohlenhydratzufuhr eine kürzere Einschlafzeit, sonst keinen Schlafparameter verändert. Gut belegt ist nur der akute Glukoseverlauf: dieselbe Menge erzeugt abends eine höhere Spitze. Für das Gewicht gibt die Datenlage keine belastbare Empfehlung her.' },
  { id: 'wasser-qualitaet', view: 'tipps', evidenz: 3, mechanismus: 5, sicherheit: 7, hype: 4, anwendung: 9, richtung: 'offen',
    beleg: 'Deutsches Leitungswasser ist eines der am strengsten überwachten Lebensmittel; ein gesundheitlicher Nutzen zusätzlicher Filterung ist in Studien nicht gezeigt. Umgekehrt können schlecht gewartete Filter die Keimzahl erhöhen.' },
  { id: 'testosteron-natural', view: 'tipps', evidenz: 5, mechanismus: 7, sicherheit: 8, hype: 4, anwendung: 9, richtung: 'gemischt',
    beleg: 'Für die Einzelbausteine – Schlaf, Krafttraining, Zink bei Mangel – gibt es jeweils Humandaten. Die Zahl „80 % des Hebels" ist dagegen frei geschätzt; ein gemeinsamer Effekt des Bündels ist nie gemessen worden.' },
  { id: 'protein-longevity', view: 'tipps', evidenz: 7, mechanismus: 8, sicherheit: 9, hype: 7, anwendung: 9, richtung: 'positiv',
    beleg: 'Dass ältere Menschen für dieselbe Muskelproteinsynthese mehr Protein brauchen (anabole Resistenz), ist am Menschen gemessen – 0,40 gegenüber 0,24 g/kg pro Mahlzeit. Die genannten Mengen von 1,6 bis 2,2 g/kg liegen allerdings deutlich über den Empfehlungen der geriatrischen Fachgesellschaften (PROT-AGE und ESPEN: 1,0 bis 1,2 g/kg für gesunde Ältere) und stammen aus dem Longevity-Umfeld, nicht aus einer Leitlinie. Bei eingeschränkter Nierenfunktion gilt das nicht.' },
  { id: 'nef-training', view: 'tipps', evidenz: 9, mechanismus: 8, sicherheit: 9, hype: 8, anwendung: 10, richtung: 'positiv',
    beleg: 'Krafttraining ist die am besten belegte Einzelmassnahme dieser gesamten Datenbank: Meta-Analysen zeigen Effekte auf Muskelmasse, Knochendichte und Stoffwechsel. Bei der Sterblichkeit ist es ein Zusammenhang aus Kohortenstudien, keine gemessene Wirkung, und die Dosis-Wirkungs-Kurve ist J-förmig mit einem Optimum bei 30 bis 60 Minuten pro Woche. Der Abzug betrifft die Formulierung „nichts ist so anti-aging“ – ein Vergleich, den keine Studie so angestellt hat.' },
  { id: 'zone-2', view: 'tipps', evidenz: 6, mechanismus: 7, sicherheit: 9, hype: 4, anwendung: 9, richtung: 'gemischt',
    beleg: 'Dass Ausdauertraining die Mitochondriendichte erhöht, geht auf Holloszy 1967 zurück – eine Rattenstudie; die Humandaten sind jünger, und die aktuellste Meta-Analyse stuft ihre Sicherheit selbst als sehr niedrig bis niedrig ein. Dass ausgerechnet die Zone-2-Intensität das Maximum darstellt, ist eine populäre Zuspitzung – im direkten Vergleich schneidet hochintensives Training bei der Mitochondrien-Biogenese oft ebenso gut ab.' },
  { id: 'zone2-mito', view: 'tipps', evidenz: 6, mechanismus: 7, sicherheit: 9, hype: 4, anwendung: 9, richtung: 'gemischt',
    beleg: 'Dass Ausdauertraining die Mitochondriendichte erhöht, stammt im Kern aus Rattenstudien; die Humandaten umfassen 14 Studien mit 184 Teilnehmern bei sehr niedriger bis niedriger Evidenzsicherheit. Dass die Zone-2-Intensität dafür die beste ist, ist eine populäre Zuspitzung und im direkten Vergleich mit intensiverem Training nicht bestätigt.' },
  { id: 'hiit', view: 'tipps', evidenz: 8, mechanismus: 8, sicherheit: 8, hype: 7, anwendung: 9, richtung: 'positiv',
    beleg: 'Die Steigerung der VO2max durch Intervalltraining ist in vielen randomisierten Studien und Meta-Analysen gemessen. Abzug bei der Sicherheit für die Datenlage bei Herzvorerkrankten und Untrainierten, die in den Studien meist ausgeschlossen waren.' },
  { id: 'bewegung-alltag', view: 'tipps', evidenz: 8, mechanismus: 7, sicherheit: 10, hype: 5, anwendung: 10, richtung: 'positiv',
    beleg: 'Grosse Kohorten mit Schrittzählern zeigen einen klaren Zusammenhang zwischen Schrittzahl und Sterblichkeit – mit dem Grossteil des Gewinns je nach Alter schon zwischen 6.000 und 10.000 Schritten. Für die 10.000 als Ziel gibt es wenig Evidenz, wie die Kohortenarbeiten selbst festhalten; für Demenz liegt das Optimum allerdings bei fast genau 10.000 Schritten.' },
  { id: 'bewegung-post-meal', view: 'tipps', evidenz: 7, mechanismus: 8, sicherheit: 10, hype: 7, anwendung: 8, richtung: 'positiv',
    beleg: 'Inzwischen zeigen mindestens vier Meta-Analysen, dass kurze Spaziergänge nach dem Essen die Blutzuckerspitze abflachen – der Mechanismus über die muskuläre Glukoseaufnahme ist am Menschen belegt. Die verbreitete Prozentzahl steht allerdings in keiner dieser Arbeiten, und die neueste stuft die Evidenzsicherheit für alle primären Endpunkte als niedrig ein.' },
  { id: 'meditation', view: 'tipps', evidenz: 6, mechanismus: 5, sicherheit: 9, hype: 5, anwendung: 10, richtung: 'gemischt',
    beleg: 'Es gibt viele randomisierte Studien; Meta-Analysen finden kleine bis mittlere Effekte auf Angst, Stress und Depressivität – meist gegen Wartelisten, seltener gegen aktive Vergleichsgruppen. Für Cortisol zeigt die neueste Meta-Analyse einen kleinen, aber messbaren Rückgang bei weiterhin grosser Streuung zwischen den Studien.' },
  { id: 'dankbarkeit', view: 'tipps', evidenz: 5, mechanismus: 4, sicherheit: 10, hype: 5, anwendung: 9, richtung: 'gemischt',
    beleg: 'Randomisierte Studien zeigen kleine Effekte auf Stimmung und Wohlbefinden, oft nur kurz nach der Intervention. Neuere Übersichtsarbeiten mit aktiven Kontrollgruppen finden deutlich weniger als die frühen Arbeiten.' },
  { id: 'digital-detox', view: 'tipps', evidenz: 2, mechanismus: 3, sicherheit: 10, hype: 3, anwendung: 8, richtung: 'offen',
    beleg: 'Der behauptete Cortisol-Anstieg durch das morgendliche Smartphone ist nie gemessen worden. Für weniger Social-Media-Nutzung gibt es inzwischen eine Meta-Analyse randomisierter Studien mit einem kleinen, konsistenten Effekt auf depressive Symptome – geprüft ist damit aber die Menge, nicht der Zeitpunkt. Der Rat ist harmlos; für die Stunde nach dem Aufwachen belegt ist er nicht.' },
  { id: 'natur', view: 'tipps', evidenz: 4, mechanismus: 4, sicherheit: 10, hype: 4, anwendung: 8, richtung: 'gemischt',
    beleg: 'Die bekannten Befunde zu natürlichen Killerzellen stammen aus kleinen japanischen Studien einer einzigen Arbeitsgruppe und sind unabhängig kaum repliziert. Der Zusammenhang zwischen Grünflächen und Wohlbefinden ist in grossen Kohorten dagegen konsistent.' },
  { id: 'grounding', view: 'tipps', evidenz: 1, mechanismus: 2, sicherheit: 8, hype: 2, anwendung: 5, richtung: 'offen',
    beleg: 'Die vorliegenden Studien sind sehr klein, überwiegend unverblindet und stammen weitgehend aus dem Umfeld der Anbieter von Erdungsprodukten. Ein Mechanismus, über den Erdkontakt Entzündungsmarker senken sollte, ist nicht beschrieben.' },
  { id: 'nootropic-stack', view: 'tipps', evidenz: 6, mechanismus: 7, sicherheit: 8, hype: 6, anwendung: 9, richtung: 'positiv',
    beleg: 'Die Kombination aus Koffein und L-Theanin ist in mehreren randomisierten Studien auf Aufmerksamkeit und Aufgabenwechsel untersucht, mit kleinen, aber wiederholt gefundenen Effekten. Für die Löwenmähne gilt das nicht – dort fehlen die Humandaten.' },
  { id: 'dual-n-back', view: 'tipps', evidenz: 6, mechanismus: 3, sicherheit: 10, hype: 2, anwendung: 7, richtung: 'negativ',
    berichtslage: { stufe: 2, kurz: 'Viele fühlen sich schärfer — es trägt nicht', was: 'Übereinstimmend berichtet wird, sich nach einigen Wochen wacher und konzentrierter zu fühlen. Das ist ernst zu nehmen und zugleich der Kern des Problems: Genau dieses Gefühl ist das, was die Meta-Analysen gemessen und als nicht übertragbar befunden haben. Man wird in der Aufgabe besser und merkt das — nur bleibt es dort. Ein selteneres Muster: Die Berichte sind echt, die Schlussfolgerung daraus ist es nicht.', quellen: 'Anwenderkreise' },
    beleg: 'Hier gibt es Daten, und die Meta-Analysen streiten darüber: In der Aufgabe selbst wird man deutlich besser (Soveri et al. 2017: g = 0,62). Beim Transfer auf fluide Intelligenz fand Au et al. 2015 einen kleinen Effekt, Soveri 2017 einen sehr kleinen (g = 0,16, rund ein Prozent erklärter Varianz), und Melby-Lervåg, Redick & Hulme 2016 mit aktiven Kontrollgruppen keinen. Je besser die Kontrollgruppe, desto kleiner der Effekt. Die Formulierung „einziges Gehirntraining, das nachweislich wirkt" ist die Umkehrung des Befundes.' },
  { id: 'morning-routine', view: 'tipps', evidenz: 4, mechanismus: 5, sicherheit: 9, hype: 5, anwendung: 9, richtung: 'gemischt',
    beleg: 'Die einzelnen Bausteine sind unterschiedlich gut belegt – Morgenlicht gut, Kälte dünn. Das Bündel als Ganzes ist nie gegen eine Kontrollgruppe getestet worden; wer es befolgt, weiss hinterher nicht, welcher Teil gewirkt hat.' },
  { id: 'evening-routine', view: 'tipps', evidenz: 5, mechanismus: 6, sicherheit: 10, hype: 6, anwendung: 9, richtung: 'positiv',
    beleg: 'Schlafhygiene-Programme sind in der Verhaltenstherapie der Insomnie untersucht und wirksam – allerdings meist als Teil eines Gesamtpakets (KVT-I), nicht als isolierte Abendroutine.' },
  { id: 'hrv-tracking', view: 'tipps', evidenz: 5, mechanismus: 7, sicherheit: 10, hype: 4, anwendung: 8, richtung: 'gemischt',
    beleg: 'Die Herzratenvariabilität bildet die vegetative Balance nachweislich ab, und HRV-gesteuertes Training zeigt in kleinen Sportstudien Vorteile. Dass ein einzelner Tageswert am Handgelenk brauchbar steuert, ist dagegen nicht belegt – die Tagesschwankung ist gross.' },
  { id: 'blutwerte', view: 'tipps', evidenz: 6, mechanismus: 8, sicherheit: 10, hype: 7, anwendung: 10, richtung: 'positiv',
    beleg: 'Für einzelne Marker gibt es hervorragende Daten. Für das jährliche Screening bei Beschwerdefreien ist der Nutzen dagegen umstritten: Grosse Studien zu allgemeinen Gesundheits-Checks fanden keine Senkung der Sterblichkeit.' },
  { id: 'cgm-tracking', view: 'tipps', evidenz: 3, mechanismus: 7, sicherheit: 8, hype: 3, anwendung: 7, richtung: 'offen',
    beleg: 'Bei Diabetes ist der Nutzen belegt. Bei Stoffwechselgesunden gibt es keine Studie, die zeigt, dass das Vermeiden von Glukosespitzen zu besseren Ergebnissen führt – wohl aber Berichte über Verunsicherung und unnötige Einschränkung.' },
  { id: 'oura-whoop', view: 'tipps', evidenz: 4, mechanismus: 6, sicherheit: 10, hype: 3, anwendung: 9, richtung: 'gemischt',
    beleg: 'Validierungsstudien gegen Polysomnographie zeigen: Die Geräte erkennen Schlaf und Wachsein recht gut, die einzelnen Schlafphasen dagegen unzuverlässig. Genau diese Phasen stehen aber im Mittelpunkt der Vermarktung.' },
  { id: 'blutbild-erweitert', view: 'tipps', evidenz: 7, mechanismus: 8, sicherheit: 10, hype: 7, anwendung: 9, richtung: 'positiv',
    beleg: 'Die genannten Marker sind einzeln gut validiert – ApoB und HbA1c gehören zu den bestuntersuchten Risikoparametern überhaupt. Was fehlt, ist eine Studie zu diesem Panel als Bündel bei Gesunden.' },
  { id: 'zyklus-tracking', view: 'tipps', evidenz: 3, mechanismus: 5, sicherheit: 9, hype: 3, anwendung: 7, richtung: 'gemischt',
    beleg: 'Übersichtsarbeiten zum zyklusbasierten Training kommen zu einem ernüchternden Ergebnis: Die Effekte sind klein, die Studien methodisch schwach und die individuellen Unterschiede grösser als der Phaseneffekt.' },
  { id: 'hbot', view: 'tipps', evidenz: 4, mechanismus: 6, sicherheit: 7, hype: 3, anwendung: 8, richtung: 'gemischt',
    beleg: 'Am ehesten belegt ist das diabetische Fußulkus, und dort für den Sechs-Wochen-Endpunkt; für die meistgenannte Indikation Kohlenmonoxidvergiftung fand die Cochrane-Auswertung keinen signifikanten Vorteil. Die Longevity-Anwendung stützt sich auf eine kleine israelische Studie ohne Kontrollgruppe, deren Telomer-Befund unabhängig nicht bestätigt ist.' },
  { id: 'ewot', view: 'tipps', evidenz: 1, mechanismus: 3, sicherheit: 5, hype: 2, anwendung: 4, richtung: 'offen',
    beleg: 'Zu EWOT selbst gibt es keine Daten, wohl aber zwei randomisierte Studien zur Nachbarfrage – Training unter Hyperoxie bei Gesunden und bei Menschen mit belastungsinduzierter Entsättigung – und beide sind negativ ausgegangen. Der behauptete Mechanismus setzt eine Sauerstoffunterversorgung voraus, die beim gesunden Menschen auf Meereshöhe nicht vorliegt.' },
  { id: 'iht', view: 'tipps', evidenz: 3, mechanismus: 5, sicherheit: 5, hype: 3, anwendung: 5, richtung: 'offen',
    beleg: 'Es gibt kleine Studien aus der Rehabilitation mit uneinheitlichen Ergebnissen und wechselnden Protokollen; die neueren kontrollierten Arbeiten kommen aus Österreich, Spanien, Italien und Deutschland. Die Sicherheits-Datenlage ist dünn, gerade bei Herz- und Lungenvorerkrankungen, und eine vielzitierte Arbeit wurde zurückgezogen.' },
  { id: 'altitude-training', view: 'tipps', evidenz: 6, mechanismus: 8, sicherheit: 6, hype: 5, anwendung: 8, richtung: 'gemischt',
    beleg: 'Das Prinzip „live high, train low“ ist im Leistungssport gut untersucht und die EPO-Antwort messbar. Für Höhenzelte fand die einzige placebokontrollierte Studie mit normobarer Hypoxie gar keinen Effekt, und auch eine kontrollierte Studie in echter Höhe blieb ohne Befund. In der klassischen Responder-Analyse waren 15 von 32 eingeteilten Läufern Non-Responder.' },
  { id: 'eisen-ferritin', view: 'tipps', evidenz: 8, mechanismus: 9, sicherheit: 8, hype: 7, anwendung: 10, richtung: 'positiv',
    beleg: 'Der Zusammenhang zwischen Eisenmangel, Hämoglobin und Leistungsfähigkeit ist ausgezeichnet belegt. Die Richtung gilt aber nur beim Mangel – ohne nachgewiesenen Mangel schadet Eisen mehr, als es nützt, weshalb hier gemessen und nicht geraten werden muss.' },
  { id: 'fasten-omad', view: 'tipps', evidenz: 4, mechanismus: 4, sicherheit: 6, hype: 3, anwendung: 7, richtung: 'gemischt',
    beleg: 'Es gibt genau eine kontrollierte Studie zu einer Mahlzeit pro Tag – 15 Teilnehmer, in zwei Auswertungen publiziert. Sie war gewichtserhaltend angelegt und fand bei gleichem Gewicht weniger Fettmasse, aber ungünstige Veränderungen bei Nüchternglukose und Blutfetten, die nach Rückkehr zu drei Mahlzeiten sofort verschwanden. Die Datenlage trägt keine Empfehlung, weder dafür noch dagegen.' },
  { id: 'fasten-extended', view: 'tipps', evidenz: 3, mechanismus: 4, sicherheit: 5, hype: 2, anwendung: 7, richtung: 'gemischt',
    beleg: 'Die Zeitangaben – Autophagie ab 24 Stunden, Stammzellerneuerung ab 72 – stammen aus Mausversuchen. Beim Menschen wurden systemische Veränderungen im Plasmaproteom erst nach drei Tagen vollständigen Fastens sichtbar, und Autophagie ist im Fasten nie direkt gemessen worden.' },
  { id: 'fasten-fmd', view: 'tipps', evidenz: 5, mechanismus: 5, sicherheit: 7, hype: 4, anwendung: 6, richtung: 'gemischt',
    beleg: 'Es gibt randomisierte Studien mit rund hundert Teilnehmern, die Veränderungen bei Blutdruck, Blutzucker und Entzündungsmarkern zeigen – überwiegend Surrogatmarker über wenige Zyklen; zwei Studien erreichen inzwischen klinische Endpunkte bei Diabetes und Morbus Crohn. Harte Endpunkte wie Sterblichkeit fehlen. Die Ursprungsstudien stammen aus dem Umfeld des Entwicklers, die neueren Arbeiten nicht mehr.' },
  { id: 'fasten-refeed', view: 'tipps', evidenz: 5, mechanismus: 7, sicherheit: 7, hype: 6, anwendung: 8, richtung: 'positiv',
    beleg: 'Das Refeeding-Syndrom ist eine anerkannte klinische Entität mit klaren Leitlinien – das ist der belegte Kern. Die Übertragung auf mehrtägiges freiwilliges Fasten bei Gesunden ist plausibel, aber nicht studienbelegt.' },
  { id: 'fasten-elektrolyte', view: 'tipps', evidenz: 4, mechanismus: 7, sicherheit: 7, hype: 7, anwendung: 8, richtung: 'positiv',
    beleg: 'Der Natrium- und Kaliumverlust im Fasten ist physiologisch beschrieben und erklärt die typischen Beschwerden gut. Kontrollierte Studien, die eine bestimmte Zufuhr belegen, gibt es allerdings nicht – die Mengenangaben in der Szene sind Erfahrungswerte.' },
  { id: 'fasten-frauen', view: 'tipps', evidenz: 2, mechanismus: 4, sicherheit: 5, hype: 3, anwendung: 6, richtung: 'offen',
    beleg: 'Zum zyklusangepassten Fasten gibt es keine kontrollierten Studien. Was es gibt, sind Hinweise, dass starke Energiedefizite die Hypothalamus-Hypophysen-Achse stören können – daraus ist die Vorsichtsregel abgeleitet, nicht aus einem Wirknachweis.' },
  { id: 'fasten-koffein', view: 'tipps', evidenz: 3, mechanismus: 4, sicherheit: 8, hype: 3, anwendung: 9, richtung: 'offen',
    beleg: 'Die Autophagie-Verstärkung durch Kaffee stammt aus Mausversuchen, und dort wirkte entkoffeinierter Kaffee ebenso gut – das Koffein trägt den Befund also nicht einmal im Mausmodell. Beim Menschen ist die Hungerdämpfung durch Koffein uneinheitlich: In der am besten kontrollierten Einzelstudie unterschied sich die spätere Energieaufnahme nicht.' },
  { id: 'senolytikum-pulse', view: 'tipps', evidenz: 1, mechanismus: 3, sicherheit: 2, hype: 2, anwendung: 4, richtung: 'negativ',
    beleg: 'Evidenz 1: Zum Pulsschema gibt es keine berichteten Humandaten – die einzige placebokontrollierte Studie dazu (AFFIRM, 40 Frauen ab 70 Jahren) läuft seit dem 6.2.2018 und hat nichts veröffentlicht, im Register steht der 1.11.2026. Mechanismus 3: Zellkultur-Screening und die Mausarbeit von 2018 stützen den Pfad, aber das Interventions-Testprogramm fand 2023 keine Senkung der Seneszenzmarker in Leber, Niere und Gehirn, sodass der Mechanismus über die Erstbeschreibung hinaus unbestätigt ist. Sicherheit 2: Ohne berichtete Humanstudie gibt es keine systematisch erhobene Sicherheitsdatenlage für hohe Pulse, bekannt sind nur Wechselwirkungen von Quercetin mit Blutverdünnern und einigen Antibiotika. Hype 2 bleibt, weil Packungen Zellerneuerung versprechen, während der Mechanismus in der besten Replikation nicht auffindbar war, und Anwendung 4 bleibt, weil Fisetin breit und ohne regulatorischen Rahmen im Regal steht; die Richtung wird von offen auf negativ gesetzt, da mit dem Testprogramm Daten vorliegen, die gegen die Wirkung sprechen.' },
  { id: 'inuspherese', view: 'behandlungen', evidenz: 2, mechanismus: 4, sicherheit: 4, hype: 1, anwendung: 4, richtung: 'offen', berichtslage: { stufe: 2, kurz: 'Deutliche Besserung – und Rückfall', was: 'Aus dem Umfeld von Long-COVID, ME/CFS und Umweltmedizin gibt es zahlreiche, teils sehr detaillierte Berichte über deutliche Besserung nach mehreren Behandlungen, ebenso über Rückfälle nach Wochen. Dieses Muster aus Ansprechen und Wiederkehr ist spezifischer als bloße Besserung. Die Selbstauswahl ist allerdings erheblich: Die Behandlung kostet mehrere tausend Euro und wird selbst bezahlt, und wer so viel investiert, berichtet anders als wer unbehandelt bleibt.', quellen: 'Patientenkreise Long-COVID/ME-CFS · Anbieterberichte' },
    beleg: 'Die Deutsche Gesellschaft für Nephrologie hat 2022 ausdrücklich Stellung bezogen: Es gibt viele Fallberichte, aber keine randomisierten kontrollierten Studien; sie fordert solche Studien und lehnt den Einsatz bei Long- und Post-COVID außerhalb von Studien ab. Zur Lipidapherese bei Long-COVID schrieb sie, es gebe weder eine plausible Begründung noch wissenschaftliche Evidenz. Eine Dresdner Arbeit von 2025 fand im Filterrückstand von 21 ME/CFS-Patienten 14 kunststoffähnliche Substanzen, qualitativ und mit Koautoren aus dem Anbieterumfeld. Die beworbene Entfernung von Umweltgiften ist zudem eine andere Behauptung als die untersuchte Entfernung von Autoantikörpern: Dass ein Filter etwas aus dem Blut holt, ist plausibel und teils messbar; dass dies die Beschwerden verursacht hat und ihre Entfernung sie beendet, ist der ungeprüfte Teil. Der Wirkstoff ist ein Verfahren, kein Molekül – Sicherheitsdaten stammen aus der etablierten Apherese bei anderen Indikationen, nicht aus dieser Anwendung.' },
  { id: 'ihht', view: 'behandlungen', evidenz: 6, mechanismus: 5, sicherheit: 5, hype: 3, anwendung: 5, richtung: 'offen', berichtslage: { stufe: 2, kurz: 'Gehstrecke und Treppen messbar besser', was: 'Übereinstimmend berichtet werden weniger Erschöpfung und bessere Belastbarkeit nach einigen Wochen, häufig aus Reha-Einrichtungen, die das Verfahren anbieten. Eine Besonderheit macht diese Berichte belastbarer als übliche Erfahrungsberichte: Gehstrecke und Treppensteigzeit lassen sich messen, und genau das wurde in der Pilotstudie auch getan. Offen bleibt, wie viel davon auf das Verfahren und wie viel auf die begleitende Rehabilitation entfällt.', quellen: 'Reha-Einrichtungen · Anwenderkreise · messbare Gehstrecken' },
    beleg: 'Evidenz 6 statt 4, weil inzwischen mehrere randomisierte, teils doppelblinde Studien am Menschen vorliegen – klein, kurz und uneinheitlich. Positiv: eine randomisierte doppelblinde Studie an 34 geriatrischen Patienten mit besseren kognitiven Testwerten (DemTect plus 16,7 gegenüber minus 0,39 Prozent) und besserer Gehstrecke (plus 24,1 gegenüber plus 10,8 Prozent) gegenüber Scheinbehandlung (Bayer et al. 2017); eine randomisierte Studie an 120 Bypass-Patienten mit weniger postoperativen Komplikationen (23,3 gegenüber 41,1 Prozent, p = 0,041; Mandel et al. 2023); eine randomisierte Studie an 65 Patienten mit metabolischem Syndrom mit deutlich gesenktem Blutdruck (Cohens d 1,15 und 0,7; Bestavashvili et al. 2022). Dagegen steht ein negativer Befund aus derselben geriatrischen Population: Mobilität und selbst eingeschätzte Gesundheit unterschieden sich nicht (Bayer et al., BMC Geriatrics 2019, p-Werte 0,25 für den Mobilitätstest, 0,51 für Aufstehen und Gehen, 0,56 für den Barthel-Index und 0,24 für die Gesundheitsskala). Die bekannteste Arbeit, die Pilotstudie an 145 Long-COVID-Patienten mit 91,7 gegenüber 32,6 Metern Gehstrecke (Doehner et al. 2024), war nicht randomisiert und unverblindet – bei einem anstrengungsabhängigen Endpunkt die Konstellation, in der Erwartung mitträgt – und hat in derselben Zeitschrift eine methodische Kritik samt Autorenantwort nach sich gezogen. Mechanismus 5, weil die Sauerstoffwahrnehmung über HIF am Menschen gesichert ist (Nobelpreis 2019), die behauptete Mitochondrien-Selektion unter diesen Bedingungen aber nicht direkt nachgewiesen wurde. Sicherheit 5, weil die Verträglichkeit in kontrollierten Studien über Wochen gut war, systematische Langzeitdaten aber fehlen. Hype 3 und Anwendung 5 bleiben. Für den Einsatz bei Gesunden zur Leistungssteigerung oder Verjüngung existieren diese Daten nicht; eine systematische Übersicht über 38 Arbeiten stellt ausdrücklich fest, dass keine Studie eine längere Lebenserwartung beim Menschen belegt (Tessema et al. 2022).' },
  { id: 'infrarot-a', view: 'behandlungen', evidenz: 6, mechanismus: 7, sicherheit: 7, hype: 4, anwendung: 6, richtung: 'gemischt',
    beleg: 'Für eine klar umrissene Indikation gibt es echte kontrollierte Daten. Eine Übersicht von 2016 fasst 7 prospektive Studien zur Wundheilung zusammen, davon 6 randomisierte, jeweils Standardversorgung plus wIRA gegen Standardversorgung allein. Berichtet werden unter anderem eine Wundflächenreduktion von 89,2 gegenüber 49,5 Prozent bei brandverletzten Kindern nach 9 Tagen und ein Ulkusverschluss nach 14 statt 42 Tagen. Am Menschen gemessen sind höhere Gewebetemperatur und ein höherer Sauerstoffpartialdruck im Gewebe (41,6 gegenüber 30,2 mmHg nach Bauchoperation). Die Einschränkungen: Die Studien stammen überwiegend aus einem Forschernetzwerk, der Erstautor der Übersicht arbeitet für eine Stiftung, die diese Forschung fördert, und die Übersicht argumentiert, die Studien unterschätzten den Nutzen. In der größten Studie mit 400 Patienten sanken Wundinfektionen in der Auswertung der vollständig erfassten Patienten von 12,1 auf 5,1 Prozent, in der Auswertung aller Randomisierten (16 gegenüber 20 Prozent) war der Unterschied jedoch nicht signifikant. Für Schmerz gibt es eine kleine scheinkontrollierte Studie bei Fibromyalgie mit positivem Ergebnis und kleinere Studien ohne Scheinkontrolle. Vor allem gilt: Diese Daten betreffen Wundheilung und bestimmte Schmerzerkrankungen. Für die im Biohacking beworbenen Ziele – Regeneration, Mitochondrien, Verjüngung – sind sie kein Beleg, sondern eine andere Fragestellung.' },
  { id: 'akkermansia', view: 'supplement', evidenz: 4, mechanismus: 4, sicherheit: 5, hype: 3, anwendung: 4, richtung: 'positiv',
    beleg: 'Human-Evidenz: Zum Bakterium selbst existiert genau eine randomisierte Studie am Menschen mit 32 auswertbaren Teilnehmern über 3 Monate, die ihre Autoren selbst eine Machbarkeitsstudie nennen, plus eine Studie von 2020 an 76 Menschen, die ein Gemisch aus 5 Stämmen prüfte — kleine Studien, nur Surrogatmarker. Mechanismus: Die Kette vom Mucinabbau über die dichtere Barriere zum besseren Zuckerstoffwechsel ist im Tier durchgemessen, am Menschen nicht; dass im Tier nur lebende, am Menschen nur abgetötete Bakterien wirkten, zeigt, dass der Pfad beim Menschen nicht verstanden ist. Sicherheits-Datenlage: kontrollierte Daten über 3 Monate, aber nur an wenigen Dutzend Menschen und ohne jede Langzeitbeobachtung. Hype-Abstand: Der Insulinbefund ist real, doch beworben werden Gewichtsverlust, der die Signifikanz verfehlte, und Lebensverlängerung, die nie gemessen wurde. Anwendung: seit der EU-Zulassung Anfang 2022 breit als Nahrungsergänzung verkauft, aber erst wenige Jahre und nur in der pasteurisierten Form reguliert. Richtung positiv, weil die vorhandenen Humandaten bei den Stoffwechselwerten in die versprochene Richtung zeigen — nicht beim Gewicht.' },
  { id: 'glp1-muskel', view: 'tipps', evidenz: 5, mechanismus: 7, sicherheit: 6, hype: 4, anwendung: 7, richtung: 'positiv',
    berichtslage: { stufe: 2, kurz: 'Sorge um Muskeln und Müdigkeit', was: 'In einer britischen Umfrage unter 544 aktuellen und früheren Anwendern (u. a. über Reddit- und Facebook-Gruppen rekrutiert) waren viele hochzufrieden; zugleich sorgte sich fast die Hälfte mehr als ein bisschen um Muskelverlust, 62 Prozent berichteten so wenig Energie, dass Bewegung oder Alltag darunter litten, und 62 Prozent ließen mindestens zwei- bis dreimal pro Woche Mahlzeiten aus. In Forenauswertungen beschreiben viele Anwender eiweißreiche Kost und Krafttraining, was sich mit der Empfehlung der Fachgesellschaften deckt. Selbstauskünfte, motivierte Stichprobe, nicht gemessen.', quellen: 'Tallis 2026 (BMC Public Health) · Plenn 2025 (Obes Sci Pract) · Sehgal 2026 (medRxiv, Vorabdruck)' },
    beleg: 'Evidenz 5: Es gibt mehrere randomisierte Studien mit vierstelligen (STEP 1, 1961 Teilnehmer) bis dreistelligen Teilnehmerzahlen (BELIEVE, 507; QUALITY, 168), aber fast alle Endpunkte sind DXA-Surrogate, und die Funktionsdaten sind dünn: In BELIEVE besserte sich die Griffkraft nur in einer von vier Kombinationen, und die Treppenmessung aus QUALITY stammt aus einer Firmenmitteilung statt aus einer begutachteten Veröffentlichung. Mechanismus 7: Der Myostatin-Weg ist am Menschen bestätigt, Bimagrumab allein steigerte die fettfreie Masse über 48 Wochen um 1,0 bis 1,1 Prozent, und auch der Verwässerungseffekt über Glykogen, das etwa 3 Gramm Wasser je Gramm bindet, ist am Menschen messbar. Sicherheit 6: Für Bimagrumab liegen kontrollierte Daten über 48 Wochen vor, mit Abbruchraten von 14 bis 21 Prozent unter Bimagrumab allein und häufig Muskelkrämpfen (57 bis 64 Prozent) und Akne (43 bis 55 Prozent) in den Kombinationsgruppen, für Enobosarm nur 16 Wochen ohne veröffentlichte Vollpublikation. Hype 4: Die Leitzahl vom Drittel Muskelverlust misst Nicht-Fett statt Muskel und wird trotzdem als Muskelverlust verkauft, während die Primärliteratur die DXA-Grenze selbst benennt. Anwendung 7: Krafttraining und Eiweiß werden seit Jahrzehnten breit angewendet, die medikamentösen Gegenmittel dagegen bislang nur in Studien.' },
  { id: 'hmg', view: 'experimental', evidenz: 6, mechanismus: 9, sicherheit: 9, hype: 6, anwendung: 9, richtung: 'positiv',
    beleg: 'Evidenz 6: Für die zugelassene Anwendung in der Fortpflanzungsmedizin ist die Datenlage erstklassig; bei Männern mit Gonadotropinmangel fand eine Metaanalyse aus 41 Studien mit 1.673 Patienten nach median 18 Monaten bei 78 % wieder Spermien, mit HCG plus FSH besser als HCG allein (Muir 2025). Für die eigentliche Szeneanwendung nach einer Steroidkur gibt es dagegen nur etablierte andrologische Praxis, einen Fallbericht (Menon 2003) und eine retrospektive Kohorte zur Nachbehandlung (İbis 2026), aber keine kontrollierte Studie zu HMG. Mechanismus 9: Die Wirkkette ist am Menschen nicht nur bestätigt, sondern quantifiziert — wie viele Follikel heranwachsen, wird im Ultraschall gemessen, die Hormonantwort im Labor. Sicherheit 9: Seit 1961 in der Versorgung, mit dem Überstimulationssyndrom als gut charakterisierter Hauptkomplikation; das theoretisch diskutierte Übertragungsrisiko aus dem Urinursprung wurde nie nachgewiesen. Hype 6: Die medizinischen Aussagen bleiben auf Höhe der Daten, überdehnt wird nur die Erwartung, ein paar Wochen HMG holten die Achse zuverlässig zurück. Anwendung 9: über 60 Jahre unter ärztlicher Aufsicht eingesetzt.',
    berichtslage: { stufe: 2, kurz: 'Kinderwunsch: Sorge ums Anmischen – Steroidszene: HMG kaum Thema', was: 'Frauen in Kinderwunschbehandlung wünschen sich vor allem, eine falsch eingestellte Dosis korrigieren zu können, und beschreiben Angst beim Anmischen des Pulvers (Pen-Studie 2023, vom Hersteller finanziert). In Kinderwunschgruppen auf Facebook und Reddit dreht sich jede achte Frage um Medikamente, jede sechste um seelischen Halt (JARG 2025). In einer Auswertung von 5.059 Beiträgen australischer Steroidforen zur Nachbehandlung (Easton 2025) kommt HMG nicht vor; diskutiert werden HCG, Clomifen und Tamoxifen. In einer Umfrage unter 470 Männern (Grant 2023) berichteten 95 % Beschwerden beim Absetzen; wer nachbehandelte, schätzte die Linderung auf rund 60 %, und 52 % sorgten sich um Testosteron und Fruchtbarkeit.', quellen: 'Patient Prefer Adherence 2023 · J Assist Reprod Genet 2025 · Drug Alcohol Rev 2025 · Subst Abuse Treat Prev Policy 2023' } },
  { id: 'hoeren-demenz', view: 'behandlungen', evidenz: 6, mechanismus: 5, sicherheit: 8, hype: 4, anwendung: 9, richtung: 'gemischt',
    beleg: 'Evidenz 6: Eine große randomisierte Studie über 3 Jahre an 977 Menschen liegt vor, hat ihren Hauptendpunkt aber verfehlt – der Effekt von 48 % stammt aus einer vorab geplanten Untergruppe von 238 Personen. Mechanismus 5: Höranstrengung, sozialer Rückzug und Rückbildung der Hörbahnen sind plausibel und teils messbar, aber die umgekehrte Richtung – Demenz schädigt das Hören – ist nicht ausgeschlossen. Sicherheit 8: Hörgeräte sind seit Jahrzehnten im regulierten Einsatz, ohne pharmakologische Wirkung, und wurden in ACHIEVE über 3 Jahre kontrolliert begleitet. Hype 4: Der Satz vom größten beeinflussbaren Risikofaktor stimmt auch 2024 (7 %, gemeinsam mit LDL-Cholesterin); überdehnt wird, dass dieser Bevölkerungsanteil regelmäßig als persönliche Risikosenkung ausgegeben wird. Anwendung 9: Hörversorgung ist jahrzehntelange, regulierte Routine in Millionen Menschen, nur eben nicht als Demenzprävention.' },
  { id: 'klotho', view: 'experimental', evidenz: 2, mechanismus: 5, sicherheit: 1, hype: 2, anwendung: 2, richtung: 'offen',
    beleg: 'evidenz 2: Am Menschen liegt keine interventionelle Studie mit Ergebnissen vor — alles ist Beobachtung (718 Menschen zur Genvariante KL-VS 2014, 804 Menschen in InCHIANTI 2011), und die Genetik widerspricht sich zwischen der schottischen, der dänischen und der US-Auswertung. mechanismus 5: Der Pfad über Insulin- und IGF-1-Dämpfung ist in Maus und Affe belegt und beim Menschen durch Genvariante und Blutwert immerhin angedeutet, aber nie am Menschen geprüft. sicherheit 1: Es gab fast keine Anwendung, entsprechend keine systematisch erhobenen Verträglichkeitsdaten; aus dem Affenversuch stammt eine Einmalgabe mit 2 Wochen Beobachtung. hype 2: Die 20 bis 30 Prozent Lebensverlängerung stehen überall, die Bedingung — das Gen war von der Befruchtung an hochgedreht — nirgends, und Kapseln werden als Klotho-Booster verkauft, obwohl ein Protein aus über 1000 Aminosäuren verdaut wird. anwendung 2: Angewendet wird Klotho nur in Studien und im Graumarkt, etwa in 2 Pilotstudien mit je 14 Menschen in Honduras; seit Februar 2026 läuft dort zudem die erste verblindete, placebokontrollierte Studie mit 21 Teilnehmenden, Ergebnisse stehen aus.' },
  { id: 'lipoprotein-a', view: 'behandlungen', evidenz: 8, mechanismus: 7, sicherheit: 5, hype: 5, anwendung: 6, richtung: 'negativ',
    beleg: 'Evidenz 8, weil mit Lipoprotein(a)-HORIZON eine große, placebokontrollierte Studie an 8.323 Patienten über 5 Jahre mit harten Endpunkten vorliegt – sie ist nur negativ ausgefallen und noch nicht vollständig publiziert. Mechanismus 7, weil die Zielstruktur am Menschen bestätigt ist: Pelacarsen senkte Lipoprotein(a) in den Vorstudien um bis zu 80 Prozent, und die Mendelsche Randomisierung quantifiziert den lebenslangen Beitrag des Partikels – die Kette von der Senkung zum Ereignis ist am Menschen aber gerade gerissen. Sicherheit 5, weil zwar 5 Jahre kontrollierte Daten erhoben wurden, die Mitteilung vom 4.9.2026 dazu jedoch nichts sagt; belastbare Sicherheitsaussagen zu Pelacarsen gibt es nicht. Hype 5, weil aus dem sauberen Genetikbefund regelmäßig ein Therapieversprechen gemacht wird, während die Mitteilung des Herstellers selbst ungewöhnlich offen formuliert war. Anwendung 6, weil die Messung seit Jahren als regulärer Laborwert verfügbar ist, die senkenden Wirkstoffe dagegen ausschließlich in Studien. Richtung negativ bezieht sich auf die Senkung als Behandlung, nicht auf den Wert als Risikomarker: Dort sprechen die Daten aus HORIZON gegen den erhofften Nutzen.' },
  { id: 'liposomales-kreatin', view: 'supplement', evidenz: 1, mechanismus: 2, sicherheit: 6, hype: 2, anwendung: 4, richtung: 'negativ',
    beleg: 'Human-Evidenz: Zu liposomalem Kreatin als Nahrungsergänzung am Menschen gibt es in PubMed keine einzige Veröffentlichung; die nächstgelegene Studie von 2022 mit 37 trainierten Männern prüfte den Rohstoff als Pulver in Wasser, nicht das liposomale Produkt. Mechanismus: Eine liposomale Hülle kann nur bergen, was sonst verloren geht — bei Monohydrat sind das weniger als 1 Prozent, und der Engpass sitzt ohnehin im Muskeltransporter, nicht im Darm; bei trockenem Pulver mit Lecithin entsteht überhaupt kein nachgewiesenes Liposom. Sicherheits-Datenlage: Der Wirkstoff Monohydrat ist über Jahrzehnte kontrolliert untersucht, die liposomale Zubereitung selbst dagegen gar nicht. Hype-Abstand: Die Packung nennt 15 und 21 Prozent sowie klinisch untersucht, obwohl diese Zahlen aus einer herstellerfinanzierten Studie am Rohstoff ohne Liposom stammen und deren Autoren selbst unklar nennen, ob sie physiologisch etwas bedeuten. Anwendung: als Nahrungsergänzung frei verkäuflich und über den Versandhandel breit erhältlich, aber ohne eigenen regulatorischen Rahmen und erst seit wenigen Jahren am Markt. Richtung negativ, weil die vorhandenen Daten gegen einen Mehrwert der Sonderform sprechen: 99 Prozent Aufnahme lassen kaum Spielraum, und von 343 randomisierten Kreatinstudien seit 1994 verglichen nur 5 überhaupt zwei Formen, wobei keine Sonderform je einen Vorteil im Muskel gezeigt hat.',
    berichtslage: { stufe: 1, kurz: 'Kaufgrund Bauch – Blähgefühl ist real, aber portionsabhängig', was: 'Zu liposomalem Kreatin selbst gibt es keine erhobenen Anwenderdaten. Eine Befragung von 2.178 Kreatin-Nutzern zeigt, warum solche Produkte gekauft werden: Blähbauch und Wassereinlagerung sind die häufigsten Klagen, bei Frauen zwischen 30 und 39 bis 18 %. In kontrollierten Daten hängt Magen-Darm-Unruhe vor allem an großen Einzelportionen.', quellen: 'Befragung JISSN 2026 · Res Sports Med 2008' } },
  { id: 'luftqualitaet', view: 'tipps', evidenz: 6, mechanismus: 8, sicherheit: 7, hype: 5, anwendung: 9, richtung: 'positiv',
    beleg: 'Evidenz 6: Für den Risikofaktor gibt es Kohortendaten an knapp 61 Millionen Menschen über 13 Jahre mit 7,3 Prozent mehr Sterblichkeit je 10 Mikrogramm, für die Intervention mehrere randomisierte Studien und zwei Metaanalysen, die aber klein sind, über Tage laufen und nur Blutdruck und Entzündungsmarker messen. Mechanismus 8: Die Kette ist am Menschen messbar, von der Partikelgröße unter 2,5 Mikrometern über den Übertritt ins Blut bis zu 68 Prozent der Todesfälle durch Herzinfarkt und Schlaganfall, und der Filter senkt Konzentration, Entzündungsmarker und Blutdruck in derselben Studie. Sicherheit 7: Filtergeräte wurden in kontrollierten Studien über Zeiträume von 2 Tagen bis zu einer ganzen Schwangerschaft eingesetzt, ohne relevante Schäden; die Ausnahme sind ozonbildende Geräte, von denen die Umweltbehörde abrät. Hype 5: Die Konzentrationssenkung ist unstrittig, daraus wird aber Gesundheitsschutz gemacht, und die zweite Metaanalyse stuft die Evidenz ausdrücklich als sehr unsicher ein und warnt vor Werbeaussagen. Anwendung 9: HEPA-Filtration, Dunstabzug und Lüften sind seit Jahrzehnten in Millionen Haushalten verbreitet und über genormte Kennzahlen wie CADR sowie über EU-Grenzwerte reguliert.',
    berichtslage: { stufe: 2, kurz: 'Rauschen, Luftzug, Schlaf – den Staub spürt niemand', was: 'In einer Befragung von 150 Teilnehmenden einer Filterstudie liefen die Geräte fast durchgehend, meist auf mittlerer Stufe; Lärm störte anfangs etwa jeden Zehnten, nach drei Monaten halb so viele. Gelobt wurden das Rauschen als Einschlafhilfe und der kühle Luftzug, bemängelt die Lautstärke auf höchster Stufe, Kälte im Winter und der Platzbedarf. Den Feinstaub selbst nimmt kaum jemand wahr.', quellen: 'Befragung HAFTRAP (Trials 2024) · Build Res Inform 2022' } },
  { id: 'menopause-hrt', view: 'behandlungen', evidenz: 9, mechanismus: 9, sicherheit: 9, hype: 3, anwendung: 10, richtung: 'positiv',
    beleg: 'Evidenz 9, weil für die Beschwerde-Indikation große randomisierte Studien mit harten Endpunkten vorliegen – die WHI mit 16.608 Frauen im Kombinationsarm und 10.739 im Östrogen-Arm, dazu eine Cochrane-Auswertung aus 24 Studien mit 3.329 Frauen – und die Präparate dafür zugelassen sind; keine 10, weil die entscheidenden modernen Verfeinerungen zu Gestagentyp und Beginnzeitpunkt nicht randomisiert geprüft sind. Mechanismus 9, weil die Wirkkette am Menschen quantifiziert ist: Östrogen weitet das Toleranzfenster der überaktiven Nervenzellen im Hypothalamus, die Blockade desselben Neurokinin-3-Rezeptors durch Fezolinetant wirkt in dieselbe Richtung, und die Leberpassage der Tablette erklärt das vierfache Thromboserisiko in ESTHER gegenüber 0,9 über die Haut. Sicherheit 9, weil es Langzeitdaten aus Zulassung und Pharmakovigilanz gibt und die Risiken in absoluten Zahlen beziffert sind, bis hin zur Sterblichkeit über 18 Jahre (27,1 gegen 27,6 Prozent bei 27.000 Frauen). Hype 3, weil in beide Richtungen überdehnt wird: 20 Jahre lang wurde mit der relativen Zahl von 26 Prozent erschreckt und die absolute von 8 Fällen auf 10.000 Frauenjahre verschwiegen, heute wird daraus ein Anti-Aging-Versprechen für alle ab 50 – genau das war die WHI, und genau das ist gescheitert. Anwendung 10, weil Hormone in den Wechseljahren seit Jahrzehnten von Millionen Frauen unter ärztlicher Aufsicht angewendet werden. Richtung positiv für die belegte Indikation, also Beschwerden und Knochen; für die Vorbeugung chronischer Krankheiten sprechen die Daten dagegen.' },
  { id: 'mundmikrobiom', view: 'behandlungen', evidenz: 4, mechanismus: 6, sicherheit: 7, hype: 4, anwendung: 9, richtung: 'gemischt',
    beleg: 'Evidenz 4: Am Menschen gibt es zur Alzheimer-Frage eine einzige Studie mit 643 Teilnehmenden, die beide primären Endpunkte verfehlte, und zum Herzen nur Surrogatdaten aus einer Studie mit 120 Personen sowie zwei von Cochrane 2022 als sehr niedrig bewertete Studien zu harten Endpunkten. Mechanismus 6: Gingipaine, bakterielle DNA und der Erreger selbst wurden im menschlichen Gehirn und Nervenwasser nachgewiesen, und die entzündete Zahnfleischfläche als Eintrittspforte ist etabliert – quantifiziert ist die Wirkkette beim Menschen aber nicht. Sicherheit 7: Die Parodontitis-Behandlung verlief in der randomisierten Studie über 180 Tage ohne schwere Nebenwirkungen und ist zahnärztliche Routine, beim Wirkstoff sind die dosisabhängigen Leberwerterhöhungen aus 48 Wochen gut dokumentiert. Hype 4: Aus dem Mausbefund wird regelmäßig eine Alzheimer-Ursache gemacht, während die einzige Prüfung am Menschen, das fehlende Alltagsergebnis und der Abbruch wegen Leberwerten unerwähnt bleiben. Anwendung 9: Parodontitis-Behandlung und professionelle Zahnreinigung laufen seit Jahrzehnten reguliert in Millionen Menschen, die gezielte Beeinflussung des Mundmikrobioms gegen Herz oder Demenz dagegen nicht.' },
  { id: 'muskel-als-organ', view: 'behandlungen', evidenz: 7, mechanismus: 5, sicherheit: 7, hype: 4, anwendung: 9, richtung: 'positiv',
    beleg: 'Evidenz 7: Für die Vorhersage liegen sehr große prospektive Kohorten vor (PURE mit 139.691 Menschen, Health-ABC mit 2.292), und für die Intervention eine randomisierte Studie mit 1.635 alten Menschen und hartem Alltagsendpunkt (LIFE, 30,1 gegenüber 35,5 %) – aber keine einzige randomisierte Studie dazu, dass Krafttraining die Sterblichkeit senkt. Mechanismus 5: Dass der Muskel bei Belastung Botenstoffe abgibt, ist am Menschen bestätigt (Interleukin 6), doch die Kette von der Kraft zum Überleben ist offen, und beim bekanntesten Myokin lagen die Messkits im Mittel 18-fach auseinander. Sicherheit 7: Die geprüfte Intervention wurde in LIFE über im Mittel 2,6 Jahre randomisiert begleitet, bei einem Durchschnittsalter von 78,9 Jahren. Hype 4: Der belegte Kern stimmt, aber der Satz stärker als der Blutdruck wird zur Gesamtaussage aufgeblasen, obwohl er nur für die Sterblichkeit gilt (1,37 zu 1,15) und für neu auftretende Herz-Kreislauf-Erkrankungen umgekehrt ausfällt (1,39 zu 1,21); Anwendung 9: Dynamometrie und Krafttraining sind seit Jahrzehnten breit im Einsatz und in der Altersmedizin Teil der Routinebeurteilung.',
    berichtslage: { stufe: 2, kurz: 'Sich gut fühlen – und die Sorge ums Herz', was: 'Ältere Trainierende nennen als Gewinn vor allem, sich körperlich und seelisch gut zu fühlen, wacher zu sein und nicht abzubauen; ein sichtbarer Anstieg der Griffkraft hält bei der Stange. Die häufigste Sorge, Training könne einen Herzinfarkt auslösen, deckt sich nicht mit den Daten der großen randomisierten Studie LIFE.', quellen: 'Systematische Übersicht J Aging Phys Act 2017 · Umfrage J Sports Sci 2017 · Interviewstudie BMC Geriatrics 2026' } },
  { id: 'nandrolon', view: 'experimental', evidenz: 8, mechanismus: 9, sicherheit: 9, hype: 6, anwendung: 9, richtung: 'positiv',
    beleg: 'Evidenz 8, weil Nandrolon auf klinischen Daten für konkrete Indikationen zugelassen ist — renale Blutarmut, Osteoporose nach den Wechseljahren — und die aufbauende Wirkung seit 60 Jahren unbestritten ist; die Höchstnote bleibt aus, weil der hier gefragte Zweck, Muskelaufbau bei Gesunden, kein zugelassenes Anwendungsgebiet ist. Mechanismus 9, weil die Wirkkette am Menschen bekannt und quantifiziert ist, bis hin zum günstigen Verhältnis von aufbauender zu vermännlichender Wirkung und der gestagenen Zusatzwirkung. Sicherheit 9, weil aus 64 Jahren Zulassung und Beobachtung ein detailliertes Schadensprofil vorliegt, von Ödemen mit oder ohne Herzschwäche bei vorbestehender Erkrankung über seltene Leberfunktionsstörungen bis zur Stimmveränderung, die bei längerer Behandlung bleiben kann — eine hohe Zahl heißt hier gut untersucht und ausdrücklich nicht harmlos. Hype 6, weil die Wirkversprechen stimmen, die Schadensseite beim Handel außerhalb der Medizin aber regelmäßig fehlt; Anwendung 9, weil die Substanz seit 1962 unter ärztlicher Aufsicht eingesetzt wurde, die Anwendungsgebiete seit den 1970er Jahren jedoch eingeengt und der Verkauf vielerorts eingestellt wurde.',
    berichtslage: { stufe: 2, kurz: 'Anwender spüren Kraft – und Nebenwirkungen', was: 'In der niederländischen HAARLEM-Studie (100 Männer mit selbst geplanter Steroidkur, Steroide allgemein, ein Jahr begleitet) berichteten alle positive Effekte, vor allem mehr Kraft, und alle mindestens eine Nebenwirkung: Wassereinlagerung 56 %, Unruhe 36 %, Libidoverlust nach der Kur 58 %; dazu 4 schwere Ereignisse. Nach einem Jahr lag das meiste wieder auf dem Ausgangswert; 48 % bezeichneten sich als abhängig. In der Folgestudie 2026 kamen während der Kur 4,4 kg fettfreie Masse dazu, drei Monate danach waren davon noch 1,2 kg übrig. In Foren heißt es verbreitet, Nandrolon lindere Gelenkschmerzen; eine unkontrollierte Pilotstudie (18 von 48 antworteten, 13 besser) stützt das vorsichtig. Im Global Drug Survey 2024 (1.146 Männer, Steroide allgemein) gaben 55,8 % keine psychischen Beschwerden an, 63,9 % mindestens eine körperliche Sorge, am häufigsten ums Herz (36 %).', quellen: 'Smit 2020/2021 · Verdegaal 2026 JCEM · Tatem 2020 · Magnolini 2025 · Global Drug Survey 2024 (Drug Alcohol Rev 2026)' } },
  { id: 'partielle-reprogrammierung', view: 'experimental', evidenz: 1, mechanismus: 5, sicherheit: 1, hype: 3, anwendung: 1, richtung: 'offen',
    beleg: 'evidenz 1: Am Menschen liegt kein einziges Ergebnis vor — die erste Studie läuft seit dem 2. März 2026 mit 18 Teilnehmern in 4 Zentren, ist nicht randomisiert und nicht verblindet und misst Sicherheit statt Wirkung. mechanismus 5: Der Pfad ist in Zellkultur und Tier sauber beschrieben, von 2 Tagen an und 5 Tagen aus mit 18 auf 24 Wochen Lebenszeit bis zur Netzhautarbeit mit 3 Faktoren, aber am Menschen ist keine Stufe der Kette bestätigt. sicherheit 1: Verträglichkeitsdaten am Menschen gibt es nicht, und die Affendaten hinter ER-100 wurden nur auf einem Kongress gezeigt; im Tier ist dagegen das Tumorrisiko klar belegt, bis hin zu Teratomen nach 8 Wochen Dauerbetrieb. hype 3: Die Biologie ist echt und steht in Nature, Science und Cell, aber in Pressemitteilungen wird die rückwärts laufende epigenetische Uhr zur Verjüngung erklärt, obwohl sie in Stammzellen fast null anzeigt — und 3 Milliarden Dollar für Altos Labs sowie eine Bewertung von 1,8 Milliarden für Retro Biosciences stehen einer Phase-1-Studie ohne Zwischenergebnis gegenüber. anwendung 1: Außerhalb dieser einen Studie hat kein Mensch das Verfahren erhalten, und zu kaufen gibt es nichts.' },
  { id: 'pe-22-28', view: 'experimental', evidenz: 0, mechanismus: 4, sicherheit: 1, hype: 2, anwendung: 2, richtung: 'offen',
    beleg: 'Evidenz 0, weil es zu PE-22-28 keine einzige Studie am Menschen gibt, weder abgeschlossen noch laufend noch abgebrochen. Mechanismus 4, weil die Zielstruktur TREK-1 und ihre Blockade in Zellsystemen und Tieren sauber gemessen sind (0,12 Nanomolar, 23 Stunden Verweildauer), am Menschen aber nichts davon bestätigt wurde. Sicherheit 1, weil kein Sicherheitsprofil am Menschen existiert und allein Tierarbeiten die Kanalblockade unauffällig aussehen ließen. Hype 2, weil die echten Mäusezahlen — Wirkeintritt nach 4 Tagen gegenüber 3 bis 4 Wochen beim Menschen — auf Verkaufsseiten ohne das Wort Maus als Aussage über Menschen weitergereicht werden; Anwendung 2, weil die Substanz nur in Graumarktkreisen verwendet wird und in knapp 20 Jahren nicht einmal in eine Phase-1-Studie gekommen ist.' },
  { id: 'psilocybin', view: 'experimental', evidenz: 6, mechanismus: 5, sicherheit: 5, hype: 3, anwendung: 4, richtung: 'gemischt',
    beleg: 'Evidenz 6: Mehrere randomisierte Studien bis hin zu zwei Phase-3-Studien mit 258 und 581 Teilnehmern zeigen einen Effekt, aber das Bild ist uneinheitlich — der Vergleich gegen Escitalopram verfehlte den Hauptendpunkt, EPIsoDE mit 144 Menschen ebenfalls, und die Phase-3-Zahlen liegen bisher nur als Pressemitteilung vor. Mechanismus 5: Die Umwandlung zu Psilocin und die Bindung an Serotoninrezeptoren sind bekannt, die Kette von dort bis zur anhaltenden Stimmungsänderung ist am Menschen aber nicht ausgemessen und bleibt ein Bild. Sicherheit 5: Systematisch erfasst sind Kurzzeitdaten, unter anderem eine Metaanalyse von 2024 über mehr als 3500 Studienteilnehmer; für monatelange Einnahme fehlen Daten, und die Frage zum Serotoninrezeptor Typ 2 B am Herzen ist ausdrücklich offen. Hype 3: Ein realer Einzelbefund von 6,6 Punkten wurde zum Durchbruch erklärt, obwohl in Phase 3 nur 3,6 Punkte übrig blieben, und Microdosing wird beworben, obwohl drei verblindete Studien Nullbefunde lieferten. Anwendung 4: außerhalb von Studien verbreitet, aber ohne regulatorischen Rahmen, mit eng begrenzten Ausnahmen in Australien, Oregon und Colorado.',
    berichtslage: { stufe: 2, kurz: 'Verbundenheit und Wohlbefinden – bei bipolarer Störung auch Manie', was: 'Mikrodosierende berichten in elf Studien mit 3.262 Personen von mehr Wohlbefinden, Kreativität und besseren Beziehungen, rund 86 % ohne medizinischen Anlass. Teilnehmende der Hochdosis-Studien beschreiben vor allem Verbundenheit. In verblindeten Mikrodosis-Studien verschwindet der Unterschied zur leeren Kapsel. Eine Auswertung von Reddit-Kommentaren zu bipolarer Störung zeigt beide Seiten: weniger Depression, aber auch Manie und Psychose.', quellen: 'Front Psychiatry 2026 · Psychopharmacology 2022 · J Affect Disord 2026 (Reddit-Auswertung)' } },
  { id: 'bromelain', view: 'supplement', evidenz: 6, mechanismus: 5, sicherheit: 6, hype: 5, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz: Mehrere kleine RCTs und vier Meta-Analysen zu Weisheitszahn-Operationen finden übereinstimmend weniger Schmerz (etwa SMD −0,54 nach 7 Tagen, 6 RCTs), widersprechen sich aber bei der Schwellung; die Gesamt-Meta-Analyse von Leelakanok 2023 kommt über 9 Studien auf einen kleinen Schmerzvorteil von −0,27 bei Studien mittlerer Qualität. Bei Kniearthrose verfehlte die einzige placebokontrollierte Studie (47 Teilnehmer, 800 mg täglich, 12 Wochen) ihren Endpunkt, beim Muskelkater fand die einzige Studie mit reinem Bromelain (39 Auswertbare) nichts – daher Richtung gemischt. Mechanismus: Dass Bromelain nach dem Schlucken mit erhaltener Aktivität im Serum ankommt, ist am Menschen gezeigt; die entzündungshemmende und abschwellende Wirkkette stammt überwiegend aus Zellkultur und Tier. Sicherheit: kontrollierte Daten bis 16 Wochen, dazu Arzneimittelzulassung mit Fachinformation (Gerinnung, Allergie, Antibiotika-Wechselwirkung); LiverTox kennt keine Leberschäden. Hype: Als allgemeiner Entzündungshemmer und Erholungshilfe beworben, getragen ist nur der Schmerz nach Zahn-Operationen. Anwendung: in Deutschland als Arzneimittel reguliert, äußerlich als NexoBrid in der EU und den USA zugelassen.' },
  { id: 'chrom', view: 'supplement', evidenz: 6, mechanismus: 4, sicherheit: 5, hype: 3, anwendung: 7, richtung: 'gemischt',
    beleg: 'Es gibt viele kleine RCTs, aber sie widersprechen sich. Meta-Analysen bei Typ-2-Diabetes finden eine HbA1c-Senkung um 0,55 % (25 RCTs, J Clin Pharm Ther 2014) bzw. 0,71 % (28 Studien, Pharmacol Res 2020, Heterogenität beim Nüchternzucker I² 99,8 %); der große Effekt aus China (HbA1c 6,6 % vs. 8,5 %, Diabetes 1997) trat bei übergewichtigen, insulinpflichtigen Patienten in den Niederlanden nicht auf (Diabetes Care 2006), und klinische Zielwerte wurden nur in wenigen Studien erreicht (Nutr Rev 2016). Der Mechanismus ist schwach: Die EFSA (2014) sieht die essenzielle Funktion von Chrom nicht als belegt an und fand bei Gesunden keinen Nutzen. Beim Gewicht beträgt der Effekt 1,1 kg bei niedriger Evidenzqualität (Cochrane 2013). Sicherheitsdaten stammen aus Studien über wenige Monate und Fallberichten zu Nierenversagen bei 1.200 bis 2.400 µg; Blutzucker- und Schlankheitsversprechen gehen deutlich über die Daten hinaus.' },
  { id: 'glutamin', view: 'supplement', evidenz: 6, mechanismus: 6, sicherheit: 7, hype: 4, anwendung: 6, richtung: 'gemischt',
    beleg: 'Evidenz: Mehrere RCTs mit klinischen Endpunkten, aber in unterschiedliche Richtungen. Für den Sport fand die Meta-Analyse von Ramezani Ahmadi 2019 aus 25 Studien keinen Effekt auf Leistung, Körperzusammensetzung und Immunsystem. Beim Reizdarm nach Infektion zeigte eine RCT (Zhou 2019, Gut, 54 und 52 Auswertbare) 79,6 % gegenüber 5,8 % Ansprechen, eine zweite RCT mit 50 Patienten 88 % gegenüber 60 % zusätzlich zu Low-FODMAP; bei Sichelzellkrankheit senkte Glutamin die Schmerzkrisen (230 Patienten, Median 3,0 gegenüber 4,0), die EMA hielt die Studie aber nicht für überzeugend. Bei Intensivpatienten mit Multiorganversagen stieg die Sterblichkeit (REDOXS, 32,4 % gegenüber 27,2 %). Mechanismus: Glutamin als Brennstoff für Immun- und Darmzellen und der Abfall des Plasmaspiegels nach Belastung sind am Menschen gemessen, der Schritt zu weniger Infekten ließ sich nicht zeigen. Sicherheit: kontrollierte Daten bis 48 Wochen und große Klinikstudien, Observed Safe Level 14 g täglich. Hype: Als Muskel- und Immunbooster verkauft, beides widerlegt; der tragfähige Darmbefund steht selten auf der Dose. Anwendung: seit Jahrzehnten als Sportsupplement verbreitet, in den USA als Arzneimittel zugelassen.' },
  { id: 'kalium', view: 'supplement', evidenz: 8, mechanismus: 8, sicherheit: 8, hype: 7, anwendung: 10, richtung: 'positiv',
    beleg: 'Die Blutdruckwirkung ist konsistent belegt: 22 RCTs mit 1.606 Teilnehmern zeigten bei Hypertonie −3,49/−1,96 mmHg, ohne Schaden an Nierenfunktion oder Blutfetten (BMJ 2013); Kohorten mit 127.038 Menschen verbinden höhere Zufuhr mit 24 % weniger Schlaganfällen. Harte Endpunkte liefert der Salzersatz: In SSaSS mit 20.995 Hochrisikoteilnehmern senkte Salz mit 25 % Kaliumchlorid über 4,74 Jahre Schlaganfälle (0,86), schwere Herz-Kreislauf-Ereignisse (0,87) und Todesfälle (0,88) ohne signifikant mehr schwere Hyperkaliämien (N Engl J Med 2021); eine Meta-Analyse über 21 Studien bestätigt das. Einschränkungen: Der Salzersatz senkt zugleich Natrium, für Kaliumtabletten fehlen Endpunktstudien, und die Dosis-Wirkung ist U-förmig (J Am Heart Assoc 2020). Bei gestörter Nierenfunktion oder kaliumsparenden Medikamenten ist Hyperkaliämie das zentrale Risiko.' },
  { id: 'kalzium', view: 'supplement', evidenz: 9, mechanismus: 9, sicherheit: 9, hype: 5, anwendung: 10, richtung: 'gemischt',
    beleg: 'Für ältere Menschen ist die Wirkung zusammen mit Vitamin D gut belegt: Cochrane bewertet die Senkung der Hüftfrakturen (RR 0,84; 9 Studien, 49.853 Teilnehmer) mit hoher Evidenzqualität, in einer Pflegeheim-Studie mit 3.270 Frauen sanken sie um 43 % bei 44 % weniger Parathormon (N Engl J Med 1992). In der Schwangerschaft senkt Kalzium bei kalziumarmer Ernährung die Präeklampsie auf RR 0,36 (Cochrane 2018, niedrige Evidenzqualität). Für selbstständig lebende, gut versorgte Menschen ist der Nutzen schwach; die 4 Studien mit geringstem Verzerrungsrisiko zeigten keinen Frakturschutz (BMJ 2015). Die Sicherheit ist aus großen RCTs wie der WHI (36.282 Frauen, 7,0 Jahre) gut bekannt, mit mehr Nierensteinen (HR 1,17). Beim Herzen widersprechen sich die Meta-Analysen: HR 1,31 für Herzinfarkt (BMJ 2010) gegenüber keinem Zusammenhang (Heart Lung Circ 2023; Leitlinie Ann Intern Med 2016).' },
  { id: 'l-arginin', view: 'supplement', evidenz: 7, mechanismus: 7, sicherheit: 7, hype: 5, anwendung: 6, richtung: 'positiv',
    beleg: 'Evidenz: Zwei Meta-Analysen zum Blutdruck stimmen überein (Dong 2011: 11 RCTs, 387 Teilnehmer, systolisch −5,39 mmHg; Shiraseb 2022: 22 RCTs, systolisch −6,40 und diastolisch −2,64 mmHg), eine Auswertung von 24-Stunden-Messungen (5 RCTs, 202 Teilnehmer) bestätigt das; bei leichter bis mittelgradiger Erektionsstörung OR 3,37 aus 10 RCTs mit 540 Patienten. Das sind viele kleine, kurze Studien mit Surrogatendpunkten, keine harten Endpunkte. Mechanismus: Arginin ist das Substrat der NO-Synthase, die orale Bioverfügbarkeit von etwa 20 % und der stärkere Anstieg unter Citrullin sind am Menschen gemessen. Sicherheit: Observed Safe Level 20 g täglich, Magen-Darm-Beschwerden ab Einzelmengen über 9 g gut beschrieben, aber ein Sterblichkeitssignal nach akutem Herzinfarkt (VINTAGE MI, 6 Todesfälle gegenüber 0, 153 Patienten). Hype: Als Pump- und Potenzmittel beworben; beim Blutdruck liefern die Daten mehr als die Werbung, beim Pump weniger, und die einzige Sport-Meta-Analyse ist methodisch kritisiert. Anwendung: seit Jahren breit als Supplement verbreitet, in Deutschland über eine Allgemeinverfügung mit Warnhinweisen geregelt.' },
  { id: 'praebiotika', view: 'supplement', evidenz: 7, mechanismus: 7, sicherheit: 8, hype: 6, anwendung: 8, richtung: 'positiv',
    beleg: 'Evidenz: Der Effekt auf die Bifidobakterien ist durch eine Meta-Analyse aus 64 RCTs mit 2099 gesunden Erwachsenen sehr konsistent belegt (SMD 0,64). Klinisch tragen die Verstopfung (Meta-Analyse, 5 RCTs, 252 Teilnehmer; EU-Angabe für 12 g Chicorée-Inulin) und der Blutzucker bei Prädiabetes und Typ-2-Diabetes (33 RCTs, 1346 Teilnehmer, HbA1c −0,58 %). Beim Reizdarm fand die Meta-Analyse von Wilson 2019 (11 RCTs, 729 Patienten) keinen Nutzen, bei Gesunden blieben Gewicht und Blutzucker unverändert. Mechanismus: Die selektive Fermentation und der Anstieg der Bifidobakterien sind am Menschen quantifiziert; der Schritt zu Immun- oder Stoffwechselnutzen ist nur teilweise gezeigt, GOS erhöhte bei Älteren die Bifidobakterien ohne Effekt auf Immunfunktion. Sicherheit: kontrollierte Daten über Wochen bis 1 Jahr, auch bei Frühgeborenen (18 RCTs), Nebenwirkungen auf Blähungen und Durchfall beschränkt und dosisabhängig. Hype: Beworben für Immunsystem, Stimmung und allgemeine Darmgesundheit; getragen sind Bifidobakterien, Stuhlgang und Blutzucker bei Diabetes. Anwendung: als Lebensmittelzutat breit verbreitet, auch in Säuglingsnahrung eingesetzt, in der EU mit einer zugelassenen gesundheitsbezogenen Angabe.' },
  { id: 'vitamin-e', view: 'supplement', evidenz: 8, mechanismus: 8, sicherheit: 9, hype: 4, anwendung: 10, richtung: 'gemischt',
    beleg: 'Selten ist ein Supplement so gründlich in großen Endpunktstudien geprüft worden. Zur Vorbeugung bei Gesunden blieb es ohne Nutzen: HOPE (9.541 Hochrisikopatienten, RR 1,05), Women\'s Health Study (39.876 Frauen, 10,1 Jahre, RR 0,93) und Physicians\' Health Study II (14.641 Männer, HR 1,01) fanden keinen Schutz vor Herz-Kreislauf-Ereignissen. Bei Erkrankten gibt es echte Erfolge: In PIVENS verbesserten 800 IE die Leberhistologie bei Steatohepatitis (43 % vs. 19 %, N Engl J Med 2010), in TEAM-AD bremsten 2000 IE den Funktionsverlust bei Alzheimer um 19 % pro Jahr (JAMA 2014). Gegen hohe Dosen sprechen SELECT mit 17 % mehr Prostatakrebs unter 400 IE (JAMA 2011) und eine Meta-Analyse mit 22 % mehr Hirnblutungen (BMJ 2010). Die Sicherheitsdatenlage ist dadurch außergewöhnlich gut; der Hype um Herzschutz und Anti-Aging liegt deutlich über den Daten.' },
  { id: 'adamax', view: 'experimental', evidenz: 0, mechanismus: 2, sicherheit: 0, hype: 1, anwendung: 2, richtung: 'offen',
    beleg: 'Evidenz 0, weil es zu Adamax keine einzige Studie gibt: PubMed liefert im Peptid-, Semax- oder Nootropika-Kontext 0 Treffer, ClinicalTrials.gov 0 Einträge, ein Patent wurde nicht gefunden, und der Entwickler ist nicht dokumentiert; die früheste amtliche Erwähnung ist die Medsafe-Eingabe vom Juni 2025, die Adamax neben Semax als ACTH-Analogon führt. Mechanismus 2, weil die Wirkerzählung vollständig von den Ausgangsstoffen geborgt ist: Semax hob bei Ratten BDNF maximal 1,4-fach (Dolotov et al. 2006), die Adamantan-Kappe diente bei P021 der Hirngängigkeit (Kazim & Iqbal 2016) – gemessen ist davon für Adamax nichts, und die Hybrid-Erzählung trägt nicht, weil die P021-Entwickler die neurotrophe Wirkung dem CNTF-Kern zuschreiben, den Adamax nicht enthält. Sicherheit 0, weil weder Toxikologie noch Pharmakokinetik noch Fallberichte existieren; beim Ausgangsstoff Semax sieht die FDA (2026) ein Immunogenitätsrisiko durch Aggregate und Verunreinigungen. Hype 1, weil Anbieter Stärke- und Wirkdauervorteile gegenüber Semax ohne Messung behaupten, das Produkt als Semax-P21-Hybrid bewerben und mindestens ein Händler Dihexa unter dem Namen Adamax verkauft; die Strukturangaben im Handel widersprechen sich. Anwendung 2, weil die Substanz nur im Graumarkt und in Anwenderforen vorkommt. Einordnung zum Dihexa-Umfeld: Adamax ist chemisch kein Dihexa-Verwandter; die zurückgezogene JPET-Arbeit von 2014 und das Scheitern von Fosgonimeton in LIFT-AD (287 Patienten, 26 Wochen, p = 0,70) betreffen den HGF-Weg, nicht Adamax.' },
  { id: 'aicar', view: 'experimental', evidenz: 5, mechanismus: 6, sicherheit: 5, hype: 4, anwendung: 3, richtung: 'gemischt',
    beleg: 'Evidenz 5, weil es zwar umfangreiche Humandaten gibt, aber nicht zu der Frage, für die AICAR bekannt ist: Ausdauer, Fettmasse und Körperzusammensetzung sind am Menschen nie untersucht worden. Was am Menschen vorliegt, sind zwei kleine kontrollierte Studien mit Surrogatmarkern über Stunden (Cuthbertson et al. 2007, n = 29; Boon et al. 2008, n = 10) und eine große klinische Entwicklung zu einer anderen Indikation, deren entscheidende Studie negativ ausfiel: RED-CABG wurde nach 3080 von 7500 geplanten Patienten abgebrochen, der kombinierte Endpunkt lag bei 5,1 gegenüber 5,0 Prozent (OR 1,01), nachdem die Meta-Analyse an 4043 Patienten noch minus 27 Prozent Herzinfarkte gezeigt hatte (Newman et al. 2012; Mangano 1997). Mechanismus 6, weil die Wirkkette über ZMP als AMP-Mimetikum in Zellen quantifiziert ist (Corton et al. 1995) und die Zielstruktur AMPK beim Menschen unbestritten existiert – in beiden Humanstudien stieg die AMPK-Phosphorylierung im Muskel jedoch nicht messbar an, und ZMP wirkt nachweislich auch AMPK-unabhängig (Višnjić et al. 2021; Philippe et al. 2018), weshalb keine höhere Zahl gerechtfertigt ist. Sicherheit 5, weil kontrollierte Sicherheitsdaten an tausenden Patienten existieren, aber nur für Stunden bis wenige Gaben: Harnsäureanstiege in den Herzstudien, häufige Hyperurikämie sowie Nierenfunktionsstörungen und Blutdruckabfälle in der CLL-Studie, und ein Studienabbruch bei MDS/AML wegen schwerer Nierennebenwirkungen (Van Den Neste et al. 2013; Cluzeau et al. 2019). Langzeitdaten fehlen vollständig. Hype 4, weil die Erzählung „Sport in Pillenform" zwei Dinge weglässt, die in der Originalarbeit stehen: Die 44 Prozent stammen von Mäusen, und der Stoff wurde dort intraperitoneal gespritzt, obwohl das Abstract ihn „orally active" nennt – am Menschen lag die orale Verfügbarkeit unter 5 Prozent (Narkar et al. 2008; Dixon et al. 1991). Auch dass die Substanz an ihrem harten klinischen Endpunkt gescheitert ist, kommt in der Vermarktung nicht vor. Anwendung 3, weil AICAR am Menschen praktisch nur in Studien vorkam und im Sport seit 2009 verboten ist; Berichte über eine Verwendung im Radsport sind journalistisch und nicht durch Laborbefunde belegt. Richtung gemischt: Mechanismus und Tierdaten tragen, die kontrollierten Humandaten zeigen akute Stoffwechselwirkungen, und der eine harte Endpunkt, der geprüft wurde, fiel negativ aus.' },
  { id: 'abaloparatid', view: 'experimental', evidenz: 9, mechanismus: 9, sicherheit: 8, hype: 8, anwendung: 7, richtung: 'positiv',
    beleg: 'Evidenz 9: Der primäre Endpunkt der doppelblinden ACTIVE-Studie mit 2463 Frauen wurde klar erreicht, neue Wirbelbrüche 0,6 gegenüber 4,2 Prozent über 18 Monate, und ACTIVExtend zeigte über 43 Monate 0,9 gegenüber 5,6 Prozent; das Mittel ist in den USA und der EU für genau diese Indikation zugelassen. Die volle 10 gibt es nicht, weil der Bruchschutz auf einer einzigen Zulassungsstudie ruht und der Effekt außerhalb der Wirbelsäule wackelt: In der EU-Auswertung ohne 2 wegen GCP-Mängeln ausgeschlossene Zentren lag er bei 2,7 gegenüber 3,6 Prozent, nicht signifikant; bei Männern (ATOM, 228 Teilnehmer) ist nur die Knochendichte belegt. Mechanismus 9, weil Zielrezeptor, Knochenaufbaumarker (PINP plus 93 Prozent nach 1 Monat), Knochendichte, Histologie und Bruchrate am Menschen gemessen sind; nur die Erklärung über die RG-Rezeptorform stammt aus Zellversuchen. Sicherheit 8: kontrollierte Daten über 18 Monate plus 24 Monate Verlängerung und Marktbeobachtung seit 2017; offen bleiben das Osteosarkom-Signal aus Ratten, Daten jenseits von 2 Jahren und die Herzwirkung, die 2018 zur ersten Ablehnung in der EU beitrug. Hype 8, weil das Mittel fast nur über seine Zulassungsdaten kommuniziert wird; vereinzelte Erwartungen jenseits der Osteoporose sind nicht gedeckt. Anwendung 7: seit 2017 in den USA und seit 2022 in der EU unter ärztlicher Aufsicht, aber noch keine Jahrzehnte.' },
  { id: 'ace-031', view: 'experimental', evidenz: 5, mechanismus: 7, sicherheit: 4, hype: 2, anwendung: 3, richtung: 'gemischt',
    beleg: 'Evidenz 5, weil zwei kontrollierte Humanstudien vorliegen, aber klein und nur mit Surrogatmarkern: 48 gesunde Frauen mit einer Einzeldosis (fettfreie Masse plus 3,3 Prozent, Oberschenkelmuskelvolumen plus 5,1 Prozent, je P = 0,03; Attie et al. 2013) und 24 Jungen mit Duchenne-Muskeldystrophie über 12 Wochen (fettfreie Masse plus 3,6 und 4,1 Prozent gegen 2,6 Prozent unter Placebo), wobei die Studie vorzeitig abgebrochen wurde und die funktionellen Endpunkte nichts zeigten – Handmyometrie unverändert, 6-Minuten-Gehtest nicht signifikant. Mechanismus 7, weil die Zielstruktur am Menschen bestätigt ist: Der Köderrezeptor bindet Myostatin und Activin A, der Massen- und Knochendichteeffekt ist am Menschen gemessen, und selbst die Nebenwirkungen passen zur Wirkkette, nämlich zur Mitblockade von BMP9 und BMP10 – quantifiziert ist diese Zuordnung am Menschen allerdings nicht. Sicherheit 4, weil kontrollierte Kurzzeitdaten über 12 Wochen mit 18 behandelten Jungen und Einzeldosisdaten an 48 Frauen vorliegen und die dosislimitierende Toxizität klar benannt ist – Epistaxis 5 von 9 und Teleangiektasien 5 von 9 im höheren Schema gegen 0 von 6 unter Placebo –, aber keine Langzeit- oder Pharmakovigilanzdaten existieren. Hype 2, weil die Vermarktung im Graumarkt die Tierzahlen (plus 16 Prozent Körpergewicht, plus 46 Prozent Muskelgewicht) und die Humanmassenzuwächse weiterreicht, ohne den Grund für das Programmende zu nennen, und weil nach der einzigen Laboranalyse in 12 von 14 Produkten gar kein ACE-031 war. Anwendung 3, weil die Substanz außerhalb von Studien nur in einer kleinen Graumarktnische vorkommt und seit dem 02.05.2013 nicht weiterentwickelt wird. Richtung gemischt: Der Massenaufbau ist belegt, ein Funktionsgewinn nicht, und die Gefäßnebenwirkungen haben das Programm beendet. Abgrenzung zum Bestand: Der Eintrag follistatin führt ACE-031 bisher nur als Synonym und nennt den Abbruch korrekt, aber Follistatin (myostatinbindendes Protein), Bimagrumab (Rezeptor-Antikörper) und ACE-031 (löslicher Köderrezeptor) sind drei verschiedene Wirkprinzipien, die auch die WADA in S4.3 getrennt aufführt.' },
  { id: 'andarin', view: 'experimental', evidenz: 2, mechanismus: 5, sicherheit: 3, hype: 2, anwendung: 3, richtung: 'offen',
    beleg: 'Evidenz 2, weil es keine einzige veröffentlichte Wirksamkeitsstudie am Menschen gibt: Alle Wirksamkeitsdaten stammen aus Nagern (Gao 2005; Yin 2003; Kearbey 2007), und die drei bis vier abgeschlossenen Phase-I-Studien an 86 Freiwilligen sind nur über Firmenmitteilungen bekannt, nicht peer-reviewed publiziert (GTx SEC-Filings 2003 bis 2007). Mechanismus 5, weil der Androgenrezeptor eine gut belegte Zielstruktur ist und die Gewebeselektivität im Tier klar gezeigt wurde, die Wirkkette von Andarin am Menschen aber nicht quantifiziert ist - bekannt ist nur ein Firmenhinweis auf eine Wachstumsaktivität. Sicherheit 3, weil kontrollierte Sicherheitsdaten am Menschen fehlen; es liegen nur eine unpublizierte Phase-I-Verträglichkeit sowie Fallberichte zur SARM-Klasse vor (Leberschäden, Achillessehnenriss, ein Diabetes-Fall unter Dreier-Kombination), Langzeitdaten fehlen (Vignali 2023; Gould 2021; Sotornik 2022). Hype 2, weil Andarin in der Szene für Definition und Fettabbau beworben wird, ohne dass es dazu Humandaten gibt, und weil die verbreitete Erzählung vom Abbruch wegen Sehstörungen sich in keiner Primärquelle belegen liess - die Firmenangaben nennen ausdrücklich keine schweren Nebenwirkungen und als Grund die Bevorzugung des Nachfolgers Ostarin. Anwendung 3, weil Andarin am Menschen praktisch nur in Studien und auf dem Graumarkt vorkommt, keinen regulatorischen Rahmen hat und im Sport verboten ist. Richtung offen, weil es am Menschen keine Wirksamkeitsdaten gibt, die für oder gegen die beworbene Wirkung sprechen; die Tierdaten stützen einen anabolen Effekt, die Übertragung auf den Menschen ist ungeklärt.' },
  { id: 'cardarine', view: 'experimental', evidenz: 5, mechanismus: 6, sicherheit: 5, hype: 2, anwendung: 3, richtung: 'gemischt',
    beleg: 'Evidenz 5, weil es zwar mehrere kontrollierte Humanstudien gibt (Sprecher 2007, n=24; Riserus 2008, 6 pro Gruppe; Ooi 2011, n=13; Olson 2012, n=268, 12 Wochen), diese aber ausschließlich Surrogat-Blutfettwerte messen und keine einzige die Anwendung betrifft, für die Cardarine bekannt ist: Ausdauer und Fettabbau sind am Menschen nie untersucht worden, harte Endpunkte fehlen, die Entwicklung wurde vorher gestoppt. Mechanismus 6, weil die Zielstruktur PPARdelta am Menschen bestätigt ist und die Wirkkette über CPT1b-Induktion und gemessene Fettverbrennung teilweise quantifiziert wurde (Riserus 2008); der Ausdauereffekt selbst ist nur tierexperimentell und im Ausgangsbefund an Training gebunden - GW1516 allein steigerte die Laufleistung sitzender Mäuse nicht (Narkar 2008). Sicherheit 5, weil kontrollierte Humandaten nur über Wochen bis 12 Wochen vorliegen, Langzeitdaten fehlen und das entscheidende Krebssignal aus langfristigen Tierstudien stammt (GSK/Health Canada 2013; Apc-min-Modell Gupta 2004); dazu ein Vergiftungsfall mit Rhabdomyolyse in Kombination mit Ostarin (Kintz 2021). Hype 2, weil die Erzählung "Ausdauer in Pillenform" zwei Dinge weglässt: Die tragenden Zahlen stammen von Mäusen und nur mit Training, und dass der Hersteller die Entwicklung wegen Krebs abgebrochen hat, kommt in der Vermarktung nicht vor; die populären 44 Prozent gehören außerdem zu AICAR, nicht zu GW1516. Anwendung 3, weil GW501516 am Menschen praktisch nur in Studien und auf dem Graumarkt vorkommt, keinen regulatorischen Rahmen hat und im Sport verboten ist. Richtung gemischt: Mechanismus und die humanen Blutfettdaten tragen, aber für die beworbene Wirkung fehlen Humandaten, und das Krebssignal steht dagegen.' },
  { id: 'dhea', view: 'experimental', evidenz: 7, mechanismus: 7, sicherheit: 6, hype: 4, anwendung: 6, richtung: 'gemischt',
    beleg: 'Evidenz 7, weil es viele randomisierte Studien und mehrere Meta-Analysen gibt, die Effekte aber klein und uneinheitlich sind: Sexualfunktion SMD 0,31 im Cochrane-Review (Scheffers et al. 2015, 28 Studien, 1273 Frauen) gegenüber knapp nicht signifikanten 0,35 in 23 RCTs (Elraiyah et al. 2014), Knochendichte der Lendenwirbelsäule bei Frauen +1,0 % nach 12 Monaten (Jankowski et al. 2019, 4 RCTs), und die zweijährige NEJM-Studie fand bei 87 Männern und 57 Frauen keinen Effekt auf Körperzusammensetzung, Kraft, Insulinwirkung oder Lebensqualität (Nair et al. 2006); die Zulassung als Vaginalzäpfchen (Labrie et al. 2016, Phase III) betrifft eine andere Anwendung als das orale Anti-Aging-Versprechen. Mechanismus 7, weil die Umwandlung in Sexualhormone am Menschen quantifiziert ist (Testosteron +24,31 ng/dl, Estradiol +7,86 pg/ml, He et al. 2025), der Weg zu harten Endpunkten aber nicht. Sicherheit 6, weil kontrollierte Daten über 12 Monate bis 2 Jahre vorliegen, dazu Zulassungsdaten für die vaginale Form, aber keine Langzeitdaten zur Tablette und keine Daten zum Krebsrisiko. Hype 4, weil DHEA als Jungbrunnen vermarktet wird, obwohl genau dieser Anspruch in der besten Langzeitstudie nicht hielt. Anwendung 6, weil DHEA in den USA frei als Nahrungsergänzung erhältlich ist, als Vaginalzäpfchen in EU und USA zugelassen und in Deutschland verschreibungspflichtig reguliert ist.' },
  { id: 'eloralintid', view: 'experimental', evidenz: 7, mechanismus: 8, sicherheit: 5, hype: 6, anwendung: 2, richtung: 'positiv',
    beleg: 'Evidenz 7, weil echte Humandaten aus drei randomisierten, placebokontrollierten Studien vorliegen – einer Phase-2-Studie über 48 Wochen mit 263 Teilnehmern an 46 US-Zentren, in der alle Wirkstoffgruppen den primären Endpunkt erreichten (9 bis 20 Prozent gegenüber 0,4 Prozent unter Placebo, Billings 2025), einer Phase-1b-Studie über 12 Wochen mit 100 Teilnehmern (2,6 bis 11,3 Prozent, Bhattachar 2026) und einer Phase-1-Studie mit Einzelgaben an 48 gesunden Teilnehmern (Briere 2025). Keine 8 oder 9, weil die Phase-3-Studien erst seit Dezember 2025 rekrutieren, die längste Behandlungsdauer 48 Wochen beträgt, harte Endpunkte fehlen und derselbe Datensatz je nach Schätzgröße unterschiedlich berichtet wird (Abstract 9 bis 20 Prozent, Hersteller 9,5 bis 20,1, Bassatne 2026 7,3 bis 17,5 Prozent). Mechanismus 8, weil die Zielstruktur am menschlichen Rezeptor bestätigt ist (12-fach stärkere Aktivierung des Amylin-1-Rezeptors als des Calcitonin-Rezeptors, Briere 2025) und die Wirkkette am Menschen über Gewicht, Appetit und Pulsfrequenz messbar ist; nicht 9, weil die Zusammensetzung des Gewichtsverlusts beim Menschen nicht berichtet wird und die Fettmassen-Anteile von 68 bis 85 Prozent aus dem Rattenversuch stammen. Sicherheit 5, weil kontrollierte Daten über 48 Wochen vorliegen, aber nur an 263 Menschen: keine Pankreatitis, keine Cholezystitis, keine Todesfälle in der Phase 2 (Alhazmi 2026), dafür Übelkeit bis 64 Prozent, Erschöpfung bis 46 Prozent, etwa 10 Prozent Abbrüche wegen unerwünschter Ereignisse, ungeklärte stimmungsbezogene Ereignisse in der höchsten Dosisgruppe der Phase 1b und keine Endpunktstudie zu Herz und Kreislauf. Hype 6, weil Firmenmitteilung und Publikation in derselben Größenordnung liegen und die Nebenwirkungsraten offen berichtet werden; Abzüge, weil die Erzählung der besseren Verträglichkeit durch Rezeptorselektivität in der Phase 2 gerade nicht bestätigt wurde – die Aufdosierung war der entscheidende Faktor – und weil indirekte Vergleiche aus der Netzwerk-Metaanalyse wie Direktvergleiche weitergegeben werden. Anwendung 2, weil der Wirkstoff nur in klinischen Studien vorkommt. Richtung positiv: Alle placebokontrollierten Studien zeigen eine deutliche, dosisabhängige Gewichtsabnahme; die Verträglichkeitsfrage bildet die Sicherheitsachse ab.' },
  { id: 'hgh-fragment-176-191', view: 'experimental', evidenz: 1, mechanismus: 4, sicherheit: 1, hype: 2, anwendung: 3, richtung: 'gemischt',
    beleg: 'Evidenz 1, weil das natürliche Fragment 176-191 am Menschen nie geprüft wurde, sondern nur in einer akuten Rattenstudie von 1978, die kurzfristig Blutzucker und Insulin anhob. Humandaten gibt es nur zur Variante AOD-9604 (Tyrosin statt Phenylalanin am Anfang), die im Handel oft unter diesem Namen läuft; für das Fragment gelten sie nur indirekt: sechs placebokontrollierte Studien mit 893 Teilnehmern (Stier 2013), deren größte über 24 Wochen mit 502 Randomisierten laut Hersteller 2007 den Gewichtsendpunkt verfehlte. Mechanismus 4: Im Tier ist die Wirkkette am Fettgewebe gezeigt – hormonsensitive Lipase rauf, Acetyl-CoA-Carboxylase runter, keine Bindung am Wachstumshormon-Rezeptor (Ng 2000, Heffernan 2001) – und in menschlichem Fettgewebe ex vivo bestätigt, der Rezeptor ist aber unbekannt. Sicherheit 1, weil es für das natürliche Fragment keine Sicherheitsdaten am Menschen gibt; die kontrollierten Daten über bis zu 24 Wochen betreffen nur die AOD9604-Sequenz, stammen aus Sponsor-Nähe und lassen sich nur indirekt übertragen. Hype 2, weil das Fragment als Fettabbau-Peptid gehandelt wird, obwohl der Humanbeleg für Gewichtsverlust fehlt und die Namensgleichheit die Humandaten eines anderen Moleküls überträgt. Anwendung 3: Die Tyrosin-Sequenz lief nur in Studien; der Szenegebrauch ist verbreitet, aber nicht beziffert. Richtung gemischt: im Tier konsistent positiv, am Menschen (oral) kein Gewichtseffekt, das natürliche Fragment im Tier eher blutzuckersteigernd.' },
  { id: 'igf-1-des', view: 'experimental', evidenz: 0, mechanismus: 5, sicherheit: 1, hype: 2, anwendung: 2, richtung: 'offen',
    beleg: 'Evidenz 0, weil es keine Studie am Menschen gibt: Die Europe-PMC-Suche am 27.09.2026 lieferte 247 Arbeiten zu des(1-3)IGF-I, keine davon mit gespritztem Wirkstoff bei Menschen, und die ClinicalTrials.gov-API kennt keinen passenden Eintrag; die Übersicht von Dominikowski 2026 ordnet Peptide dieser Achse ausdrücklich bis zur Stufe völlig fehlender Humandaten ein. Mechanismus 5, weil die Wirkkette in Zellkultur und Tier quantifiziert ist – fehlende Glutaminsäure an Position 3, kaum Bindung an die IGF-Bindungsproteine, etwa 10-fach höhere Potenz in Zellkultur (Ballard 1996), 2,5-fach höhere anabole Potenz bei Ratten unter Dexamethason (Tomas 1992), höhere Clearance und größeres Verteilungsvolumen als IGF-1 (Ballard 1991) –, am Menschen aber nichts davon geprüft wurde. Sicherheit 1, weil systematische Sicherheitsdaten fehlen und die vorhandenen Signale ernst sind: stärkste Blutzuckersenkung aller geprüften IGF-1-Varianten in Krallenaffe und Schwein (Tomas 1997), Darmgewicht bis plus 60 Prozent (Read 1992), 53 Prozent Milchdrüsenkarzinome bis 23 Monate im Überexpressionsmodell (Hadsell 2000). Hype 2, weil die verbreitete Erzählung einer besonders lang wirkenden und rein örtlich im Muskel bleibenden Substanz den Daten widerspricht – die Clearance im Tier ist höher als die von IGF-1, und der stärkste Reiz traf den Darm, nicht den Muskel. Anwendung 2, weil die Substanz nur in Tierversuchen und in Graumarktkreisen vorkommt; Mongongu 2021 hält fest, dass sie nie für den Menschen zugelassen wurde und dennoch als Schwarzmarktprodukt gehandelt wird. Richtung offen: Die Tierdaten sind positiv und konsistent, sie sagen aber nichts über Nutzen oder Schaden beim Menschen.' },
  { id: 'kh-cardiogen', view: 'khavinson', evidenz: 1, mechanismus: 3, sicherheit: 1, hype: 2, anwendung: 3, richtung: 'offen',
    beleg: 'Evidenz 1: Zu Cardiogen gibt es keine Studie am Menschen; Europe PMC liefert nur Tier- und Zellarbeiten, das Patent enthält keine Humanbeispiele, und ClinicalTrials.gov führt keinen passenden Eintrag. Die tragenden Tierdaten stehen im Patent der Entwickler (US 7,662,789): Im Infarktmodell an 40 Ratten lag die Sterblichkeit in den ersten 24 Stunden bei 15 statt 45 Prozent, der Glykogengehalt des Herzmuskels blieb erhalten; die Übersicht in Cells 2022 übernimmt diese Zahlen mit Verweis auf das Patent. Begutachtet veröffentlicht sind Gewebekulturen aus dem Herzen 3 und 24 Monate alter Ratten mit mehr Zellvermehrung und weniger p53 (Adv Gerontol 2009) und die 2- bis 5-fache Steigerung von Zytoskelett-Proteinen in Mausfibroblasten (Bull Exp Biol Med 2012). Mechanismus 3, weil die epigenetische Wirkkette in Zellkultur und Tier plausibel, am Menschen aber nicht bestätigt ist. Sicherheit 1, weil nur Tiertoxikologie aus dem Patent vorliegt (6 Monate an 96 Meerschweinchen). Hype 2, weil die beworbenen Herzindikationen den Tiermodellen entsprechen, der Sprung zum Menschen aber unbelegt ist. Anwendung 3, weil das Peptid außerhalb Russlands nur als Research-Ware zirkuliert.' },
  { id: 'kh-cartalax', view: 'khavinson', evidenz: 2, mechanismus: 3, sicherheit: 1, hype: 2, anwendung: 3, richtung: 'offen',
    beleg: 'Evidenz 2: Die einzige Humanangabe ist ein Beispiel im russischen Patent RU 2299741 der Entwickler: 29 Patienten mit Kniegelenksarthrose, randomisiert, 12 davon mit Kochsalz-Injektionen, 20 Tage intramuskulär; weniger Schmerz und mehr Beweglichkeit in 54,5 bis 62,7 Prozent der Fälle, ohne wesentliche Röntgenveränderung. Ergebnis der Kontrollgruppe, Skalen, Verblindung und Nebenwirkungen fehlen, begutachtet ist der Bericht nicht, und in Europe PMC wie ClinicalTrials.gov findet sich keine Humanstudie. Präklinisch stimmig: In gealterten menschlichen Stammzellen aktivierte AED SOX9, Aggrecan, Kollagen Typ II und COMP, in gealterten Knorpelzellen normalisierte es p16, p21, p53, TNF-α, IL-1α und Sirt1 (Adv Gerontol 2023), Knorpel-Explantate der Ratte wuchsen um 26 Prozent stärker (Patent). Mechanismus 3, weil die Wirkkette in Zellkultur plausibel, am Menschen aber nicht bestätigt und nicht knorpelexklusiv ist. Sicherheit 1, weil nur Tiertoxikologie aus dem Patent vorliegt (bis zu 6 Monate an 90 Meerschweinchen). Hype 2, weil der beworbene Gelenknutzen eine Grundlage in Zellkultur und einem kleinen Patentbericht hat, Knorpelaufbau und Wirkung als Kapsel aber unbelegt sind. Anwendung 3, weil das Peptid außerhalb Russlands nur als Research-Ware zirkuliert.' },
  { id: 'kh-cortagen', view: 'khavinson', evidenz: 1, mechanismus: 3, sicherheit: 1, hype: 4, anwendung: 2, richtung: 'offen',
    beleg: 'Evidenz 1, weil keine kontrollierte Humanstudie veröffentlicht ist und ClinicalTrials.gov keine Studie zu Cortagen führt; die einzigen Daten mit menschlichem Material sind Lymphozyten 75- bis 88-jähriger Spender in der Zellkultur (Khavinson et al. 2004, Lezhava et al. 2023), und die Angabe von 2004, Cortagen habe beim Menschen die Nervenerholung gefördert, ist nicht mit einer Studie belegt. Tragender Befund ist der Rattenversuch zur Nervenregeneration mit 27 Prozent schnellerem Faserwachstum und 40 Prozent höherer Leitgeschwindigkeit über 10 Tage (Turchaninova et al. 2000), ergänzt durch Hirnischämie- und Oxidationsdaten an Ratten (2007, 2011). Mechanismus 3, weil die epigenetische Hypothese der Khavinson-Schule mit Zell- und Tierbefunden plausibel gemacht ist (Genaktivität im Mausherz, 234 von 15.247 Genabschnitten verändert; Chromatin-Auflockerung), eine konkrete Zielstruktur aber nicht identifiziert und nichts davon am Menschen bestätigt ist. Sicherheit 1, weil weder Toxikologie noch Pharmakokinetik am Menschen veröffentlicht sind. Hype 4, weil der Verkauf als Hirn- und Konzentrations-Bioregulator auf einem Nervenregenerations-Befund bei Ratten und Laborbefunden aufbaut; negative Einzelbefunde (Thymuszellen 2002, Hühnerversuch 2008) tauchen dort nicht auf. Anwendung 2, weil Cortagen außerhalb von Studien nur als Forschungspeptid im Graumarkt vorkommt. Die Datenlage ist fast ausschließlich russische Literatur aus einer Forschungslinie; das spricht nicht gegen die Befunde, macht aber eine unabhängige Wiederholung zur offenen Aufgabe.' },
  { id: 'ligandrol', view: 'experimental', evidenz: 4, mechanismus: 6, sicherheit: 3, hype: 2, anwendung: 4, richtung: 'offen',
    beleg: 'Evidenz 4, weil es nur zwei kontrollierte Humanstudien gibt, beide kurz und mit Surrogatendpunkt: 76 gesunde junge Männer über 21 Tage mit dosisabhängigem Zuwachs fettfreier Masse, in der höchsten Stufe etwa 1,2 kg über Placebo, aber unveränderter Beinkraft (Basaria 2013), und 108 Patienten ab 65 Jahren nach Hüftfraktur mit placebobereinigt bis zu 9,1 Prozent mehr fettfreier Masse in 12 Wochen, die nur als Registereintrag und Firmenmitteilung vorliegt. Mechanismus 6, weil die Rezeptorwirkung am Menschen über die dosisabhängige Senkung von Gesamttestosteron, SHBG und HDL bestätigt ist, die behauptete Gewebeselektivität aber ohne Direktvergleich mit klassischen Androgenen offen bleibt (Bond 2025). Sicherheit 3, weil kontrollierte Daten nur über 21 Tage und 12 Wochen vorliegen; dazu kommen mehrere begutachtete Fallberichte schwerer cholestatischer Leberschäden bei Anwendern und ein genau vermessener Anwender-Fall mit HDL minus 36,4 Prozent und ALT plus 205,0 Prozent. Hype 2, weil Ligandrol als starker Aufbau-SARM mit schnellen Kraftgewinnen gehandelt wird, während die einzige begutachtete Studie keinen Kraftgewinn fand und die Hormonsuppression schon nach 21 Tagen messbar war. Anwendung 4, weil es in der Kraftsportszene verbreitet ist, ohne jeden regulatorischen Rahmen. Richtung offen: Masse ist gezeigt, ob daraus Kraft oder Funktion wird, ist nicht geprüft.' },
  { id: 'noopept', view: 'experimental', evidenz: 4, mechanismus: 4, sicherheit: 4, hype: 3, anwendung: 6, richtung: 'offen',
    beleg: 'Evidenz 4, weil es mehrere klinische Studien an Patienten mit leichten kognitiven Störungen gibt, darunter eine kleine randomisierte Vergleichsstudie gegen Piracetam (Neznamov & Teleshova 2008) und ein randomisierter Vergleich mit 150 Patienten gegen Piracetam/Cinnarizin und Phenibut (Dadasheva 2022, MoCA 19,8 auf 23,3 in 45 Tagen), aber keine einzige placebokontrollierte, doppelblinde Studie; alle Arbeiten sind russisch, mehrere herstellernah, und die Endpunkte sind Testskalen statt harter Endpunkte. Mechanismus 4, weil die Wirkkette – Umbau zu Cyclo-Prolylglycin (2,5-fach im Rattenhirn, Gudasheva 1997), mehr NGF und BDNF im Hippocampus (Ostrovskaya 2008), HIF-1-Aktivierung in Zellkultur – plausibel und präklinisch gut beschrieben, am Menschen aber nicht bestätigt ist. Sicherheit 4, weil kontrollierte Verträglichkeitsdaten nur über Wochen bis wenige Monate vorliegen (unerwünschte Ereignisse 25 statt 55 Prozent unter Piracetam), dazu eine sechsmonatige Tierstudie ohne bleibende Organschäden, aber keine veröffentlichte Langzeit- oder Pharmakovigilanzauswertung. Hype 3, weil die Szene Noopept als Gedächtnisverstärker für Gesunde vermarktet, wofür keine Daten existieren, und die Formel tausendmal stärker als Piracetam aus der im Tierversuch 1000-fach niedrigeren wirksamen Dosis stammt (Ostrovskaia 2002). Anwendung 6, weil Noopept in Russland seit Jahren als rezeptfreies Arzneimittel unter Aufsicht verkauft wird, außerhalb davon nur im Graumarkt. Richtung offen, weil die vorhandenen Studien zwar einheitlich positiv ausfallen, ohne Placebovergleich aber nicht zeigen können, wie viel davon Wirkstoff ist.' },
  { id: 'ostarin', view: 'experimental', evidenz: 6, mechanismus: 7, sicherheit: 6, hype: 3, anwendung: 4, richtung: 'gemischt',
    beleg: 'Evidenz 6, weil es für einen SARM ungewöhnlich viele kontrollierte Humandaten gibt, die aber bei der entscheidenden Frage uneinheitlich sind: Bei 120 gesunden Älteren stieg die fettfreie Masse in 12 Wochen um 1,3 kg gegenüber Placebo und die Treppenleistung besserte sich (Dalton 2011), in den beiden Phase-3-Studien POWER mit 321 und 330 Krebspatienten hielten mehr Patienten ihre Muskelmasse, die Treppenleistung besserte sich aber in keiner signifikant, und die Gesamtkriterien wurden 2013 verfehlt. Mechanismus 7, weil die Rezeptorwirkung am Menschen mehrfach bestätigt ist – SHBG, Gesamttestosteron bei Männern und HDL sinken dosisabhängig, bei rezeptorpositivem Brustkrebs zeigte sich Tumoraktivität (Palmieri 2024, 136 Frauen) –, die behauptete Gewebeselektivität aber ohne Direktvergleich mit klassischen Androgenen nicht belegt ist. Sicherheit 6, weil kontrollierte Daten über Monate vorliegen, mit HDL-Senkung um bis zu 27 Prozent und ALT-Anstiegen, dazu Fallberichte schwerer cholestatischer Leberschäden; Langzeit- und Pharmakovigilanzdaten fehlen. Hype 3, weil der Ruf als sanfter, nebenwirkungsarmer Einstiegs-SARM für Trainierende auf Studien an Älteren und Kranken ohne Training beruht und die Testosteron- und HDL-Senkung ausblendet; die jüngsten Muskelschutzdaten unter Semaglutid (QUALITY, 168 Teilnehmer) stammen bisher nur aus einer Firmenmitteilung. Anwendung 4, weil Ostarin in der Kraftsportszene seit Jahren ohne regulatorischen Rahmen verbreitet ist, als Arzneimittel aber nirgends zugelassen. Richtung gemischt: Masse ja, Funktion bisher nicht gesichert.' },
  { id: 'peg-mgf', view: 'experimental', evidenz: 0, mechanismus: 3, sicherheit: 1, hype: 1, anwendung: 3, richtung: 'offen',
    beleg: 'Evidenz 0, weil es zu PEG-MGF keine begutachtete Studie gibt, weder am Tier noch am Menschen: Die FDA fand keinerlei Humandaten zu irgendeinem Verabreichungsweg (Stand 22.04.2026), eine Übersicht von 2026 stuft es in die unterste Evidenzstufe ein, und ClinicalTrials.gov führt keinen Eintrag. Mechanismus 3: Die Biologie dahinter ist real – beim Menschen steigt die MGF-Botschaft nach Krafttraining bei 8 Jungen, nicht bei 7 Älteren (Hameed 2003) –, und synthetische E-Peptide schützten im Tier Herz und Nervenzellen (Schaf: 35 Prozent weniger geschädigter Herzmuskel nach 8 Tagen, Carpenter 2008). Die Grundlage ist aber umstritten: Ein natürliches MGF-Peptid wurde nie nachgewiesen (Matheny 2010), zwei Pharmaunternehmen konnten die Zelleffekte nicht reproduzieren (Fornaro 2014), und die PEG-Kette verändert Verteilung und Verweildauer so grundlegend, dass Befunde am nackten Peptid nicht übertragbar sind. Sicherheit 1: nicht untersucht; dazu ein Laborsignal für Wachstum von Prostatakrebszellen (Armakolas 2010). Hype 1, weil Muskelaufbau und Regeneration versprochen werden, ohne dass das Molekül je geprüft wurde, und Dauer-Aktivierung im Mausmuskel sogar Masse ohne Kraft ergab (Brisson 2014). Anwendung 3: Gebrauch im Kraftsport-Graumarkt, belegt durch Dopingfunde (2014, 2017), ohne klinische Nutzung. Richtung offen, weil keine Daten zum Stoff selbst vorliegen und die Befunde zum Ausgangspeptid widersprüchlich sind.' },
  { id: 'phenibut', view: 'experimental', evidenz: 4, mechanismus: 5, sicherheit: 5, hype: 2, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz 4, weil zur angstlösenden Wirkung mehrere klinische Studien aus Russland und Lettland vorliegen (systematischer Review: 11 Studien, 583 Patienten, Kupats 2020; randomisiert, aber ohne Placebo: Dadasheva 2022 mit Angstrückgang um 20,0 Punkte, Esin 2022 mit 120 Patienten), jedoch keine placebokontrollierte Studie gefunden wurde, die Übersicht im Deutschen Ärzteblatt keine prospektive randomisierte kontrollierte Studie fand und die nootropische Wirkung bei Gesunden nicht untersucht ist. Mechanismus 5, weil beide Zielstrukturen an Hirnmembranen quantifiziert sind – GABA-B deutlich schwächer als Baclofen, α2-δ mit 4-mal höherer Affinität als GABA-B (Zvejniece 2015) – und das klinische Bild mit benzodiazepinähnlichem Entzug, der auf Baclofen anspricht, dazu passt, eine Messung der Zielbindung am Menschen aber fehlt. Sicherheit 5, weil die Risiken ungewöhnlich breit dokumentiert sind – 1.320 US-Giftnotrufe mit 12,6 Prozent schweren Verläufen und 3 Todesfällen (Graves 2020), systematische Reviews zu Vergiftung und Entzug (Weleff 2023, Feldman 2023), GIZ-Nord-Daten (Bonnet 2024) –, kontrollierte Langzeitdaten zur Abhängigkeitshäufigkeit bei bestimmungsgemäßer Anwendung aber fehlen; die Zahl heißt gut untersucht, nicht harmlos. Hype 2, weil Phenibut online als Nahrungsergänzung und Nootropikum für Gesunde verkauft wird, ohne Daten dazu und ohne Hinweis auf Abhängigkeit, und die Ware nach FDA-Warnungen in 3 von 4 Marken sogar mehr Wirkstoff enthielt (Cohen 2022). Anwendung 7, weil Phenibut seit 1965 in der Sowjetunion und Russland ärztlich verordnet wird und in Lettland verschreibungspflichtig registriert ist, im Westen aber ohne Rahmen im Graumarkt kursiert. Richtung gemischt, weil die angstlösende Wirkung in Studien einheitlich beschrieben ist, Abhängigkeit und Entzug bei täglicher Einnahme aber ebenso klar belegt sind.' },
  { id: 'stenabolic', view: 'experimental', evidenz: 1, mechanismus: 4, sicherheit: 1, hype: 1, anwendung: 4, richtung: 'offen',
    beleg: 'Evidenz 1, weil am Menschen keine einzige Wirksamkeitsstudie existiert – die Abfrage der ClinicalTrials.gov-Schnittstelle zu SR9009 und Stenabolic gibt am 27.09.2026 keinen Eintrag zurück –, und die gesamte Humanliteratur aus zwei Schadensfallberichten besteht (Case Reports Hepatol 2026, Cureus 2025). Die Wirkerzählung stammt aus Mausversuchen mit intraperitonealer Gabe: 60 Prozent stärkerer Gewichtsverlust über 12 Tage und Cholesterin minus 47 Prozent bei fettleibigen Tieren (Solt et al., Nature 2012), mehr Laufleistung unter 100 mg/kg über 30 Tage (Woldt et al., Nat Med 2013). Mechanismus 4, weil die Zielstruktur am Menschen bedeutsam und die Wirkkette im Tier gut beschrieben ist (IC50 670 und 800 nM, Signalweg Lkb1-Ampk-Sirt1-Ppargc-1alpha), die Zuordnung aber nachweislich unvollständig bleibt: In Zellen ohne REV-ERBalpha und REV-ERBbeta wirkt SR9009 weiter (Dierickx et al., PNAS 2019), und es gibt Hinweise auf LXR-Aktivität. Sicherheit 1, weil am Menschen nichts systematisch untersucht ist und die einzigen Befunde zwei Leberschäden sind, einer mit Notfalltransplantation. Hype 1, weil die Vermarktung als Sport in der Kapsel echte Mauszahlen aus Bauchhöhleninjektionen auf Kapseln überträgt, obwohl nach Schlundgabe die Plasmaspiegel unter 0,3 µg/ml bleiben, die Halbwertszeit rund 0,5 Stunden beträgt und die Wirkung nach Autorenangabe auf den Darm begrenzt sein könnte (Yu et al., Nat Commun 2021). Anwendung 4, weil die Substanz seit Jahren ohne jeden regulatorischen Rahmen im Fitnessmarkt kursiert – in 39 Prozent von 44 als SARM verkauften Internetprodukten fand sich ein anderer nicht zugelassener Wirkstoff, darunter SR9009 (JAMA 2017). Richtung offen: Die Humanfrage ist nicht beantwortet, aber die orale Pharmakokinetik spricht gegen die verkaufte Anwendungsform. Einordnungsfehler, der überall wiederkehrt: SR9009 ist kein SARM, sondern ein REV-ERB-Agonist; die WADA führt es unter S4.4.1, nicht unter S1.2.' },
  { id: 'tudca', view: 'supplement', evidenz: 6, mechanismus: 6, sicherheit: 7, hype: 4, anwendung: 6, richtung: 'gemischt',
    beleg: 'Evidenz 6, weil es mehrere randomisierte Studien gibt, diese aber klein oder auf Surrogatmarker beschränkt sind und sich bei ALS widersprechen: Gleichwertigkeit zu UDCA bei primär biliärer Cholangitis (Ma et al., Medicine 2016, n = 199, 24 Wochen), etwa 30 % bessere Insulinsensitivität in Leber und Muskel (Kars et al., Diabetes 2010, n = 20, 4 Wochen), 87 % vs. 43 % Responder in der ALS-Pilotstudie (Elia et al., Eur J Neurol 2016, n = 34) – aber ein verfehlter primärer Endpunkt in der Phase III TUDCA-ALS mit 336 Teilnehmenden über 18 Monate (Topline 2024). Mechanismus 6, weil die Verschiebung des Gallensäurepools beim Menschen gemessen ist (Setchell et al., Gut 1996) und das Insulinsignal im menschlichen Muskel anstieg, die ER-Stress-Marker sich beim Menschen aber nicht änderten; der Chaperon-Mechanismus ist vor allem aus Mäusen belegt (Özcan et al., Science 2006). Sicherheit 7, weil kontrollierte Daten über 54 Wochen und 18 Monate vorliegen und TUDCA in Italien als Arzneimittel zugelassen ist, Langzeit-Pharmakovigilanz aber nicht öffentlich greifbar ist. Hype 4, weil Leberschutz bei Anabolika, Entgiftung und Neuroprotektion über die Daten hinausgehen. Anwendung 6, weil es in Italien als verschreibungspflichtiges Arzneimittel reguliert eingesetzt und anderswo breit als Nahrungsergänzung verkauft wird. Richtung gemischt: positiv bei Galle und Insulinwirkung, negativ in der großen ALS-Studie.' },
  { id: 'b7-33', view: 'experimental', evidenz: 1, mechanismus: 6, sicherheit: 1, hype: 3, anwendung: 2, richtung: 'offen',
    beleg: 'Evidenz 1, weil es zu B7-33 keine Humanstudie gibt: Die Abfrage von ClinicalTrials.gov liefert 0 Einträge, und keine der 12 Arbeiten mit B7-33 im Abstract hat menschliche Teilnehmer; belegt ist nur Zellkultur an menschlichem Material, darunter Herzfibroblasten. Mechanismus 6, weil die Zielstruktur am Menschen zweifelsfrei ansprechbar ist – Serelaxin senkte bei 71 Patienten den pulmonalkapillären Verschlussdruck um 2,44 mmHg stärker als Placebo – und die Wirkkette von B7-33 in Zellen quantifiziert ist (pKi 5,54 gegenüber 8,96; cAMP pEC50 5,12 gegenüber 10,49; ERK1/2 und MMP-2 auf Hormonniveau in Fibroblasten), die funktionelle Selektivität am Menschen aber nicht bestätigt wurde und die Entwicklergruppe die schwache Affinität am überexprimierten Rezeptor selbst als offene Frage benennt (Handley et al. 2023). Sicherheit 1, weil nichts am Menschen untersucht ist, keine Toxikologie vorliegt und die längste veröffentlichte Behandlungsdauer 4 Wochen im Mausmodell beträgt. Hype 3, weil die Vermarktung echte Tierbefunde – Fibrose in Herz, Lunge und Niere, Infarktgröße 21,99 gegenüber 45,32 Prozent – ohne das Wort Maus weiterreicht und die gescheiterte Entwicklung des Muttermoleküls weglässt: RELAX-AHF-2 verfehlte mit 6545 Patienten beide primären Endpunkte, die EMA lehnte Serelaxin am 23. Mai 2014 ab. Anwendung 2, weil die Substanz nur in Studien und in kleinen Graumarktkreisen vorkommt; ein Forenthread von März 2026 umfasst 5 Beiträge ohne eigene Anwendererfahrungen. Richtung offen: Die Tierdaten zeigen konsistent in eine Richtung, aber die Frage, ob ein funktionell selektiver RXFP1-Agonist beim Menschen Fibrose senkt, ist weder beantwortet noch widerlegt – in den gescheiterten Serelaxin-Studien wurde sie gar nicht geprüft.' },
  { id: 'dim', view: 'experimental', evidenz: 6, mechanismus: 6, sicherheit: 6, hype: 4, anwendung: 5, richtung: 'gemischt',
    beleg: 'Evidenz 6, weil mehrere doppelblinde RCTs vorliegen, diese aber meist Surrogatmarker messen und bei klinischen Endpunkten ohne signifikanten Effekt blieben: Verschiebung des Östrogenabbaus (+3,2 vs. -0,7) und SHBG +25 nmol/L bei 130 Frauen über 12 Monate (Thomson et al., Breast Cancer Res Treat 2017), aber bei 551 Frauen mit leichten Zellveränderungen am Gebärmutterhals CIN2+ 9 % vs. 12 %, RR 0,7 (0,4 bis 1,2) (Castañon et al., Br J Cancer 2012), kein Unterschied bei 64 Frauen mit CIN 2 oder 3 (Del Priore et al. 2010) und ein verfehlter primärer Endpunkt bei 60 prämenopausalen Frauen (Godínez-Martínez et al. 2023). Mechanismus 6, weil die Wirkung über den Arylhydrocarbon-Rezeptor und die Enzyme CYP1A1 und CYP1B1 aus Zell- und Tierdaten gut beschrieben ist und die Verschiebung der Östrogenmetaboliten sowie der SHBG-Anstieg am Menschen gemessen sind (Williams, Front Nutr 2021; Thomson et al. 2017), der Weg zu klinischen Effekten aber nicht. Sicherheit 6, weil kontrollierte Daten über 6 und 12 Monate vorliegen, dazu Dosisfindungsstudien mit Hyponatriämie bei 2 von 4 Patienten unter 300 mg zweimal täglich (Heath et al. 2010), aber keine Langzeit-Pharmakovigilanz und relevante Interaktionen mit Tamoxifen und Estradiol-Pflastern (Newman und Smeaton 2025). Hype 4, weil der real messbare Effekt auf den Östrogenabbau zu Versprechen wie Östrogen-Detox, Akne-Heilung oder Testosteron-Boost ausgebaut wird, für die es keine randomisierten Studien gibt. Anwendung 5, weil DIM seit Jahren in den USA breit als Supplement genutzt wird, ohne regulatorisch geprüft zu sein, und in der EU nicht zugelassen ist. Richtung gemischt: positiv beim Hormonstoffwechsel, ohne Effekt bei den bisher gemessenen klinischen Endpunkten.' },
  { id: 'huperzin-a', view: 'experimental', evidenz: 6, mechanismus: 7, sicherheit: 5, hype: 4, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz 6, weil es viele randomisierte, placebokontrollierte Studien bei Alzheimer gibt, die zusammengefasst positiv ausfallen – Cochrane 2008 mit 6 RCTs und 454 Patienten (MMSE +2,81), Yang et al. 2013 mit 20 RCTs und 1.823 Teilnehmenden, die größte chinesische Einzelstudie mit 202 Patienten über 12 Wochen –, die Studien aber überwiegend klein und mit hohem Verzerrungsrisiko sind und die sorgfältigste westliche Studie (Rafii et al., Neurology 2011, 210 Patienten, 16 Wochen) ihren primären Endpunkt verfehlte; für leichte kognitive Störung fand Cochrane 2012 keine geeignete Studie, für Gesunde gibt es keine belastbaren Daten. Mechanismus 7, weil die Hemmung der Acetylcholinesterase beim Menschen direkt gemessen ist (Haigh et al. 2008: 30 bis 40 Prozent bis über 50 Prozent in roten Blutkörperchen, Butyrylcholinesterase unverändert) und das Wirkprinzip dem der zugelassenen Alzheimer-Medikamente entspricht; die zusätzlichen Schutzeffekte stammen nur aus Zell- und Tiermodellen. Sicherheit 5, weil kontrollierte Daten nur über 8 bis 24 Wochen vorliegen und das RIVM 2024 mangels Langzeit- und Reproduktionsstudien keinen sicheren Aufnahmewert ableiten konnte, bei Hinweisen auf Embryotoxizität im Tier. Hype 4, weil ein Alzheimer-Befund mit Qualitätsvorbehalt als Gedächtnisbooster für Gesunde verkauft wird. Anwendung 7, weil Huperzin A in China seit Jahren als Arzneimittel eingesetzt wird, im Westen aber ohne klaren Rechtsrahmen als Supplement kursiert. Richtung gemischt, weil positive Meta-Analysen einem verfehlten primären Endpunkt in der besten Einzelstudie gegenüberstehen.' },
  { id: 'kanna', view: 'experimental', evidenz: 4, mechanismus: 5, sicherheit: 5, hype: 4, anwendung: 5, richtung: 'gemischt',
    beleg: 'Evidenz 4, weil es mehrere randomisierte, placebokontrollierte Studien gibt, diese aber durchweg klein und kurz sind, nur Gesunde untersuchen und oft Surrogatmarker messen: Terburg et al. 2013 (16 Gesunde, fMRT nach Einzeldosis), Chiu et al. 2014 (21 Gesunde, 3 Wochen, bessere kognitive Flexibilität p < 0,032 und Exekutivfunktion p < 0,022), Reay et al. 2020 (eine von zwei Laborstudien positiv) und Hoffman et al. 2020 (60 Sportler, 8 Tage, komplexe Reaktion besser, Stimmung unverändert); Studien an Patienten mit Angst oder Depression fehlen, und de Jong et al. 2026 sprechen von gemischter Evidenz. Mechanismus 5, weil Serotonintransporter- und PDE4-Hemmung in vitro quantifiziert sind (Harvey 2011: IC50 4,3 und 8,5 µg/ml, Mesembrin Ki 1,4 nM) und eine Hirnwirkung am Menschen per fMRT gezeigt ist, die Zielstruktur-Besetzung beim Menschen aber nie gemessen wurde und laut Novel-Food-Antrag die Hauptalkaloide nach dem Schlucken systemisch nicht verfügbar sind. Sicherheit 5, weil eine kontrollierte Studie über 3 Monate (Nell 2013, 37 Personen) und eine 90-Tage-Rattenstudie ohne Befund vorliegen (Murbach 2014, NOAEL 600 mg/kg), längere Daten und Daten zu Wechselwirkungen aber fehlen. Hype 4, weil kleine Befunde an Gesunden als natürliches Antidepressivum vermarktet werden. Anwendung 5, weil Kanna traditionell seit Jahrhunderten genutzt und weltweit als Supplement verkauft wird, in der EU aber ohne Zulassung. Richtung gemischt, weil positive Einzelbefunde neben Nullbefunden stehen und klinische Studien fehlen.' },
  { id: 'nmnh', view: 'experimental', evidenz: 3, mechanismus: 5, sicherheit: 4, hype: 3, anwendung: 3, richtung: 'offen',
    beleg: 'Evidenz 3, weil die Humandaten aus einer einzigen randomisierten, doppelblinden Phase-I-Studie stammen, die bisher nur als Preprint vorliegt und vom Hersteller finanziert wurde: 80 Gesunde, 90 Tage, NAD+ im Vollblut dosisabhängig, bei der höchsten Stufe von 19,43 auf 59,33 µM (Li 2026, NCT06889740); biologisches Alter, Gehstrecke und Lebensqualität waren explorativ. Mechanismus 5, weil der eigene Weg über NMNAT und der starke NAD+-Anstieg in Zellen und Mäusen von zwei unabhängigen Gruppen gezeigt sind – Leberkrebszellen 5- bis 7-fach, Mausleber 4-fach (Zapata-Pérez 2021; Liu 2021) – am Menschen aber nur der Blutwert gemessen ist und die Umstellung von Glykolyse, Citratzyklus und Stressgenen noch nicht verstanden ist (Vinten 2026). Sicherheit 4, weil nur 90 Tage an 80 Gesunden kontrolliert beobachtet sind, ohne schwere Ereignisse, ohne Langzeit- und Wechselwirkungsdaten. Hype 3, weil der Hersteller aus dem explorativen Blutalter-Befund ein „5 Jahre jünger“ macht, der NAD+-Anstieg im Blut aber tatsächlich gemessen ist. Anwendung 3, weil NMNH erst seit kurzem vor allem in den USA vermarktet wird und in der EU nicht zugelassen ist. Richtung offen, weil es keinen klinischen Endpunkt gibt, der für oder gegen einen Nutzen spricht.' },
  { id: 'prl-8-53', view: 'experimental', evidenz: 3, mechanismus: 2, sicherheit: 2, hype: 3, anwendung: 2, richtung: 'offen',
    beleg: 'Evidenz 3, weil es genau eine Humanstudie gibt: doppelblind und placebokontrolliert, mit signifikant besserem Behalten verbaler Listen (meist p unter 0,01, teils unter 0,001) und unveränderter Reaktionszeit und Motorik (Hansl & Mead 1978), aber vom Erfinder selbst, nie wiederholt, ohne Registereintrag bei ClinicalTrials.gov und mit Fallzahl und Effektgrößen nur im kostenpflichtigen Volltext. Mechanismus 2, weil außer der Einordnung als cholinerg und krampflösend im Patent und einer knappen Erstbeschreibung (Hansl 1974) nichts publiziert ist; Tierdaten zu Lernen und Behalten existieren nur als Herstellerangabe. Sicherheit 2, weil Toxizitätsangaben (Mäuse, Ratten über zwei Nachkommengenerationen, Hund, Affe) allein im Patent stehen und es am Menschen keine systematische Verträglichkeitsprüfung gibt. Hype 3, weil die Szene aus einer Einzelstudie eine Gedächtnisverdopplung und eine vielfach bestätigte Wirkung macht und die Substanz teils fälschlich als Peptid führt. Anwendung 2, weil PRL-8-53 nie klinisch eingeführt wurde und nur in Studien und einer Nische des Graumarkts vorkommt. Richtung offen, weil der einzige Befund positiv ist, ohne Wiederholung aber nicht trägt.' },
  { id: 's23', view: 'experimental', evidenz: 1, mechanismus: 5, sicherheit: 1, hype: 2, anwendung: 3, richtung: 'offen',
    beleg: 'Evidenz 1, weil es zu S-23 keine klinische Wirksamkeitsstudie und keinen Registereintrag gibt – die Dopinganalytiker halten ausdrücklich fest, dass S-23 nie Gegenstand einer klinischen Studie war (Alhalabi 2025); am Menschen existieren nur Ausscheidungsdaten aus Mikrodosis-Studien, die keine Wirkung messen (Alhalabi 2025; Korsmeier 2025; Ameline 2022). Alle Wirkungsdaten stammen aus Ratten: Bindung Ki 1,7 nM, ED50 am Muskel 0,079 gegenüber 0,43 mg/d an der Prostata, LH über 14 Tage um mehr als 50 Prozent gesenkt, mit Estradiolbenzoat bei 4 von 6 Tieren keine Spermien und 0 von 6 Schwangerschaften, nach 100 Tagen Erholung wieder 100 Prozent (Jones 2009). Mechanismus 5, weil der Androgenrezeptor eine gut belegte Zielstruktur ist und die Wirkkette im Tier quantifiziert wurde, am Menschen aber nichts davon bestätigt ist; zudem war S-23 in der Analogreihe gerade der Vertreter ohne Prostata-Schonung (Jones 2010), die SARM-Selektivität gilt für ihn also weniger. Sicherheit 1, weil es keine kontrollierten Sicherheitsdaten am Menschen gibt; belastbar sind nur Klassenbefunde – seit 2020 20 Berichte über unerwünschte Ereignisse, meist Leberschäden, darunter ein Fall mit S-23 plus Ligandrol (Leciejewska 2024) – und die FDA-Warnung zu SARM-Produkten. Hype 2, weil S-23 in der Szene als besonders starker Muskelaufbau-SARM beworben wird, während der eigentliche Entwicklungszweck die Unterdrückung der Hormonachse war und Humandaten zur Wirkung fehlen; die Werbung verschweigt außerdem, dass in einer Behördenanalyse eines von zwei als S-23 verkauften Produkten gar kein S-23 enthielt (Gaudiano 2024). Anwendung 3, weil S-23 nur auf dem Graumarkt und in Dopingfällen vorkommt – 5 positive Proben für 2022 – und keinen regulatorischen Rahmen hat. Richtung offen, weil am Menschen keine Daten vorliegen, die für oder gegen die beworbene Wirkung sprechen; die Tierdaten stützen einen anabolen Effekt samt Achsen-Suppression, die Übertragung ist ungeklärt.' },
  { id: 'sunifiram', view: 'experimental', evidenz: 0, mechanismus: 4, sicherheit: 1, hype: 3, anwendung: 2, richtung: 'offen',
    beleg: 'Evidenz 0, weil es keine Humanstudie gibt und die ClinicalTrials.gov-API zu Sunifiram, DM235 und Unifiram keinen Eintrag liefert; alle Befunde stammen aus Mäusen, Ratten und Hirnschnitten. Mechanismus 4, weil im Tier mehrere Spuren quantifiziert sind – Aufhebung der NBQX-Amnesie und AMPA-abhängige Wirkung in Hippocampus-Schnitten (Galeotti 2003), Verstärkung der Langzeitpotenzierung über die Glycin-Bindestelle des NMDA-Rezeptors mit PKC-alpha und CaMKII (Moriguchi 2013), doppelte Acetylcholin-Freisetzung 45 Minuten nach Gabe (Romanelli 2006) –, diese aber nicht zu einem Bild zusammengeführt und am Menschen nicht bestätigt sind. Sicherheit 1, weil nur Verhaltens- und Motoriktests an Tieren vorliegen, keine veröffentlichte Toxikologie, und der frühere Leiter der Entwicklergruppe die Langzeitgiftigkeit als unbekannt bezeichnet (Gualtieri 2016). Hype 3, weil die Szene aus einer robusten Tierwirkung eine Gedächtnissteigerung für Gesunde macht und die Formel tausendmal stärker als Piracetam die im Tier 1000- bis 10.000-fach niedrigere wirksame Dosis meint, nicht eine stärkere Wirkung; bei gesunden Tieren zeigte sich im Standardtest keine Verbesserung. Anwendung 2, weil Sunifiram nie klinisch entwickelt wurde (Vialko 2025) und nur in Studien und im Graumarkt vorkommt. Richtung offen, weil die Tierdaten konsistent positiv sind, es für den Menschen aber keine Daten gibt.' },
  { id: 'turkesterone', view: 'experimental', evidenz: 3, mechanismus: 4, sicherheit: 2, hype: 2, anwendung: 4, richtung: 'offen',
    beleg: 'Evidenz 3, weil es für Turkesteron selbst nur eine randomisierte Einzeldosis-Studie mit 11 Männern gibt, die auf Surrogatmarker schaut und keinen signifikanten Effekt auf IGF-1, Ruheumsatz oder Stoffwechsel fand (Harris et al., Muscles 2024), und ClinicalTrials.gov keinen Eintrag führt; die Humandaten zum Verwandten Ecdysteron sind uneinheitlich – mehr Muskelmasse und Bankdrückkraft bei 46 Männern über 10 Wochen (Isenmann et al., Arch Toxicol 2019), kein Effekt bei 45 Trainierten über 8 Wochen (Wilborn et al. 2006) – und nicht ohne Weiteres übertragbar. Mechanismus 4, weil die anabole Wirkung der Substanzklasse in Rattenmuskel und Zellkultur gut gezeigt ist (Parr et al. 2015, 5 mg/kg über 21 Tage), für Turkesteron aber nur sowjetische Rattendaten ab 1976 vorliegen und weder Zielstruktur noch Aufnahme beim Menschen bestätigt sind. Sicherheit 2, weil Turkesteron nur als Einzeldosis untersucht ist; die kontrollierten Daten über 6 bis 9 Monate stammen vom gereinigten Ecdysteron BIO101 (Fielding et al. 2025, n = 233). Hype 2, weil Turkesteron als natürliches Anabolikum verkauft wird, obwohl Trainingsdaten fehlen und in 4 von 8 US-Produkten kein Turkesteron nachweisbar war (Cohen et al., JAMA Netw Open 2023). Anwendung 4, weil es vor allem in den USA verbreitet als Supplement genutzt wird, ohne dass Gehalt oder Wirkung reguliert geprüft werden; in der EU ist es nicht zugelassen. Richtung offen, weil die Substanzklasse vielversprechend ist, für Turkesteron aber aussagekräftige Humandaten schlicht fehlen.' },
  { id: 'ahk-cu', view: 'experimental', evidenz: 1, mechanismus: 4, sicherheit: 2, hype: 3, anwendung: 4, richtung: 'offen',
    beleg: 'Evidenz 1, weil es keine Anwendung am Menschen gibt: Die Abfrage der ClinicalTrials.gov-API am 27.09.2026 liefert zu AHK-Cu 0 Einträge, und eine Suche in Europe PMC ergibt 5 Arbeiten, von denen nur eine AHK-Cu selbst untersucht hat — Pyo et al. 2007 mit isolierten menschlichen Haarfollikeln in Organkultur und kultivierten Haarpapillenzellen. Dieses menschliche Gewebe ist mehr als Zellkultur aus der Maus, bleibt aber ex vivo. Mechanismus 4, weil die Kupferseite am Menschen unstrittig ist — Kupfer ist Cofaktor von Lysyloxidase, Superoxiddismutasen, Cytochrom-c-Oxidase und Coeruloplasmin — die Wirkkette von AHK-Cu selbst aber nur in Kultur gezeigt wurde und die Übersicht 2026 ausdrücklich festhält, dass sein Signalweg schlechter charakterisiert ist als der von GHK-Cu; der vorgeschlagene Apoptoseschutz war in der Originalarbeit nicht statistisch signifikant, belegt sind Follikelverlängerung und Zellteilung bei 10 hoch -12 bis 10 hoch -9 Mol pro Liter. Sicherheit 2, weil zu AHK-Cu selbst keine systematische Untersuchung am Menschen vorliegt und sich Aussagen nur von der Kupferseite ableiten lassen: empfohlene Zufuhr 900 Mikrogramm pro Tag, obere Aufnahmemenge 10 Milligramm pro Tag, nach EFSA keine Anreicherung bei 5 Milligramm pro Tag und eine akzeptable tägliche Aufnahme von 0,07 Milligramm pro Kilogramm Körpergewicht; bei Morbus Wilson und Kupferallergie ist der Stoff nichts. Hype 3, weil aus einem einzigen Organkulturbefund von 2007 ein Haarwuchspeptid geworden ist und Zahlen schon ungenau weiterwandern: Die Übersicht 2026 gibt für dieselbe Arbeit 10 hoch -13 bis 10 hoch -7 Mol pro Liter an. Anwendung 4, weil AHK-Cu nach Anbieterangaben als kosmetischer Rohstoff für Seren und Kopfhautpflege im Handel ist und zusätzlich als Forschungspeptid für den Selbstversuch verkauft wird, ohne arzneimittelrechtlichen Rahmen und ohne Wirksamkeitsprüfung. Richtung offen: Der einzige tragende Befund zeigt in eine günstige Richtung, ist aber nicht am Menschen geprüft und nicht bestätigt; beim besser untersuchten Schwesterpeptid GHK liegt immerhin eine Studie an 45 Männern über 6 Monate vor, dort mit einer Haarzahlzunahme von 52,6 und 71,5 gegenüber 9,6 unter Placebo — allerdings mit einem Kombinationspräparat und nicht mit AHK-Cu.' },
  { id: 'bam15', view: 'experimental', evidenz: 1, mechanismus: 5, sicherheit: 1, hype: 3, anwendung: 3, richtung: 'offen',
    beleg: 'Evidenz 1, weil es keine Humanstudie gibt: Die Abfrage der ClinicalTrials.gov-API am 27.09.2026 liefert zu BAM15 0 einschlägige Einträge und zu „mitochondrial uncoupler" 0 Einträge, belegt ist nur Zellkultur samt menschlicher Zellen sowie Nager und Taufliege. Dafür ist diese Tierdatenlage ungewöhnlich stark und von mehreren Gruppen unabhängig bestätigt: 15 Prozent weniger Körpergewicht bei gleicher Kalorienaufnahme über 5 Wochen (Alexopoulos et al., Nat Commun 2020), 7,5 Gramm Unterschied an Tag 20 mit höherem Energieumsatz und unveränderter Körpertemperatur (Axelrod et al., EMBO Mol Med 2020) und im direkten Vergleich von 15 Entkopplern über 4 Wochen HbA1c zurück auf die 4 Prozent der gesunden db/+-Tiere, während die Kontrolle von 6 auf 8 Prozent stieg (Shah et al., Mol Metab 2025). Mechanismus 5, weil die Wirkkette in Zellen quantifiziert und plausibel ist — Protonentransport an der ATP-Synthase vorbei, kein Depolarisieren der Plasmamembran, AMPK-Abhängigkeit — der Zusammenhang zwischen Entkopplung und Gewichtsverlust beim Menschen aber nur historisch über die Vergiftungsdaten zu 2,4-Dinitrophenol bekannt ist und für BAM15 selbst am Menschen nichts gemessen wurde. Sicherheit 1, weil am Menschen nichts systematisch untersucht ist: keine Toxikologie, keine Pharmakokinetik, keine Fallserie; die unauffälligen Leber- und Nierenmarker und die stabile Körpertemperatur stammen aus Mäusen, und in der Klasse zeigt die Tiertoxikologie von OPC-163493 je nach Art Leber, Gefäße oder Niere als Zielorgan (Inoue et al. 2022). Hype 3, weil die Vermarktung echte Mauszahlen ohne das Wort Maus weiterreicht und aus dem Vergleich mit 2,4-Dinitrophenol ein sicheres DNP macht: Belegt ist nur, dass BAM15 in Zellen die Plasmamembran nicht depolarisiert und in Mäusen die Körpertemperatur nicht anhob, während die Fallliteratur zu 2,4-Dinitrophenol Todesfälle und eine funktionelle Halbwertszeit der Entkopplung von 4,9 Tagen beschreibt (Lindeman et al. 2026). Anwendung 3, weil die Substanz außerhalb von Studien nur in der Szene vorkommt, dort aber dokumentiert: Eine Netnographie zweier großer Bodybuilding-Foren samt YouTube-Anleitung zur Eigensynthese zeigt Nachahmungsabsicht trotz fehlender klinischer Daten (Turnock und Piatkowski, Performance Enhancement & Health 2025). Richtung offen: Die Tierdaten zeigen über Organe, Modelle und Arbeitsgruppen hinweg in dieselbe Richtung, aber die Frage, ob pharmakologische Entkopplung beim Menschen mit vertretbarem Abstand zur Toxizität wirkt, ist weder beantwortet noch widerlegt.' },
  { id: 'boswellia', view: 'supplement', evidenz: 6, mechanismus: 5, sicherheit: 6, hype: 5, anwendung: 7, richtung: 'positiv',
    beleg: 'Evidenz 6, weil mehrere doppelblinde RCTs und Meta-Analysen einen Nutzen bei Kniearthrose zeigen – Cochrane 2014 mit hoher Evidenzqualität für 100 mg angereicherten Extrakt über 90 Tage (2 Studien, 85 Teilnehmende, Schmerz -17 Punkte auf 100), Yu 2020 mit 7 RCTs und 545 Patienten, Zhang 2025 als Netzwerk-Meta-Analyse –, die Studien aber klein, kurz und teils herstellernah sind (AkdÄ 2017), Bannuru 2018 die Qualität insgesamt niedrig nennt und Dalmonte 2024 wegen Heterogenität insgesamt keinen signifikanten Effekt fand. Mechanismus 5, weil die Hemmung der 5-Lipoxygenase und der mPGES-1 im Labor und im menschlichen Vollblut gut beschrieben ist (Siemoneit 2011, IC50 3 bis 10 µM), die Plasmaspiegel am Menschen aber oft unter diesen Konzentrationen liegen (Abdel-Tawab 2021) und eine Zielstruktur-Hemmung im Körper nicht gemessen ist. Sicherheit 6, weil kontrollierte Daten bis 52 Wochen ohne Nachteile gegenüber Placebo vorliegen (Holtmeier 2011) und LiverTox Leberschäden für unwahrscheinlich hält (Likelihood score E), eine Pharmakovigilanz wie bei Arzneimitteln aber fehlt. Hype 5, weil Weihrauch oft als natürliche Alternative zu Schmerzmitteln beworben wird, obwohl kein RCT gegen zugelassene NSAR vorliegt und viele Produkte nicht der Deklaration entsprechen (Meins 2016: 41 %). Anwendung 7, weil Weihrauch traditionell im Ayurveda und seit Jahren breit als Nahrungsergänzung genutzt wird, ohne als Arzneimittel zugelassen zu sein. Richtung positiv: Bei Arthrose zeigen die Daten überwiegend in eine Richtung, beim Remissionserhalt von Morbus Crohn blieb ein Effekt aus.' },
  { id: 'maca', view: 'supplement', evidenz: 5, mechanismus: 3, sicherheit: 5, hype: 4, anwendung: 7, richtung: 'positiv',
    beleg: 'Mehrere kleine doppelblinde RCTs zeigen positive Effekte auf subjektive Endpunkte: mehr sexuelles Verlangen bei gesunden Männern ab Woche 8 (Gonzales 2002, 1,5 oder 3,0 g, 12 Wochen), IIEF-5 +1,6 vs. +0,5 bei leichter Erektionsstörung (Zenico 2009, n = 50) und bessere Stimmung und Energie (Gonzales-Arimborgo 2016, n = 175). Systematische Übersichten werten das als begrenzte Evidenz (Shin 2010: 4 RCTs; Lee 2011: 4 RCTs zu Wechseljahren), eine Meta-Analyse 2026 zu Erektionsstörung als unzureichend. Bei der Spermienqualität zeigt die Meta-Analyse von 5 RCTs keinen gesicherten Effekt (Lee 2022). Der Mechanismus ist am Menschen offen: Reproduktionshormone blieben in allen Humanstudien unverändert, die FAAH-Hemmung durch Macamide stammt aus Labor und Tier. Die Sicherheitsdaten reichen nur über 12 bis 16 Wochen; das BfR konnte 2007 keine unbedenkliche Verzehrsmenge ableiten. Die verbreitete Vorstellung von Maca als Testosteron-Booster deckt sich nicht mit den Humandaten.' },
  { id: 'modafinil', view: 'experimental', evidenz: 8, mechanismus: 8, sicherheit: 9, hype: 4, anwendung: 9, richtung: 'positiv',
    beleg: 'Evidenz 8, weil die wachheitsfördernde Wirkung in großen doppelblinden RCTs mit objektiven Endpunkten belegt ist – Narkolepsie mit 283 und 271 Patienten (1998, 2000), Schichtarbeitsstörung mit 209 Patienten und weniger Unfällen auf dem Heimweg, 29 % gegenüber 54 % (Czeisler, NEJM 2005) –, für die im Biohacking gesuchte Leistungssteigerung bei Ausgeruhten aber nur ein kleiner Effekt aus Einzeldosis-Studien vorliegt (g = 0,10 über 19 Studien, Kredlow 2019); die 10 bliebe der zugelassenen Indikation Narkolepsie vorbehalten. Mechanismus 8, weil die Zielstruktur am Menschen quantifiziert ist: Im PET belegte Modafinil 53,8 % der Dopamintransporter im Nucleus caudatus und erhöhte Dopamin im Nucleus accumbens (Volkow, JAMA 2009), der Weg von dort zur kognitiven Wirkung aber nicht im Detail gemessen ist. Sicherheit 9, weil Langzeitdaten aus Zulassung und Pharmakovigilanz seit 1998 vorliegen und die EMA 2011 das Nutzen-Risiko-Profil umfassend geprüft hat (Hautreaktionen, psychiatrische und kardiovaskuläre Risiken); offen bleiben Daten zur Schwangerschaft und zur Dauereinnahme durch Gesunde. Hype 4, weil Modafinil als Smart Drug für mehr Intelligenz und Produktivität gilt, während die Meta-Analysen bei Ausgeruhten nur kleine Effekte zeigen und Repantis 2010 schreibt, dass die Erwartungen die tatsächlichen Effekte übersteigen. Anwendung 9, weil es seit 1998 in den USA und in Deutschland 2008 bereits zehn Jahre auf dem Markt war, jeweils unter ärztlicher Verordnung. Richtung positiv: Die Wirkung auf Wachheit ist klar belegt, die auf Kognition bei Gesunden klein, aber gleichgerichtet.' },
  { id: 'pregnenolon', view: 'experimental', evidenz: 5, mechanismus: 6, sicherheit: 4, hype: 3, anwendung: 5, richtung: 'gemischt',
    beleg: 'Evidenz 5, weil es zwar gut ein Dutzend kleine randomisierte Studien gibt, diese aber fast nur als Zusatztherapie bei psychiatrischen Diagnosen oder Schmerz laufen, mit 18 bis 120 Teilnehmenden und höchstens 12 Wochen, und uneinheitlich ausfallen: Kreuzschmerz -0,56 Punkte gegenüber Placebo (Naylor et al. 2020, 94 Veteranen), Negativsymptome d = 0,79 (Ritsner et al. 2014, 60 Patienten), aber kein Kognitionseffekt in der größten Studie (Marx et al. 2014, 120 Teilnehmende) und kein Gesamteffekt bei Schizophrenie in der Meta-Analyse (Heringa et al. 2015, k = 4); zu den populären Anwendungen bei Gesunden gibt es keine Studie. Mechanismus 6, weil beim Menschen der Anstieg von Pregnenolon, Allopregnanolon und Pregnenolonsulfat im Serum und eine Hirnwirkung im fMRT gemessen sind (Sripada et al. 2013), die NMDA- und CB1-Spur aber aus Tierdaten stammt (Vallée et al. 2014). Sicherheit 4, weil alle kontrollierten Daten bis 500 mg pro Tag gut verträglich waren, aber nur bis 12 Wochen reichen und die hormonelle Weiterverarbeitung bei Dauereinnahme nicht systematisch gemessen ist. Hype 3, weil das Mutterhormon als Gedächtnis- und Anti-Aging-Mittel verkauft wird, gestützt auf Mausversuche mit Injektion ins Gehirn (Flood et al. 1992), während die Humandaten aus ganz anderen Anwendungen kommen. Anwendung 5, weil Pregnenolon seit Jahren breit als Nahrungsergänzung verkauft wird, ohne dass Behörden in Deutschland oder den USA seinen Status geklärt haben. Richtung gemischt: positive Einzelstudien zu Schmerz, Negativsymptomen und bipolarer Depression, neutrale Ergebnisse bei Kognition und in der Meta-Analyse.' },
  { id: 'sam-e', view: 'experimental', evidenz: 6, mechanismus: 6, sicherheit: 7, hype: 6, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz 6, weil es viele randomisierte Studien gibt, die aber meist klein und kurz sind und sich widersprechen: SMD -0,58 gegenüber Placebo in der Meta-Analyse mit 23 RCTs und 2183 Teilnehmenden (Limveeraprajak et al. 2024), dagegen kein klarer Unterschied im Cochrane-Review mit 8 Studien und 934 Erwachsenen (Galizia et al. 2016) und kein Placebo-Vorteil in der größten modernen Studie mit 189 Patienten (Mischoulon et al. 2014); bei Arthrose nur 0,4 cm auf einer 10-cm-Skala bei schlechter Studienqualität (Rutjes et al. 2009), bei alkoholischer Zirrhose primärer Endpunkt verfehlt (Mato et al. 1999, 123 Patienten, p = 0,077). Mechanismus 6, weil die Rolle als Methylgruppen-Spender und Glutathion-Vorstufe biochemisch gesichert und der SAM-e-Mangel bei chronischer Lebererkrankung beim Menschen gemessen ist (Lu & Mato 2012), der Wirkweg gegen Depression aber offen bleibt. Sicherheit 7, weil kontrollierte Daten über 2 Jahre ohne schwere Nebenwirkungen vorliegen und es in Italien als Arzneimittel mit Fachinformation zugelassen ist, öffentlich greifbare Langzeit-Pharmakovigilanz aber fehlt; bekannte Risiken sind Manie bei bipolarer Störung und serotonerge Wechselwirkungen. Hype 6, weil die Vermarktung als natürliches Antidepressivum und Gelenkmittel überwiegend auf echten Studien fußt, die Unsicherheit beim Placebo-Vergleich aber meist verschwiegen wird. Anwendung 7, weil SAM-e in Italien als verschreibungspflichtiges Arzneimittel reguliert eingesetzt und in den USA seit Jahren breit als Nahrungsergänzung verkauft wird. Richtung gemischt: positive Meta-Analyse und SSRI-Zusatzstudie, neutrale Ergebnisse im Cochrane-Review, in der größten Depressionsstudie und bei Zirrhose.' },
  { id: 'tart-cherry', view: 'supplement', evidenz: 6, mechanismus: 5, sicherheit: 6, hype: 5, anwendung: 8, richtung: 'positiv',
    beleg: 'Für die Regeneration liegt eine Meta-Analyse aus 19 Studien vor: Die Maximalkraft erholte sich nach 24 h (Effektstärke 1,12) und 48 h (1,29) besser, CRP sank bis 48 h, Muskelkater und CK blieben unverändert; die Evidenzsicherheit ist sehr niedrig bis moderat bei hoher Heterogenität (Daab 2026). Für die Ausdauerleistung fanden Gao und Chilibeck 2020 in 10 RCTs einen kleinen, einheitlichen Vorteil (SMD 0,36). Beim Schlaf stiegen bei 20 Gesunden Melatonin und Schlafzeit (Howatson 2012), bei Insomnie gibt es nur Pilotstudien mit 15 bzw. 8 Auswertbaren, und 500 mg Kapseln blieben bei 34 Übergewichtigen ohne Effekt (Tucker 2024). Bei Gicht verfehlte die RCT mit 50 Patienten jede Harnsäuresenkung (Stamp 2020); die Meta-Analyse aus 4 RCTs zeigt nur SMD -0,22. Mechanistisch sind Phenolsäuren im Blut und Melatonin im Urin am Menschen gemessen, die COX-Hemmung stammt aus dem Labor. Über 3 Monate mit 30 mL zweimal täglich blieb das Konzentrat ohne nachteilige Effekte (Kimble 2021, n = 50).' },
  { id: 'teriparatid', view: 'experimental', evidenz: 9, mechanismus: 9, sicherheit: 9, hype: 7, anwendung: 8, richtung: 'positiv',
    beleg: 'Evidenz 9: Zwei große doppelblinde Studien mit Bruchendpunkten tragen die Zulassung, die Zulassungsstudie mit 1637 Frauen (neue Wirbelbrüche 5 gegenüber 14 Prozent) und VERO mit 1360 Frauen, in der Teriparatid Risedronat schlug (5,4 gegenüber 12,0 Prozent); dazu der Vorteil gegenüber Alendronat bei Kortison-Osteoporose. Die volle 10 gibt es nicht, weil ein Schutz vor Hüftbrüchen nicht nachgewiesen ist, bei Männern nur die Knochendichte belegt ist und die erhoffte Heilungsbeschleunigung in randomisierten Studien nicht bestätigt wurde (Speichenbruch, Schenkelhals, Rotatorenmanschette; Meta-Analyse von 5 RCTs mit 380 Patienten). Mechanismus 9: Zielrezeptor, Kalziumverlauf, Knochendichte und Bruchrate sind am Menschen gemessen. Sicherheit 9: kontrollierte Daten aus der Zulassung, Marktbeobachtung seit 2003 und eine 15-jährige US-Überwachung ohne erhöhtes Osteosarkom-Risiko (3 beobachtete gegenüber 4,17 erwarteten Fällen); offen bleiben Daten jenseits von 2 Jahren. Hype 7, weil das Mittel bei Osteoporose auf Höhe der Daten kommuniziert wird, die Erwartung an schnellere Heilung von Knochen und Sehnen aber über die Daten hinausgeht. Anwendung 8: seit 2003 in der EU unter ärztlicher Aufsicht, inzwischen mit mehreren Biosimilars.' },
  { id: 'acth', view: 'experimental', evidenz: 7, mechanismus: 9, sicherheit: 9, hype: 5, anwendung: 9, richtung: 'gemischt',
    beleg: 'Evidenz 7, weil ACTH für seine Kernanwendungen in RCTs und Meta-Analysen belegt ist – infantile Spasmen mit 73 % gegenüber 54 % Anfallsfreiheit unter Hormontherapie (UKISS, 107 Säuglinge, 2004), MS-Schub mit OR 0,37 (Cochrane 2000, 6 RCTs, 377 Teilnehmer), ACTH-Test mit 30 Studien und 1.209 Erwachsenen (Ospina 2016) –, die Studien aber klein und methodisch oft schwach sind (Cochrane 2013) und hochdosiertes Prednisolon gleich gut abschneidet (5 RCTs, 239 Kinder, 2019); für die im Biohacking denkbare Nutzung bei Gesunden gibt es nur eine Studie mit 8 Radfahrern ohne Effekt (Baume 2008). Mechanismus 9, weil die Wirkkette vom Rezeptor der Nebennierenrinde über cAMP bis zum Cortisolanstieg am Menschen so genau vermessen ist, dass sie 30 Minuten nach Injektion als Diagnostikum dient; nicht quantifiziert ist die steroidunabhängige Melanocortin-Wirkung. Sicherheit 9, weil Pharmakovigilanz seit 1952 (USA) und 1965 (Deutschland) vorliegt und die Fachinformationen das Risikoprofil einer Kortisontherapie plus Anaphylaxie klar beschreiben; hohe Zahl heißt gut untersucht, nicht harmlos. Hype 5, weil die zugelassenen Anwendungen sachlich kommuniziert werden, Acthar in den USA aber trotz wenig Belegen für einen Vorteil gegenüber Kortikosteroiden breit verordnet wurde, bei 88 % der Vielverordner mit Herstellerzahlungen (Hartung 2018), und der Ruf als Leistungsmittel im Sport auf Anekdoten beruht. Anwendung 9, weil ACTH seit Jahrzehnten unter ärztlicher Aufsicht eingesetzt wird. Richtung gemischt: klar positiv für Diagnostik, infantile Spasmen und MS-Schub, ohne Beleg und mit einem Nullbefund für Leistungssteigerung bei Gesunden.' },
  { id: 'anabole-steroide', view: 'experimental', evidenz: 7, mechanismus: 9, sicherheit: 6, hype: 4, anwendung: 6, richtung: 'gemischt',
    beleg: 'Evidenz 7, weil die Muskelwirkung randomisiert belegt ist (Bhasin et al. 1996, 43 Männer, 10 Wochen, +6,1 kg fettfreie Masse mit Training) und einzelne Wirkstoffe für medizinische Indikationen zugelassen sind, es für die Anwendung ohne Indikation aber nur kleine und kurze kontrollierte Studien gibt. Mechanismus 9, weil Androgenrezeptor, Eiweißaufbau und die Abschaltung der Hormonachse am Menschen genau vermessen sind. Sicherheit 6, weil große Registerkohorten mit langer Nachbeobachtung vorliegen (Windfeld-Mathiasen et al. 2024 und 2025: 1189 Anwender gegen 59450 Kontrollen, 11,2 Jahre, Sterblichkeit HR 2,81, Kardiomyopathie aHR 8,90), dazu prospektive Daten über 1 Jahr (HAARLEM, 100 Männer) und Querschnittsstudien zu Herz und Hormonachse, aber keine randomisierten Langzeitdaten und kaum Daten zu Frauen. Hype 4, weil die Muskelwirkung real ist, die Risiken in der Szene aber systematisch unterschätzt werden – die Endocrine Society spricht ausdrücklich von einer verbreiteten Fehleinschätzung, die Anwendung sei sicher oder beherrschbar (Pope et al. 2014). Anwendung 6, weil Testosteron seit Jahrzehnten ärztlich reguliert eingesetzt wird, die nichtmedizinische Anwendung aber bei geschätzt 3,3 % der Weltbevölkerung ohne Aufsicht stattfindet. Richtung gemischt: Die Muskelwirkung ist unbestritten, doch die Daten zeigen bei der Anwendung ohne ärztliche Indikation ein klar erhöhtes Sterbe- und Herzrisiko und bleibende Hormonschäden bei einem Teil der Anwender (27,2 % unter dem Referenzwert Jahre nach dem Aufhören, Rasmussen et al. 2016).' },
  { id: 'benfotiamin', view: 'experimental', evidenz: 6, mechanismus: 5, sicherheit: 7, hype: 5, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz 6, weil mehrere randomisierte Studien vorliegen, die aber klein oder kurz sind und sich widersprechen: Kurzstudien zur diabetischen Polyneuropathie zeigen weniger Beschwerden (BENDIP, 133 Ausgewertete, 6 Wochen, NSS per Protokoll p = 0,033, ITT p = 0,055; BEDIP, 40 Patienten, 3 Wochen), die langen Studien mit objektiven Endpunkten fanden keinen Effekt (BOND, 57 Teilnehmende, 12 Monate; Fraser 2012, 67 Teilnehmende, 24 Monate). Mechanismus 5, weil die Transketolase-Aktivierung und die Blockade von drei Schadenswegen nur im Tier gezeigt sind (Hammes 2003); am Menschen ist der Anstieg von Thiamin im Blut gut gemessen, die Senkung von AGEs aber in einer RCT mit 82 Patienten nicht bestätigt (Alkhalaf 2012). Sicherheit 7, weil kontrollierte Daten bis 24 Monate ohne relevante Unterschiede zu Placebo vorliegen und es in Deutschland als Arzneimittel mit Fachtext zugelassen ist; die EFSA fand 2008 aber keine ausreichenden Studien zu Fortpflanzung, Erbgut und Langzeittoxizität. Hype 5, weil die Vermarktung als Glykations- und Anti-Aging-Schutz auf Tierdaten fußt, während der Nutzen bei Neuropathie-Beschwerden echt, aber kurzfristig belegt ist. Anwendung 7, weil Benfotiamin seit vielen Jahren in Deutschland als Arzneimittel reguliert eingesetzt wird, frühe Studien mit Präparaten stammen von 1996 und 1999. Richtung gemischt: positive Kurzstudien und ein Alzheimer-Signal (CDR p = 0,034) gegen neutrale Langzeitstudien.' },
  { id: 'cbd', view: 'experimental', evidenz: 7, mechanismus: 6, sicherheit: 7, hype: 4, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz 7, weil drei große doppelblinde RCTs mit 120, 171 und 225 Patienten die Wirkung bei Dravet- und Lennox-Gastaut-Syndrom belegen (Devinsky 2017, Thiele 2018, Devinsky 2018) und die Zulassung tragen, für die typischen Biohacking-Anwendungen aber nur kleine, uneinheitliche Studien vorliegen: Angst positiv in einer Meta-Analyse mit 316 Teilnehmenden (Han 2024), aber ohne Nutzen als Zusatz zur Expositionstherapie (Kwee 2022, 80 Patienten), bei Fibromyalgie schlechter als Placebo (Rasmussen 2026, 200 Patienten), beim Schlaf nur 2 von 34 Studien an Menschen mit Insomnie (Ranum 2023); die 10 bliebe der zugelassenen Indikation vorbehalten. Mechanismus 6, weil am Menschen der Anstieg von Anandamid gemessen ist (Leweke 2012), die EMA den genauen Wirkmechanismus aber als unbekannt einstuft. Sicherheit 7, weil kontrollierte Daten aus der Zulassung und eine FDA-Studie an 201 Gesunden vorliegen (5,6 % Leberwerte über dem 3-Fachen, Florian 2025), die EFSA 2026 für Langzeitgebrauch in Lebensmitteln aber weiter Datenlücken sieht und nur etwa 2 mg pro Tag vorläufig als sicher einstuft. Hype 4, weil CBD-Öle für Stress, Schlaf und Schmerz vermarktet werden, wofür das BfR keine ausreichenden Belege sieht, und die Epilepsiedaten mit hohen Studiendosen oft auf den Alltag übertragen werden. Anwendung 7, weil CBD seit Jahren breit ohne Lebensmittelzulassung verkauft wird und zugleich als Arzneimittel in EU und USA reguliert ist. Richtung gemischt: klar positiv bei Epilepsie, uneinheitlich bei Angst und Schmerz, kaum untersucht beim Schlaf.' },
  { id: 'clenbuterol', view: 'experimental', evidenz: 4, mechanismus: 7, sicherheit: 4, hype: 2, anwendung: 5, richtung: 'negativ',
    beleg: 'Evidenz 4, weil es für die Szene-Anwendung nur zwei kleine, kurze randomisierte Studien gibt: 11 gesunde Männer über 2 Wochen (Hostrup et al. 2025, +0,91 kg Magermasse, kein Effekt auf die Fettmasse) und 14 Übergewichtige über 4 Wochen (Van Lier et al. 2026, Gewicht und Fettmasse unverändert); die Zulassung betrifft Asthma, nicht Muskelaufbau oder Abnehmen. Mechanismus 7, weil die Beta-2-Signalkette im menschlichen Muskel per Biopsie nachgewiesen ist, einschließlich der Toleranz innerhalb von 2 Wochen, der Fettabbau aus der Tiermast (Mersmann 1998) sich beim Menschen aber nicht bestätigt hat. Sicherheit 4, weil es für die therapeutische Anwendung eine Zulassung seit 1988 gibt, für die missbräuchliche Nutzung aber nur Giftnotruf-Serien (Brett et al. 2014: 63 Expositionen, 84 % stationär) und Fallberichte bis zum Herzinfarkt; die Fachinformation berichtet tödliche Verläufe bei Missbrauch. Hype 2, weil der zentrale Fatburner-Anspruch in beiden randomisierten Humanstudien nicht hielt und die Leistung sogar sank (maximale Sauerstoffaufnahme −7 %). Anwendung 5, weil Clenbuterol ärztlich reguliert nur als Asthma-Mittel in einzelnen Ländern eingesetzt wird, im Sport- und Abnehmbereich aber seit Jahrzehnten ohne Aufsicht verbreitet ist. Richtung negativ für die Anwendung ohne Indikation: Die Daten sprechen gegen den beworbenen Fettabbau und gegen einen Leistungsnutzen, bei dokumentierten schweren Herz- und Stoffwechselrisiken.' },
  { id: 'dnp', view: 'experimental', evidenz: 3, mechanismus: 8, sicherheit: 3, hype: 2, anwendung: 4, richtung: 'negativ',
    beleg: 'Evidenz 3, weil die Wirkung von DNP selbst am Menschen nur aus unkontrollierter Anwendung der 1930er Jahre stammt (bis zu 1,5 kg pro Woche, Übersicht Grundlingh et al. 2011); kontrollierte Daten gibt es nur für die nicht zugelassene Vorstufe HU6, etwa minus 2,86 kg gegenüber Placebo über 19 Wochen bei 66 Teilnehmenden (Pandey et al. 2025) und relativ minus 26,8 bis minus 35,6 Prozent Leberfett nach 61 Tagen bei 80 Teilnehmenden (Noureddin et al. 2023). Mechanismus 8, weil die Entkopplung der Atmungskette seit Jahrzehnten verstanden ist und am Menschen gemessen wurde, zuletzt an Blutplättchen zweier Vergifteter mit einer funktionellen Halbwertszeit von 4,9 Tagen (Lindeman et al. 2026). Sicherheit 3, weil es keine kontrollierten Sicherheitsdaten zu DNP gibt; bekannt ist die Toxizität aus Giftnotruf-Serien, die aber groß und in sich stimmig sind: 17 Prozent tödlich in Großbritannien 2007 bis 2013 (Kamour et al. 2015), 11,6 und 16,9 Prozent in USA und Großbritannien bei 204 Fällen (Potts et al. 2021), 11,9 Prozent bei 456 Fällen aus 38 Ländern (Gziut und Thomas 2022). Hype 2, weil DNP als Fettverbrenner verkauft wird, während die Risiken laut Verbraucherzentrale in der Werbung häufig verharmlost werden und das BfR von nicht deklariertem DNP in Produkten berichtet. Anwendung 4, weil DNP seit den frühen 2000er Jahren ohne jeden regulatorischen Rahmen in der Szene genutzt wird, dokumentiert durch steigende Giftnotruf-Zahlen von 4 Fällen 2010 auf 71 im Jahr 2015. Richtung negativ bezieht sich auf die Anwendung außerhalb von Studien: Der Gewichtsverlust ist real, aber es gibt keine anerkannte medizinische Indikation, keine belegte sichere Menge und kein Gegenmittel, und die Fallsterblichkeit liegt in allen Auswertungen im zweistelligen Prozentbereich.' },
  { id: 'epo', view: 'experimental', evidenz: 8, mechanismus: 9, sicherheit: 8, hype: 5, anwendung: 9, richtung: 'gemischt',
    beleg: 'Evidenz 8, weil die zugelassene Wirkung auf Blutarmut und Transfusionsbedarf in großen RCTs und Meta-Analysen gesichert ist (TREAT mit 4038 Patienten, Pfeffer et al. 2009; Cochrane-Review mit 91 Studien und 20.102 Teilnehmenden, Tonia et al. 2012), während die Leistungsfrage bei Gesunden nur auf kleinen, kurzen Studien ruht: Im doppelblinden RCT mit 48 Radfahrern stiegen VO2max (60,1 gegen 57,4 ml/min/kg) und Maximalleistung, das Bergrennen auf den Mont Ventoux blieb gleich (Heuberger et al. 2017). Mechanismus 9, weil die Kette vom EPO-Rezeptor über JAK2/STAT5 bis zum gemessenen Anstieg von Hämoglobin am Menschen quantifiziert ist (Chlebowska et al. 2026; Eschbach et al. 1987). Sicherheit 8, weil es jahrzehntelange Pharmakovigilanz und große RCTs mit harten Endpunkten gibt, die klare Risikosignale zeigen, etwa Schlaganfall HR 1,92 in TREAT, Thromboembolien RR 1,52 bei Krebspatienten; für Gesunde ohne Indikation fehlen dagegen bevölkerungsbezogene Daten, es gibt nur Fallberichte und kurze Studien. Hype 5, weil der Ruf als Wundermittel des Ausdauersports auf echten Laboreffekten beruht, die im einzigen kontrollierten Rennen aber nicht ankamen, und weil die Todesfälle von Radprofis um 1990 oft als bewiesen erzählt werden, obwohl sie nur als stark verdächtig gelten (Vecchiato et al. 2026). Anwendung 9, weil EPO seit 1988 unter ärztlicher Aufsicht Standardtherapie der renalen Anämie ist. Richtung gemischt: Die blutbildende Wirkung ist eindeutig und im Labor leistungssteigernd, aber die Wettkampfleistung ist im kontrollierten Rennen nicht belegt, und die Risikodaten sprechen klar gegen eine Anwendung ohne ärztliche Indikation.' },
  { id: 'kh-crystagen', view: 'khavinson', evidenz: 2, mechanismus: 3, sicherheit: 2, hype: 3, anwendung: 3, richtung: 'offen',
    beleg: 'Evidenz 2, weil die einzige Humanstudie eine offene, nicht randomisierte Patientenstudie aus der Patentschrift ist (38 ältere Patienten gegen 32 Kontrollen, 10 Tage, normalisierte Immunwerte bei 82 gegenüber 56 Prozent) und nie in einer Fachzeitschrift erschien; ClinicalTrials.gov führt keine Studie, PubMed unter dem Namen nur 1 Arbeit. Tragend sind daneben Organkulturen aus Thymus und Milz 24 Monate alter Ratten (Wachstumsfläche plus 24 bzw. 28 Prozent) und ein Bestrahlungsmodell der Thymusalterung, beide aus derselben Patentschrift. Mechanismus 3, weil die epigenetische Hypothese der Khavinson-Schule mit Zellbefunden (mehr Lymphozytenteilung, Khavinson et al. 2011) und Computermodellen (DNA-Bindung 2016, Transporter 2022/2023) plausibel gemacht, aber keine Zielstruktur am Menschen bestätigt ist. Sicherheit 2, weil nur Tiertoxikologie aus der Patentschrift (Ratten 90 Tage, Meerschweinchen 6 Monate) und eine 10-tägige Patientenanwendung vorliegen, ohne Pharmakokinetik am Menschen. Hype 3, weil der Verkauf als Immun-Bioregulator auf einer unveröffentlichten Offenstudie ruht und Negativbefunde (keine Zellerneuerung in der alternden Milz 2014, schwächer als Vilon und Thymogen 2019) nicht auftauchen. Anwendung 3, weil Crystagen in Russland als Nahrungsergänzung verkauft wird, im Westen aber nur über den Graumarkt. Die Datenlage stammt aus einer einzigen Forschungslinie; das spricht nicht gegen die Befunde, macht aber eine unabhängige, verblindete Studie zur offenen Aufgabe.' },
  { id: 'laktoferrin', view: 'supplement', evidenz: 6, mechanismus: 4, sicherheit: 7, hype: 5, anwendung: 6, richtung: 'gemischt',
    beleg: 'Evidenz 6, weil mehrere Meta-Analysen randomisierter Studien vorliegen, die Effekte aber auf Kinder beschränkt oder widersprüchlich sind: weniger Atemwegsinfekte mit einer Odds Ratio von 0,57 über 6 RCTs mit 1.194 Teilnehmenden (Ali, Clin Nutr ESPEN 2021), bei Erwachsenen jedoch 1,00 (Berthon, Adv Nutr 2022); weniger späte Sepsis bei Frühgeborenen (Cochrane 2020, RR 0,82, niedrige Evidenzsicherheit), aber kein Effekt in ELFIN mit 2203 Frühgeborenen (Lancet 2019); bei Eisenmangel Gleichwertigkeit in älteren Meta-Analysen, aber Unterlegenheit in der doppelblinden RCT mit 555 Frauen (Huda, J Nutr 2026). Mechanismus 4, weil Eisenbindung und antimikrobielle Wirkung vor allem aus Labor und Tier stammen; am Menschen sinkt IL-6, CRP aber nicht, und oral wird Laktoferrin teilweise verdaut. Sicherheit 7, weil die EFSA 2012 eine Sicherheitsbewertung vorgenommen hat, randomisierte Studien über Wochen bis Monate ohne Nebenwirkungssignal vorliegen und Laktoferrin in Säuglingsnahrung eingesetzt wird. Hype 5, weil Immunstärkung und Eisenersatz für Erwachsene über die Daten hinausgehen. Anwendung 6, weil es seit 2012 in der EU als neuartiges Lebensmittel reguliert und breit verkauft wird. Richtung gemischt: positiv bei Kindern und bei der Verträglichkeit, neutral bei Erwachsenen und uneinheitlich beim Eisen.' },
  { id: 'rotschimmelreis', view: 'supplement', evidenz: 7, mechanismus: 8, sicherheit: 7, hype: 5, anwendung: 7, richtung: 'positiv',
    beleg: 'Evidenz 7, weil die LDL-Senkung in Meta-Analysen konsistent ist (Gerards 2015: 20 randomisierte Studien, -1,02 mmol/l; Trogkanis 2024: 14 doppelblinde Studien) und die CCSPS mit 4.870 Herzinfarkt-Patienten über 4,5 Jahre sogar harte Endpunkte senkte (10,4 auf 5,7 Prozent), diese Daten aber aus einem chinesischen Präparat in einer Dosis stammen, die in der EU nicht mehr erlaubt ist, und für weniger als 3 mg Monacoline pro Tag nur kleine offene Studien mit Kombinationspräparaten vorliegen. Mechanismus 8, weil Monacolin K mit Lovastatin identisch ist und die Hemmung der HMG-CoA-Reduktase mit Senkung des LDL am Menschen belegt ist; die Wirkung der übrigen Monacoline und Inhaltsstoffe ist dagegen wenig untersucht. Sicherheit 7, weil kontrollierte Daten aus 53 RCTs mit 8.535 Teilnehmenden (Fogacci 2019) und einer 4,5-Jahres-Studie vorliegen und zusätzlich Meldesysteme und die Lovastatin-Daten ausgewertet wurden – mit dem Ergebnis, dass EFSA 2018 und 2025 keine sichere Tagesmenge festlegen konnte und Einzelfälle schwerer Nebenwirkungen schon ab 3 mg pro Tag beschreibt. Hype 5, weil Rotschimmelreis oft als natürliche Alternative zu Statinen beworben wird, obwohl er selbst ein Statin enthält, und die in der EU verkaufte Menge weit unter den Studiendosen liegt. Anwendung 7, weil er in Ostasien seit mehr als tausend Jahren genutzt und in Europa seit Jahren reguliert als Nahrungsergänzung verkauft wird. Richtung positiv: Die Daten zur Cholesterinsenkung zeigen klar in eine Richtung; die Einschränkungen betreffen Sicherheit, Dosis und Rechtslage.' },
  { id: 'saegepalme', view: 'supplement', evidenz: 7, mechanismus: 4, sicherheit: 8, hype: 4, anwendung: 8, richtung: 'gemischt',
    beleg: 'Evidenz 7, weil es viele RCTs gibt, auch große (CAMUS 369 Männer über 72 Wochen, STEP 225 Männer über 1 Jahr, PERMAL 704 Männer über 12 Monate), die Ergebnisse aber uneinheitlich sind: Der Cochrane-Review 2023 mit 27 Studien und 4.656 Teilnehmern fand für Sägepalme allein nur -0,90 Punkte im IPSS und damit kaum einen Unterschied zu Placebo (hohe Vertrauenswürdigkeit), während die herstellernahe Meta-Analyse zum Hexan-Extrakt (Vela-Navarrete 2018, 5.800 Patienten) weniger Nykturie und besseren Harnfluss zeigt. Mechanismus 4, weil 5-Alpha-Reduktase-Hemmung und antiandrogene Effekte vor allem im Labor beschrieben sind, die EMA den Wirkmechanismus als unbekannt bezeichnet und der PSA-Wert selbst bei 960 mg pro Tag unverändert bleibt (Andriole 2013). Sicherheit 8, weil kontrollierte Daten bis 72 Wochen, eine systematische Übersicht über 40 Arbeiten (Agbabiaka 2009) und jahrzehntelange Erfahrung als zugelassenes pflanzliches Arzneimittel mit EU-Monografie vorliegen; Nebenwirkungen waren nicht häufiger als unter Placebo (RR 1,01). Hype 4, weil Sägepalme als pflanzliche Prostata- und Haarlösung beworben wird, obwohl die unabhängigen Studien bei den Prostatabeschwerden kaum Effekte zeigen und die Haar-Daten auf wenigen kleinen Studien beruhen. Anwendung 8, weil Sägepalmenfrüchte seit Jahrzehnten unter Arzneimittelaufsicht genutzt werden (Kommission E 1989, EU-Monografie 2016). Richtung gemischt: Ein bestimmter Extrakt zeigt positive Ergebnisse, die unabhängigen Placebo-Studien und Cochrane sprechen gegen einen spürbaren Effekt.' },
  { id: 'telmisartan', view: 'experimental', evidenz: 7, mechanismus: 6, sicherheit: 9, hype: 5, anwendung: 9, richtung: 'gemischt',
    beleg: 'Evidenz 7: Für die zugelassene Indikation ist Telmisartan mit harten Endpunkten belegt, etwa gleichwertig zu Ramipril in ONTARGET mit 25.620 Patienten über median 56 Monate (NEJM 2008); für die im Biohacking gesuchte Wirkung auf Stoffwechsel und Alterung gibt es aber nur Meta-Analysen mit Surrogatmarkern (HOMA-IR -15,34 % in 8 doppelblinden Studien, Takagi 2014; viszerales Fett -18,13 cm², Choi 2016), während harte Endpunkte ausblieben: neuer Diabetes in PRoFESS 1,7 % gegenüber 2,1 % nicht signifikant, keine bessere Gehstrecke in TELEX (JAMA 2022), kein Schutz der Kognition. Mechanismus 6, weil die AT1-Blockade am Menschen quantifiziert ist, die PPAR-gamma-Wirkung aber vor allem aus Zellen und Ratten (Benson 2004) und am Menschen nur indirekt und aus einer Biopsie-Substudie mit 13 Teilnehmenden stammt. Sicherheit 9, weil Zulassung seit 1998, Endpunktstudien über 56 Monate und Pharmakovigilanz vorliegen und das Krebssignal von 2010 in der Auswertung von 138.769 Teilnehmenden nicht bestätigt wurde; offen sind Daten zu Gesunden mit normalem Blutdruck. Hype 5, weil aus Tierdaten ein Longevity-Mittel gemacht wird, obwohl die Kombination mit Atorvastatin im Lebensdauerprogramm ITP die Lebensdauer von Mäusen nicht verlängerte (Geroscience 2026). Anwendung 9, weil es seit 1998 jahrzehntelang unter ärztlicher Aufsicht eingesetzt wird. Richtung gemischt: positiv bei Blutdruck, Herz-Kreislauf-Schutz und Stoffwechselmarkern, neutral bei Diabetes, Kognition, Leistung und Lebensdauer.' },
  { id: 'vinpocetin', view: 'experimental', evidenz: 5, mechanismus: 5, sicherheit: 6, hype: 3, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz 5, weil es zwar mehrere RCTs gibt, diese aber klein, alt oder offen sind: Beim akuten Schlaganfall ist die Meta-Analyse von Panda et al. 2022 mit 4 RCTs (601 gegen 236 Patienten, RR 0,67 nach 3 Monaten) positiv, der Cochrane-Review 2008 mit 2 Studien und 70 Teilnehmenden ohne Aussage; bei Demenz fand Cochrane 2003 mit 3 RCTs und 583 Patienten nur nicht schlüssige Vorteile, und für Gesunde fehlen belastbare Daten (Meador 2021: 8 Gesunde ohne Effekt). Mechanismus 5, weil PDE1-Hemmung, Natriumkanal-Blockade und IKK-Hemmung aus Zellkultur und Tier stammen und am Menschen nur die gedämpfte NF-κB-Aktivierung bei 60 Schlaganfallpatienten gemessen ist, während die orale Bioverfügbarkeit mit 6,2 % sehr niedrig ist. Sicherheit 6, weil kontrollierte Daten über 16 Wochen (Hindmarch 1991, 203 Patienten) und eine jahrzehntelange Arzneimittelanwendung vorliegen, Nebenwirkungen in den Studien aber uneinheitlich erfasst wurden und das NTP 2020 eine klare Entwicklungstoxizität im Tier zeigte, die zur FDA-Warnung 2019 führte. Hype 3, weil ein Mittel mit Daten bei Schlaganfall und Durchblutungsstörungen als Gedächtnisbooster für Gesunde vermarktet wird. Anwendung 7, weil Vinpocetin als Cavinton seit über fünf Jahrzehnten in mehreren Ländern als Arzneimittel eingesetzt wird, in Deutschland aber seit 2006 kein Fertigarzneimittel mehr im Handel ist. Richtung gemischt, weil positiven Schlaganfalldaten ein nicht schlüssiges Demenzbild und fehlende Wirkung bei Gesunden gegenüberstehen.' },
  { id: 'yohimbin', view: 'experimental', evidenz: 6, mechanismus: 8, sicherheit: 7, hype: 4, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz 6, weil es für Erektionsstörungen mehrere RCTs und Meta-Analysen mit positivem Ergebnis gibt (Ernst & Pittler 1998: 7 RCTs, OR 3,85; Wibowo 2021: 8 RCTs, OR 2,08), diese aber alt und methodisch schwach sind, und weil für die Biohacking-Anwendungen Fettabbau und Leistung nur kleine, widersprüchliche Studien vorliegen – positiv bei 20 Fußballprofis über 21 Tage (Ostojic 2006) und bei 18 Frauen nach Einzeldosis (Barnes 2022), negativ bei 47 Männern über 6 Monate (Sax 1991). Mechanismus 8, weil die Blockade der Alpha-2-Rezeptoren am Menschen über den Anstieg von Noradrenalin (100 % bei Berlan 1991, 66 % bei Grossman 1993), freien Fettsäuren und Blutdruck gemessen und die CYP2D6-abhängige Kinetik quantifiziert ist (Vay 2020). Sicherheit 7, weil Yohimbin seit Jahrzehnten als Arzneimittel mit Fachinformation im Einsatz ist, kontrollierte Daten über bis zu 6 Monate existieren und Giftnotruf-Auswertungen mit 238 Fällen die Risiken beschreiben; systematische moderne Langzeitdaten fehlen. Hype 4, weil ein kleiner, uneinheitlicher Datensatz zum Körperfett als verlässlicher Fatburner-Effekt verkauft wird. Anwendung 7, weil Yohimbin seit Jahrzehnten als verschreibungspflichtiges Arzneimittel reguliert ist und parallel in US-Supplements breit kursiert. Richtung gemischt, weil klaren Befunden zur Erektion und zur Physiologie ein ungeklärter Nutzen beim Fettabbau gegenübersteht.' },
  { id: 'astragalus', view: 'supplement', evidenz: 4, mechanismus: 5, sicherheit: 5, hype: 3, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz 4, weil es zu TA-65 nur kleine RCTs mit Surrogatmarkern gibt: Telomere +530 bp gegenüber -290 bp unter Placebo bei 117 Teilnehmenden über 12 Monate (Salvador 2016), in einer Meta-Analyse von 8 RCTs mit 750 Teilnehmenden SMD 0,47 (Su 2025), überwiegend herstellerfinanziert; die Studien zur Wurzel sind laut Cochrane (22 Studien, 1323 Teilnehmende) von niedriger Qualität und ohne harte Endpunkte. Mechanismus 5, weil die Telomerase-Aktivierung durch Cycloastragenol in menschlichen Zellen und bei Mäusen telomeraseabhängig gezeigt ist (Fauce 2008, Bernardes de Jesus 2011) und die Telomerlänge beim Menschen reagiert, der Weg von dort zu Funktion und Gesundheit aber nicht belegt ist. Sicherheit 5, weil kontrollierte Daten über 12 Monate ohne schwere Ereignisse, eine 91-Tage-Rattenstudie und für die Wurzel lange traditionelle Nutzung vorliegen, das theoretische Krebsrisiko einer dauerhaften Telomerase-Aktivierung aber nie langfristig untersucht wurde. Hype 3, weil aus längeren Telomeren ein Verjüngungsversprechen gemacht wird, obwohl sich Gebrechlichkeit und Entzündung in der Meta-Analyse nicht besserten und TA-65 die Lebensdauer von Mäusen nicht verlängerte. Anwendung 7, weil die Wurzel seit Jahrhunderten in der chinesischen Medizin und in der EU schon vor 1997 in Nahrungsergänzungsmitteln verwendet wird; reines Cycloastragenol ist dagegen in der EU nicht zugelassen. Richtung gemischt: positive Befunde bei Telomerlänge und einzelnen Immunwerten, kein Nutzen bei funktionellen Endpunkten und ein verfehlter primärer Endpunkt nach Herzinfarkt.' },
  { id: 'beta-glucan', view: 'supplement', evidenz: 7, mechanismus: 7, sicherheit: 7, hype: 6, anwendung: 8, richtung: 'positiv',
    beleg: 'Evidenz 7, weil viele RCTs und mehrere konsistente Meta-Analysen eine LDL-Senkung durch Hafer- und Gersten-Beta-Glucan zeigen (Whitehead 2014: 28 RCTs, -0,25 mmol/l; Ho 2016: 58 RCTs mit 3.974 Teilnehmenden, -0,19 mmol/l; Ho 2016 Gerste: 14 RCTs, -0,25 mmol/l) und die EFSA die Wirkung anerkennt, der Endpunkt aber ein Surrogatmarker bleibt, die Studien nur 2 bis 12 Wochen liefen und die Heterogenität hoch ist (I² = 79 %). Mechanismus 7, weil die Wirkkette am Menschen gezeigt ist – Gallensäureausscheidung +144 % mit nativem, nicht mit hydrolysiertem Beta-Glucan (Ellegård 2007) und LDL-Senkung abhängig vom Molekulargewicht (Wolever 2010) –, während die Immunwirkung von Hefe- und Pilz-Glucanen über Dectin-1 nur aus Zell- und Tierstudien stammt. Sicherheit 7, weil kontrollierte Daten über Wochen bis Monate vorliegen, Beta-Glucan bis 28 g pro Tag gut vertragen wurde (Mysonhimer 2022) und die EFSA Hefe-Beta-Glucan als sicher bewertete (2011), eine systematische Langzeitüberwachung von Extrakten aber fehlt. Hype 6, weil die Cholesterinwerbung weitgehend der Datenlage entspricht, Immunversprechen für Hefe- und Pilz-Glucane aber über kleine, heterogene Studien hinausgehen (Zhong 2021) und die EFSA 2010 eine Immunangabe ablehnte. Anwendung 8, weil Hafer und Gerste seit Jahrzehnten gegessen werden und die Gesundheitsangaben seit 2011 in der EU reguliert sind. Richtung positiv: Beim Cholesterin zeigen die Daten klar in eine Richtung, beim Immunsystem ist das Bild offener.' },
  { id: 'egcg', view: 'supplement', evidenz: 6, mechanismus: 4, sicherheit: 7, hype: 4, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz 6, weil mehrere Meta-Analysen randomisierter Studien kleine Effekte auf Surrogatmarker zeigen (Xu 2020: 31 RCTs, LDL -4,55 mg/dl; Khalesi 2014: 13 Studien, Blutdruck -2,08/-1,71 mmHg), der Cochrane-Review beim Gewicht außerhalb Japans aber nur -0,04 kg ohne Signifikanz fand (Jurgens 2012) und die größte RCT mit 1.075 Frauen ihren Endpunkt Brustdichte verfehlte (Samavat 2017). Mechanismus 4, weil die meisten Wirkwege aus Zellkultur und Tier stammen (Singh 2011), am Menschen nur ein thermogener Effekt mit Koffein in einer Kammerstudie an 10 Männern gezeigt ist (Dulloo 1999) und Grüntee-Extrakt im Interventions Testing Program das Mäuseleben nicht verlängerte (Strong 2013). Sicherheit 7, weil ein doppelblindes Jahres-RCT (Dostal 2015: ALT-Anstieg bei 6,7 % gegenüber 0,7 %), das EFSA-Gutachten 2018, LiverTox (mehr als 100 Fälle, Likelihood score A) und die USP-Übersicht 2020 das Leberrisiko klar beschreiben; hohe Zahl heißt gut untersucht, nicht harmlos. Hype 4, weil Grüntee-Extrakt breit als Fatburner und Longevity-Molekül beworben wird, obwohl keine der fünf beantragten EU-Gesundheitsangaben zugelassen wurde und sich die Gewichtswirkung in Cochrane nicht bestätigte. Anwendung 7, weil Extrakte seit vielen Jahren breit genutzt werden und die EU sie seit 2022 mit Obergrenze und Warnhinweisen reguliert; grüner Tee als Getränk ist davon nicht betroffen. Richtung gemischt: Blutfette und Blutdruck zeigen kleine positive Effekte, beim beworbenen Abnehmen und bei der Krebsvorbeugung überzeugen die Humandaten nicht.' },
  { id: 'forskolin', view: 'supplement', evidenz: 4, mechanismus: 5, sicherheit: 4, hype: 3, anwendung: 5, richtung: 'gemischt',
    beleg: 'Evidenz 4, weil es nur vier kleine kontrollierte Studien zur Körperzusammensetzung mit 23 bis 60 Teilnehmenden über höchstens 12 Wochen gibt, deren Ergebnisse auseinandergehen: weniger Fettmasse bei 30 Männern (Godard 2005), kein Gewichtsverlust bei 23 Frauen (Henderson 2005), kein Gewichtsunterschied, aber besseres Insulin bei 30 Erwachsenen unter Diät (Loftus 2015) und −1,93 kg in einer nur quasi-randomisierten Studie mit 60 Teilnehmenden (Channangihalli Thimmegowda 2026). Mechanismus 5, weil die direkte Aktivierung der Adenylatcyclase im Labor klar belegt ist (Seamon 1981) und ein Derivat klinisch am Menschen wirkt (Colforsin-Daropat), für oral eingenommenes Forskolin aber keine Humandaten zu Blutspiegeln oder cAMP im Fettgewebe gefunden wurden. Sicherheit 4, weil nur Kurzzeitdaten bis 12 Wochen vorliegen, eine japanische Befragung dosisabhängigen Durchfall zeigt (10,5 % der Nutzer mit Nebenwirkungen) und Tierstudien Leberschäden durch den Extrakt sowie eine Induktion arzneimittelabbauender Enzyme finden (Virgona 2013, Ding 2005). Hype 3, weil Forskolin als Fatburner vermarktet wird, obwohl die Humandaten klein und widersprüchlich sind. Anwendung 5, weil die Pflanze traditionell im Ayurveda genutzt und der Extrakt seit Jahren breit als Nahrungsergänzung verkauft wird, ohne Zulassung als Arzneimittel. Richtung gemischt: einzelne kleine Studien positiv, andere ohne Effekt auf das Gewicht.' },
  { id: 'l-tryptophan', view: 'supplement', evidenz: 5, mechanismus: 6, sicherheit: 6, hype: 5, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz 5, weil die Schlafdaten überwiegend aus kleinen Studien der Jahre 1979 bis 1987 stammen, die sich teilweise widersprechen (Hartmann 1979 mit 15 Personen positiv, Adam und Oswald 1979 negativ, Demisch 1987 mit 39 Personen nur je nach Reihenfolge), und die Meta-Analyse aus 4 Studien nur bei der Wachzeit nach dem Einschlafen einen Effekt findet (SMD -1,08; Sutanto 2022). Dazu kommen eine positive RCT bei prämenstrueller Dysphorie (34,5 gegen 10,4 Prozent; Steinberg 1999), gemischte Stimmungsdaten bei Gesunden (4 von 11 RCTs; Kikuchi 2021) und für Depression nur 2 verwertbare Studien mit 64 Patienten (Cochrane 2002). Mechanismus 6, weil am Menschen gezeigt ist, dass Tryptophanaufnahme ins Gehirn und Serotoninsynthese vom Angebot im Blut abhängen (Fernstrom 2013), die Kette zur Stimmung aber indirekt ist: Tryptophan-Depletion senkt die Stimmung Gesunder nicht (Ruhé 2007, 45 Studien). Sicherheit 6, weil eine kontrollierte Dosisstudie bis 5 g pro Tag über 21 Tage keine Nebenwirkungen fand (Hiratsuka 2013) und die Wechselwirkungen aus der Arzneimittelzulassung bekannt sind, Langzeitdaten aber fehlen und die EMS-Epidemie mit 27 Todesfällen die Bedeutung der Reinheit zeigt. Hype 5, weil Tryptophan als natürliches Schlaf- und Glücksmittel beworben wird, obwohl nur einzelne Schlafparameter und einzelne Stimmungsstudien positiv sind. Anwendung 7, weil Tryptophan in Deutschland als apothekenpflichtiges Arzneimittel zugelassen und als Nahrungsergänzung mit BVL-Obergrenze von 500 mg pro Tag reguliert ist. Richtung gemischt: positive Signale beim Schlaf und bei prämenstrueller Dysphorie, widersprüchliche oder fehlende Effekte bei anderen Endpunkten.' },
  { id: 'moenchspfeffer', view: 'supplement', evidenz: 7, mechanismus: 5, sicherheit: 7, hype: 6, anwendung: 8, richtung: 'positiv',
    beleg: 'Evidenz 7, weil mehrere doppelblinde RCTs mit 162 bis 217 Frauen über 3 Zyklen übereinstimmend eine Linderung des prämenstruellen Syndroms zeigen (Schellenberg 2001: Responder 52 gegen 24 Prozent; He 2009; Schellenberg 2012 mit Dosis-Wirkungs-Beziehung) und eine strenge Meta-Analyse aus 3 Studien mit 520 Frauen ein RR von 2,57 findet (Csupor 2019); gegen eine höhere Zahl sprechen die sehr hohe Heterogenität (I² 91 %) und der Publikationsbias in der breiten Meta-Analyse (Verkaik 2017). Mechanismus 5, weil die D2-Aktivität von Diterpenen und Triterpenen nur im Zellmodell gezeigt ist (Reinhardt 2024, herstellernah), die Prolaktinsenkung am Menschen auf kleinen Studien beruht (Milewicz 1993, 37 ausgewertete Frauen) und die EMA den Mechanismus als unbekannt bezeichnet. Sicherheit 7, weil eine systematische Übersicht über Studien, Spontanmeldungen und Herstellerdaten nur milde, reversible Nebenwirkungen findet (Daniele 2005) und eine EU-Monografie vorliegt, kontrollierte Daten aber meist nur über 3 Zyklen reichen und die Häufigkeit der Nebenwirkungen laut EMA unbekannt ist. Hype 6, weil die Werbung für PMS und Brustspannen weitgehend zur Datenlage passt, Versprechen zu Hormonbalance, Fruchtbarkeit und Wechseljahren aber auf wenigen kleinen Studien beruhen. Anwendung 8, weil Mönchspfeffer seit Jahrzehnten als Arzneimittel unter Aufsicht genutzt wird (Kommission E, EU-Monografie mit traditioneller Anwendung von mindestens 30 Jahren). Richtung positiv: Nahezu alle kontrollierten Studien zum prämenstruellen Syndrom fallen zugunsten von Mönchspfeffer aus.' },
  { id: 'pea', view: 'experimental', evidenz: 2, mechanismus: 4, sicherheit: 2, hype: 3, anwendung: 4, richtung: 'offen',
    beleg: 'Evidenz 2, weil es zu PEA als Supplement keine randomisierte Wirksamkeitsstudie gibt: Die Depressionsdaten sind unkontrollierte Serien einer Arbeitsgruppe mit dem MAO-B-Hemmer Selegilin als Partner (Sabelli 1996: 12 von 14 mit anhaltender Besserung über 20 bis 50 Wochen), die Sportstudie misst nur ein Abbauprodukt im Urin (Szabo 2001: +77 % bei 20 Männern), und die einzige Placebostudie (Lüthy 1983, 27 Gesunde) erfasste nur Beschwerden. Mechanismus 4, weil TAAR1-Aktivierung und amphetaminähnliche Transporterhemmung in Zellstudien gut quantifiziert sind (Rickli 2019: IC50 0,05 und 1,8 µM), aber orales PEA laut Dopinganalytik weitgehend abgebaut wird, bevor es im Urin erscheint (Sigmund 2015; Krombholz 2022), und eine Zielwirkung am Menschen nach Einnahme nie gemessen wurde. Sicherheit 2, weil keine systematischen Daten existieren, nur eine kleine Placebostudie mit Beschwerden, Fallberichte (Hirnblutung nach PEA-verunreinigtem Kratom, Panikattacken mit Selegilin) und die bekannte Gefahr mit MAO-Hemmern. Hype 3, weil ein spannender Mechanismus und alte offene Depressionsbefunde als verlässlicher Stimmungs-, Fokus- und Fatburner-Effekt verkauft werden. Anwendung 4, weil PEA verbreitet in Pre-Workout- und Stimmungsprodukten steckt, ohne regulatorischen Rahmen und mit Beanstandungen in mehreren EU-Staaten. Richtung offen, weil Humandaten für die beworbenen Wirkungen schlicht fehlen, nicht weil sie dagegen sprechen.' },
  { id: 'sglt2-hemmer', view: 'experimental', evidenz: 7, mechanismus: 9, sicherheit: 9, hype: 6, anwendung: 8, richtung: 'positiv',
    beleg: 'Evidenz 7: Für Patienten ist die Datenlage außergewöhnlich stark, mit großen doppelblinden Studien und harten Endpunkten, etwa DAPA-HF (4744 Patienten, HR 0,74), DAPA-CKD (4304, HR 0,61, Gesamtsterblichkeit HR 0,69) und einer Meta-Analyse von 13 Studien mit 90.409 Teilnehmenden (Nierenprogression -37 %, auch ohne Diabetes); für die im Biohacking gesuchte Anwendung bei Gesunden gibt es aber keine einzige randomisierte Studie, nur Mausdaten und eine Kohorte zum Demenzrisiko (HR 0,65, Shin 2024), deshalb nicht 9. Mechanismus 9, weil die Wirkkette am Menschen quantifiziert ist, mit rund 78 g Glucose pro Tag im Urin, Natriurese, Gewichts- und Blutdrucksenkung; die Fastenmimikry ist dagegen Hypothese. Sicherheit 9, weil Zulassungen seit 2012 und 2014, Endpunktstudien über mehrere Jahre und Pharmakovigilanz vorliegen; bekannt sind Genitalinfektionen, Volumenmangel und die seltene, auch euglykämische Ketoazidose. Hype 6, weil das Longevity-Narrativ überwiegend auf echten Befunden ruht, aber Patientendaten und Mausstudien auf Gesunde überträgt. Anwendung 8, weil Millionen Patienten seit über einem Jahrzehnt unter ärztlicher Aufsicht behandelt werden. Richtung positiv: Die Humandaten zeigen konsistent in eine Richtung, der Nutzen für Gesunde ist allerdings nicht untersucht.' },
  { id: 'synephrin', view: 'supplement', evidenz: 5, mechanismus: 5, sicherheit: 5, hype: 3, anwendung: 6, richtung: 'gemischt',
    beleg: 'Evidenz 5, weil es zwar viele kleine placebokontrollierte Studien gibt (Meta-Analyse Koncz 2022: 18 Studien, 341 Teilnehmende), diese aber überwiegend Einzeldosen und Surrogatmarker wie die Fettoxidation beim Sport messen (Gutiérrez-Hellín 2016: 0,29 auf 0,40 g/min, 18 Personen) und die wenigen Studien über 6 bis 8 Wochen keinen Gewichtsverlust zeigen (3 Studien, 0,60 kg, nicht signifikant). Mechanismus 5, weil die adrenerge Wirkung über Alpha-1- und Beta-3-Rezeptoren pharmakologisch plausibel und die veränderte Substratnutzung beim Menschen gemessen ist, die Rezeptorbindung aber vor allem aus Tier- und Laborversuchen stammt und bei Nagern stärker ist als beim Menschen (Stohs 2017). Sicherheit 5, weil kontrollierte Daten nur bis 8 Wochen reichen und dort einen Blutdruckanstieg zeigen (systolisch +6,37 mmHg), Einzeldosis-Studien sich widersprechen (Bui 2006 vs. Shara 2016) und 30 Fallberichte mit 35 Patienten vorliegen (de Jonge 2023); BfR und BVL/BfArM haben das Risiko ausführlich bewertet. Hype 3, weil Synephrin als Fatburner beworben wird, obwohl ein Effekt auf Körpergewicht nicht belegt ist. Anwendung 6, weil p-Synephrin seit den 1930er Jahren als Arzneimittel Oxedrin und seit Jahren breit in Sportprodukten genutzt wird, mit behördlichen Richtwerten in mehreren Ländern. Richtung gemischt: positiv bei der akuten Fettverbrennung im Training, kein Beleg für Gewichtsverlust.' },
  { id: 'theacrin', view: 'experimental', evidenz: 5, mechanismus: 4, sicherheit: 5, hype: 4, anwendung: 4, richtung: 'gemischt',
    beleg: 'Evidenz 5, weil es rund ein Dutzend randomisierte, meist doppelblinde Studien gibt, diese aber klein (8 bis 125 Teilnehmer), kurz und oft herstellerfinanziert sind und uneinheitlich ausfallen: Das subjektive Energiegefühl stieg in Ziegenfuss 2017 (15 Gesunde), nicht aber in Cesareo 2019 (12) und Stoke 2026 (19); weniger Aussetzer im Wachsamkeitstest fand Gardiner 2024 (22 Männer), und für Leistung zeigten 4 von 5 Studien mit Theacrin allein keinen Effekt, Bello 2019 nur eine Tendenz (P < 0,052). Mechanismus 4, weil Adenosin-Antagonismus und Dopaminbeteiligung nur bei Ratten gezeigt sind (Feduccia 2012), Mausstudien dagegen sedierende Effekte fanden (Xu 2007; Qiao 2017) und am Menschen lediglich die Kinetik beschrieben ist (He 2017: 8 Personen; Halbwertszeit 16 bis 26 Stunden). Sicherheit 5, weil kontrollierte Daten über 8 Wochen mit 60 Gesunden ohne Auffälligkeiten vorliegen (Taylor 2016) und 4 Wochen in Kombination mit 125 Personen (VanDusseldorp 2020), höhere Dosen aber Blutdruck, Cortisol und Nebenwirkungen erhöhten (Vieira-Cavalcante 2025; Stoke 2026) und längere Daten fehlen. Hype 4, weil Koffein ohne Absturz und ohne Gewöhnung versprochen wird, obwohl die Gewöhnungsfreiheit im Wesentlichen auf einer herstellerfinanzierten Studie beruht und der Leistungsnutzen sich nicht bestätigt hat. Anwendung 4, weil Theacrin seit Jahren in US-Supplements verbreitet ist, in der EU aber ohne Zulassung. Richtung gemischt, weil positive Befunde zu Energiegefühl und Wachsamkeit neben überwiegend negativen Leistungsstudien stehen.' },
  { id: 'betain-hcl', view: 'supplement', evidenz: 3, mechanismus: 7, sicherheit: 3, hype: 4, anwendung: 5, richtung: 'offen',
    beleg: 'Evidenz 3, weil es zum eigentlichen Anwendungszweck, weniger Verdauungsbeschwerden oder bessere Nährstoffaufnahme, keine kontrollierte Studie gibt, nur einen Fallbericht (Amidon 2024) und eine unkontrollierte Beobachtung mit einem anderen Säure-Pepsin-Präparat bei 97 Patienten (Forssmann 2017); Fachübersichten nennen randomisierte Studien ausdrücklich als fehlend (Gomez Cifuentes 2022). Mechanismus 7, weil die Säuerung im menschlichen Magen direkt gemessen ist: 1500 mg senkten den pH bei 6 Gesunden von 5,2 auf 0,6 für 73 Minuten (Yago 2013), und nüchtern hob Betain-HCl die Wirkung eines Säureblockers auf die Aufnahme von Dasatinib vollständig auf (Yago 2014); mit Mahlzeit war der Effekt schwach (Faber 2017, Surofchy 2019). Sicherheit 3, weil nur Einzeldosen bei insgesamt wenigen Gesunden ohne Nebenwirkungen untersucht sind und Langzeitdaten fehlen; in einer Beobachtung mit einem Säure-Pepsin-Präparat brachen 27 von 97 Patienten ab. Hype 4, weil Betain-HCl breit gegen Blähungen, Reflux und schlechte Nährstoffaufnahme beworben wird, belegt aber nur die pH-Senkung ist. Anwendung 5, weil es seit Jahrzehnten frei verkauft wird, in den USA aber als rezeptfreies Magensäuerungsmittel 1988 mangels Wirksamkeitsdaten nicht anerkannt wurde. Richtung offen: Die Säuerung ist belegt, der Nutzen für Beschwerden ist nicht untersucht.' },
  { id: 'dmg', view: 'experimental', evidenz: 5, mechanismus: 4, sicherheit: 4, hype: 3, anwendung: 5, richtung: 'offen',
    beleg: 'Evidenz 5, weil es sechs kleine placebokontrollierte Studien mit klinischen Endpunkten gibt (5 bis 37 Teilnehmende), die bei Autismus (Kern 2001, Bolman 1999), Epilepsie (Gascon 1989), progredienter MS über 12 Monate (Wolfsegger 2021), Laufbandleistung (Gray 1982, Pangamsäure) und Mitochondrienkrankheit (Liet 2003) übereinstimmend keinen Effekt fanden; dem steht nur ein nie wiederholter Immunbefund mit 20 Freiwilligen gegenüber (Graber 1981). Mechanismus 4, weil die Rolle von DMG im Betain-Stoffwechsel am Menschen gut beschrieben ist (McGregor 2001, Binzak 2001), die beworbene bessere Sauerstoffnutzung aber nur aus Zellkultur und Tier stammt und am Menschen nicht messbar war (Liet 2003). Sicherheit 4, weil kontrollierte Daten bis 12 Monate mit 125 mg pro Tag bei 20 Behandelten keine Auffälligkeiten zeigten, systematische Langzeitdaten aber fehlen und hohe körpereigene DMG-Spiegel mit Herzinfarkten assoziiert sind (Svingen 2013). Hype 3, weil DMG seit der Pangamsäure-Zeit als Leistungs-, Immun- und Autismusmittel beworben wird, gestützt auf Einzelbefunde. Anwendung 5, weil es seit 1974 breit als Nahrungsergänzung verkauft wird, ohne regulatorischen Rahmen in der EU. Richtung negativ: Alle placebokontrollierten Studien zu den beworbenen Hauptwirkungen fanden keinen Effekt, wenn auch in kleinen Gruppen.' },
  { id: 'gamma-butyrobetain', view: 'experimental', evidenz: 2, mechanismus: 5, sicherheit: 2, hype: 2, anwendung: 3, richtung: 'offen',
    beleg: 'Evidenz 2, weil es am Menschen nur eine unkontrollierte Fütterungsstudie von 1989 gibt, in der GBB über 10 Tage die Carnitinbildung stärker steigerte als andere Vorstufen (Rebouche 1989); Studien zu Fettabbau, Energieverbrauch oder Leistung fehlen, und bei ClinicalTrials.gov ist keine GBB-Studie registriert. Mechanismus 5, weil der Umbau von GBB zu Carnitin durch BBOX1 beim Menschen gesichert ist (Rebouche & Engel 1980; Li 2025, 3 Patienten mit Enzymdefekt), der Schritt von mehr Carnitin zu mehr Fettverbrennung für GBB aber nur aus Tierdaten abgeleitet ist (Sandor 1991; Higashi 2001). Sicherheit 2, weil GBB-Supplemente nie systematisch geprüft wurden und die vorhandenen Signale in die falsche Richtung weisen: beschleunigte Atherosklerose bei Mäusen (Koeth 2014) und schlechtere Prognose bei hohen Blutwerten in zwei Patientenkohorten (HR 3,3 bei 264 Patienten, Skagen 2016; HR 1,93 bei 395 Patienten, Chen 2025). Hype 2, weil GBB als Super-Carnitin und schweißtreibender Fatburner verkauft wird, ohne dass ein Effekt auf Körperfett je gemessen wurde; das Schwitzen passt eher zur acetylcholinartigen Wirkung der Ester (Dambrova 2004, Ratte). Anwendung 3, weil GBB nur in Nischenprodukten der Sportszene vorkommt und in der EU nicht zugelassen ist. Richtung offen, weil es keine kontrollierten Humandaten gibt, die für oder gegen die beworbene Wirkung sprechen.' },
  { id: 'l-ornithin', view: 'supplement', evidenz: 5, mechanismus: 5, sicherheit: 7, hype: 4, anwendung: 6, richtung: 'gemischt',
    beleg: 'Evidenz 5, weil es zum Arzneimittel L-Ornithin-L-Aspartat viele RCTs gibt, der Cochrane-Review die Qualität aber als sehr niedrig einstuft und der Effekt in Studien mit niedrigem Verzerrungsrisiko verschwindet (Goh 2018, 29 Studien mit 1.891 Teilnehmern), während für Gesunde nur kleine RCTs mit subjektiven Endpunkten vorliegen (Miyake 2014 mit 52, Moriyasu 2024 mit 65, Sugino 2008 mit 17 Teilnehmern). Mechanismus 5, weil die Rolle im Harnstoffzyklus gesichert ist und LOLA bei kranker Leber auf Harnstoff- und Glutaminsynthese wirkt, Ornithin bei gesunder Leber laut Fachinformation aber nicht begrenzend ist und die Ammoniak-Senkung beim Sport ausblieb (Nagayama 2025); wie Ornithin auf Müdigkeit und Schlaf wirkt, ist offen. Sicherheit 7, weil eine systematische Übersicht über 22 Studien bis 156 Tage (Yang 2025) und eine gestufte Verträglichkeitsstudie bis 12 g pro Tag (Miura 2023) vorliegen und das Arzneimittel seit Jahren unter Pharmakovigilanz steht. Hype 4, weil Ornithin als Leberentgifter, Wachstumshormon-Booster und Schlafmittel beworben wird, obwohl die Wachstumshormon-Daten aus einer Kombination mit Arginin bei 17 Athleten stammen (Zajac 2010) und die Entgiftung nur bei Leberzirrhose untersucht ist. Anwendung 6, weil LOLA in Deutschland als apothekenpflichtiges Arzneimittel zugelassen ist und L-Ornithin als Nahrungsergänzung per BVL-Allgemeinverfügung reguliert ist. Richtung gemischt: positive subjektive Effekte bei Gesunden und ein möglicher Nutzen bei Zirrhose stehen widersprüchlichen Cortisol-Daten und fehlender Wirkung auf Ammoniak und Leistung beim Sport gegenüber.' },
  { id: 'leucin', view: 'supplement', evidenz: 6, mechanismus: 8, sicherheit: 6, hype: 5, anwendung: 6, richtung: 'gemischt',
    beleg: 'Evidenz 6, weil zahlreiche RCTs und mehrere Meta-Analysen vorliegen, die aber auseinanderlaufen: Isoliertes Leucin veränderte bei Älteren weder fettfreie Masse noch Kraft (Guo 2022, 17 RCTs mit 1.418 Teilnehmern; Verhoeven 2009, 7,5 g pro Tag über 3 Monate), leucinreiche Kombinationspräparate verbesserten bei Sarkopenie dagegen die Kraft (Lee 2022, 6 RCTs; PROVIDE mit 380 Teilnehmern nur bei sekundären Endpunkten). Mechanismus 8, weil die Aktivierung der Muskelproteinsynthese über mTORC1 am Menschen mit Tracer-Studien quantifiziert ist (+110 % mit 3,42 g, Wilkinson 2013; Meta-Analyse über 9 RCTs, Xu 2015), der Schritt von der Syntheserate zur Muskelmasse aber nicht gelingt. Sicherheit 6, weil kontrollierte Daten über 3 Monate unauffällig sind und Akutstudien Ammoniakanstiege erst bei sehr hohen Mengen zeigen, das BfR seine Orientierungswerte (4,0 g Leucin pro Tag) mangels Humandaten aber aus Tierstudien ableiten musste. Hype 5, weil Leucin als Muskelaufbauer beworben wird, obwohl nur die akute Synthese belegt ist und isoliertes Leucin über Monate keine Muskeln bringt. Anwendung 6, weil Leucin seit vielen Jahren breit in Sportlernahrung und klinischer Trinknahrung genutzt wird und in Deutschland über BVL-Allgemeinverfügung und BfR-Orientierungswerte eingeordnet ist. Richtung gemischt: klarer Mechanismus und positive Kombinationsdaten, aber kein Effekt von Leucin allein auf Muskelmasse und Kraft.' },
  { id: 'msm', view: 'supplement', evidenz: 5, mechanismus: 4, sicherheit: 5, hype: 4, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz 5, weil mehrere kleine RCTs über 12 Wochen positive Effekte bei Kniearthrose zeigen (Kim 2006: 50 Patienten; Debbi 2011: 49 Patienten, Funktion signifikant, Schmerz mit p = 0,08 nicht; Usha 2004: 118 Patienten; Toguchi 2023: 88 Teilnehmende), die Meta-Analyse von Brien 2011 über 3 RCTs mit 326 Patienten aber nicht signifikant war, das größte Einzel-RCT mit 180 Rekruten keinen Effekt fand (Tennent 2017) und Liu 2018 die klinische Bedeutung als unklar einstuft. Mechanismus 4, weil Entzündungshemmung über NF-κB und die Rolle als Schwefelspender aus Zellkultur und Tier stammen und beim Menschen Plasmasulfat und Homocystein nicht dosisabhängig anstiegen (Butawan 2017); am Menschen gibt es nur kleine Zytokinstudien (van der Merwe 2016). Sicherheit 5, weil RCTs bis 16 Wochen ohne relevante Nebenwirkungen, Tierstudien über 90 Tage (NOAEL 1,5 g/kg/Tag) und eine FDA-GRAS-Notiz ohne Einwände (GRN 229) vorliegen, Langzeitdaten und Daten zu Schwangerschaft aber fehlen. Hype 4, weil MSM für Gelenke, Haut, Haare, Nägel, Immunsystem und Allergien beworben wird, die EU aber alle beantragten Health Claims abgelehnt hat und außerhalb der Arthrose nur einzelne kleine, oft herstellernahe Studien existieren. Anwendung 7, weil MSM seit vielen Jahren breit als Nahrungsergänzung genutzt wird, in der EU als nicht neuartig in Nahrungsergänzungsmitteln gilt und in den USA als Lebensmittelzutat angemeldet ist. Richtung gemischt: kleine positive Arthrose-Studien stehen einer nicht signifikanten Meta-Analyse und einem negativen Präventions-RCT gegenüber.' },
  { id: 'opc', view: 'supplement', evidenz: 5, mechanismus: 5, sicherheit: 5, hype: 3, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz 5, weil es viele, aber kleine RCTs gibt: Der Cochrane-Review 2020 fasst 27 RCTs mit 1.641 Teilnehmenden in 10 Erkrankungen zusammen und bewertet alle Endpunkte mit sehr niedriger Vertrauenswürdigkeit (Robertson 2020); die Blutdruck-Meta-Analysen widersprechen sich (Mohammadi 2025: 27 RCTs, −2,26/−2,62 mmHg; Fogacci 2020: 7 doppelblinde RCTs mit 626 Teilnehmenden ohne Effekt), und harte Endpunkte fehlen. Mechanismus 5, weil am Menschen eine verbesserte Endothelfunktion mit gesenktem Oxidationsmarker (Enseleit 2012, 23 Patienten) und eine Hemmung der Plättchenaggregation (Pütter 1999) gemessen wurden, die meisten übrigen Wirkwege aber aus Labor und Tier stammen. Sicherheit 5, weil kontrollierte Studien bis 6 Monate und LiverTox (Score E, keine Leberschäden) eine gute Verträglichkeit nahelegen, Cochrane aber bemängelt, dass schwere Nebenwirkungen meist nicht berichtet wurden, und Langzeitdaten fehlen. Hype 3, weil OPC und Kiefernrindenextrakt für eine sehr breite Palette von Gefäßen über Haut bis ADHS beworben werden, die EU mehrere Claims (Cholesterin, Venen, Sehvermögen, Blutdruck, Antioxidans) abgelehnt hat und kein Claim für OPC allein zugelassen ist. Anwendung 7, weil beide Extrakte seit vielen Jahren breit als Nahrungsergänzung genutzt werden und laut EU-Novel-Food-Katalog in Nahrungsergänzungsmitteln nicht neuartig sind. Richtung gemischt: Gefäßfunktion und mehrere kleine Studien sind positiv, beim Blutdruck und in der Gesamtbewertung von Cochrane bleibt die Datenlage widersprüchlich bzw. sehr unsicher.' },
  { id: 'tulsi', view: 'supplement', evidenz: 5, mechanismus: 4, sicherheit: 5, hype: 5, anwendung: 7, richtung: 'positiv',
    beleg: 'Evidenz 5, weil es mehrere kleine placebokontrollierte Studien gibt, von denen eine registrierte doppelblinde RCT mit 100 Erwachsenen den primären Endpunkt erreichte (Stress −37 % gegenüber −19 %, Lopresti 2022), die Gesamtlage aber schwach ist: 24 Studien mit 1.111 Teilnehmenden, nur 8 mit Placebo und nur 7 hochwertig (Jamshidi 2017), keine Meta-Analyse mit gepoolten Effekten, und die zwei besten Stressstudien stammen vom selben Hersteller (Saxena 2012). Mechanismus 4, weil die Dämpfung der Stressachse vor allem aus Zell- und Tierversuchen stammt (CRF1-Antagonismus, weniger Corticosteron; 2023) und am Menschen nur Surrogatwerte wie Haar- und Speichelcortisol oder Immunzellen gemessen sind (Mondal 2011). Sicherheit 5, weil kontrollierte Daten nur 2 bis 13 Wochen abdecken, dort ohne schwere Ereignisse (83 % ohne Beschwerden, Lopresti 2022), während Tierdaten zur Fruchtbarkeit (Sethi 2010) und der Methyleugenol-Gehalt violetter Sorten (Balaji 2024) offene Fragen lassen. Hype 5, weil die Stresswirkung ungefähr auf Höhe der Daten beworben wird, das Versprechen eines Elixiers des Lebens aber ohne Humandaten ist. Anwendung 7, weil Tulsi in Indien eine lange Tradition als Tee und Heilkraut hat und in der EU als nicht neuartiges Lebensmittel im Handel ist. Richtung positiv, weil alle kontrollierten Studien in dieselbe günstige Richtung zeigen, bei insgesamt dünner Datenlage.' },
  { id: 'baikal-helmkraut', view: 'supplement', evidenz: 4, mechanismus: 4, sicherheit: 6, hype: 4, anwendung: 7, richtung: 'offen',
    beleg: 'Evidenz 4, weil es nur einzelne, meist kleine oder nicht replizierte Humanstudien gibt: Baicalin verbesserte zusätzlich zur Standardtherapie Blutfette und CRP in einer RCT mit 374 Patienten aus einem einzigen Zentrum (Hang 2018), ein Extrakt die Glukosetoleranz in einer kleinen Crossover-Studie (Shin 2020), während eine registrierte Kognitionsstudie mit einem Kombinationsprodukt keinen Unterschied zu Placebo fand (Krieger 2025); systematische Übersichten von Humanstudien fehlen. Mechanismus 4, weil Entzündungshemmung und die Bindung von Wogonin an den GABA-A-Rezeptor aus Zell- und Tierversuchen stammen (Hui 2002) und am Menschen nur die Pharmakokinetik von Baicalein in Phase-1-Studien gezeigt ist (Dong 2021). Sicherheit 6, weil neben Phase-1-Studien und einer 12-Wochen-RCT (Morgan 2009) umfangreiche Daten aus der Anwendung vorliegen: eine Fallserie und 194 FDA-Meldungen zu Flavocoxid mit Rückruf 2018 (Chalasani 2012), eine Inzidenz von 0,095 % Leberschäden in chinesischen Kliniken mit Dosisabhängigkeit (Fu 2026), ein Pneumonitis-Signal aus Japan (Oura 2024) und belegte Wechselwirkungen mit Rosuvastatin (Fan 2008). Hype 4, weil Baikal-Helmkraut als entzündungshemmend, beruhigend und neuroprotektiv vermarktet wird, die Grundlage dafür aber überwiegend Labordaten sind. Anwendung 7, weil die Wurzel seit über 2000 Jahren in der chinesischen Medizin genutzt wird und in Japan Bestandteil vieler Kampo-Arzneien ist. Richtung offen, weil die wenigen Humanstudien zwar meist günstig ausfallen, für eine Aussage aber zu dünn, zu heterogen und zu oft Kombinationen sind.' },
  { id: 'biotin', view: 'supplement', evidenz: 5, mechanismus: 7, sicherheit: 8, hype: 3, anwendung: 9, richtung: 'gemischt',
    beleg: 'Bei echtem Mangel ist Biotin unbestritten wirksam, etwa beim Biotinidase-Mangel, der im Neugeborenen-Screening erfasst wird (Leitlinie 2020). Für das Hauptversprechen, mehr Haarwachstum ohne Mangel, fand eine Übersicht von 2024 nur 3 Studien; die beste, doppelblind und placebokontrolliert, zeigte keinen Unterschied (Yelich 2024). Brüchige Nägel besserten sich in unkontrollierten Serien von 1989 bis 1993 deutlich (41 von 45 Patienten, Floersheim 1989), eine placebokontrollierte Bestätigung fehlt. Die Sicherheitsdaten sind gut: Selbst sehr hohe Dosen lagen in der Phase-3-Studie SPI2 mit 642 MS-Patienten über im Mittel 20,1 Monate bei den Nebenwirkungen auf Placeboniveau (84 % vs. 85 %), die MS-Wirkung bestätigte sich dort nicht (Lancet Neurol 2020). Das reale Risiko ist die Laborwert-Störung, die in JAMA 2017 bei 9 von 23 biotinbasierten Tests auftrat und zu FDA-Warnungen führte. Das Haar-Marketing liegt deutlich über den Daten.' },
  { id: 'calcium-d-glucarat', view: 'experimental', evidenz: 2, mechanismus: 3, sicherheit: 2, hype: 2, anwendung: 4, richtung: 'offen',
    beleg: 'Evidenz 2, weil es am Menschen nur einen Kongressbeitrag mit vorläufigen Befunden gibt (Walaszek 2004, laut MSKCC Beta-Glucuronidase gesenkt) und keine veröffentlichte kontrollierte Studie zu Östrogenspiegeln, Beschwerden oder Krebsrisiko; die einzige RCT mit Calcium-Glucarat testete ein Kombinationspräparat (Laidlaw 2010). Mechanismus 3, weil die Hemmung der Beta-Glucuronidase bei Ratten gut gezeigt ist (Serum −57 %, Dwivedi 1990) und mehrere Tiermodelle weniger Tumoren zeigen (Brust über 70 %, Walaszek 1986; Abou-Issa 1995), die Befunde aber nicht einheitlich sind (unveränderte Enzymspiegel bei Abou-Issa 1993, Wirkung ohne Lacton bei Curley 1994) und die Zielstruktur am Menschen nicht bestätigt ist. Sicherheit 2, weil keine systematischen Sicherheitsdaten am Menschen existieren und Wechselwirkungen über die Glucuronidierung nicht untersucht sind. Hype 2, weil das Östrogen-Detox-Versprechen auf Rattendaten beruht und am Menschen nie geprüft wurde. Anwendung 4, weil es als Nahrungsergänzung verbreitet angeboten wird, in der EU aber ohne geklärten Rechtsrahmen (kein Novel-Food-Katalogeintrag). Richtung offen: Es gibt keine Humandaten, die für oder gegen die beworbene Wirkung sprechen.' },
  { id: 'gotu-kola', view: 'supplement', evidenz: 5, mechanismus: 5, sicherheit: 5, hype: 4, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz 5, weil es zwar mehrere RCTs gibt, diese aber klein sind und meist Surrogatwerte messen: 8 Venenstudien mit der Triterpenfraktion verbesserten Mikrozirkulation und Knöchelschwellung, sind aber alt, schlecht berichtet und zu 4 von 8 aus derselben Arbeitsgruppe (Chong 2013); für die Haut gibt es 5 kleine Studien zur äußerlichen Anwendung (Kongkaew 2020) und eine RCT mit 112 Frauen zur Einnahme (Hur 2026, mittlere Faltentiefe −11,1 %). Mechanismus 5, weil Kollagen- und Gefäßeffekte aus Zell- und Tierversuchen stammen, am Menschen aber immerhin die Aufnahme der Aglykone und eine Veränderung der NRF2-Expression gezeigt sind (Wright 2022, 4 Personen). Sicherheit 5, weil kontrollierte Daten meist nur Wochen umfassen, mit einzelnen Studien über 6 Monate und 52 Wochen ohne Lebersignal (Tawanwongsri 2025; Lou 2018), während Fallberichte von Leberentzündungen (Jorge 2005) und Rattendaten die EMA veranlassten, die innere Anwendung nicht in ihre Monografie aufzunehmen. Hype 4, weil Gotu Kola vor allem als Gehirn- und Gedächtnispflanze beworben wird, die Meta-Analyse dazu aber keinen Effekt fand (Puttarak 2017), während Venen- und Hautwirkung eher zurückhaltend vermarktet werden. Anwendung 7, weil die Pflanze in Asien seit langem als Lebensmittel und Heilmittel genutzt wird und in Portugal und Frankreich als Arzneimittel zugelassen wurde. Richtung gemischt, weil Venen- und Hautdaten günstig sind, Kognition und Blutzucker in kontrollierten Studien aber nicht ansprachen (Tawanwongsri 2025).' },
  { id: 'l-lysin', view: 'supplement', evidenz: 5, mechanismus: 4, sicherheit: 7, hype: 4, anwendung: 7, richtung: 'gemischt',
    beleg: 'Evidenz 5, weil es zum Herpes zwar mehrere randomisierte Studien gibt, die aber klein (21 bis 52 Auswertbare), alt (1978 bis 1987) und widersprüchlich sind: Positiv waren 3 g pro Tag über 6 Monate (Griffith 1987, 2,4 Episoden weniger) und 1.248 mg pro Tag (McCune 1984), negativ 400 mg 3-mal täglich (DiGiovanna 1984), und die Cochrane-Übersicht über 32 RCTs fand für Lysin keine Belege (Chi 2015). Mechanismus 4, weil die Arginin-Lysin-Konkurrenz nur in Zellkultur gezeigt ist (Griffith 1981), am Menschen allein ein Zusammenhang mit dem Serumspiegel beobachtet wurde (Thein 1984) und Lysin bei Katzen Arginin nicht verdrängt (Bol 2015). Sicherheit 7, weil eine systematische Übersicht 71 Studien mit 3.357 Teilnehmern und Laufzeiten bis 1.095 Tage auswertet und einen vorläufigen NOAEL von 6,0 g pro Tag ableitet (Hayamizu 2019, 2020), es aber einen Fallbericht mit Nierenversagen gibt (Lo 1996). Hype 4, weil Lysin als sicheres Herpes-Mittel gilt, obwohl die Daten widersprüchlich sind, und die Pauling-Therapie gegen Arteriosklerose nur auf einer Hypothese und 3 Fallberichten beruht. Anwendung 7, weil Lysin seit Jahrzehnten breit als Nahrungsergänzung und zur Lebensmittelanreicherung genutzt wird und in Deutschland per BVL-Allgemeinverfügung von 2013 eingeordnet ist. Richtung gemischt: positive und negative RCTs zum Herpes, ohne Bestätigung in der Cochrane-Übersicht.' },
  { id: 'shiitake', view: 'supplement', evidenz: 4, mechanismus: 5, sicherheit: 6, hype: 4, anwendung: 8, richtung: 'offen',
    beleg: 'Evidenz 4, weil es für den Pilz selbst nur kleine Studien mit Surrogatmarkern gibt: die Immunstudie mit 52 Gesunden ohne Kontrollgruppe (Dai 2015), ein RCT mit 68 Personen, in dem nur die Triglyceride um 10 % sanken (Spim 2021), und ein RCT mit 52 Personen ohne Wirkung auf Cholesterin (Morales 2021); die starken Lentinan-Daten bei Magenkrebs (650 Patienten, HR 0,80, Oba 2009) betreffen ein gespritztes Arzneimittel. Mechanismus 5, weil die Beta-Glucan-Erkennung durch Immunzellen und die Eritadenin-Wirkung auf den Fettstoffwechsel in Zell- und Tierversuchen gut beschrieben sind (Lindequist 2024), am Menschen aber nur Immunmarker im Labor verändert wurden. Sicherheit 6, weil neben langer Verzehrstradition kontrollierte Studien über Wochen bis Monate, eine EFSA-Bewertung eines Myzelextrakts (2010) und Giftnotruf-Daten zur Shiitake-Dermatitis vorliegen (59 Fälle, Boels 2022), eine systematische Langzeitüberwachung von Pulvern und Kapseln aber fehlt. Hype 4, weil Immun-, Krebs- und Cholesterinversprechen sich auf Lentinan-Injektionen, Laborwerte und alte Kurzzeitdaten stützen. Anwendung 8, weil Shiitake seit Jahrhunderten gegessen wird und in der EU als Lebensmittel reguliert ist. Richtung offen: Die Immunmarker zeigen in eine günstige Richtung, klinische Endpunkte fehlen, und beim Cholesterin sind die Ergebnisse widersprüchlich.' },
  { id: 'tremella', view: 'supplement', evidenz: 4, mechanismus: 3, sicherheit: 4, hype: 2, anwendung: 6, richtung: 'offen',
    beleg: 'Evidenz 4, weil es nur zwei kleine RCTs mit Tremella allein gibt: 75 Personen über 8 Wochen mit erreichtem, aber subjektivem Hauptendpunkt zu Gedächtnisbeschwerden (Ban 2018) und 56 Personen mit Prädiabetes, bei denen HbA1c und Taillenumfang nur innerhalb der Tremella-Gruppe sanken (Gitsomboon 2024); für die beworbene Hautwirkung bei Einnahme gibt es keine Humanstudie (Wang 2026). Mechanismus 3, weil Wasserbindung, Wirkung über die Darmflora und antioxidative Effekte nur in Zell- und Tierstudien gezeigt sind (Xie 2022; Li 2025). Sicherheit 4, weil nur Kurzzeitdaten aus Studien über 8 bis 12 Wochen ohne Häufung von Nebenwirkungen vorliegen und ich keine Fallberichte zu Schäden durch Präparate fand; das bekannte Risiko betrifft Bakteriengift in verdorbenem oder zu lange eingeweichtem Pilz (Xiao 2025). Hype 2, weil das Hauptversprechen pflanzliche Hyaluronsäure für die Haut ohne Humandaten zur Einnahme auskommt und die Wasserbindungs-Werbung in keiner Primärstudie zu finden ist. Anwendung 6, weil Tremella in Asien seit Jahrhunderten gegessen wird und als Fruchtkörper in der EU ein gewöhnliches Lebensmittel ist, für Nahrungsergänzungen aber kein eigener Regelungsrahmen mit Höchstmengen besteht. Richtung offen: Die wenigen Humandaten weisen in eine günstige Richtung, sind aber zu dünn für ein Urteil.' },
  { id: 'vitamin-a', view: 'supplement', evidenz: 8, mechanismus: 9, sicherheit: 9, hype: 6, anwendung: 10, richtung: 'gemischt',
    beleg: 'Bei Mangel ist Vitamin A hervorragend belegt: Die Cochrane-Übersicht von 2022 zeigt über 19 Studien mit 1.202.382 Kindern eine um 12 % geringere Sterblichkeit (RR 0,88, hohe Vertrauenswürdigkeit). Für gut versorgte Erwachsene fehlt dagegen jeder Zusatznutzen; Vitamin A allein veränderte die Sterblichkeit in 12 Studien nicht (RR 1,07, Cochrane 2012). Die großen Präventionsstudien mit Beta-Carotin schadeten Rauchern: ATBC mit 29.133 Männern fand 18 % mehr Lungenkrebs (NEJM 1994), CARET mit 18.314 Risikopersonen RR 1,28 und wurde 21 Monate früher abgebrochen (NEJM 1996). Die Teratogenität von hochdosiertem Retinol ist durch Rothman 1995 (22.748 Schwangere) belegt und Grundlage des EFSA-Grenzwerts von 3.000 µg pro Tag (2024). Die Sicherheitsdatenlage ist damit außergewöhnlich gut, der Wirkmechanismus am Menschen bis ins Detail bekannt. Die Werbung für Immunsystem und Haut ist formal durch EU-Angaben gedeckt, verschweigt aber oft, dass bei uns kaum jemand einen Mangel hat.' }
];

/* Label aus Human-Evidenz, Richtung der Evidenz und Hype-Abstand – bewusst kein
 * Mittelwert. Die Richtung ist entscheidend: Eine hohe Human-Evidenz heisst nur,
 * dass viel und gut untersucht wurde. Bei der Chelat-Therapie etwa liegen zwei
 * grosse randomisierte Studien mit harten Endpunkten vor – und beide fielen
 * negativ aus. Ohne das Feld 'richtung' wuerde daraus faelschlich "gut belegt". */
function bkLabel(s) {
  const anw = typeof s.anwendung === 'number' ? s.anwendung : 0;
  // Widerlegtes zuerst: hier gibt es Daten, und sie fallen negativ aus.
  if (s.richtung === 'negativ' && s.evidenz >= 6) return 'Gut untersucht – Wirkung nicht bestätigt';
  if (s.richtung === 'negativ' && s.evidenz >= 4) return 'Untersucht – Nutzen nicht gezeigt';
  if (s.evidenz >= 8 && s.hype >= 6) return 'Gut belegt';
  if (s.evidenz >= 8) return 'Gut belegt, stark überhöht beworben';
  if (s.evidenz >= 6) return 'Belegt, mit Einschränkungen';
  if (s.evidenz >= 4) return 'Dünne Humanevidenz';
  // Ab hier ist die Studienlage duenn. Frueher stand hier pauschal
  // "Hype weit vor Evidenz" - das warf zwei verschiedene Dinge zusammen:
  // etwas, das lange angewendet, aber nie sauber untersucht wurde, und etwas,
  // das schlicht neu und ungeprueft ist. Die Anwendungsachse trennt das.
  if (anw >= 6) return 'Lange angewendet, kaum untersucht';
  // „Nie versucht" und „versucht, nie veroeffentlicht" duerfen nicht
  // dasselbe Etikett bekommen - das zweite ist die unangenehmere Aussage.
  if (s.evidenz <= 1 && s.belegLuecke === 'unveroeffentlicht')
    return 'Am Menschen geprüft, Ergebnisse unveröffentlicht';
  if (s.evidenz <= 1) return 'Nicht am Menschen untersucht';
  if (s.hype <= 3) return 'Hype weit vor Evidenz';
  return 'Experimentell';
}
